window.__Q=window.__Q||{};window.__Q["prev/8/A1"]=[{"q":"低位小肠梗阻的患者，可有腹胀、腹痛、剧烈呕吐及排便、排气停止的症状，其呕吐物的性质应是","o":["呕吐棕黄色带粪臭的内容物","呕吐大量胃、肠、胰液和胆汁的内容物","剧烈呕吐胃内容物后呕吐血液","呕吐大量隔宿食物","喷射性呕吐"],"a":0,"e":"低位小肠梗阻时肠内容物停留过久，经细菌分解产生粪臭味，呕吐物为棕黄色带粪臭的小肠内容物，且呕吐出现较晚。B项为高位小肠梗阻表现，呕吐早、量大，含胃肠液及胆汁；C项咖啡色血性液提示肠管血供障碍；E项喷射性呕吐多见于颅内高压"},{"q":"下列不属于入院记录的书写形式的是","o":["入院记录","再次或多次入院记录","24h内出入院记录","24h内入院死亡记录","死亡病例讨论记录"],"a":4,"e":"入院记录形式包括入院记录、再次或多次入院记录、24小时内入出院记录及24小时内入院死亡记录。死亡病例讨论记录是病人死亡一周内对死亡病例进行讨论分析的记录，属讨论记录而非入院记录。D项24小时内入院死亡记录仍属入院记录范畴，应与死亡记录、死亡病例讨论记录区分"},{"q":"主动脉瓣第二听诊区位于","o":["心尖部","胸骨左缘第2肋间","胸骨右缘第2肋间","胸骨左缘第4、5肋间","胸骨左缘第3肋间"],"a":4,"e":"主动脉瓣第二听诊区位于胸骨左缘第3肋间，又称Erb区，是主动脉瓣关闭不全舒张期叹气样杂音的听诊区。B项胸骨左缘第2肋间为肺动脉瓣区；C项胸骨右缘第2肋间为主动脉瓣区；D项胸骨左缘第4、5肋间为三尖瓣区；A项心尖部为二尖瓣区"},{"q":"下述引起局部性水肿疾病的原因均正确，但除外","o":["肢体局部炎症","肢体静脉血栓形成","上腔静脉阻塞","门静脉压力增高","象皮腿"],"a":3,"e":"局部性水肿多由局部炎症、静脉或淋巴回流障碍引起，肢体炎症、静脉血栓、上腔静脉阻塞及象皮腿均属此类。门静脉压力增高主要引起腹腔积液，属门静脉高压的液体异常分布，不属局部性水肿；上腔静脉阻塞为局部性，门静脉高压形成腹水，两者不可混淆"},{"q":"下列关于肝脏的描述均正确，但除外","o":["肝脏位置因体位、呼吸而改变","右肋缘下正常时触不到肝脏","右肋缘下触到肝脏即是肝大","直立与吸气时，肝稍下降","单靠触诊不能完全判断肝大"],"a":2,"e":"正常成人肝脏一般在肋缘下触不到，但腹壁松软的瘦长体型者深吸气时可触及肋下1cm以内的肝下缘，故肋缘下触及肝脏不等于肝大。单靠触诊不能完全判断肝大，须结合叩诊肝上下径及影像学；直立与吸气时肝稍下降属正常变异。把正常可触及误判为肝大，属错误叙述"},{"q":"低钾血症是指血清钾低于","o":["3.4mmol/L","3.5mmol/L","4.1mmol/L","4.7mmol/L","5.6mmol/L"],"a":1,"e":"血清钾低于3.5mmol/L即为低钾血症，其中3.0～＜3.5为轻度，2.5～＜3.0为中度，＜2.5为重度。3.4只是轻度低钾的一个具体值，并非诊断界值；4.7、4.1均在正常范围；5.6已属高钾血症"},{"q":"以Hb为标准，下列可认为有贫血的是","o":["男性Hb＜125g/L，女性Hb＜115g/L","成年男性Hb＜125g/L，成年女性Hb＜115g/L","男性Hb＜120g/dl，女性Hb＜110g/dl","男性Hb＜125g/dl，女姓Hb＜115g/dl","成年男性Hb＜120g/L，成年女性Hb＜110g/L"],"a":4,"e":"贫血以血红蛋白浓度为准，成年男性Hb＜120g/L、成年女性＜110g/L可诊断，孕妇＜100g/L。C项单位为g/dl，120g/dl远超生理范围，属单位错误；A、B项界值误写为125g/L；D项单位误用g/dl且性别表述有误"},{"q":"内生肌酐清除率参考值是","o":["50～70ml/min","70～90ml/min","80～120ml/min","120～130ml/min","130～150ml/min"],"a":2,"e":"内生肌酐清除率参考区间为成人80～120ml/min，老年人随之自然下降，是反映肾小球滤过功能的常用指标。50～70ml/min提示中度肾功能损害；70～90ml/min偏低；120ml/min以上高于正常，可见于妊娠或高滤过状态"},{"q":"以下哪种细胞与杀伤无关","o":["NK细胞","LAK细胞","Th细胞","TIL细胞","K细胞"],"a":2,"e":"Th细胞主要分泌细胞因子辅助B细胞及其他T细胞发挥免疫调节作用，本身不直接杀伤靶细胞。NK细胞可自然杀伤肿瘤及病毒感染细胞；LAK细胞为淋巴因子激活的杀伤细胞；TIL为肿瘤浸润淋巴细胞，具抗瘤活性；K细胞经ADCC效应杀伤"},{"q":"下列叙述正确地描述了心前区震颤的是","o":["常见于瓣膜关闭不全的病变","它是触诊时感觉到的较强烈的振动感","它的出现表明心力衰竭","狭窄越重，震颤越强，极度狭窄时，震颤最强","它是器质性心脏病的特征性体征"],"a":4,"e":"心前区震颤是血液经狭窄瓣口产生湍流、使瓣膜或血管壁振动传导至胸壁所致，为器质性心脏病的特征性体征，触及即有病理意义。极度狭窄时因血流量锐减，震颤反而减弱或消失；震颤多见于瓣膜狭窄与先天性心脏病，而非关闭不全；其性质为细小震动感而非强烈振动感"},{"q":"发热发生机制中，共同的基本因素是","o":["外源性致热原","内生性致热原","前列腺素","精氨酸加压素","白介素"],"a":1,"e":"外源性致热原多不能通过血脑屏障，须激活中性粒细胞、单核巨噬细胞等产生并释放内生性致热原，后者作用于体温调节中枢使调定点上移，故内生性致热原是发热共同的基本环节。外源性致热原须经其介导；前列腺素、精氨酸加压素为中枢介质；白介素仅为内生致热原之一种"},{"q":"腹部视诊检查内容不包括","o":["腹外形","呼吸运动","腹壁静脉","胃肠型","腹壁紧张度"],"a":4,"e":"腹部视诊观察腹外形、呼吸运动、腹壁静脉及胃肠型等可见征象。腹壁紧张度须通过触诊感知肌张力增高或减低，属腹部触诊内容，不属视诊；腹壁静脉曲张与胃肠型则是视诊的重要发现"},{"q":"负性心尖冲动最常见于","o":["粘连性心包炎","左心室肥大","左侧胸腔积液","大量心包积液","急性心肌梗死"],"a":0,"e":"负性心尖搏动指心脏收缩时心尖部胸壁反而内陷，最常见于粘连性心包炎或心包与周围组织广泛粘连，重度右室肥厚致顺钟向转位亦可引起。左心室肥大表现为心尖搏动增强并向左下移位；大量心包积液使心尖搏动减弱或消失；左侧胸腔积液使心尖搏动移向健侧"},{"q":"最常见的第二心音分裂是","o":["生理分裂","通常分裂","固定分裂","反常分裂","逆分裂"],"a":1,"e":"第二心音分裂中通常分裂最常见，受呼吸影响，见于右室排血时间延长（二尖瓣狭窄伴肺动脉高压、肺动脉瓣狭窄）或左室射血时间缩短（二尖瓣关闭不全、室间隔缺损）。生理分裂多见于青少年吸气末；固定分裂为房间隔缺损特征；反常（逆）分裂属病理性，见于完全性左束支传导阻滞"},{"q":"下列属于中性粒细胞反应性增多的是","o":["原发性血小板增多症","白血病","急性感染或炎症","骨髓纤维化症","真性红细胞增多症"],"a":2,"e":"中性粒细胞反应性增多是机体对急性感染、炎症等应激的暂时性反应，急性化脓菌感染最常见，常伴核左移。白血病、原发性血小板增多症、骨髓纤维化、真性红细胞增多症均为骨髓克隆性增殖性疾病，属病理性增多，而非反应性"},{"q":"下列关于舒张期额外心音的叙述正确的是","o":["喷射音","喀喇音","奔马律","舒张期隆隆样杂音","舒张期叹气样杂音"],"a":2,"e":"奔马律是发生在舒张期的额外心音，与S1、S2组成三音心律，为心肌严重损害的体征，常见于心力衰竭、急性心肌梗死、重症心肌炎。喷射音、喀喇音位于收缩期；舒张期隆隆样杂音为二尖瓣狭窄、叹气样杂音为主动脉瓣关闭不全的杂音，二者属杂音而非额外心音"},{"q":"抗体的特异性是由下列哪一区段决定的","o":["重链和轻链","重链易变区","轻链易变区","重链和轻链的易变区","重链和轻链的恒定区"],"a":3,"e":"抗体特异性由重链和轻链可变区决定，二者N端氨基酸序列高度可变，共同构成抗原结合部位。恒定区序列相对恒定，与抗体类别及效应功能相关；仅重链或仅轻链易变区均不完整；重链与轻链范围过宽，未区分可变区与恒定区"},{"q":"下列各项为捻发音的特点，但应除外","o":["是一种极细而均匀一致的湿啰音","颇似在耳边用手指捻发时发出之音","产生是由于黏着、陷闭的肺泡壁被气流冲开重新充气","正常人在临床上不可能出现此种改变","少数人在数次深吸气或咳嗽后可消失"],"a":3,"e":"捻发音是极细而均匀一致的湿啰音，似耳边捻发之声，由黏着陷闭的肺泡壁被气流冲开重新充气产生，少数人深吸气或咳嗽后可消失，正常老年人或长期卧床者亦可闻及。称正常人绝不可能出现属绝对化错误；极细均匀、捻发样音色及黏着肺泡冲开机制均为其正确特点"},{"q":"为鉴别黄疸类型，最有意义的检查项目是","o":["总胆红素","结合胆红素","非结合胆红素","结合胆红素/总胆红素","尿胆原"],"a":3,"e":"结合胆红素与总胆红素比值是鉴别黄疸类型的关键：小于20%提示溶血性，20%～50%多为肝细胞性，大于50%为梗阻性，故该比值最有意义。总胆红素只反映黄疸程度；单看结合或非结合胆红素不如比值全面；尿胆原虽可协助，但受肠道吸收及肾功能影响，特异性不及比值"},{"q":"血清铜蓝蛋白降低最常见于","o":["肝豆状核变性","肝硬化","肝转移癌","各种感染","白血病"],"a":0,"e":"肝豆状核变性为常染色体隐性遗传的铜代谢障碍，血浆铜蓝蛋白减少致游离铜增多并沉积于肝、脑基底核，故血清铜蓝蛋白降低最常见于此病，可伴Kayser-Fleischer环。肝硬化、肝转移癌铜蓝蛋白多正常或升高；各种感染、白血病并非铜蓝蛋白降低的典型病因"},{"q":"梨形心最常见于下列何种疾病","o":["肺源性心脏病","冠状动脉粥样硬化性心脏病","二尖瓣狭窄","二尖瓣关闭不全","主动脉瓣关闭不全"],"a":2,"e":"二尖瓣狭窄致左房增大合并肺动脉段扩张，胸骨左缘第2、3肋间心界增大、心腰消失或膨出，心浊音界呈梨形。主动脉瓣关闭不全致左室增大、心腰加深，心界呈靴形；肺源性心脏病为右室增大，心界向两侧扩大；二尖瓣关闭不全主要为左室扩大"},{"q":"下列属于非感染性发热的疾病是","o":["肺结核","肺炎","急性肾盂肾炎","伤寒","中暑"],"a":4,"e":"中暑属物理及化学性损害所致的非感染性发热，因高温环境致散热障碍、体温调节失衡而发热，无病原体感染。肺结核、肺炎、急性肾盂肾炎、伤寒分别由结核分枝杆菌、细菌等病原体引起，均属感染性发热；非感染性发热还包括血液病、结缔组织病及恶性肿瘤"},{"q":"可以引起QT间期缩短的药物是","o":["地高辛","美托洛尔","普罗帕酮","胺碘酮","利多卡因"],"a":0,"e":"地高辛属洋地黄类药物，其效应使动作电位2位相缩短，心电图表现为ST段下垂型压低、T波低平双向呈鱼钩型及QT间期缩短。胺碘酮、普罗帕酮延长QT间期，可致尖端扭转型室速；美托洛尔、利多卡因对QT影响不明显，不引起缩短"},{"q":"下列试验检测纤溶功能的是","o":["凝血酶凝固时间测定","可溶性纤维蛋白单体复合物的检查","纤维蛋白肽A测定","凝血酶-抗凝血酶Ⅲ复合物测定","纤维蛋白肽B测定"],"a":1,"e":"纤溶功能检测包括硫酸鱼精蛋白副凝试验，其原理是检测可溶性纤维蛋白单体与纤维蛋白降解产物形成的复合物，故该检查可反映纤溶活性。凝血酶凝固时间主要反映纤维蛋白原含量及肝素样抗凝物质；纤维蛋白肽A、纤维蛋白肽B及凝血酶-抗凝血酶Ⅲ复合物均为凝血酶生成标志物，反映凝血激活而非纤溶"},{"q":"关于主要症状的特点，不包括","o":["部位","性质","发展与演变过程","持续时间及程度","缓解与加重的因素"],"a":2,"e":"主要症状的特点指症状的部位、性质、持续时间及程度、缓解与加重因素，用以刻画症状本身。病情的发展与演变属现病史中另一项目，记录主要症状的变化及新症状的出现，不列入症状特点；部位、性质、持续时间及程度、缓解加重因素均直接描述症状特征"},{"q":"下面情况易致低血钾的是","o":["严重腹泻","高热","创伤","急性肾衰少尿期","缺氧"],"a":0,"e":"严重腹泻使消化液大量丢失，钾随粪便排出过多，是低钾血症常见原因，常伴脱水及代谢性酸中毒。高热、创伤、缺氧主要引起分解代谢增强或应激反应，非失钾主因；急性肾衰少尿期因排钾减少反而易致高钾血症，与低钾方向相反"},{"q":"下列均为腹部触诊的正确方法，但除外","o":["边触诊边观察被检查者的表情","一律遵循自左下腹开始逆时针方向触诊原则","触诊脾脏时可向右侧卧位","触诊肾脏时可用坐位或立位","被检查者两手自然放于躯干两侧两腿屈曲"],"a":1,"e":"腹部触诊一般自左下腹逆时针方向进行，但原则是先触健康部位、渐移向病变区域，并非机械地一律按此顺序，故该表述错误。边触诊边观察表情、脾触诊取右侧卧位、肾触诊用坐位或立位、屈膝放松腹肌均为正确方法"},{"q":"关于二尖瓣关闭不全的叙述，下列哪项是正确的","o":["相对性二尖瓣关闭不全的杂音粗糙","二尖瓣瓣叶和腱索病变可引起相对性二尖瓣关闭不全","左心室扩大可引起器质性二尖瓣关闭不全","功能性二尖瓣关闭不全的杂音在原因去除后可消失","器质性二尖瓣关闭不全杂音为递增型"],"a":3,"e":"功能性（相对性）二尖瓣关闭不全多因左心室扩大致瓣环扩张，杂音柔和，随心腔缩小、病因去除可减弱或消失。左心室扩大引起的是相对性而非器质性关闭不全；瓣叶、腱索病变属器质性病因；相对性杂音多柔和而非粗糙；器质性者为全收缩期吹风样杂音，非递增型"},{"q":"正常人心尖搏动位于第5肋间的哪一部位","o":["胸骨左缘外0.5～1、0cm","左锁骨中线内0.5～1.0cm","左锁骨中线外0.5～1.0cm","左锁骨中线外1.0～2.0cm","左腋前线内0.5～1.0cm"],"a":1,"e":"正常成人心尖搏动位于第5肋间左锁骨中线内侧0.5～1.0cm，范围直径2.0～2.5cm。锁骨中线外提示左心室增大，外1.0～2.0cm为明显左室扩大；胸骨左缘外距离过近不符正常位置；左腋前线内已偏离正常心尖位置"},{"q":"用于评价阻塞性通气功能障碍程度的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":1,"e":"肺通气功能障碍程度按FEV1占预计值百分比分级，轻度≥70%、中度60%～69%、中重度50%～59%、重度35%～49%、极重度＜35%。FEV1/FVC用于区分阻塞性与限制性，反映气流受限而非程度；FVC主要反映肺容量；流速指标用于判断小气道病变"},{"q":"心脏收缩时，心脏哪一部分形成心尖冲动","o":["左心房","右心房","右心室","左心室","全心"],"a":3,"e":"心尖搏动主要由心室收缩时左心室心尖向前冲击前胸壁形成，故形成心尖冲动的为左心室。左心房位于心脏后上方，收缩时不与前胸壁相贴；右心房、右心室构成心脏前下部但不形成心尖；以全心概括过于笼统，不准确"},{"q":"诊断思维应该注意的问题，不包括","o":["现象和本质","主要和次要","局部和整体","典型和不典型","高花费和低花费"],"a":4,"e":"诊断思维应注意现象与本质、主要与次要、局部与整体、典型与不典型等关系，以透过临床表现把握疾病本质。费用高低属诊疗决策的经济学考量，不是诊断思维方法学问题；现象与本质、主要与次要、局部与整体、典型与不典型均为教材所列的辩证关系"},{"q":"细胞外铁消失，铁粒幼细胞＜10%，最可能的疾病是","o":["铁粒幼细胞贫血","溶血性贫血","缺铁性贫血","巨幼红细胞贫血","再生障碍性贫血"],"a":2,"e":"缺铁性贫血时骨髓贮存铁最早耗尽，铁染色示细胞外铁阴性、铁粒幼细胞显著减低常＜15%甚至为0，故本例最符合。铁粒幼细胞贫血细胞外铁增多、环形铁粒幼细胞＞15%；溶血性贫血、巨幼细胞贫血、再生障碍性贫血的细胞外铁多增加，常为+++～++++"},{"q":"下述何种情况肺下界移动度不消失","o":["膈神经麻痹","肺气肿","血气胸","胸腔大量积液","广泛胸膜肥厚粘连"],"a":1,"e":"肺气肿时肺组织弹性减弱，肺下界移动度减弱但不消失；膈神经麻痹、大量胸腔积液或血气胸、广泛胸膜肥厚粘连时肺下界及其移动度不能叩得而消失。肺气肿呈减弱，故为不消失之答案；其余四项均使移动度消失"},{"q":"导致排尿困难的动力性梗阻原因是","o":["前列腺癌","膀胱结核","糖尿病","前列腺增生症","先天性后尿道发育不全"],"a":2,"e":"糖尿病可引起神经源性膀胱，逼尿肌收缩无力导致动力性排尿困难，常伴血糖、尿糖升高，无机械性阻塞。前列腺癌、前列腺增生、先天性后尿道发育不全均为机械性梗阻；膀胱结核致膀胱挛缩亦属器质性改变，故仅糖尿病为动力性原因"},{"q":"下列为肺部叩诊呈过清音的正确描述，但应除外","o":["比清音的音调高","持久性良好","呈较深的回声","声音相对较强","极易听到"],"a":0,"e":"过清音介于鼓音与清音之间，音调较清音低而音响较清音强，属类乐性音，正常人不应出现，见于肺含气量增多、弹性减弱如肺气肿，且极易听到、持久性良好。称音调比清音高与过清音特点相反，故为除外项；持久良好、回声较深、声音较强、极易听到均符合其特点"},{"q":"丝虫病引起的淋巴管炎可导致","o":["阴囊湿疹","阴囊水肿","阴囊象皮肿","阴囊疝","鞘膜积液"],"a":2,"e":"丝虫病成虫阻塞淋巴管致淋巴回流障碍，阴囊皮肤水肿粗糙、增厚如橡皮样，形成阴囊象皮肿。阴囊湿疹为皮肤过敏或炎症；阴囊水肿多为全身性水肿的一部分；阴囊疝为肠管经腹股沟管降入；鞘膜积液为鞘膜腔液体积聚，均非丝虫病淋巴管炎的直接后果"},{"q":"中度贫血是指","o":["Hb 60～90g/L","Hb 30～60g/L","Hb＜30g/L","Hb＜参考值低值至90g/L","Hb＜35g/L"],"a":0,"e":"贫血按Hb浓度分度：轻度＞90g/L但低于参考下限，中度60～90g/L，重度30～59g/L，极重度＜30g/L，故中度贫血为60～90g/L。30～60g/L为重度；＜30g/L为极重度；低于参考值低值至90g/L接近轻度；＜35g/L无对应分度标准"},{"q":"下列哪一项是左室肥大的可靠体征","o":["心尖冲动向左下移位","心尖抬举性搏动","心界向左扩大","心界向右扩大","心尖冲动向左移位"],"a":1,"e":"心尖区抬举性搏动徐缓有力，可使手指尖端抬起并持续至第二心音开始，伴范围增大，是左心室肥厚的可靠体征；胸骨左下缘抬举性搏动提示右室肥厚。心尖冲动移位受心脏转位影响不够特异；心界扩大可由多种原因引起，亦非左室肥厚的可靠体征"},{"q":"正常人每昼夜尿量常为","o":["400～1500ml","500～2500ml","1000～2000ml","1000～2500ml","2500ml以上"],"a":2,"e":"正常成人24小时尿量为1000～2000ml，受饮水量、出汗等影响；少于400ml为少尿，少于100ml为无尿，多于2500ml为多尿。500～2500ml范围过宽；400～1500ml下限已达少尿标准；上限2500ml属多尿界限；2500ml以上为多尿，非正常"},{"q":"尿液胆红素阳性是指","o":["溶血性黄疸","肝性和梗阻性黄疸合并严重肾损伤","血液中结合胆红素浓度＞34μmol/L","血液中非结合胆红素浓度＞34μmol/L","是肾脏损伤的标志"],"a":2,"e":"结合胆红素为水溶性，可透过肾小球；当血中结合胆红素超过肾阈约34μmol/L时即自尿排出，尿胆红素试验阳性。溶血性黄疸以非结合胆红素升高为主，不能滤过肾小球，尿胆红素阴性；非结合胆红素不能经尿排出；尿胆红素阳性提示肝胆疾病，而非肾损伤标志"},{"q":"除下列情况外，均可出现红细胞尿","o":["再生障碍性贫血","系统性红斑狼疮","急性溶血","流行性出血热","感染性心内膜炎"],"a":2,"e":"急性溶血时红细胞在血管内破坏，血红蛋白经尿排出形成血红蛋白尿，尿呈酱油色，镜检无大量红细胞，故不出现红细胞尿。系统性红斑狼疮致狼疮性肾炎、流行性出血热、感染性心内膜炎并发免疫性肾炎均可有红细胞尿；再生障碍性贫血伴血小板减少亦可血尿"},{"q":"关于颈部包块的性质判断，错误的是","o":["若颈部包块弹性大又无全身症状，应考虑囊肿的可能","淋巴结肿大，质地不硬，有轻度压痛时，可能为非特异性炎症","颈部包块为圆形，表面光滑、有囊样感，压迫能使之缩小，可能为囊状瘤","淋巴结肿大，质地较硬，且伴有纵隔、胸腔或腹腔病变的症状或体征，应诊断为淋巴结结核","如为全身性、无痛性淋巴结肿大，多见于血液系统疾病"],"a":3,"e":"颈部淋巴结质硬且伴纵隔、胸腔或腹腔病变症状体征时，应首先考虑恶性肿瘤淋巴结转移，而非淋巴结结核，故该项错误。质不硬、轻度压痛多为非特异性淋巴结炎；弹性大、无全身症状提示囊肿；圆形光滑、囊样感、压迫缩小符合囊状瘤；全身无痛性肿大常见于血液系统疾病"},{"q":"鉴别肝源性水肿和心源性水肿最有意义的体征是","o":["腹水","颜面部水肿","肝大","双下肢凹陷性水肿","颈静脉怒张"],"a":4,"e":"颈静脉怒张反映体循环静脉压升高，是右心衰竭的特征；肝源性水肿虽有肝大、腹水，但无颈静脉怒张，故为二者鉴别最有意义的体征。腹水在肝硬化与右心衰均可出现；肝大二者皆有；双下肢凹陷性水肿为共同表现；颜面部水肿多见于肾源性"},{"q":"诊断的目的不包括","o":["弄清疾病的内在联系","让病人知道自己是患了何种疾病","为了更好的防治疾病","安慰亲属，解除不必要的担忧","越早弄清疾病的诊断，越能使病人更早的恢复健康"],"a":3,"e":"诊断旨在认识疾病本质、明确病因与病变以指导防治、促进康复，并向病人说明所患疾病。安慰亲属、解除担忧属医患沟通与人文关怀，并非诊断本身目的；弄清内在联系、指导防治、告知病情、早期诊断促康复均属诊断目的"},{"q":"作为中性粒细胞增多的原因，下列中最常见的为","o":["急性感染和化脓性炎症","中毒","急性失血","恶性肿瘤","心肌梗死"],"a":0,"e":"中性粒细胞增多最常见于急性感染和化脓性炎症，尤其急性化脓菌感染，常伴核左移及中毒性改变，是机体对病原体入侵的应激反应。中毒、急性失血、恶性肿瘤、心肌梗死均可引起增多，但发生率远低于急性化脓性感染，属次要原因"},{"q":"PT延长见于","o":["因子Ⅰ、Ⅱ、Ⅴ、Ⅷ、Ⅹ异常","因子Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ异常","因子Ⅰ、Ⅴ、Ⅷ、Ⅸ、Ⅹ异常","因子Ⅱ、Ⅶ、Ⅸ、Ⅹ、Ⅺ异常","因子Ⅰ、Ⅱ、Ⅴ、Ⅸ、Ⅹ异常"],"a":1,"e":"PT是外源性凝血系统筛选试验，延长见于因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及低（无）纤维蛋白原血症，即因子Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ异常。含Ⅷ、Ⅸ的选项涉及内源性途径因子，不影响PT；含Ⅺ、缺Ⅴ的组合错误，故该组合正确"},{"q":"支配眼球运动的三对脑神经是","o":["动眼神经、展神经、滑车神经","三叉神经、展神经、动眼神经","展神经、滑车神经、视神经","滑车神经、展神经、面神经","视神经、副神经、三叉神经"],"a":0,"e":"动眼神经（Ⅲ）、滑车神经（Ⅳ）、展神经（Ⅵ）共同支配眼外肌，合称眼球运动神经。三叉神经（Ⅴ）主司面部感觉与咀嚼运动；视神经（Ⅱ）司视觉；面神经（Ⅶ）支配表情肌；副神经（Ⅺ）支配胸锁乳突肌与斜方肌，均不参与眼球运动"},{"q":"前清蛋白比清蛋白更能早期反映肝细胞损害的原因是","o":["其血清浓度高","半衰期短","易于测定","浓度恒定","分子量小"],"a":1,"e":"前清蛋白半衰期约2天，远短于清蛋白，肝细胞受损合成减少时其血清浓度下降更早更明显，是反映肝损害的早期敏感指标。其血清浓度并不高；易于测定与早期反映无关；浓度受营养及肝功能影响而非恒定；分子量小并非早期反映的决定因素"},{"q":"对类风湿关节炎描述不正确的是","o":["一般以腕、掌指、近端指间关节肿痛为首发症状","关节晨僵时间大于60min","关节肿痛对称分布","晚期有关节畸形","常伴有皮肤黏膜损害"],"a":4,"e":"类风湿关节炎以对称性小关节滑膜炎为特征，常以腕、掌指、近端指间关节肿痛起病，晨僵超过1小时，晚期出现关节畸形，但皮肤黏膜损害并非其常见表现，多见于系统性红斑狼疮。其余四项均符合类风湿关节炎特点"},{"q":"下列疾病叩诊浊音，但须除外哪一项","o":["胸膜肥厚","胸腔积液","肺实变","肺肝界上移","肺含气量增多"],"a":4,"e":"下列疾病叩诊浊音但须除外肺含气量增多，因含气量增多、弹性减弱时叩诊呈过清音；胸膜肥厚、胸腔积液、肺实变均使含气量减少而叩诊浊音。肺肝界上移使浊音区扩大，亦属叩诊浊音范畴；故仅肺含气量增多不呈浊音，为除外项"},{"q":"成人高血压的诊断标准中，正确的是","o":["收缩压≥18.7kPa（140mmHg）和（或）舒张压≥12kPa（90mmHg）","收缩压＞20kPa（150mmHg）和（或）舒张压＞12kPa（90mmHg）","收缩压＞21..3kPa（160mmHg）和（或）舒张压＞12kPa（90mmHg）","收缩压≥21.3kPa（160mmHg）和（或）舒张压≥12.7kPa（95mmHg）","收缩压≥21.3kPa（160mmHg）和（或）舒张压＞13.3kPa（100mmHg）"],"a":0,"e":"高血压定义为未用降压药、非同日3次诊室测量收缩压≥140mmHg和/或舒张压≥90mmHg，18.7kPa、12kPa为其千帕换算值。160mmHg、160/95mmHg、160/100mmHg均为既往或过高标准，不符现行140/90mmHg界值"},{"q":"心电图表现：①P波时限增宽＞0.11s；②P波形态有切迹，双峰，峰距≥0.04s。提示诊断为","o":["左心房肥大","右心房肥大","左心室肥厚","右心室肥厚","双心房肥大"],"a":0,"e":"左心房肥大时心房除极时间延长，表现为P波增宽≥0.12秒、双峰且峰距≥0.04秒，以Ⅰ、Ⅱ、aVL导联明显，常见于二尖瓣疾病，称二尖瓣型P波。右心房肥大表现为P波高尖、时限正常；心室肥厚以QRS改变为主；双心房肥大还须振幅≥0.25mV"},{"q":"急性白血病患者的出血主要是","o":["血小板减少","多种凝血因子缺乏","白血病细胞浸润血管壁","弥散性血管内凝血","严重贫血使血管壁缺氧"],"a":0,"e":"急性白血病时骨髓巨核细胞受抑制致血小板生成减少，是出血主要原因，表现为皮肤瘀点瘀斑、鼻出血等。多种凝血因子缺乏与DIC主要见于重症肝病或弥散性血管内凝血；白血病细胞浸润血管壁可致损伤但非主要机制；贫血致血管壁缺氧不是主因"},{"q":"提示终末期肾衰竭的Ccr值为","o":["＜50ml/min","＜40ml/min","＜30ml/min","＜20ml/min","＜10ml/min"],"a":4,"e":"Ccr反映肾小球滤过功能，＜10ml/min时肾脏几近丧失排泄功能，需结合临床行肾脏替代治疗，提示终末期肾衰竭。＜50ml/min为肾功能轻中度下降；＜40ml/min需限制蛋白；＜30ml/min噻嗪类利尿无效；＜20ml/min为重度损害，均未达终末期"},{"q":"可提示陈旧性心肌梗死的心电图改变是","o":["QRS波群低电压","电轴显著左偏","ST段上抬","冠状T出现","V3～V5的Q波＞0.04s"],"a":4,"e":"陈旧性心肌梗死的心电图标志是坏死型异常Q波，即面向坏死区导联Q波时限＞0.04s，V3～V5对应前壁梗死。ST段上抬为急性损伤期；冠状T波为缺血性倒置，非陈旧性特异；QRS低电压、电轴左偏均非坏死性改变"},{"q":"肺泡呼吸音增强见于下列情况，但除外","o":["发热","贫血","运动","酸中毒","肺气肿"],"a":4,"e":"肺泡呼吸音增强因呼吸运动加强或需氧增加所致，发热、贫血、运动、酸中毒呼吸深大均可使其增强。肺气肿时肺泡弹性回缩力减弱、含气量增多，肺泡呼吸音减弱而非增强，故为除外项；其余四项均使呼吸加深加快、通气量增加"},{"q":"一名视物模糊的患者入院进行检查，接诊医生哪一项检查不是视神经检查内容","o":["视力检查","视野检查","视网膜检查","视盘检查","玻璃体检查"],"a":4,"e":"视神经检查包括视力、视野及眼底视盘、视网膜等视功能检查。玻璃体位于眼球后部，其检查属内眼检查，需检眼镜在暗室进行，不属视神经检查内容；视力、视野、视网膜、视盘均直接反映视神经功能"},{"q":"关于正常人血压的叙述，正确的是","o":["上肢血压高于下肢","下肢血压高于上肢","上、下肢血压相等","男性上肢血压高，女性下肢血压高","女性上肢血压高，男性下肢血压高"],"a":1,"e":"正常下肢血压高于上肢约20～40mmHg，与下肢动脉口径及测量条件有关；下肢血压低于上肢提示主动脉缩窄或胸腹主动脉型大动脉炎。上肢高于下肢与事实相反；上下肢相等不符生理；按性别区分上下肢血压高低无依据"},{"q":"关于肠鸣音以下均正确，除外","o":["肠鸣音活跃可见于胃肠道大出血","肠鸣音正常为每分钟3～4次","肠鸣音减弱可见于腹膜炎","肠鸣音为肠管内气体和液体流动产生","肠鸣音消失为持续3～5min无肠鸣音"],"a":1,"e":"正常肠鸣音约每分钟4～5次，频率音调变异较大，餐后频繁、休息稀疏，故每分钟3～4次表述不准确，为除外项。肠鸣音活跃可达10次以上，见于胃肠道大出血；腹膜炎可致减弱；由肠管气液流动产生；持续3～5分钟未闻及为消失"},{"q":"玫瑰疹常出现的部位在","o":["面颊部","颈背部","肩部","胸腹部","四肢"],"a":3,"e":"玫瑰疹为伤寒、副伤寒的特征性皮疹，压之褪色、松开复现，多出现于胸腹部。面颊部常见麻疹或痤疮；颈背部、肩部非玫瑰疹好发部位；四肢可见于过敏性紫癜等，但玫瑰疹主要分布于胸腹部"},{"q":"心尖部舒张期室性奔马律最常见于","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，二尖瓣关闭不全","原发性高血压（Ⅲ期）","法洛四联症","肺源性心脏病"],"a":2,"e":"舒张期室性奔马律即舒张早期奔马律，是左室心肌严重受损、左心衰竭的体征，原发性高血压Ⅲ期常并发左心衰，故最常见。二尖瓣狭窄、关闭不全以瓣膜病变为主要表现；法洛四联症、肺源性心脏病主要引起右心改变，其奔马律多为右室性"},{"q":"关于主动脉缩窄的临床表现，以下说法不正确的是","o":["下肢血压明显高于上肢","腹主动脉、股动脉脉搏微弱或不能触及","胸骨旁及中上腹搏动显著伴震颤","胸骨左缘可闻及收缩中后期吹风样杂音","伴有二叶主动脉瓣者，主动脉瓣区可闻及收缩期杂音或兼有舒张期杂音"],"a":0,"e":"主动脉缩窄使狭窄段以下血流减少，下肢血压低于上肢、股动脉及腹主动脉搏动减弱，而非下肢血压高于上肢，故该项错误。股动脉搏动微弱、胸骨旁及中上腹搏动伴震颤、胸骨左缘收缩中后期杂音、合并二叶主动脉瓣杂音均为其常见表现"},{"q":"细胞质中不含颗粒的细胞是","o":["早幼粒细胞","中幼粒细胞","晚幼红细胞","幼淋巴细胞","幼单核细胞"],"a":2,"e":"红细胞系统各阶段胞质内均无颗粒，晚幼红细胞胞质充满血红蛋白而不含任何颗粒。早幼粒细胞含紫红色嗜天青颗粒；中幼粒细胞含中性、嗜酸性或嗜碱性特异性颗粒；幼单核细胞含嗜天青颗粒，故仅晚幼红细胞符合"},{"q":"一患者右胸大量积气，下列体征不正确的是","o":["气管移向右侧","右侧语颤减弱","右侧叩诊鼓音","右肺呼吸音弱","肝浊音界下移"],"a":0,"e":"右侧大量气胸时胸膜腔压力升高，气管和心脏被推向健侧（左侧），而非移向右侧，故该项错误。右侧语颤减弱或消失、叩诊鼓音、呼吸音减弱或消失均为气胸典型体征；右侧气胸使肝浊音界下移，亦为正确表现"},{"q":"下列哪种疾病肝叩诊浊音界缩小","o":["肝炎","肝淤血","脂肪肝","Budd-Chiari综合征","肝硬化"],"a":4,"e":"肝硬化时肝实质萎缩、纤维组织增生致肝体积缩小，叩诊肝浊音界缩小，急性重型肝炎亦然。肝炎、肝淤血、脂肪肝均使肝肿大、浊音界扩大；Budd-Chiari综合征因肝静脉回流受阻致肝淤血肿大，浊音界增大"},{"q":"心脏叩诊相对浊音界呈梨形改变，最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","肺源性心脏病","二尖瓣狭窄","二尖瓣关闭不全"],"a":3,"e":"二尖瓣狭窄致左房扩大及肺动脉段膨出，心腰消失、胸骨左缘第2、3肋间心界增宽，心浊音界呈梨形。主动脉瓣关闭不全致左室增大、心腰加深呈靴形心；主动脉瓣狭窄亦以左室肥厚为主；肺源性心脏病心界向两侧扩大；二尖瓣关闭不全主要为左室扩大"},{"q":"当体重减轻低于标准体重（ ）时称为消瘦","o":["5%","10%","15%","18、5%","20%"],"a":1,"e":"体重低于标准体重10%即可诊断消瘦，BMI＜18.5kg/m²亦可判定，须与营养不良、慢性消耗性疾病鉴别。超过标准体重10%为超重、20%为肥胖，非消瘦界值；5%属正常波动；15%并非标准；18.5实为BMI界值而非体重百分比"},{"q":"用袖带法测量上、下肢血压，正常时下肢血压较上肢血压高，其范围为","o":["5～10mmHg","20～40mmHg","10～20mmHg","30～40mmHg","40～60mmHg"],"a":1,"e":"正常下肢收缩压较上肢高20～40mmHg，与下肢肌群丰厚及测量条件有关；下肢血压低于上肢提示主动脉缩窄。5～10mmHg为双侧上肢血压正常差别；10～20mmHg数值偏低；30～40mmHg、40～60mmHg超出正常上限"},{"q":"下列情况下可以使左右两肺前界间浊音区缩小的是","o":["扩张型心肌病","心包积液","主动脉瘤","肺门淋巴结肿大","肺气肿"],"a":4,"e":"两肺前界间浊音区反映心脏大血管在前胸壁的投影，肺气肿时肺过度充气、肺前界内移使其缩小；心脏扩大、心包积液、主动脉瘤及肺门淋巴结肿大则使其扩大。扩张型心肌病、心包积液、主动脉瘤、肺门淋巴结肿大均致扩大，故肺气肿正确"},{"q":"下列情况下，均可引起第一心音减弱，但应除外","o":["二尖瓣狭窄","二尖瓣关闭不全","P-R间期延长","心肌炎","心肌梗死"],"a":0,"e":"第一心音强度取决于心室内压上升速率及瓣膜位置；二尖瓣狭窄时充盈减少、瓣膜位置低垂，收缩振动幅度大，S1反而增强，为引起减弱的除外项。二尖瓣关闭不全、P-R间期延长、心肌炎、心肌梗死均使收缩力减弱或关闭振动减小，致S1减弱"},{"q":"二尖瓣脱垂综合征是","o":["心率增快，出现在S2之后，音调低弱，与S1和S2的间距相仿","位于S2之后，调高，短促响亮，呈拍击性","位于S2之后，中频，短促响亮，胸骨左缘容易听见","位于S2之后，音调较低，随体位变动","位于S2之后，音调高，短促清脆，可伴心尖区收缩晚期杂音"],"a":4,"e":"二尖瓣脱垂综合征听诊为心尖区收缩中晚期喀喇音，音调高、短促清脆，并伴心尖区收缩晚期杂音，由脱垂瓣叶骤然绷紧及反流所致。呈拍击样的高调短促音为二尖瓣狭窄开瓣音；胸骨左缘中频短促响亮音提示心包叩击音；音调低、随体位改变见于心房黏液瘤"},{"q":"细胞质内含有嗜天青颗粒的细胞是","o":["中幼粒细胞","早幼粒细胞","晚幼粒细胞","原单核细胞","分叶核粒细胞"],"a":1,"e":"颗粒随粒细胞发育由无到有，早幼粒细胞胞质出现粗大、分布不均的紫红色嗜天青颗粒，中幼粒以后转为特异性颗粒。中幼粒与晚幼粒细胞以特异性颗粒为主；原单核细胞为原始阶段，胞质一般无颗粒；分叶核粒细胞含特异性颗粒，均非嗜天青颗粒典型细胞"},{"q":"最常见血清MAO活性增高的疾病是","o":["急性肝炎","慢性肝炎活动期","肝硬化","肝癌","暴发性肝衰竭"],"a":2,"e":"单胺氧化酶活性与结缔组织增生、肝纤维化程度正相关，80%以上重症肝硬化病人增高，故肝硬化最常见。急性肝炎MAO大多正常，仅急性重型肝炎因肝细胞坏死逸出而增高；中度以上慢性肝炎约50%增高；肝癌多伴肝硬化才增高"},{"q":"二尖瓣狭窄时，下列体征提示瓣膜弹性尚好的是","o":["心尖部可触及舒张期震颤","开瓣音","舒张期杂音随体位改变","肺动脉第二音亢进","心尖部舒张期杂音"],"a":1,"e":"开瓣音见于二尖瓣狭窄而瓣膜尚柔软时，舒张早期血液自左房迅速流入左室，弹性尚好的瓣叶骤然开放又突然停止，产生拍击样声音，故提示瓣膜弹性及活动度良好。舒张期震颤与杂音只说明狭窄存在；杂音随体位改变非弹性指标；P2亢进反映肺动脉高压"},{"q":"下列各项为既往史内容，但除外","o":["病人过去的健康状况","预防接种史","曾有肝炎接触史","到过传染病流行区","过敏史"],"a":3,"e":"既往史记录既往健康状况、曾患疾病、外伤手术、预防接种史及过敏史等。到过传染病流行区属个人史的社会经历，须按潜伏期追问，不属既往史；既往健康状况、预防接种史、肝炎接触史、过敏史均为既往史内容"},{"q":"下述是冲击触诊法，或称浮沉触诊法，但除了","o":["检查者以右手三、四个手指并拢","并拢的三、四个手指与腹壁呈70°～90°角","置并拢手指于腹壁相应的部位上","并拢的手指作数次急速而较有力的冲击动作","并拢的手指作数次轻柔的、缓慢的按压动作"],"a":4,"e":"冲击触诊法以右手三、四指并拢取70°～90°角置于腹壁，作数次急速而较有力的冲击动作，指端感受脏器或包块浮沉，多用于大量腹水时肝脾触诊。轻柔缓慢按压属深压或一般触诊手法，不符急速有力要求；三、四指并拢、取角、置腹壁、急速冲击均为正确描述"},{"q":"风湿性心脏病主动脉瓣关闭不全的主要体征是","o":["心浊音界向左下扩大","主动脉瓣区第二心音减弱或消失","胸骨左缘第3肋间舒张期叹气样杂音","Austin Flint杂音","毛细血管搏动征"],"a":2,"e":"主动脉瓣关闭不全的典型体征是主动脉瓣第二听诊区（胸骨左缘第3肋间）舒张早期递减型柔和叹气样杂音，前倾坐位、深呼气后最清楚。A2减弱非特异；心界向左下扩大为左室增大表现；Austin Flint杂音为相对性二尖瓣狭窄杂音；毛细血管搏动征属周围血管征"},{"q":"有关临床思维的要素是","o":["临床实践","科学思维","临床实践，科学思维","主观判断","经验再现"],"a":2,"e":"临床思维两大要素为临床实践和科学思维，前者通过病史采集、体格检查等观察发现问题，后者对资料归纳分析形成判断，二者反复循环上升。仅取临床实践或科学思维均不完整；主观判断易致误诊，非科学思维；经验再现只是临床实践的一部分"},{"q":"下列疾病见不到棒状小体的是","o":["M2","M3","M4","M5","急性淋巴细胞白血病"],"a":4,"e":"棒状小体（Auer小体）为急性髓系白血病原始或早幼粒细胞胞质中的棒状包涵体，M2、M3、M4、M5均可出现；急性淋巴细胞白血病细胞中不见棒状小体，MPO染色亦阴性。M2～M5均为髓系亚型，可见棒状小体"},{"q":"以下尿蛋白含量均称为蛋白尿，但需除外","o":["尿蛋白定量试验20～80mg/24h","尿蛋白定量试验＞100mg/L","尿蛋白定量试验＞150mg/24h","蛋白质定性试验阳性","尿蛋白定量试验3、5g/24h"],"a":0,"e":"蛋白尿指定量＞150mg/24h或＞100mg/L、定性阳性；正常成人尿蛋白定量0～80mg/24h，故20～80mg/24h属正常，不称蛋白尿。＞150mg/24h、＞100mg/L均达标准；定性阳性提示蛋白尿；3.5g/24h为大量蛋白尿，可达肾病综合征水平"},{"q":"以下哪项属于特异性杀伤瘤细胞","o":["TDTH细胞","K细胞","M¢","NK细胞","CTL细胞"],"a":4,"e":"CTL（CD8+细胞毒性T细胞）通过识别MHCⅠ类分子呈递的抗原，特异性杀伤肿瘤或病毒感染细胞。TDTH主要释放淋巴因子；K细胞经ADCC非特异杀伤；巨噬细胞杀伤非特异；NK细胞属天然免疫，无须抗原致敏，亦非特异性杀伤"},{"q":"下列疾病中S1增强的是","o":["大面积心肌梗死","扩张型心肌病","心肌炎","二尖瓣狭窄","大量心包积液"],"a":3,"e":"二尖瓣狭窄时左室充盈减少、瓣膜位置低垂，收缩时室内压上升快、振动幅度大，故S1增强。大面积心肌梗死、扩张型心肌病、心肌炎均因收缩力减弱致S1减弱；大量心包积液使心音遥远、S1减弱"},{"q":"左腋中线脾的浊音界长度为","o":["4～7cm","7～9cm","9～10cm","11～12cm","12～13cm"],"a":0,"e":"正常脾浊音区在左腋中线第9～11肋间叩得，长度约4～7cm，前方不超腋前线；脾大时扩大，左侧气胸、胃扩张、肠胀气时缩小。7～9cm、9～10cm已提示脾大；11～12cm、12～13cm明显超过正常范围"},{"q":"下列各项均为大量腹水的体征，但除外","o":["蛙腹","波动感","振水音","移动性浊音","脐疝"],"a":2,"e":"大量腹水可见蛙腹、液波震颤、移动性浊音及脐疝。振水音是胃内大量液体与气体存留时的气液撞击声，空腹或餐后6～8小时以上出现提示幽门梗阻或胃扩张，与腹水无关，故为除外项；其余四项均为腹腔积液增多的典型表现"},{"q":"关于主诉的写作要求，下列哪项不正确","o":["提示疾病主要属何系统","提示疾病的急性或慢性","指出发生并发症的可能","指出疾病发生发展及预后","文字精练、术语准确"],"a":3,"e":"主诉为最主要症状或体征及其持续时间，文字精练、术语准确，可提示病变系统及急慢性、指出并发症可能。疾病发生发展属现病史内容，预后须综合判断，均非主诉所能涵盖；提示系统、急慢性、并发症及精练准确均符合主诉要求"},{"q":"个人史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":2,"e":"个人史记录出生地及长期居留地、生活习惯、烟酒嗜好、职业与毒物接触史等，出生地及居住时间属其社会经历。主要症状特点属现病史；药物食物过敏史属既往史；夫妻关系属婚姻史；生育次数属生育史"},{"q":"下列凝血因子中哪组凝血因子为维生素K依赖因子","o":["Ⅰ，Ⅲ，Ⅳ，Ⅴ","Ⅱ，Ⅶ，Ⅹ，Ⅺ","Ⅱ，Ⅶ，Ⅸ，Ⅹ","Ⅷ，Ⅸ，Ⅺ，Ⅻ","Ⅲ，Ⅴ，Ⅶ，Ⅹ"],"a":2,"e":"维生素K依赖凝血因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ，在肝合成，须维生素K参与羧化才有活性；华法林拮抗维生素K使其合成减少，PT延长。含Ⅰ、Ⅲ、Ⅳ、Ⅴ者、含Ⅺ者、含Ⅷ、Ⅺ、Ⅻ者及含Ⅲ、Ⅴ者均不属维生素K依赖因子"},{"q":"下列不引起腹式呼吸减弱的是","o":["腹膜炎症","腹水","急性腹痛","腹腔内巨大肿物","胸腔积液"],"a":4,"e":"腹式呼吸减弱见于腹膜炎症、大量腹水、腹腔内巨大肿物及急性腹痛等使膈肌运动受限者；胸腔积液主要限制胸廓扩张，引起胸式呼吸减弱而腹式呼吸常代偿增强。其余四项均使膈肌活动受限、腹式呼吸减弱"},{"q":"心外膜下损伤时，ST段如何偏移","o":["ST段弓背向上抬高","ST段无变化","ST段压低","ST段弓背向下抬高","ST段压低合并T波倒置"],"a":0,"e":"心外膜下心肌损伤（含透壁性缺血）时损伤电流指向心外膜面导联，ST段抬高，急性心梗时呈弓背向上抬高，显著者成单向曲线。ST段无变化不符；压低见于心内膜下损伤；弓背向下抬高见于急性心包炎；压低伴T波倒置为心内膜下缺血"},{"q":"下列哪项是有关T细胞检查的常用试验","o":["抗体依赖细胞介导的细胞毒测定","E玫瑰花结形成试验","酵母菌花环试验","免疫球蛋白测定","补体含量测定"],"a":1,"e":"T细胞表面E受体（CD2）可与绵羊红细胞结合形成花结，即E玫瑰花结形成试验，是检测T细胞数量的常用方法。ADCC测定主要检测NK或K细胞功能；酵母菌花环试验检B细胞；免疫球蛋白测定、补体含量测定均非T细胞检查"},{"q":"健康人可见哪种管型","o":["红细胞管型","透明管型","白细胞管型","颗粒管型","脂肪管型"],"a":1,"e":"透明管型由T-H蛋白、白蛋白及少量氯化物构成，健康人偶见0～1个/HPF，运动发热后可增多。红细胞管型提示急性肾小球病变或出血；白细胞管型见于肾感染；颗粒管型提示肾实质病变伴淤滞；脂肪管型见于肾小管损伤及脂肪变性"},{"q":"革兰阴性细菌的致热物质主要是","o":["外毒素","螺旋毒素","溶血素","全菌体、肽聚糖和内毒素","细胞毒因子"],"a":3,"e":"革兰阴性菌致热物质主要为全菌体、肽聚糖及细胞壁脂多糖（内毒素），内毒素属外源性致热原，激活单核巨噬细胞释放内源性致热原而致发热。外毒素、螺旋毒素、溶血素多为革兰阳性菌等产生，非革兰阴性菌主要致热物质"},{"q":"病态窦房结综合征心电图改变的特点不包括","o":["持续窦性心动过缓，心率＜50次/min","应用阿托品后心率明显增快","窦性停搏或窦房传导阻滞","可有双结病变","常出现慢快综合征"],"a":1,"e":"病态窦房结综合征表现为持续窦缓（＜50次/分）且不易被阿托品纠正，故用药后心率明显增快不符合，为不包括项。窦性停搏或窦房阻滞、慢快综合征、双结病变均为其特点；阿托品试验心率不增快反有助诊断"},{"q":"主治医师首次查房记录应当于患者入院（ ）小时内完成","o":["24","48","36","72","12"],"a":1,"e":"主治医师首次查房记录至少于入院48小时内完成，并须查房医师审阅签名；常规查房间隔视病情而定，疑难危重须及时有上级医师查房记录。24小时、36小时、12小时短于规定；72小时超过时限"},{"q":"“三凹征”是指","o":["胸骨上窝、锁骨下窝、肋间隙向内凹陷","锁骨下窝、锁骨上窝、肋间隙向内凹陷","胸骨上窝、锁骨下窝、肋间隙向外凹陷","胸骨上窝、锁骨上窝、肋间隙向外凹陷","胸骨上窝、锁骨上窝、肋间隙向内凹陷"],"a":4,"e":"三凹征见于吸气性呼吸困难，上呼吸道阻塞时吸气肌强力收缩使胸内负压极度增高，出现胸骨上窝、锁骨上窝及肋间隙明显向内凹陷，伴干咳及高调吸气性喉鸣。误列锁骨下窝为凹陷部位或写成向外凹陷均与体征不符"},{"q":"过敏性紫癜导致皮肤黏膜出血的机制是","o":["血管壁缺陷","血小板数量异常","血小板质量异常","凝血因子活性下降","纤溶亢进"],"a":0,"e":"过敏性紫癜属血管壁功能异常，毛细血管壁受损、通透性脆性增加致皮肤黏膜出血，表现为四肢对称性高出皮面紫癜，可伴关节痛、腹痛、血尿。血小板数量或质量异常多见于血小板疾病；凝血因子活性下降见于血友病；纤溶亢进见于DIC"},{"q":"呼吸深大见于","o":["肺纤维化","段性肺不张","急性肺炎","支气管肺癌","酮症酸中毒"],"a":4,"e":"酮症酸中毒等严重代谢性酸中毒时HCO3-不足、pH降低，通过深快呼吸（Kussmaul呼吸）排出CO2代偿。肺纤维化、段性肺不张、急性肺炎、支气管肺癌多表现为呼吸浅快或呼吸困难，不出现典型深大呼吸"},{"q":"颈静脉搏动最常见于","o":["二尖瓣关闭不全","上腔静脉阻塞","三关瓣关闭不全","心脏压塞","主动脉瓣关闭不全"],"a":2,"e":"三尖瓣关闭不全时收缩期血液反流入右房，使颈静脉出现收缩期搏动，是最常见原因，常伴肝脏收缩期搏动。二尖瓣关闭不全、主动脉瓣关闭不全为左心病变；上腔静脉阻塞表现为颈静脉充盈怒张而非搏动；心脏压塞致颈静脉怒张、奇脉"},{"q":"血尿伴腰腹部绞痛，放射至会阴部，最常见于","o":["肾结石","肾结核","膀胱结石","输尿管结石","肾肿瘤"],"a":3,"e":"输尿管结石移动刺激平滑肌痉挛，引起阵发性腰腹绞痛，沿输尿管放射至会阴，常伴血尿，最常见。肾结石多为腰部钝痛，放射至会阴不典型；肾结核以尿频、无痛性血尿为主；膀胱结石致排尿中断；肾肿瘤为无痛性全程血尿"},{"q":"关于医院感染和社区感染，叙述正确的是","o":["医院感染为内源性，社区感染为外源性","前者的病原体主要是条件致病菌，后者为典型致病菌","二者的易感者相同","二者均为多重耐药的病原体","前者较易治疗，后者较难治疗"],"a":1,"e":"医院感染病原体多为正常菌群或机会致病菌，常多重耐药，易感者为免疫力低下的住院者；社区感染病原体多为典型致病菌，易感者多为健康人群。医院感染也可由外源病原体引起，易感者不同；多重耐药主要为医院感染特点，且治疗更困难"},{"q":"维持细胞外液渗透压的主要离子是","o":["钾离子和氯离子","钾离子和磷酸氢根","钠离子和氯离子","钠离子和磷酸氢根","钠离子和碳酸氢根"],"a":2,"e":"细胞外液主要阳离子为Na+、主要阴离子为Cl-，二者构成氯化钠，是维持细胞外液渗透压与容量的主要离子。钾主要分布于细胞内液；磷酸氢根、碳酸氢根虽在细胞外液，但含量远少于氯离子，非维持渗透压的主导阴离子"},{"q":"血浆凝血酶原时间，超过正常对照（ ）以上有临床意义","o":["3s","5s","7s","10s","12s"],"a":0,"e":"PT须设正常对照，测定值超过对照3秒以上为异常，是外源性凝血系统常用筛选试验，延长见于Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及纤维蛋白原异常。5秒、7秒、10秒、12秒均超过判定异常的标准"},{"q":"下腹壁反射是由下述哪个胸段脊髓神经节支配","o":["胸3～4节","胸5～6节","胸7～8节","胸9～10节","胸11～12节"],"a":4,"e":"腹壁反射分上中下三部，分别由胸髓7～8节（肋缘下）、9～10节（脐平）、11～12节（腹股沟上）支配，故下腹壁反射对应胸11～12节。胸3～4、胸5～6节支配上胸段，胸7～8为上腹壁反射，胸9～10为中腹壁反射"},{"q":"急性肾功能不全时，下列检查不必要的是","o":["自由水清除率","内生肌酐清除率","尿渗量","血清蛋白电泳","血肌酐"],"a":3,"e":"急性肾功能不全主要评估肾小球滤过与肾小管功能，内生肌酐清除率、血肌酐、尿渗量、自由水清除率均可反映损害程度；血清蛋白电泳主要用于肝病及多发性骨髓瘤等蛋白异常筛查，与急性肾损伤无关，故不必要"},{"q":"下列哪种疾病骨髓巨核细胞减少","o":["血友病","缺铁性贫血","ITP","急性再生障碍性贫血","巨幼细胞贫血"],"a":3,"e":"急性再生障碍性贫血因骨髓造血衰竭，巨核细胞显著减少甚至消失，伴全血细胞减少、网织红细胞降低。血友病为凝血因子缺乏，巨核细胞正常；缺铁性贫血、巨幼细胞贫血骨髓增生活跃；ITP巨核细胞正常或增多伴成熟障碍"},{"q":"产生全身性水肿的病因不会是","o":["肝硬化","缩窄性心包炎","肾病综合征","下肢静脉血栓形成","尿毒症"],"a":3,"e":"下肢静脉血栓形成致局部静脉回流障碍，仅引起单侧下肢肿胀，属局部性水肿，不产生全身性水肿。肝硬化、缩窄性心包炎、肾病综合征、尿毒症分别经低蛋白血症、静脉压升高、水钠潴留等机制引起全身性水肿"},{"q":"pH为7.48，标准碳酸氢盐超过45mmol/L时，下描述最准确的是","o":["受呼吸影响较大","是反应呼吸性碱中毒的指标","是准确反应代谢性酸碱平衡失调的指标","肯定为代谢性碱中毒","受代谢影响较大"],"a":2,"e":"标准碳酸氢盐（SB）在标准PaCO2条件下测得，一般不受呼吸影响，是准确反映代谢性酸碱平衡的指标；pH 7.48提示碱血症，SB显著升高提示代谢性碱中毒。称受呼吸影响大与SB特性相反；AB＜SB才反映呼吸性碱中毒；仅凭SB不能断言肯定"},{"q":"18岁女性，Hb 80g/L，属于","o":["正常","轻度贫血","中度贫血","重度贫血","极重度贫血"],"a":2,"e":"成年女性Hb 80g/L处于60～90g/L区间，属中度贫血，体力劳动时可有心慌气短。正常女性Hb应在110g/L以上；轻度为＞90g/L但低于下限；重度为30～59g/L；极重度＜30g/L"},{"q":"肺心病的心电图改变中，错误的是","o":["右心房肥大","极度顺钟向转位","肺性P波","肢体导联QRS波群低电压","左心房肥大"],"a":4,"e":"肺源性心脏病因右心负荷增加，表现为右心房肥大（肺性P波）、右心室肥厚、极度顺钟向转位及肢体导联QRS低电压，不出现左心房肥大。极度顺钟向转位、肺性P波、QRS低电压均为常见改变；右心房肥大即肺性P波基础；左房肥大常见于二尖瓣疾病"},{"q":"正常成年人体内HbF占","o":["98%","60%","50%","3%","＜1%"],"a":4,"e":"正常成人血红蛋白以HbA为主，HbA2占2.5%～3.5%，HbF＜1%；新生儿HbF可达6%～93%，随年龄增长被HbA替代。98%接近HbA占比；60%、50%为新生儿水平；3%高于成人正常，可见于某些血红蛋白病"},{"q":"一患者因突发左胸剧痛被送至急诊科，医师应最先了解","o":["患者姓名等一般项目","胸痛发作的时间及特点","胸痛的治疗过程","患者的既往健康状况","患者的家族史"],"a":1,"e":"急诊胸痛时间紧迫，应首先抓住发作时间、部位、性质、程度、放射及诱因等核心特点，快速判断病因争取救治。一般项目可待病情稳定后补充；治疗过程、既往健康状况、家族史均属后续追问内容"},{"q":"最常见血钠降低的情况是","o":["大量应用利尿剂","原发性醛固酮增多症","大面积烧伤渗液","昏迷","肾上腺皮质功能亢进症"],"a":0,"e":"大量应用利尿剂（尤其噻嗪类）致肾性排钠增多，是低钠血症常见原因，常伴细胞外液减少。原发性醛固酮增多症、肾上腺皮质功能亢进因钠潴留多致血钠升高；大面积烧伤渗液可致低钠但不如利尿剂常见；昏迷本身非失钠原因"},{"q":"常见诊断失误的原因不包括","o":["主观臆断","病人欠配合","医学知识不足","病史资料不完整、不准确","体格检查不细致、不全面"],"a":2,"e":"官方答案为【医学知识不足】，但依据教材，正确答案为【病人欠配合】。教材明列医学知识不足、缺乏临床经验是构成误诊的常见原因，病史资料不完整不准确、体格检查不细致不全面及主观臆断亦属常见失误原因；病人欠配合未列入常见原因，原答案把知识不足排除在外站不住"},{"q":"舌头萎缩、舌体较小，舌面光滑呈粉红色或红色，见于","o":["慢性萎缩性胃炎","黏液性水肿","严重脱水","长期发热","维生素B2缺乏"],"a":0,"e":"舌萎缩、舌体小、舌面光滑呈粉红色或红色为镜面舌，见于巨幼红细胞性贫血、恶性贫血及慢性萎缩性胃炎，故慢性萎缩性胃炎符合。黏液性水肿舌体肥大伴齿痕；严重脱水舌干燥；长期发热舌有苔或干燥；维生素B2缺乏表现为牛肉舌或地图舌"},{"q":"由卧位或下蹲位到迅速站立时，可使下列何种疾病的杂音增强","o":["二尖瓣狭窄","特发性肥厚性主动脉瓣下狭窄","肺动脉瓣狭窄","主动脉瓣狭窄","三尖瓣狭窄"],"a":1,"e":"由卧位或下蹲位迅速站立时回心血量骤减，多数瓣膜病杂音减轻，而梗阻性肥厚型心肌病（特发性肥厚性主动脉瓣下狭窄）因左室容积缩小、流出道梗阻加重，杂音反而增强。二尖瓣狭窄、肺动脉瓣狭窄、主动脉瓣狭窄、三尖瓣狭窄杂音均随回心血量减少而减轻"},{"q":"S2出现的时间是","o":["与房室瓣关闭同时发生","与半月瓣开放同时发生","与半月瓣关闭同时发生","与心房收缩同时发生","在舒张晚期发生"],"a":2,"e":"第二心音主要由主动脉瓣、肺动脉瓣（半月瓣）突然关闭及血流突然减速引起瓣膜振动所致，与半月瓣关闭同时发生，标志心室舒张开始。房室瓣关闭产生S1；半月瓣开放与S1同时；心房收缩产生S4；舒张晚期出现的是S4而非S2"},{"q":"左锁骨上触及肿大坚硬的淋巴结，考虑为","o":["肺癌","消化道肿瘤","甲状腺癌","鼻咽癌","乳房癌"],"a":1,"e":"左锁骨上窝淋巴结肿大坚硬是腹腔恶性肿瘤尤其胃癌经胸导管转移的标志，故首先考虑消化道肿瘤。肺癌多转移至右锁骨上或纵隔；甲状腺癌多至颈部；鼻咽癌常见颈部转移；乳房癌多转移至同侧腋窝"},{"q":"关于慢性肾盂肾炎，哪项不正确","o":["可反复急性发作","可有高血压","可有低热","尿路刺激症状可不明显","肾小管功能正常"],"a":4,"e":"慢性肾盂肾炎主要累及肾小管与肾间质，早期即有肾小管浓缩功能减退、尿渗量降低，故肾小管功能正常错误。反复急性发作、高血压、低热、尿路刺激症状不明显均为其常见表现，病情隐匿者可以全身症状为主"},{"q":"关于乙型肝炎病毒的性状，哪项是错误的","o":["病毒核心为双股DNA，属于包膜病毒","HbsAg本身不具有传染性","血清中检测不到核心抗原","HbeAg阳性表明处于感染恢复期","HbeAg可刺激机体产生抗-HBe"],"a":3,"e":"HBeAg阳性表明乙肝处于活动期、病毒复制活跃且传染性强，而非恢复期；恢复期出现的是抗-HBe与抗-HBs。HBsAg本身无传染性仅为感染标志；HBcAg主要在肝细胞内，血清中检测不到；HBeAg可刺激产生抗-HBe；HBV核心为双股DNA，属包膜病毒"},{"q":"以下免疫球蛋白类型，在人体血清中含量最高的是","o":["IgM","IgA","IgE","IgG","IgD"],"a":3,"e":"IgG是血清含量最高、最主要的免疫球蛋白，占总免疫球蛋白70%～80%，属再次应答抗体，也是唯一通过胎盘的抗体。IgM含量较低，为初次应答抗体；IgA居第二，主存黏膜分泌液；IgE、IgD血清含量极低"},{"q":"下列各项均为腹内积气临床表现，但除外","o":["全腹膨隆","腹内呈球形","两侧腰部膨出不明显","移动体位其形状无明显改变","蛙腹"],"a":4,"e":"腹内积气使腹部呈球形膨隆，两侧腰部膨出不明显，移动体位形状无明显改变；蛙腹是腹腔积液平卧时液体下沉致腹部扁而宽的表现，属腹水而非积气。全腹膨隆、球形、腰部膨出不明显、体位改变形状不变均为腹内积气特点"},{"q":"如图，心电图诊断考虑","o":["右心房肥大","左心房肥大","右心室肥厚","左心室肥厚","左心房室增大"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就左心房肥大而言，其心电图表现为P波增宽≥0.12秒、双峰且峰距≥0.04秒，以Ⅰ、Ⅱ、aVL导联明显，常见于二尖瓣疾病。右房肥大叫肺型P波；心室肥厚以QRS电压增高为主；双心房肥大兼有增宽与振幅增高\n\n官方题库中缺失图片"},{"q":"非肝细胞合成，但肝实质细胞受损时，其生成可以增多的蛋白质是","o":["糖蛋白","脂蛋白","白蛋白","各种转运蛋白","球蛋白"],"a":4,"e":"球蛋白（尤γ球蛋白）由B淋巴细胞及浆细胞产生，非肝细胞合成；肝受损尤其慢性炎症时刺激单核吞噬细胞系统，γ球蛋白生成增多。白蛋白、各种转运蛋白由肝细胞合成，受损时减少；糖蛋白、脂蛋白多在肝合成，非受损后增多的主要蛋白"},{"q":"维生素C缺乏症（坏血病）导致皮肤黏膜出血的机制是","o":["毛细血管壁缺陷","小静脉管壁缺陷","血小板聚集功能异常","血小板释放功能异常","凝血因子合成异常"],"a":0,"e":"维生素C缺乏致胶原合成障碍，毛细血管壁脆性增加、不能正常收缩止血，引起皮肤黏膜出血，属血管壁缺陷，表现为牙龈出血、瘀点瘀斑。小静脉管壁缺陷非坏血病机制；血小板聚集或释放异常属血小板疾病；凝血因子合成异常见于肝病或维生素K缺乏"},{"q":"二尖瓣狭窄时心浊音界出现哪种改变","o":["靴形","梨形","普大型","三角形","第3肋间心左界向外扩大"],"a":1,"e":"二尖瓣狭窄致左房增大及肺动脉段扩张，胸骨左缘第2、3肋间心界增宽、心腰消失或膨出，心浊音界呈梨形。靴形为主动脉瓣关闭不全的左室增大表现；普大型见于扩张型心肌病；三角形（烧瓶样）见于心包积液；第3肋间心左界外扩亦可见于左房增大，但梨形最典型"},{"q":"患者突然高热、胸痛、咳嗽，呼吸困难，下列哪项有助于肺炎实变与胸腔积液的鉴别","o":["呼吸运动","气管位置","叩诊音","胸膜摩擦音","肺泡呼吸音"],"a":4,"e":"肺泡呼吸音及病理性呼吸音有助鉴别：肺实变时肺泡呼吸音减弱，但可闻响亮的病理性支气管呼吸音、语音共振增强；胸腔积液时肺泡呼吸音减弱或消失，语颤减弱，仅积液上方闻及较弱而遥远的支气管呼吸音。呼吸运动二者均减弱；胸膜摩擦音提示胸膜炎，非鉴别要点"},{"q":"咯血患者在咯血前常有下列症状，除了","o":["喉部痒感","胸闷","上腹部不适","咳嗽","焦虑"],"a":2,"e":"咯血前常有喉部痒感、胸闷、咳嗽及焦虑，血随咳嗽而出。上腹部不适伴恶心是呕血的前驱症状，提示上消化道出血，不属咯血；喉部痒感与咳嗽最具特征，胸闷、焦虑亦常见"},{"q":"下面哪一项不是浅反射检查内容","o":["角膜反射","腹壁反射","提睾反射","眼心反射","跖反射"],"a":3,"e":"浅反射刺激皮肤、黏膜或角膜，包括角膜反射、腹壁反射、提睾反射及跖反射。眼心反射通过压迫眼球观察脉率变化，属自主神经（迷走神经）功能检查，不属浅反射；其余四项均为浅反射项目"},{"q":"诊断急性阑尾炎的最重要依据是","o":["转移性右下腹痛","McBurney点压痛、反跳痛","加压左下腹部突然松手引起右下腹痛","腰大肌征阳性","直肠指检有局部触痛"],"a":1,"e":"急性阑尾炎早期腹痛可在上腹或脐周，数小时后固定于右下腹McBurney点，出现显著而持续的压痛与反跳痛，是诊断最重要依据。转移性右下腹痛虽典型但仅70%～80%出现且属症状；腰大肌征、直肠指检触痛及结肠充气试验均为辅助体征"},{"q":"MCV、MCH、MCHC均明显低于参考值下限的贫血是","o":["再生障碍性贫血","巨幼细胞贫血","缺铁性贫血","失血性贫血","急性失血"],"a":2,"e":"缺铁性贫血属小细胞低色素性贫血，MCV、MCH、MCHC均降低，RDW增高，红细胞体积小、中央淡染区扩大。巨幼细胞贫血为大细胞性，MCV增高；再生障碍性贫血及失血性贫血多为正常细胞性，三项指数一般正常"},{"q":"内生致热原是","o":["由中枢神经系统产生的能引起体温升高的内在介质","由产热器官产生的能引起体温升高的内在介质","由产热原细胞产生的能引起体温升高的神经激素","由产EP细胞在发热激活物的作用下，产生和释放的能引起体温升高的物质","由产EP细胞在磷酸激酶的作用下，产生和释放的能引起体温升高的物质"],"a":3,"e":"内生致热原由产EP细胞（单核巨噬细胞、中性粒细胞）在发热激活物作用下产生释放，如白介素-1、肿瘤坏死因子、干扰素，经血脑屏障升高调定点。中枢、产热器官并非产生部位；称神经激素或用磷酸激酶作激活物均属机制错误"},{"q":"医生发现患者右侧舌咽神经损伤，临床检查不可能发现以下哪项表现","o":["右侧咽反射迟钝","右侧软腭抬举减弱","腭垂偏向右侧","声音嘶哑","饮水呛咳"],"a":2,"e":"一侧舌咽神经（常伴迷走神经）损伤时该侧软腭上抬减弱，悬雍垂偏向健侧即左侧，而非右侧，故该项不可能。右侧咽反射迟钝、软腭抬举减弱、饮水呛咳均为延髓神经损害表现；声音嘶哑多见于迷走神经喉返支受累，可并存"},{"q":"剑突下异常搏动见于","o":["右心室肥大","左心室肥大","右位心","大量腹水","门静脉高压"],"a":0,"e":"剑突下搏动常见于肺源性心脏病右心室肥大，因右室增大使心搏动传至剑突下，深吸气后增强支持右室来源，腹主动脉瘤所致者反而减弱。左心室肥大搏动向左下移位；右位心搏动在右侧胸壁；大量腹水、门静脉高压不产生此搏动"},{"q":"脉压增大不可能出现的体征是","o":["De Musset征","Traube征","Duroziez征","Kussmaul征","点头征"],"a":3,"e":"脉压增大见于主动脉瓣关闭不全等，可出现点头征（De Musset征）、枪击音（Traube征）、股动脉双重杂音（Duroziez征）等周围血管征。Kussmaul征是缩窄性心包炎体征，吸气时颈静脉更怒张，与脉压增大无关"},{"q":"下列关于Kernig征检查的描述，哪项错误","o":["仰卧位","一侧髋关节屈成直角","抬高小腿","正常可将膝关节伸达150°以上","阳性为伸膝受限伴疼痛"],"a":3,"e":"Kernig征检查时病人仰卧，一侧髋膝屈成直角，检查者抬高小腿伸膝；正常人可伸达135°以上，伸膝受限伴疼痛与屈肌痉挛为阳性，故伸达150°以上错误。仰卧、髋膝屈直角、抬高小腿及阳性判定均符合方法"},{"q":"肺泡呼吸音减弱可见于下列情况，除了","o":["重症肌无力","大量腹水","胸膜肥厚","重症哮喘","酸中毒"],"a":4,"e":"酸中毒时血酸度增高刺激呼吸中枢，呼吸深快，肺泡呼吸音增强而非减弱，故为除外项。重症肌无力致呼吸肌无力、大量腹水使膈肌抬高、胸膜肥厚阻碍传导、重症哮喘致呼气受限，均使肺泡呼吸音减弱；发热贫血及一侧病变时健侧代偿亦增强"},{"q":"人体最重要的散热途径是","o":["肺","皮肤","小便","粪便","肌肉"],"a":1,"e":"皮肤是人体最主要散热器官，通过辐射、传导、对流及蒸发散发绝大部分热量，血管收缩或广泛病变可致散热减少而发热。肺呼吸散热有限；小便、粪便散热量小；肌肉为产热器官而非散热途径，运动产热主要经皮肤散出"},{"q":"结合胆红素进入胆道后还原为尿胆原，在肠内被吸收入肝的比例是","o":["1%～5%","5%～10%","10%～15%","10%～20%","25%～30%"],"a":3,"e":"结合胆红素入肠道经细菌还原为尿胆原，大部分随粪便排出，约10%～20%被肠道重吸收，经门静脉回肝再转为结合胆红素排入肠内，构成肠肝循环。1%～5%、5%～10%比例过低；10%～15%偏窄；25%～30%过高"},{"q":"右肺肺活量占全肺肺活量的百分数为","o":["55%","50%","45%","60%","40%"],"a":0,"e":"右肺肺活量约占全肺55%，左肺约45%，与右肺容积较大（三叶）有关；肺活量为尽力吸气后缓慢完全呼出的最大气量。50%为左右均等不符解剖；45%为左肺占比；60%、40%均偏离正常比例"},{"q":"心电图ST段下移呈鱼钩形改变应考虑","o":["低血钾","低血钙","洋地黄作用","高钾血症","心肌梗死"],"a":2,"e":"洋地黄效应使动作电位2位相缩短，表现为ST段下垂型压低、T波低平双向或倒置，ST-T呈鱼钩型，伴QT缩短，是洋地黄治疗标志。低血钾致T波低平、U波增高；低血钙致ST延长、QT延长；高血钾致T波高尖；心梗呈弓背向上抬高及异常Q波"},{"q":"临床表现为体温骤降，常见于","o":["败血症","风湿热","结缔组织病","伤寒","霍奇金病"],"a":4,"e":"霍奇金淋巴瘤可表现为回归热，体温骤升至39℃以上、持续数天后骤降正常，高热期与无热期规律交替。败血症多为弛张热或不规则热；风湿热、结缔组织病多不规则发热；伤寒为稽留热，体温维持高位而非骤降"},{"q":"关于腹腔积液的描述，下列各项均正确，但除外","o":["平卧时腹型呈扁而宽状","侧卧时下腹部膨出","脐部突出","可见尖腹","常见腹壁静脉曲张"],"a":4,"e":"大量腹腔积液时平卧腹型扁而宽、侧卧下腹膨出、脐可突出，伴腹膜炎症或肿瘤浸润时可见尖腹。腹壁静脉曲张是门静脉高压或腔静脉回流受阻致侧支循环形成的表现，并非腹水本身常见体征；其余四项均符合腹水腹部外形改变"},{"q":"特异性酯酶染色呈强阳性反应，见于","o":["晚期的原始细胞","嗜酸性粒细胞","淋巴细胞","早幼粒细胞","单核细胞"],"a":3,"e":"氯乙酸AS-D萘酚酯酶（特异性酯酶）主要存于粒系，自早幼粒至成熟中性粒细胞阳性，早幼粒呈强阳性，活性随成熟渐减弱。晚期原始细胞阴性或弱阳性；嗜酸性粒细胞、淋巴细胞、单核细胞均阴性，故早幼粒细胞正确"},{"q":"下列各项均为编写病历的基本要求，但除外","o":["内容要客观、真实","格式要规范","应选用通俗易懂的用词","填写要全面","字迹要清楚"],"a":2,"e":"病历书写要求客观真实、格式规范、填写全面、字迹清楚并使用规范医学术语。通俗易懂是对问诊时与病人交谈的语言要求，而非病历书写基本规范；客观真实、格式规范、填写全面、字迹清楚均为基本要求"},{"q":"急性腹膜炎的患者腹部检查的腹膜炎三联征是","o":["腹式呼吸减弱，腹肌紧张和压痛","腹式呼吸增强，腹肌紧张和压痛","腹肌紧张、压痛和反跳痛","腹部膨胀、腹肌紧张和反跳痛","肝浊音上界消失，腹肌紧张和压痛"],"a":2,"e":"急性腹膜炎典型三联征为腹肌紧张、压痛和反跳痛，局限性者局限于病变部位，弥漫者伴腹式呼吸减弱或消失。腹式呼吸减弱虽可见于弥漫性腹膜炎但非三联征；腹式呼吸增强错误；腹部膨胀、肝浊音界消失为伴随表现"},{"q":"深吸气后，可使下列何种疾病的杂音增强","o":["二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣关闭不全","主动脉瓣关闭不全","主动脉瓣狭窄"],"a":2,"e":"深吸气时胸腔负压增大，回心血量及右室排血量增加，使右心相关杂音增强，肺动脉瓣关闭不全杂音随之增强。二尖瓣狭窄、二尖瓣关闭不全、主动脉瓣关闭不全、主动脉瓣狭窄均为左心杂音，深吸气多减轻或不变，深呼气后更清楚"},{"q":"出血时间和凝血时间均延长的疾病是","o":["血小板减少性紫癜","过敏性紫癜","血友病甲、乙、丙","纤维蛋白缺乏症","弥散性血管内凝血"],"a":4,"e":"DIC时血小板大量消耗且凝血因子（纤维蛋白原、Ⅱ、Ⅴ、Ⅷ等）被消耗，故出血时间与凝血时间均延长。血小板减少性紫癜仅出血时间延长而凝血时间正常；血友病仅凝血时间延长；过敏性紫癜为血管壁缺陷二者多正常；纤维蛋白缺乏主要影响凝血"},{"q":"不可能引起颈椎活动受限的疾病是","o":["颈肌纤维组织炎","强直性脊柱炎","颈椎病","先天性斜颈","颈椎结核"],"a":3,"e":"先天性斜颈因胸锁乳突肌挛缩致头偏向一侧、病侧肌肉隆起，属肌源性姿势异常，颈椎活动度一般不受限。颈肌纤维组织炎因疼痛受限；强直性脊柱炎致颈椎强直；颈椎病、颈椎结核直接累及颈椎致活动受限"},{"q":"哪种疾病的气管位置居中","o":["肺实变","肺不张","胸腔积液","胸膜肥厚","气胸"],"a":0,"e":"肺实变不伴明显胸腔容积或压力改变，气管位置居中；肺不张及胸膜肥厚牵拉使气管移向患侧，胸腔积液与气胸推挤使气管移向健侧。肺不张、胸膜肥厚移向病侧，胸腔积液、气胸移向健侧，均不居中"},{"q":"过氧化物酶染色呈强阳性反应的疾病是","o":["急性淋巴细胞白血病","急性粒细胞白血病","急性单核细胞白血病","急性红白血病","慢性淋巴细胞白血病"],"a":1,"e":"过氧化物酶染色主要用于急性白血病类型鉴别，急性粒细胞白血病原始细胞多呈阳性乃至强阳性，因粒系细胞富含该酶。急性单核细胞白血病仅呈弱阳性或阴性，急性淋巴细胞白血病则完全阴性，两者常与急粒混淆；急性红白血病以幼红细胞增生为主，该染色并非其鉴别要点"},{"q":"下列疾病中不会发生中心型发绀的是","o":["Eisenmenger综合征","慢性阻塞性肺病","原发性肺动脉高压","右心衰竭","大量胸腔积液"],"a":3,"e":"中心型发绀源于动脉血氧饱和度降低，见于肺换气障碍或右向左分流。Eisenmenger综合征、原发性肺动脉高压均因肺血管阻力增高出现右向左分流，大量胸腔积液压迫肺组织致换气不足，故都属中心型。右心衰竭以体循环淤血为主，动脉血氧合本身正常，表现为肢体末端发绀，属周围型而非中心型"},{"q":"TDTH细胞的特征是","o":["CD8＋Tc细胞","CD4＋Th1细胞","CD8＋Ts细胞","CD4＋Th2细胞","CD3＋Th2细胞"],"a":1,"e":"TDTH即迟发型超敏反应T细胞，为CD4＋Th1亚群，通过分泌IL-2、IFN-γ等Th1型细胞因子介导细胞免疫。CD8＋Tc为细胞毒性T细胞，主司直接杀伤；CD4＋Th2分泌IL-4、IL-6参与体液免疫并拮抗Th1；CD8＋Ts为抑制性T细胞，三者均非TDTH"},{"q":"抬举性心尖冲动见于","o":["腹主动脉瘤","肺心病右心室肥大","升主动脉瘤或主动脉弓瘤","Broadbent征","高血压左心室肥大"],"a":4,"e":"抬举性心尖冲动指心尖区徐缓有力、可使指尖抬起并持续至第二心音的搏动，是左心室肥厚的可靠体征，高血压心脏病长期压力负荷致左室肥厚时最典型。高血压左室肥大位于心尖区；肺心病右心室肥大的抬举性搏动在胸骨左下缘或剑突下，非心尖区；升主动脉瘤搏动位于胸骨右缘第2肋间"},{"q":"下列哪种不属于正常细胞性贫血","o":["再生障碍性贫血","急性失血性贫血","溶血性贫血","地中海贫血","白血病所致贫血"],"a":3,"e":"贫血按MCV、MCH、MCHC分为大细胞性、正常细胞性与小细胞低色素性。再生障碍性贫血、急性失血性贫血、白血病所致贫血均属正常细胞性。地中海贫血因珠蛋白合成障碍致血红蛋白减少，呈小细胞低色素性，故不属于正常细胞性贫血；溶血性贫血多为正常细胞性"},{"q":"免疫球蛋白的同种型抗原决定簇位于","o":["C区","V区","超变区","C区和V区","C区和超变区"],"a":0,"e":"同种型抗原决定簇为同一种属所有个体免疫球蛋白共有的抗原标志，位于恒定区（C区），重链与轻链C区均可决定其类别与亚类。V区及超变区属可变区，承载独特型和互补决定簇，与抗原特异性结合相关；同种异型决定簇亦在C区，但仅见于部分个体，需与之区分"},{"q":"细胞圆形，直径13～15mm，核常分叶呈眼镜形，浆内充满均匀橘红色颗粒，为何种细胞的特点","o":["N（中性粒细胞）","E（嗜酸性粒细胞）","B（嗜碱性粒细胞）","L（淋巴细胞）","M（单核细胞）"],"a":1,"e":"嗜酸性粒细胞胞体圆形，直径13～15μm，胞质充满粗大均匀紧密排列的橘红色嗜酸性颗粒，核常分两叶呈眼镜状，符合题干描述。中性粒细胞颗粒细小呈淡紫红色、核分3～5叶；嗜碱性粒细胞颗粒深紫黑且遮盖核；淋巴细胞与单核细胞均无特异性颗粒"},{"q":"下列关于第一心音（S1）叙述正确的是","o":["声音较清脆，历时较短","与心尖冲动同时出现","心底部听诊最清楚","半月瓣关闭引起的振动","房室瓣开放引起的振动"],"a":1,"e":"第一心音由二尖瓣、三尖瓣关闭产生，音调较低钝、强度较响、历时约0.1秒，与心尖冲动同步，在心尖部最响。声音清脆历时短、心底部最响及半月瓣关闭所致者均为第二心音；房室瓣开放参与第二心音形成而非第一心音，故其余描述皆归S2"},{"q":"变异型心绞痛的心电图表现为","o":["相关导联ST段呈弓背向上型抬高，变化迅速，出现病理性Q波","普通导联ST段呈凹面向上型太高（aVR、V1导联除外），不出现病理性Q波","ST段呈凹面向上型抬高，主要为J点抬高，多见于胸导联，不出现病理性Q波","相关导联ST段呈弓背向上型抬高，持续达数个月，有病理性Q波","相关导联一过性ST段抬高，对应导联ST段下移，变化迅速"],"a":4,"e":"变异型心绞痛主要由冠状动脉痉挛所致，发作时相关导联ST段一过性弓背向上抬高，伴高耸T波及对应导联ST段下移，症状缓解后迅速恢复，不出现病理性Q波。弓背向上抬高持续并出现病理性Q波提示急性心肌梗死；凹面向上型抬高、J点抬高为急性心包炎或早期复极表现"},{"q":"诊断贫血最可靠的指标是","o":["外周血红细胞数","血细胞比容","皮肤颜色改变","外周血血红蛋白浓度","红细胞平均血红蛋白含量"],"a":3,"e":"贫血指外周血血红蛋白浓度低于同年龄同性別参考下限，它直接反映血液携氧能力，是诊断最可靠指标。红细胞数受血浆容量影响，单凭计数易误判；血细胞比容受红细胞体积左右；皮肤颜色受肤色与毛细血管状态干扰；红细胞平均血红蛋白含量仅用于形态学分类"},{"q":"关于病历书写及修改，正确的是","o":["实习期及试用期医务人员不能书写病历","实习期及试用期医务人员可以书写病历，但需要本医疗机构合法执业的医务人员审核修改并签名","修改病历应该在48h内完成，上级医师审核签名在左侧，并以斜线隔开","进修医生不能在接收其进修的医疗机构书写病历","病历书写过程中出现错字错句，应当用涂改液抹去，然后在原处继续书写，签名及注明修改日期"],"a":1,"e":"实习期、试用期医务人员可以书写病历，但须经本医疗机构具有执业资格的上级医务人员审阅、修改并签名方可生效。进修及规培人员经接收机构认定后书写，同样需上级审核，故'进修医生不能书写'错误。修改错字应划双线并签名注明日期，不得用涂改液抹去；上级审核签名及修改时限亦非48小时"},{"q":"腱鞘滑膜炎最常见于","o":["强直性脊柱炎","风湿性关节炎","老年性骨关节炎","类风湿性关节炎","内生软骨瘤"],"a":3,"e":"腱鞘滑膜炎是类风湿关节炎的常见表现，其本质为滑膜的慢性增生性炎症，累及腱鞘可致肿胀与功能障碍，伴对称性小关节疼痛及晨僵。风湿性关节炎以游走性大关节痛为主，不累及腱鞘滑膜；老年性骨关节炎为退行性变，无滑膜炎性增生；强直性脊柱炎主要侵犯骶髂关节；内生软骨瘤为骨肿瘤"},{"q":"急性左心衰竭患者多采用的体位是","o":["被动体位","强迫坐位","强迫站立位","强迫仰卧位","强迫侧卧位"],"a":1,"e":"急性左心衰竭肺淤血严重，病人被迫端坐，即强迫坐位（端坐呼吸），可使膈肌下降、肺通气量增加，并减少回心血量以减轻心脏负荷。被动体位见于意识丧失或极度虚弱者；强迫仰卧位多见于急性腹膜炎；强迫侧卧位见于一侧胸膜炎或大量胸腔积液；强迫站立位并非本病体位"},{"q":"蜘蛛痣常见的部位不包括","o":["面颈部","肩部","胸部","腹部","手背"],"a":3,"e":"蜘蛛痣由雌激素水平升高致皮肤小动脉末端分支扩张形成，多分布在上腔静脉引流区域，如面颈部、胸部、肩部及手背。腹部属下腔静脉引流区，不是蜘蛛痣的常见部位。面颈、胸、肩及手背均在上腔静脉分布范围内，肝硬化时这些部位蜘蛛痣尤为多见"},{"q":"诊断尿路感染的最重要依据是","o":["有尿频、尿急、尿痛症状","腰痛和肾区叩击痛","有真性细菌尿","有白细胞尿","有蛋白尿"],"a":2,"e":"尿路感染确诊依据是真性细菌尿，即清洁中段尿培养出有意义菌量的细菌，可排除污染。尿频尿急尿痛仅为膀胱刺激症状，亦见于无菌性尿频；腰痛与肾区叩击痛提示上尿路受累但不特异；白细胞尿可由结核、结石引起；蛋白尿更非感染所独有"},{"q":"下列有关低血压的叙述正确的是","o":["指血压＜90/70mmHg","常伴有脉压减小","为血管紧张度降低所致","主要见于严重贫血","可见于多发性大动脉炎"],"a":1,"e":"低血压指收缩压与舒张压均低于正常下限，因心输出量减少或外周阻力改变，常伴脉压减小。成人低血压界定为收缩压低于90mmHg、舒张压低于60mmHg，而非90/70mmHg；其成因并非单纯血管紧张度降低；严重贫血只是诱因之一；多发性大动脉炎多致上肢血压不对称或高血压"},{"q":"强直性脊柱炎病变特点不包括","o":["青壮年男性多见","常累及骶髂关节","胸椎常后凸畸形","病变常下行性进展","仰卧位脊柱不能伸直"],"a":3,"e":"强直性脊柱炎起病于骶髂关节，病变沿脊柱自下而上逐渐上行性发展，最终致脊柱强直固定，故'下行性进展'不符合。本病青壮年男性多见，常累及骶髂关节；胸椎受累呈弧形后凸畸形；脊柱强直后仰卧位亦不能伸直，均为典型表现"},{"q":"交替脉常见于","o":["心包积液","肺源性心脏病","左心衰竭","休克","伤寒"],"a":2,"e":"交替脉指脉搏节律规则而强弱交替出现，因心室收缩力强弱交替所致，是左心衰竭的重要体征。心包积液常见奇脉而非交替脉；肺源性心脏病以体循环淤血体征为主；休克表现为脉搏细速无力；伤寒常见相对缓脉，均不以交替脉为特征"},{"q":"气管与食管的感觉是通过（ ）传入的","o":["三叉神经","面神经","交感神经","迷走神经","听神经"],"a":3,"e":"气管、支气管与食管的感觉冲动主要经迷走神经传入，故气道刺激引起的咳嗽等反射由迷走神经介导。三叉神经司面部感觉；面神经主管面部表情肌运动；交感神经支配主动脉等处的痛觉纤维，主要传导胸痛；听神经司听觉与平衡，均不承担气管食管感觉传入"},{"q":"剑突下心尖冲动见于","o":["肺心病右室肥大","升主动脉瘤或主动脉弓瘤","Broadbent征","高血压左室肥大","扩张型心肌病"],"a":0,"e":"剑突下搏动多为右心室肥大所致，肺心病右室增大时心脏顺时针转位，右室搏动可出现于剑突下，深吸气后增强可佐证。腹主动脉瘤或升主动脉瘤搏动位于上腹部或胸骨右缘，深吸气减弱；Broadbent征为心包粘连的体征；高血压左室肥大搏动在心尖区；扩张型心肌病以心界扩大为主"},{"q":"最常出现惊厥伴瞳孔扩大与舌咬伤的疾病是","o":["癫痫大发作","癔症发作","低钙性抽搐","一氧化碳中毒","结核性脑膜炎"],"a":0,"e":"癫痫大发作时突然意识丧失、全身强直后阵挛性抽搐，常伴瞳孔扩大、舌咬伤及大小便失禁，故最具此组合特征。癔症发作意识多不真正丧失、无舌咬伤；低钙性抽搐为腕足痉挛、神志清楚；一氧化碳中毒有接触史；结核性脑膜炎以脑膜刺激征为主"},{"q":"最容易引起重叠性奔马律的疾病是","o":["心功能不全伴心动过速","心功能不全伴正常心率","心功能不全伴二度房室传导阻滞","二度房室传导阻滞","完全性左束支传导阻滞"],"a":0,"e":"重叠性奔马律由舒张早期与晚期奔马律重叠而成，当心功能不全且心率增快、舒张期缩短时两者融合，故最多见于心功能不全伴心动过速。心率正常时两种奔马律分开出现；二度房室传导阻滞及完全性左束支阻滞主要改变心律或QRS形态，并非重叠性奔马律的成因"},{"q":"以下哪项不是共济运动相关检查","o":["指鼻试验","跟膝胫试验","闭目难立征","快速轮替试验","凯尔尼格征"],"a":4,"e":"共济运动由小脑协调，检查包括指鼻试验、跟膝胫试验、快速轮替试验及闭目难立征，用以评估肢体协调与平衡。凯尔尼格征属脑膜刺激征，通过被动伸膝引发疼痛反应判断脑膜受累，与小脑共济功能无关，故不属于共济运动检查"},{"q":"二尖瓣狭窄时最能提示肺动脉高压的体征是","o":["开瓣音响亮","心尖部第一心音增强","心界向两侧扩大","心尖部舒张期杂音","肺动脉瓣第二心音亢进、分裂"],"a":4,"e":"二尖瓣狭窄致左房压升高、肺淤血，继而肺动脉压力增高，使肺动脉瓣关闭延后且有力，听诊肺动脉瓣区第二心音亢进并分裂，是提示肺动脉高压的可靠体征。开瓣音与心尖部第一心音增强反映瓣叶活动度好；心界扩大、心尖部舒张期杂音均为二尖瓣狭窄本身表现，不特异提示肺动脉高压"},{"q":"与JAK2基因突变相关最密切的是","o":["真性红细胞增多症","原发性血小板增多症","原发性骨髓纤维化","慢性髓细胞白血病","系统性肥大细胞增多症"],"a":0,"e":"JAK2 V617F突变常见于骨髓增殖性肿瘤，以真性红细胞增多症检出率最高、关系最密切，导致红细胞生成素非依赖性红细胞增生。原发性血小板增多症与骨髓纤维化也可检出该突变但阳性率较低；慢性髓细胞白血病以BCR-ABL融合基因为特征；系统性肥大细胞增多症多见KIT突变"},{"q":"下述哪项描述最符合急性肺水肿的肺部查体所见","o":["两肺底细小水泡音","两肺底捻发音","两肺野布满湿啰音","两肺野布满干啰音","一侧肺底湿啰音"],"a":2,"e":"急性肺水肿时肺毛细血管压急剧升高，液体大量渗入肺泡与间质，双肺满布湿啰音并可伴哮鸣音。两肺底细小湿啰音或捻发音多见于心力衰竭肺淤血早期；局限性一侧肺底湿啰音提示局部病变如肺炎；干啰音为主见于气道痉挛，均不符合急性肺水肿的典型体征"},{"q":"结合胆红素增高为主的黄疸产生的机制主要是","o":["胆红素排泄障碍","胆红素结合障碍","胆红素摄取障碍","胆红素来源过多","胆红素肾脏排泄障碍"],"a":0,"e":"以结合胆红素增高为主的黄疸多因肝细胞排泄结合胆红素障碍或胆道阻塞，使已结合的胆红素反流入血，如Dubin-Johnson综合征及胆道梗阻。胆红素摄取或结合障碍导致非结合胆红素升高，如Gilbert综合征；来源过多见于溶血，以非结合胆红素增高为主；肾脏并非胆红素排泄主要途径"},{"q":"血浆碱剩余（BE）的正常值约为","o":["0±3mmol/L","－1±3mmol/L","5mmol/L","10mmol/L","15mmol/L"],"a":0,"e":"碱剩余（BE）是在标准条件下测得的反映代谢性因素的血气指标，正常约为0±3mmol/L，正值为代谢性碱中毒，负值为代谢性酸中毒。选项5mmol/L、10mmol/L、15mmol/L均为明显偏高，提示代谢性碱中毒；-1±3mmol/L偏离以零为中心的参考范围，非通用正常值"},{"q":"晕厥的临床表现不包括","o":["短暂的意识丧失","由一过性广泛的脑供血不足所致","突然发作，迅速恢复","发作时四肢肌张力消失而倒地","可以表现为持续的昏迷"],"a":4,"e":"晕厥是一过性广泛脑供血不足所致的短暂意识丧失，突然发作、迅速恢复，发作时肌张力消失可致跌倒，但意识障碍历时短暂。持续昏迷属严重而持久的意识障碍，不符合晕厥自限性特点。短暂意识丧失、突然发作迅速恢复及肌张力消失倒地均为晕厥的典型表现"},{"q":"肠鸣音消失，常见于","o":["麻痹性肠梗阻","急性腹膜炎早期","急性胃肠炎","习惯性便秘","上消化道出血"],"a":0,"e":"持续听诊3～5分钟未闻肠鸣音，经叩击、搔弹腹部仍无者称肠鸣音消失，提示肠蠕动极度减弱，见于麻痹性肠梗阻及急性弥漫性腹膜炎。急性腹膜炎早期肠鸣音多减弱而非消失；急性胃肠炎肠鸣音亢进；习惯性便秘与上消化道出血均无肠鸣音消失的特征"},{"q":"关于心源性水肿体征，错误的是","o":["首先出现在身体下垂部","严重时出现胸腔积液、腹水","肺水肿","可有肝大","颈静脉怒张"],"a":2,"e":"水肿指组织间隙液体积聚，心源性水肿为体循环淤血所致的凹陷性水肿，首先出现于下垂部位，严重者可有胸腔积液、腹水及肝大、颈静脉怒张。肺水肿是肺间质与肺泡内液体积聚，属脏器局部水肿，一般不纳入'水肿'这一体征范畴，故不属于心源性水肿体征"},{"q":"用于评价大气道功能状态的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":2,"e":"最大呼气流量（PEF）为用力呼气时最快瞬间流速，主要反映呼吸肌力量及大气道有无阻塞，是评价大气道功能的指标，其昼夜变异率对哮喘诊断有意义。FEV1/FVC与FEV1%pred反映通气阻塞程度；MEF50及FEF50等反映小气道功能，非大气道指标"},{"q":"大量咯血是指每日咯血量为","o":["200ml以上","300ml以上","400ml以上","500ml以上","600ml以上"],"a":3,"e":"咯血量分级以每日计，100ml以内为小量，100～500ml为中等量，500ml以上或一次咯血100～500ml为大量咯血，常见于空洞型肺结核、支气管扩张与慢性肺脓肿。200ml、300ml、400ml均落在中等量区间；600ml虽属大量，但划分界限以500ml为准"},{"q":"用于评价限制性通气功能障碍指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":3,"e":"限制性通气功能障碍以肺容量减少为主，用力肺活量（FVC）或肺活量下降，FEV1/FVC正常或增高，故FVC是评价限制性的主要指标。FEV1/FVC降低是阻塞性通气障碍的特征；PEF反映大气道通畅度；MEF50为小气道指标；FEV1%pred多用于判断阻塞程度与分级"},{"q":"关于外源性致热原种类的描述，错误的是","o":["包括细菌及细菌毒素","炎性渗出物","无菌性坏死组织","抗原抗体复合物","肿瘤坏死因子"],"a":4,"e":"外源性致热原包括细菌及其毒素、炎性渗出物、无菌性坏死组织及抗原抗体复合物等，通过激活内源性致热原发挥致热作用。肿瘤坏死因子（TNF）与白介素-1、干扰素同属内源性致热原，由机体免疫细胞产生，可直接作用于体温调节中枢，故不属于外源性致热原"},{"q":"下列均为正常肾脏查体所具有的特征，但除外","o":["表面光滑","无压痛","可触到切迹","随呼吸上下移动","肾前方叩诊呈实音"],"a":2,"e":"正常肾脏表面光滑、无压痛，随呼吸上下移动，位置较深一般不易触及。可触到切迹是脾脏的形态特征，用于脾大与肾或腹腔肿块的鉴别，正常肾脏无切迹，故为除外项。肾前方叩诊因肠管覆盖多呈鼓音；表面光滑、无压痛、随呼吸移动均符合正常肾脏查体特点"},{"q":"正常人平卧时，颈外静脉在锁骨下缘和下颌角的充盈水平是","o":["下2/3以内","下1/2以内","下1/3以内","上1/3以内","不显露"],"a":0,"e":"正常人立位或坐位时颈外静脉不显露，平卧时可稍充盈，其水平限于锁骨上缘至下颌角连线的下2/3以内。若坐位或半卧位颈静脉明显充盈、怒张或搏动，提示颈静脉压升高，见于右心衰竭、缩窄性心包炎、心包积液及上腔静脉阻塞综合征，不属生理范围"},{"q":"网织红细胞减少的贫血是","o":["再生障碍性贫血","巨幼细胞贫血","缺铁性贫血","急性失血性贫血","急性溶血性贫血"],"a":0,"e":"网织红细胞反映骨髓红系造血活跃程度，减少表示骨髓造血功能减低，见于再生障碍性贫血及纯红细胞再生障碍性贫血。急性失血与急性溶血时骨髓代偿性增生，网织红细胞明显升高；缺铁性贫血治疗前可正常或轻度变化，巨幼细胞贫血亦非以网织红细胞减少为主要特点"},{"q":"当医生用手触诊患者腹部时，出现压痛后，手指压于疼痛部位稍停片刻，使压痛感觉趋于稳定，然后迅速将手抬起，如此时患者感觉腹痛骤然加重，并伴有痛苦表情或呻吟，称为反跳痛，这一体征表示的意义是","o":["脏器的炎症已累及腹膜的脏层","脏器的炎症已累及腹膜的壁层","脏器的炎症已发生穿破","脏器的炎症已波及邻近脏器","脏器的炎症已波及大网膜"],"a":1,"e":"反跳痛是触诊腹部出现压痛后，手指稍停片刻再迅速抬起，患者腹痛骤然加重并伴痛苦表情，提示炎症已累及腹膜壁层。仅脏层腹膜受累时痛觉不敏感，一般不出现反跳痛；炎症穿破或波及邻近脏器、大网膜属于病变进展阶段，反跳痛本身只标志壁层腹膜受刺激"},{"q":"以下哪项心电图特征不可能出现在仅有左房增大的患者","o":["P波振幅4mm","P波时限0.16s","P波双向","P波切迹","V1导P波负向部分大于0.04s"],"a":0,"e":"左房增大心电图表现为P波时限延长超过0.12秒、双峰切迹及V1导联P波终末负向部分增宽加深。P波振幅多在正常范围，振幅4mm明显增高属右房肥大表现，因右房除极向量增大所致，故不可能仅见于单纯左房增大。P波双向、切迹及V1负向增宽均为左房增大的典型改变"},{"q":"脉压增大可见于哪种疾病","o":["主动脉瓣关闭不全","主动脉瓣狭窄","心包积液","严重左心衰竭","全心衰竭"],"a":0,"e":"脉压为收缩压与舒张压之差，主动脉瓣关闭不全时舒张期血液反流使舒张压显著降低，收缩压因每搏量增大而升高，致脉压增大，并可出现周围血管征。主动脉瓣狭窄、心包积液及严重左心衰竭、全心衰竭均使每搏量减少或充盈受限，收缩压下降或舒张压升高，脉压反而减小"},{"q":"关于右室肥大的心电图表现，下列哪个描述是错误的","o":["V1导联R/S≤1，呈r型或rS型","V5导联R/S≤1或S波比正常加深","aVR导联以R波为主R/q或R/S≥1","RV1＋SV5＞1、05mV（重度＞1.20mV）","心电轴右偏≥＋90°（重度可大于110°）"],"a":0,"e":"右心室肥厚时右室除极向量增大，V1导联R/S≥1、呈R型或Rs型，重度可呈qR型，V5导联R/S≤1或S波加深，伴电轴右偏≥+90°及RV1+SV5>1.05mV。V1导联R/S≤1呈rS型为正常或左室占优势的表现，恰与右室肥大相反，故该项错误"},{"q":"不符合心房扑动诊断条件的是","o":["QRS波群时限增宽","可见F波","心房率250～350次/min","无等电位线","P波消失"],"a":0,"e":"心房扑动心电图特点为P波消失、代之以锯齿状F波，心房率250～350次/min，F波在Ⅱ、Ⅲ、aVF最清晰，因房室传导比例固定，QRS波群时限通常正常。QRS波群时限增宽提示室内传导阻滞、预激或室性心律，并非房扑诊断条件；F波、P波消失及无等电位线均符合房扑"},{"q":"鉴别中度昏迷与深昏迷最有价值的要点是","o":["各种刺激无反应","不能唤醒","无自主运动","深浅反射均消失","大小便失禁"],"a":3,"e":"深昏迷时意识完全丧失，全身肌肉松弛，对任何强刺激均无反应，深、浅反射均消失，生命体征可有改变；中度昏迷对强烈疼痛刺激尚可有防御反应，角膜反射、瞳孔对光反射等仍存在。各种刺激无反应、不能唤醒及无自主运动在中、深昏迷均可出现，不能据此区分"},{"q":"关于血压叙述正确的是","o":["测量时被测上肢裸露，肘部高于心脏水平","测量前30min禁烟和咖啡等","测量时声音突然变小而低沉为舒张压","正常人两上肢血压略有差异，可相差15～20mmHg","测量时为操作方便，应将听诊器体件塞于袖带内"],"a":1,"e":"测血压前受检者应至少安静休息5分钟，半小时内禁烟、禁咖啡并排空膀胱，以避免交感兴奋影响读数。测量时上肢应裸露、肘部与心脏同一水平，过高会使读数偏低；听诊以变音为收缩压、音消失为舒张压需区分；两上肢血压差异一般不超过5～10mmHg；听诊器体件不得塞入袖带"},{"q":"hCG尿液检测最好收集","o":["晨尿","清洁中段尿","全天尿液","尿道口拭子","血液"],"a":0,"e":"晨尿在膀胱内停留时间最长，hCG浓度最高，是尿液妊娠试验的最佳标本，可提高检出率。清洁中段尿多用于尿培养以避开污染；全天尿液不便于常规检测；尿道口拭子用于病原体采样；血液hCG虽更灵敏定量，但题干限定尿液检测，故选晨尿"},{"q":"下列缓冲对中哪一对缓冲能力最强","o":["[HPO42－]/[H2PO4－]为2mol/L、0.5mol/L","[HPO42－]/[H2PO4－]为1.6mol/L、0.4mol/L","[HPO42－]/[H2PO4－]为1.2mol/L、0.3mol/L","[HPO42－]/[H2PO4－]为1.0mol/L、0.25mol/L","[HPO42－]/[H2PO4－]为2.4mol/L、0.6mol/L"],"a":4,"e":"缓冲对缓冲能力取决于总浓度及共轭酸碱比值，比值越接近1、总浓度越高，缓冲容量越大。各选项[HPO42-]与[H2PO4-]比值均为4∶1，缓冲比相同，此时总浓度最高者缓冲能力最强。E项总量达3.0mol/L为最高，故缓冲能力最强；其余各项总浓度依次降低，缓冲容量较小"},{"q":"大叶性肺炎实变期肺部体征不正确的是","o":["语音震颤增强","叩诊呈浊音","可听到管样呼吸音","可听到哮鸣音","可听到胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变期肺组织含气减少、质地致密，语音震颤增强，叩诊呈浊音，可闻及支气管呼吸音即管样呼吸音，累及胸膜时可有胸膜摩擦音。哮鸣音是气道狭窄或部分阻塞形成的干啰音，多见于哮喘、慢性阻塞性肺疾病，并非肺实变的体征，故不正确"},{"q":"前列腺增生手术后尿失禁与下列哪项因素无关","o":["括约肌损伤","不稳定膀胱","膀胱出口梗阻","后尿道损伤刺激及创面感染","膀胱尿道角度改变"],"a":4,"e":"男性控尿依靠近端与远端两组尿道括约肌，前列腺增生手术损伤近端括约肌，若远端括约肌完好仍可控制排尿；不稳定膀胱、后尿道损伤刺激与创面感染、膀胱出口梗阻均可导致术后尿失禁。膀胱尿道角度改变并非该函数障碍的机制，与术后尿失禁无关"},{"q":"血小板膜糖蛋白GPⅠb与下列哪种血小板功能有关","o":["黏附功能","分泌功能","聚集功能","止血功能","血块收缩功能"],"a":0,"e":"血小板膜糖蛋白GPⅠb/Ⅴ/Ⅸ复合物通过vWF与内皮下胶原结合，介导血小板黏附于受损血管壁，是黏附功能的关键分子，其缺陷导致巨大血小板综合征。聚集功能主要由GPⅡb/Ⅲa介导；分泌与止血为血小板活化后的效应；血块收缩依赖血小板收缩蛋白，均与GPⅠb无直接关系"},{"q":"以血红蛋白为标准，贫血是指成年男性血红蛋白","o":["＜120g/L","＜110g/L","＜100g/L","＜90g/L","＜80g/L"],"a":0,"e":"贫血以血红蛋白浓度低于参考下限为标准，成年男性血红蛋白低于120g/L可判为贫血，女性低于110g/L。110g/L为成年女性标准而非男性；90g/L为轻中度贫血分界附近；100g/L、80g/L已属明显贫血，均非诊断阈值。该标准以海平面条件下静脉血为准"},{"q":"医生在给患者体检时，发现其双眼调节反射和辐辏反射均消失。最可能是下列哪种神经病变所致","o":["视神经损害","动眼神经损害","展神经损害","面神经损害","三叉神经损害"],"a":1,"e":"调节反射与辐辏（集合）反射的传出均由动眼神经支配的睫状肌与双眼内直肌完成，动眼神经损害时二者消失，伴上睑下垂、眼球向内向上及向下活动受限。视神经损害影响传入与视力；展神经支配外直肌，损伤致外展受限；面神经司表情肌；三叉神经司面部感觉与咀嚼肌"},{"q":"巨幼细胞贫血的原因是","o":["铁缺乏","RBC内在缺陷","RBC以外因素","骨髓造血功能障碍","叶酸缺乏"],"a":4,"e":"巨幼细胞贫血因DNA合成障碍致红细胞发育异常，最常见于叶酸或维生素B12缺乏，叶酸缺乏时可见巨红细胞、中央淡染区消失。铁缺乏导致小细胞低色素性贫血；RBC内在缺陷如遗传性球形红细胞增多症属溶血性贫血；骨髓造血功能障碍见于再生障碍性贫血，均非巨幼变机制"},{"q":"心尖冲动有力，呈抬举样，见于","o":["甲亢","发热","左心室肥大","剧烈运动","消瘦"],"a":2,"e":"心尖冲动有力呈抬举样，指搏动徐缓有力、使手指被抬起并持续至第二心音，是左心室肥厚、收缩力增强的体征。甲亢、发热、剧烈运动及消瘦所致者为高动力状态，搏动振幅大但持续时间短、抬举力弱，可与器质性左室肥大鉴别"},{"q":"关于小红细胞常见于以下情况，但应除外","o":["缺铁性贫血","小细胞低色素性贫血","铁粒幼细胞贫血","遗传性球形细胞增多症","巨幼细胞贫血"],"a":4,"e":"小红细胞指直径小于6μm的红细胞，常见于缺铁性贫血、铁粒幼细胞贫血等小细胞低色素性贫血，遗传性球形红细胞增多症红细胞体积亦偏小且中央淡染区消失。巨幼细胞贫血由叶酸或维生素B12缺乏引起，红细胞体积增大，属大细胞性贫血，不出现小红细胞"},{"q":"关于肺肝界，哪项是错误的","o":["肺气肿时肺肝界下移","肺不张时肺肝界上移","腹腔积液时，肺肝界下移","肺底积液时，肺肝界上移","鼓肠时，肺肝界上移"],"a":2,"e":"肺肝界即肝脏上界叩诊的浊音界，肺气肿时肺过度充气使膈肌下降、肺肝界下移；肺不张或肺底积液使膈肌抬高、肺肝界上移；鼓肠时肠管胀气推膈上移，肺肝界上移。大量腹腔积液使腹压升高、膈肌上抬，肺肝界应上移而非下移，故该项错误"},{"q":"胸导联低电压的定义","o":["QRS波群振幅都小于0.5mV","QRS波群振幅都小于0.8mV","QRS波群振幅都小于1mV","QRS波群正向或负向振幅都小于0.5mV","QRS波群正向或负向振幅都小于0.8mV"],"a":1,"e":"低电压指QRS波群振幅普遍降低，6个胸导联QRS波群振幅（正向与负向绝对值相加）均小于0.8mV即为胸导联低电压，肢体导联标准为均小于0.5mV。小于0.5mV是肢导联而非胸导联标准；小于1mV阈值过高；以正向或负向单独计算不符合振幅相加的测量规定"},{"q":"第一心音强弱不等，最常见于","o":["P-R间期延长","P-R间期缩窄","甲状腺功能亢进症","心房颤动","左心衰竭"],"a":3,"e":"第一心音强弱不等最常见于心房颤动，因心律绝对不规则使心室充盈量时多时少，收缩时瓣膜位置与张力不一，两次心搏相近时S1增强、相距远时减弱，并伴脉搏短绌。完全性房室传导阻滞亦可有强弱不等，出现'大炮音'，但远不如房颤常见；PR间期改变与甲亢、左心衰主要影响S1强度而非强弱不等"},{"q":"急性纤维蛋白性心包炎具有的特征性体征是","o":["心尖冲动减弱或消失","心包叩击音","心包摩擦音","腹水","颈静脉怒张"],"a":2,"e":"急性纤维蛋白性心包炎时脏、壁两层心包因纤维蛋白沉积而粗糙，心脏搏动时相互摩擦产生心包摩擦音，与心搏一致、屏气后仍存在，是本病特征性体征。心包叩击音、颈静脉怒张及腹水多在渗出增多或缩窄性心包炎出现；心尖冲动减弱或消失提示心包积液，均非纤维蛋白性阶段特征"},{"q":"铁蛋白增高的疾病是","o":["恶性肿瘤","缺铁性贫血","红斑狼疮","营养不良","维生素C缺乏"],"a":0,"e":"铁蛋白是储存铁的蛋白，同时属急性时相反应蛋白，在恶性肿瘤、感染、炎症及肝脏疾病时合成增加而升高，可作为肿瘤标志之一。缺铁性贫血时铁蛋白明显降低，是诊断缺铁的敏感指标；营养不良、维生素C缺乏不使其升高；红斑狼疮活动期虽可影响，但升高不如恶性肿瘤典型"},{"q":"关于血尿概念下列各项均正确，但除外","o":["血尿的尿色可以正常","血尿的尿色呈洗肉水样","当尿液呈酸性时血尿颜色可呈暗黑色","当尿液呈碱性时血尿为红色","血尿即为血红蛋白尿"],"a":4,"e":"血尿指尿中红细胞增多，尿色可正常、呈洗肉水样，酸性尿中红细胞破坏可呈暗黑色，碱性尿可呈红色，但镜检可见红细胞。血红蛋白尿是血管内溶血时血红蛋白经尿排出，尿呈暗红或酱油色、镜检无红细胞，与血尿本质不同，故二者不可等同"},{"q":"最常引起手指关节梭形肿胀的疾病是","o":["指关节结核","风湿性关节炎","类风湿关节炎","尺神经损伤","正中神经损伤"],"a":2,"e":"梭形指表现为近端指间关节增生肿胀呈梭形，多双侧对称，伴晨僵、疼痛，晚期强直并向尺侧偏斜，是类风湿关节炎的典型手部改变。风湿性关节炎以游走性大关节痛为主；指关节结核多为单关节破坏；尺神经与正中神经损伤表现为感觉运动障碍，不引起关节梭形肿胀"},{"q":"肺部叩诊呈浊音或实音常见于","o":["支气管哮喘","肺内大空洞","肺气肿","大叶性肺炎","气胸"],"a":3,"e":"肺部叩诊浊音或实音提示肺组织含气量减少或胸膜腔积液、占位，大叶性肺炎实变期肺泡被炎性渗出物填充，叩诊呈浊音。支气管哮喘与肺气肿因肺过度充气叩诊呈过清音；肺内大空洞叩诊可呈鼓音；气胸胸膜腔积气叩诊呈鼓音，均非浊音或实音"},{"q":"下列哪种腹型属于健康正力型","o":["腹部平坦","腹部低平","腹部膨隆","蛙腹","尖腹"],"a":0,"e":"健康正常成年人平卧时前腹壁大致与肋缘和耻骨联合处于同一平面或略低凹，称腹部平坦，属正力型腹型。腹部低平多见于消瘦者；腹部膨隆见于肥胖、腹水或肿块；蛙腹为大量腹水时腹壁松弛向两侧膨出；尖腹多见于结核性腹膜炎，均非健康正力型表现"},{"q":"双侧心室肥大的心电图表现包括","o":["只显示左室肥大","只显示右室肥大","同时显示双室肥大","大致正常","同时显示双房、双室肥大"],"a":2,"e":"双侧心室肥厚的心电图并非左右心室改变简单相加，可表现为大致正常、仅显示一侧肥厚或同时显示双室肥厚三种情况；题目所列'同时显示双室肥大'即为其中之一，表现为既有V1导联R波为主、电轴右偏等右室肥厚特征，又有V5导联R/S＞1、R波增高这类左室肥厚征象"},{"q":"以下不是呼气性呼吸困难的特点的是","o":["呼气费力","呼气时间延长","呼气缓慢","出现“三凹征”","常伴哮鸣音"],"a":3,"e":"呼气性呼吸困难因肺泡弹性减弱或小支气管痉挛狭窄所致，表现为呼气费力、呼气缓慢、呼气时间明显延长，常伴呼气期哮鸣音，见于哮喘、慢性阻塞性肺疾病。三凹征是吸气性呼吸困难的特征，因上气道阻塞、吸气时胸腔负压极度增高致胸骨上窝、锁骨上窝及肋间隙凹陷"},{"q":"肺气肿时可出现下列体征，但应除外","o":["触诊语颤增强","桶状胸","叩诊过清音","肺下界下移","呼吸音减弱"],"a":0,"e":"肺气肿时肺泡含气过多、肺过度膨胀，可见桶状胸，叩诊过清音，肺下界下移，呼吸音减弱，语音震颤因含气量增多而减弱。语颤增强见于肺实变或接近胸膜的肺内大空腔，如大叶性肺炎实变期、空洞型肺结核，因声波传导良好，与肺气肿的含气增多相反"},{"q":"P-R间期的正常值为","o":["0.05～0.10s","0.06～0.10s","0.10～0.12s","0.10～0.20s","0.12～0.20s"],"a":4,"e":"PR间期自P波起点至QRS波群起点，代表心房开始除极至心室开始除极的时间，心率正常范围为0.12～0.20秒，幼儿及心动过速时缩短，老年人及心动过缓时可略延长但一般不超过0.22秒。0.05～0.10秒与0.06～0.10秒过短；0.10～0.12秒为下限附近，均非正常参考区间"},{"q":"下列组合正确的是","o":["左侧卧位——主动脉瓣关闭不全的舒张期杂音明显","坐位前倾位——二尖瓣狭窄的舒张期杂音明显","深吸气时——左心发生的杂音增强","深呼气时——右心发生的杂音增强","作Valsalva动作——特发性肥厚性主动脉瓣下狭窄杂音增强"],"a":4,"e":"Valsalva动作使胸腔压力升高、回心血量减少，多数经瓣膜产生的杂音减轻，而梗阻性肥厚型心肌病因左室容量减小、流出道梗阻加重，杂音反而增强，故该组合正确。左侧卧位使二尖瓣狭窄杂音更明显；前倾坐位听主动脉瓣关闭不全杂音清楚；深吸气增强右心杂音，深呼气增强左心杂音"},{"q":"本例心电图最可能的病变冠脉是","o":["左前降支","左旋支","右冠脉","后降支","钝缘支"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，心电图定位诊断依梗死导联推断病变血管，前间壁V1～V3、前壁V3～V5及广泛前壁V1～V5梗死多由左前降支闭塞所致。下壁Ⅱ、Ⅲ、aVF多为右冠状动脉或左回旋支；侧壁Ⅰ、aVL、V5、V6可为左前降支或左回旋支；正后壁V7～V9多为左回旋支或右冠脉\n\n官方题库中缺失图片"},{"q":"下述为湿啰音特点的描述，但应除外","o":["呼吸音外的附加音","吸气时较明显，也可出现于呼气早期","部位较恒定，性质不易变","一次常连续多个出现","中、小水泡音不能同时存在"],"a":4,"e":"湿啰音是呼吸音外的附加音，断续短暂、一次常连续多个出现，吸气时或吸气终末较明显，也可出现于呼气早期，部位较恒定、性质不易变，咳嗽后可减轻或消失。中、小湿啰音可同时存在，如肺淤血时既可闻及中水泡音也可闻及细湿啰音，故'不能同时存在'的描述错误"},{"q":"McBurney压痛点的位置在","o":["脐与右髂前上棘连线的中点上","脐与左髂前上棘连线的中外1/3交界处","脐与右髂前上棘连线的中外1/3交界处","脐水平线上右腹直肌外缘","两髂前上棘连线与右耻骨结节垂直线的相交点"],"a":2,"e":"麦氏点（McBurney点）位于脐与右髂前上棘连线的中、外1/3交界处，此处压痛标志阑尾病变。脐与右髂前上棘连线中点偏内；脐与左髂前上棘连线中外1/3为左侧对称位置，无此命名；脐水平右腹直肌外缘的说法不准确；两髂前上棘连线与右耻骨结节垂线交点非麦氏点"},{"q":"下述情况的体温升高不属于生理性体温波动的是","o":["妇女月经前期","妇女妊娠期","剧烈运动后","流行性感冒","进食后"],"a":3,"e":"生理性体温波动可见于妇女月经前期、妊娠期、剧烈运动后及进食后，幅度小且可自行恢复。流行性感冒为病毒感染，致体温调定点上移出现病理性发热，常呈骤升型高热并伴寒战等症状，属病理性体温升高，不属于生理性波动"},{"q":"音乐性杂音最常见于","o":["二尖瓣狭窄","室间隔缺损","房间隔缺损","感染性心内膜炎","肺动脉瓣狭窄"],"a":3,"e":"音乐性杂音为高调、乐音样杂音，多因感染性心内膜炎时瓣膜穿孔、撕裂或腱索断裂，血流喷射产生振动所致，是其特征之一。二尖瓣狭窄为低调隆隆样舒张期杂音；室间隔缺损为粗糙全收缩期杂音；房间隔缺损多为肺动脉瓣区收缩期杂音；肺动脉瓣狭窄为喷射性收缩期杂音，均非音乐性"},{"q":"关于法洛四联症的临床表现，不正确的是","o":["严重发绀及杵状指","脉搏正常","S1正常，但S2缺少肺动脉瓣成分","可有抬举性心尖冲动","胸骨缘较低位置可闻及收缩期喷射性杂音伴随震颤"],"a":3,"e":"法洛四联症主要病理为右心室肥大，其抬举性搏动位于胸骨左下缘，而非心尖区；心尖区抬举性冲动是左心室肥厚的体征，故该项错误。本症因右向左分流有严重发绀及杵状指；脉搏正常；主动脉骑跨使第二心音肺动脉瓣成分减弱；胸骨左缘低位可闻收缩期喷射性杂音伴震颤"},{"q":"关于结核性渗出性胸膜炎的胸腔积液，不正确的是","o":["多呈草黄色，易自行凝固","比重大于1.018","蛋白含量大于30g/L","细胞成分以嗜酸性粒细胞为主","李凡他试验阳性"],"a":3,"e":"结核性渗出性胸膜炎的胸腔积液多呈草黄色、易自行凝固，比重大于1.018，蛋白含量超过30g/L，李凡他试验阳性，细胞分类以淋巴细胞为主。嗜酸性粒细胞为主见于血胸、气胸、肺梗死、真菌或寄生虫感染及过敏综合征，并非结核性胸膜炎特点，故该项错误"},{"q":"下列哪种情况可以判定为消瘦","o":["BMI＜17","BMI＜17、5","BMI＜18","BMI＜18、5","BMI＜19"],"a":3,"e":"体重指数（BMI）=体重（kg）/身高（m）的平方，我国与世界卫生组织标准均以BMI＜18.5kg/m为消瘦，18.5～23.9为正常。BMI＜17或17.5属更严重的营养不良范畴，但不是消瘦的通用界定值；18、19均接近或落入正常低限，不作为消瘦标准"},{"q":"关于脾脏轻度肿大正确的是","o":["深吸气时脾缘不超过肋下2cm","深呼气时脾缘不超过肋下2cm","深吸气时脾缘不超过肋下3cm","深呼气时脾缘不超过肋下3cm","平静呼吸脾缘不超过肋下3cm"],"a":0,"e":"脾肿大分度以深吸气时脾缘为准，不超过肋下2cm为轻度；超过2cm但在脐水平线以上为中度；超过脐水平线或前正中线为高度即巨脾。以深呼气或以3cm为界均不符合分度标准，平静呼吸也未作为判定条件，故只有深吸气时肋下2cm以内为轻度肿大"},{"q":"语音震颤减弱或消失见于下列疾病，但除外","o":["肺气肿","阻塞性肺不张","气胸","肺梗死","胸壁皮下气肿"],"a":3,"e":"语音震颤减弱或消失见于肺含气量增多如肺气肿、气胸、胸壁皮下气肿，以及肺不张、胸腔积液等传导受阻的情况。肺梗死造成肺组织实变，使声波传导良好，语音震颤反而增强，与大叶性肺炎实变期类似，故不属于语颤减弱的疾病"},{"q":"大量胸腔积液部位的叩诊音应为","o":["清音","过清音","实音","浊鼓音","空瓮音"],"a":2,"e":"大量胸腔积液时胸膜腔充满液体，叩诊呈实音，积液区呼吸音与语音共振减弱或消失，积液区上方因压迫性肺不张可闻及支气管呼吸音。清音为正常肺野叩诊音；过清音见于肺气肿；鼓音见于气胸或肺内大空洞；浊鼓音多见于肺水肿或肺炎早期，均非大量积液表现"},{"q":"脑脊液白细胞数300×106/L以上，以淋巴细胞为主，蛋白质增高，糖和氯化物明显降低，首先考虑哪种诊断的可能","o":["细菌性脑膜炎","病毒性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":2,"e":"脑脊液白细胞数中度增高、以淋巴细胞为主，蛋白增高，糖与氯化物明显降低，尤以氯化物下降显著，是结核性脑膜炎的典型改变。细菌性脑膜炎以中性粒细胞为主、外观浑浊；病毒性脑膜炎糖与氯化物正常；隐球菌性脑膜炎可查见隐球菌；乙型脑炎糖正常或略高，均不符"},{"q":"关于收缩早期喷射音，下列哪项是正确的","o":["肺动脉喷射音于呼气时增强，吸气时减弱","肺动脉喷射音于吸气时增强，呼气时减弱","肺动脉喷射音于胸骨右缘2、3肋间最响","主动脉喷射音于呼气时增强，吸气时减弱","主动脉喷射音于吸气时增强，呼气时减弱"],"a":0,"e":"肺动脉收缩期喷射音在肺动脉瓣区最响，因吸气时回心血量增加使肺动脉扩张、瓣叶开放受限减轻，故吸气时减弱、呼气时增强。主动脉喷射音在主动脉瓣区最响并向心尖传导，不受呼吸影响；将肺动脉喷射音位置说成胸骨右缘第2、3肋间属主动脉瓣区，定位错误"},{"q":"大量腹水的体征是","o":["尺压试验阳性","腹部浊音呈移动性","腹部浊音无移动性","振水音阳性","仰卧位浊音区在中腹部"],"a":1,"e":"大量腹水时液体随体位变动积聚于低位，叩诊浊音区随体位改变而移动，称移动性浊音，是腹水的重要体征，一般腹水量超过1000ml可检出。卵巢囊肿所致巨大浊音区不呈移动性且仰卧时多在腹中部；尺压试验用于卵巢囊肿鉴别；振水音提示胃潴留，均非大量腹水表现"},{"q":"管样呼吸音可见于下列疾病，但除外","o":["肺癌","大叶肺炎","肺脓肿","肺结核","胸腔积液时积液区上方"],"a":0,"e":"管样呼吸音即异常支气管呼吸音，见于肺实变如大叶性肺炎，以及肺脓肿、肺结核等形成的空洞或实变，胸腔积液上方压迫性肺不张亦可闻及。肺癌主要引起局限性哮鸣音或呼吸音减弱，并非管样呼吸音的典型病因，故为除外项"},{"q":"临床表现为咯血伴呛咳的疾病是","o":["大叶性肺炎","支气管肺癌","肺脓肿","湿性支气管扩张","化脓性肺炎"],"a":1,"e":"咯血伴呛咳多见于支气管肺癌与支原体肺炎，肺癌因肿瘤刺激支气管黏膜引起刺激性干咳并痰中带血，40岁以上长期吸烟者尤应警惕。大叶性肺炎多咳铁锈色痰；肺脓肿咳大量脓臭痰；支气管扩张为慢性咳嗽伴大量脓痰及反复咯血；化脓性肺炎以脓痰为主，均不以呛咳为特征"},{"q":"下列属于体表标志的是","o":["肋弓下缘","左上腹","右上腹","左下腹","麦氏点"],"a":0,"e":"体表标志是体表可触及的固定解剖结构，肋弓下缘由第8～10肋软骨连接形成，为腹部体表上界，常用于腹部分区、肝脾测量与胆囊定位。左上腹、右上腹、左下腹为四分法划分的区域而非标志；麦氏点是人为设定的压痛点，属投影定位，均非严格意义的体表标志"},{"q":"诊断学的辅助检查也包括一些特殊检查，但不包括","o":["心电图检查","超声检查","内窥镜检查","磁共振检查","建立遗传基因实验室与否的检查"],"a":4,"e":"诊断学的辅助检查包括心电图、超声、内镜、磁共振等临床常用检查手段。建立遗传基因实验室与否属于科室或机构建设管理范畴，不是针对患者的检查项目，故不属于辅助检查内容。心电图记录电活动，超声与磁共振提供影像，内镜直接观察腔道，均为常规辅助检查"},{"q":"下列哪项提示滑车神经受损","o":["眼上睑下垂","眼球向内活动受限","眼球向下及外展运动减弱","眼球向上活动受限","视野变小"],"a":2,"e":"滑车神经支配上斜肌，使眼球向下、向外及内旋运动，受损时眼球向下及外展运动减弱，出现复视。上睑下垂与眼球向内、向上及向下活动受限提示动眼神经损害；眼球向外转动障碍为展神经受损；视野变小多与视神经或视路病变相关，均非滑车神经特征"},{"q":"S1出现的时间是","o":["与半月瓣关闭同时发生","与房室瓣关闭同时发生","在舒张早期发生","在心室射血高峰发生","在心室收缩中晚期发生"],"a":1,"e":"第一心音发生于心室收缩开始，主要由二尖瓣与三尖瓣关闭时瓣叶突然紧张振动产生，故与房室瓣关闭同步，并在心尖部最响。半月瓣关闭产生第二心音；舒张早期为第三心音出现时期；心室射血高峰在收缩中期；收缩中晚期无第一心音，第一心音标志收缩期开始"},{"q":"中毒不会引起高铁血红蛋白血症性发绀的物质是","o":["亚硝酸盐","地高辛","磺胺","苯胺","伯氨喹"],"a":1,"e":"高铁血红蛋白血症性发绀由血红蛋白二价铁被氧化为三价铁、失去携氧能力所致，常见于苯胺、硝基苯、伯氨喹、亚硝酸盐及磺胺类等中毒，抽血呈深棕色、氧疗无效，亚甲蓝或维生素C可解救。地高辛为强心苷，中毒表现为心律失常与胃肠道反应，不引起高铁血红蛋白血症"},{"q":"下列属于心源性水肿的体征的是","o":["颈静脉怒张","肝脾大","非凹陷性水肿","胸壁上肢静脉怒张","单侧肢体水肿"],"a":0,"e":"颈静脉怒张是右心衰竭体循环淤血的重要体征，伴肝大、肝颈静脉回流征阳性及下垂部位凹陷性水肿时，水肿可判为心源性。非凹陷性水肿见于黏液性水肿或淋巴回流障碍；单侧肢体水肿多为局部静脉或淋巴病变；胸壁上肢静脉怒张提示上腔静脉阻塞；肝脾大也可见于肝源性疾病，均不特有心源性"},{"q":"心脏听诊能诊断的心律失常中，最常见的是","o":["房性心动过速","室性心动过速","心房颤动","窦性心动过缓","完全性房室传导阻滞"],"a":2,"e":"心房颤动听诊有心律绝对不规则、第一心音强弱不等及脉搏短绌三大特点，仅凭听诊即可诊断，是临床最常见且能被听诊识别的心律失常。房性与室性心动过速及完全性房室传导阻滞多需心电图确诊；窦性心动过缓心律规则，听诊难以独立判断，故不作首选"},{"q":"消化性溃疡有诊断意义的症状是","o":["反酸、嗳气","恶心、呕吐","呕吐隔夜食","出汗、脉缓","节律性上腹部疼痛"],"a":4,"e":"消化性溃疡以上腹部疼痛为主要症状，具有慢性、周期性与节律性特点，如胃溃疡餐后痛、十二指肠溃疡空腹或夜间痛，这种节律性疼痛对其诊断最有意义。反酸嗳气、恶心呕吐为非特异性消化不良表现；呕吐隔夜食提示幽门梗阻；出汗脉缓为迷走反射表现，均无溃疡特异性"},{"q":"腹部检查的正确顺序是","o":["听诊、视诊、叩诊、触诊","听诊、视诊、触诊、叩诊","视诊、听诊、叩诊、触诊","视诊、听诊、触诊、叩诊","视诊、叩诊、触诊、听诊"],"a":2,"e":"腹部检查按视诊、听诊、叩诊、触诊顺序进行，因触诊可刺激肠蠕动、改变肠鸣音，故将听诊置于触诊之前，而叩诊亦在触诊前完成。先听诊后触诊能保留真实肠鸣音，避免人为干扰。视诊、听诊、叩诊、触诊以外的排列，如先触诊或听诊置于最后，均不符合避免蠕动干扰的原则"},{"q":"该符号代表第几颗牙","o":["右上第一尖牙","左上第—尖牙","右上中切牙","左上中切牙","左下第一磨牙"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，牙位记录常用部位记录法，以十字分四区，右上区以数字标注，中切牙为1、侧切牙为2、尖牙为3，第一磨牙为6；左上、左下、右下依次对应不同象限。十字定位配合牙序数字可确定具体牙位，其中右上中切牙标记为右上1\n\n官方题库中缺失图片"},{"q":"心动周期中的等容收缩期相当于","o":["半月瓣开放而房室瓣关闭","半月瓣及房室瓣均处于关闭状态","心室内压急剧下降","出现心室射血高峰","出现心室快速充盈"],"a":1,"e":"等容收缩期位于房室瓣关闭之后、半月瓣开放之前，此时室内压急剧升高但容积不变，半月瓣与房室瓣均处于关闭状态。半月瓣开放标志射血期开始，非等容收缩；室内压急剧下降发生等容舒张期；射血高峰在快速射血期；快速充盈属舒张期，均与等容收缩无关"},{"q":"严重吸气性呼吸困难不会出现","o":["端坐呼吸","鼻翼翕动","咯粉红色泡沫痰","呼吸加深加快","三凹征"],"a":2,"e":"严重吸气性呼吸困难因上气道阻塞，表现为吸气费力、三凹征、鼻翼翕动、呼吸加深加快及端坐呼吸等代偿表现。咯粉红色泡沫痰是急性左心衰竭肺水肿的特征，因肺毛细血管压升高、液体渗入肺泡所致，属心源性呼吸困难表现，与吸气性呼吸困难的机制不同，故不会出现"},{"q":"下图所示心电图的诊断是","o":["二度Ⅱ型房室传导阻滞","二度Ⅰ型房室传导阻滞","三度房室传导阻滞","房性期前收缩","室性期前收缩"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，二度Ⅰ型房室传导阻滞表现为P波规律出现、PR间期逐渐延长直至一个P波后QRS波脱漏，漏搏后PR又缩短，周而复始称文氏现象。二度Ⅱ型PR间期固定而突然脱漏；三度房室分离、P与QRS各自独立；房性与室性期前收缩为提前出现的异位搏动\n\n官方题库中缺失图片"},{"q":"以下不符合扩张型心肌病心脏体征的是","o":["心界扩大","心音增强","可闻及第三或第四心音","奔马律","有时心尖部可闻及收缩期杂音"],"a":1,"e":"扩张型心肌病心肌收缩力下降、心腔扩大，体征有心界扩大、心音减弱、可闻第三或第四心音及奔马律，心尖部可因相对性二尖瓣关闭不全出现收缩期杂音，故心音增强不符合。心音增强多见于高热、贫血、甲亢等高动力状态，与扩张型心肌病心功能减退相反"},{"q":"下列不属于一般项目的内容是","o":["籍贯","民族","入院日期","发病日期","记录日期"],"a":3,"e":"住院病历一般项目包括姓名、性别、年龄、籍贯、出生地、民族、婚姻、住址、职业、入院日期、记录日期及病史陈述者等，需逐项填写。发病日期属现病史内容，记录疾病起始时间与演变过程，不列入一般项目；籍贯、民族、入院日期与记录日期均为一般项目组成部分"},{"q":"关于FDP，错误的是","o":["FDP是在纤溶亢进时产生的纤溶酶的作用下，纤维蛋白或纤维蛋白原被分解后产生的降解产物的总称","原发性和继发性纤维蛋白溶解活性增高时，血中纤维蛋白（原）降解产物含量升高","原发性纤维蛋白溶解功能亢进，FDP降低","继发性纤维蛋白溶解功能亢进，FDP增高","FDP主要反映纤维蛋白溶解功能"],"a":2,"e":"FDP是纤溶酶分解纤维蛋白或纤维蛋白原产生的降解产物总称，主要反映纤溶功能，原发性与继发性纤溶活性增高时血中FDP均升高。原发性纤溶时纤维蛋白原被降解，FDP升高而D-二聚体正常，故'原发性纤溶FDP降低'错误；继发性纤溶如DIC时FDP与D-二聚体均升高"},{"q":"第二心音生理分裂中，下列哪项是正确的","o":["深吸气末可听到第二心音分裂，呼气时又成为单一的第二心音","深呼气时可听到第二心音分裂，吸气时又成为单一的第二心音","与呼吸无关","卧位时可听到第二心音分裂，立位时则无","左侧卧位时明显，右侧卧位时则减轻"],"a":0,"e":"第二心音生理性分裂见于深吸气末，因胸腔负压增加、右心回心血量增多、右室排血时间延长，使肺动脉瓣关闭明显迟于主动脉瓣而出现分裂，呼气时两者接近又成为单一心音，青少年更明显。分裂与呼吸密切相关，非呼气时出现；卧位、侧卧位改变并非生理分裂的决定因素"},{"q":"关于心脏杂音的叙述正确的是","o":["收缩期杂音分为0～5的等级","2/6级以上杂音通常见于器质性病变","杂音是由血流加速形成旋涡所致","5级杂音在听诊器离胸壁一定距离也能听到","杂音与震颤一起存在"],"a":2,"e":"心脏杂音基本机制是血流加速、瓣膜异常或异常通道使层流变为湍流或涡流，冲击心壁、瓣膜、腱索等产生振动，故血流加速形成旋涡是杂音产生的机制。收缩期杂音分1～6级而非0～5级；3/6级以上多为器质性，2/6级常为功能性；6级杂音听诊器离开胸壁仍可闻及；杂音与震颤并非总是并存"},{"q":"头发全脱落称","o":["全秃","普秃","斑秃","假性斑秃","头癣"],"a":0,"e":"头发全部脱落而眉毛、睫毛等其他体毛存在者称全秃；若全身毛发包括眉、睫、腋毛、阴毛等均脱落则称普秃。斑秃为圆形或椭圆形局限性脱发，边界清楚；假性斑秃为瘢痕性脱发，局部皮肤萎缩光滑；头癣为真菌感染，多伴鳞屑与断发，均非头发全部脱落"},{"q":"被检查者直立位两上肢自然下垂时，肩胛下角位于","o":["第3或第4肋骨","第5或第6肋骨","第7或第8肋骨","第9或第10肋骨","第11或第12肋骨"],"a":2,"e":"受检者直立、两上肢自然下垂时，肩胛下角相当于第7或第8肋骨水平，也约平第8胸椎，是后胸部计数肋骨和椎体的重要体表标志。第3、4肋骨及第5、6肋骨位置偏高；第9、10及第11、12肋骨位置偏低，均与肩胛下角实际水平不符"},{"q":"Duroziez双重杂音见于下列疾病，但除外","o":["主动脉瓣关闭不全","严重贫血","维生素B1缺乏性心脏病","主动脉瓣狭窄","甲状腺功能亢进"],"a":3,"e":"Duroziez双重杂音是听诊器压迫股动脉时听到的收缩期与舒张期双重杂音，属周围血管征，见于主动脉瓣关闭不全及其他脉压增大的高动力状态，如严重贫血、维生素B1缺乏性心脏病、甲状腺功能亢进。主动脉瓣狭窄使脉压减小、周围搏动减弱，不会出现该双重杂音"},{"q":"适用于大量腹水时肝脾及腹腔包块检查的是","o":["深部滑行触诊法","深压触诊法","双手触诊法","冲击触诊法","浅部触诊法"],"a":3,"e":"冲击触诊法又称浮沉触诊法，用并拢三指急速冲击腹壁，使腹水在脏器表面暂时移去，指端得以触及肿大肝脾或包块，专用于大量腹水时肝脾及腹腔包块难以触及者。深部滑行触诊用于腹腔深部包块与胃肠病变；深压触诊用于压痛与反跳痛；双手触诊用于肝脾肾；浅部触诊用于腹壁浅表病变"},{"q":"成熟T细胞的特性包括","o":["自身耐受","记忆","介导免疫应答","特异性杀伤","非特异性杀伤"],"a":0,"e":"成熟T细胞在中枢发育过程中经阳性选择与阴性选择，对自身抗原形成免疫耐受即自身耐受，是成熟T细胞的重要特性，可避免攻击自身组织。记忆为记忆性T细胞亚群的特点；介导免疫应答是T细胞整体功能；特异性杀伤为细胞毒性T细胞功能；非特异性杀伤属NK细胞，均非成熟T细胞共有的界定特性"},{"q":"患者具有持续发热、相对缓脉、肝脾大、玫瑰疹等临床特点，诊断应考虑","o":["病毒感染","白血病","斑疹伤寒","伤寒","败血症"],"a":3,"e":"伤寒由伤寒沙门菌引起，典型表现为持续发热、相对缓脉、肝脾大、玫瑰疹及白细胞减少，题干特点高度符合。病毒感染热型多样无相对缓脉与玫瑰疹；白血病有贫血出血及原始细胞；斑疹伤寒皮疹为斑疹且无相对缓脉；败血症多为弛张热伴寒战，均无相对缓脉与玫瑰疹组合"},{"q":"器质性心脏病的体征之一是","o":["心尖向左下移位","心前区触及震颤","心尖部闻及3/6级的收缩期杂音","剑下心尖冲动","听到第三心音"],"a":1,"e":"心前区触及震颤提示器质性心脏病，因其多为先天性心血管病或狭窄性瓣膜病变产生湍流所致，如主动脉瓣狭窄、室间隔缺损、二尖瓣狭窄，临床上触及震颤处多可闻及响亮杂音。心尖向左下移位可见于左室肥大但非特异；3/6级收缩期杂音可为功能性；剑下心尖冲动见于右室肥大；第三心音可在健康青少年闻及"},{"q":"下列各项均为现病史的内容，但除外","o":["病因与诱因","伴随症状","诊治、用药经过","病程中一般情况","与现病有密切关系的疾病"],"a":4,"e":"现病史包括起病情况、病因与诱因、主要症状特点、病情发展演变、伴随症状、诊治及用药经过和病程中一般情况。与现病有密切关系的既往疾病属既往史内容，应写入既往史而非现病史，故为除外项。病因诱因、伴随症状、诊治经过与病程一般情况均为现病史组成部分"},{"q":"咯血与呕血鉴别点不正确的是","o":["血色鲜红","痰中带血","有支气管扩张症病史","咯出物为酸性反应","咯血前有咳嗽、喉部痒感"],"a":3,"e":"咯血为喉以下呼吸道出血经口咯出，血色鲜红、常痰中带血，咯前多有喉部痒感与咳嗽，混有痰与泡沫，酸碱反应呈碱性，咯后数日常有血痰。呕血为上消化道出血，色暗红或咖啡渣样、呈酸性、常伴黑便。将咯出物说成酸性反应是把呕血特点误加于咯血，故不正确；支气管扩张史支持咯血"},{"q":"患者咳嗽，咳痰成砖红色胶冻样痰液时，首先考虑感染因素为","o":["军团菌","肺炎克雷伯杆菌","铜绿假单胞菌","曲霉菌","肺炎球菌"],"a":1,"e":"砖红色胶冻样痰是肺炎克雷伯杆菌肺炎的特征，因细菌荚膜使痰液黏稠呈胶冻状并带血。军团菌肺炎多为少量黏痰；铜绿假单胞菌感染痰呈黄绿色或带甜味；曲霉菌感染可见棕褐色痰栓；肺炎链球菌肺炎典型为铁锈色痰，均不同于砖红色胶冻样痰"},{"q":"下列哪种疾病不会出现血块收缩不良的结果","o":["血小板减少症","血小板无力症","血友病","低纤维蛋白原症","血小板增多症"],"a":2,"e":"血块收缩主要依赖血小板数量与功能及纤维蛋白原，血小板减少症、血小板无力症与血小板增多症均可致收缩不良，低纤维蛋白原症因纤维蛋白网形成不足亦收缩不良。血友病为凝血因子Ⅷ或Ⅸ缺乏，属凝血障碍，血小板与纤维蛋白原正常，血块收缩不受影响，故不会出现收缩不良"},{"q":"四肢对称性紫癜伴关节痛或腹痛、血尿常见于","o":["血小板减少性紫癜","过敏性紫癜","血友病","维生素K缺乏症","播散性血管内凝血"],"a":1,"e":"过敏性紫癜为血管壁通透性增高所致，表现为四肢对称、高出皮面的紫癜，可伴关节痛、腹痛及血尿，累及肾时血尿明显，题干特点典型。血小板减少性紫癜为散在瘀点瘀斑、血小板减少；血友病为深部与关节出血；维生素K缺乏与播散性血管内凝血均有凝血因子异常，均无对称高出皮面的紫癜"},{"q":"病理反射出现是由于","o":["脊髓反射弧的损害","神经系统兴奋性普遍增高","基底节受损","锥体束受损","脑干网状结构损害"],"a":3,"e":"病理反射是锥体束受损时，大脑失去对脑干和脊髓的抑制而释放出的异常反射，如Babinski征、Oppenheim征，故其出现提示锥体束病变；1岁半以内婴幼儿因神经发育未完善可出现，属生理性。脊髓反射弧损害表现为反射减弱或消失；基底节受损致锥体外系症状；脑干网状结构损害主要影响意识"},{"q":"有关诊断思维的基本原则，正确的是","o":["现象和本质不统一","面面俱到","只关注某一系统变化","只关注典型症状","首先应考虑器质性疾病"],"a":4,"e":"诊断思维基本原则要求在器质性与功能性疾病鉴别困难时首先考虑器质性疾病，以免延误手术等治疗时机，如腹痛的结肠癌早期易被误当功能性肠病。现象与本质应统一而非不统一；面面俱到与只关注单一系统或典型症状均失之偏颇，不是正确的诊断思维原则"},{"q":"正常人血清中的胆红素主要是","o":["结合胆红素","未结合胆红素","与球蛋白结合的胆红素","与总蛋白结合的胆红素","与白蛋白结合的胆红素"],"a":1,"e":"血清胆红素包括结合胆红素与未结合胆红素，正常人血清中绝大部分为未结合胆红素，其参考区间约1.7～10.2μmol/L，结合胆红素仅0～6.8μmol/L。结合胆红素为经肝细胞处理后可直接排泄者，占比低；胆红素在血中主要与白蛋白结合运输，但这并非胆红素的分类名称，与题意不符"},{"q":"可出现气管移向健侧的疾病为","o":["肺实变","肺气肿","肺不张","胸膜肥厚","气胸"],"a":4,"e":"气胸时胸膜腔积气使患侧胸廓饱满、压力升高，将气管与心脏推向健侧，叩诊鼓音、呼吸音减弱。肺实变与肺不张使患侧容积缩小，气管移向患侧；肺气肿为双侧病变，气管居中；胸膜肥厚牵拉使气管移向患侧，均不使气管移向健侧"},{"q":"图中所示心电图最可能的诊断是","o":["心房颤动","心房扑动","房性心动过速","窦性心动过速","阵发性室上性心动过速"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，心房扑动心电图特点为正常P波消失，代之以连续锯齿状F波，在Ⅱ、Ⅲ、aVF导联最清晰，心房率250～350次/min，QRS波一般不增宽。心房颤动代之以不规则f波、心律绝对不齐；房性与窦性心动过速仍有形态明确P波；阵发性室上速为突发窄QRS心动过速\n\n官方题库中缺失图片"},{"q":"腹部触诊柔韧感最常见于","o":["自发性腹膜炎","慢性膀胱炎","急性盆腔炎","结核性腹膜炎","弥漫性腹膜炎"],"a":3,"e":"腹部触诊柔韧感又称揉面感，是结核性腹膜炎的特征性体征，因腹膜慢性炎症、增厚与粘连，使腹壁触之柔韧而有阻力。自发性腹膜炎与弥漫性腹膜炎多为急性腹膜刺激征，表现为腹肌紧张、压痛反跳痛；慢性膀胱炎与急性盆腔炎病变在盆腔，均无腹部揉面感"},{"q":"下列疾病临床多表现为弛张热，但需除外","o":["重症肺结核","风湿热","化脓性肺炎","急性肾盂肾炎","败血症"],"a":3,"e":"弛张热体温常在39℃以上，波动幅度大，24小时内波动超过2℃但均高于正常，见于败血症、风湿热、重症肺结核及化脓性肺炎等。急性肾盂肾炎多表现为间歇热或不规则热，伴寒战、高热、腰痛与尿路刺激征，不以弛张热为典型热型，故应除外"},{"q":"下列中细胞质内不含有特异性颗粒的细胞是","o":["早幼粒细胞","中幼粒细胞","晚幼粒细胞","杆状核细胞","分叶核粒细胞"],"a":0,"e":"粒系细胞颗粒随成熟演变，原始细胞无颗粒，早幼粒细胞出现紫红色非特异性嗜天青颗粒，至中幼粒细胞阶段才出现中性、嗜酸性或嗜碱性特异性颗粒，此后晚幼粒、杆状核及分叶核粒细胞均含特异性颗粒。故早幼粒细胞胞质内不含特异性颗粒，仅含嗜天青颗粒"},{"q":"呼气延长可见于","o":["肺不张","胸腔积液","气胸","支气管哮喘急性发作期","间质性肺炎"],"a":3,"e":"呼气延长是呼气性呼吸困难的典型表现，因小支气管痉挛狭窄、呼气气流受限所致，支气管哮喘急性发作时广泛气道痉挛，呼气费力且时间延长，伴哮鸣音。肺不张、气胸、胸腔积液以限制性通气或吸气受限为主；间质性肺炎表现为吸气浅快，均无呼气延长"},{"q":"下列是关于气胸体征的描述，错误的是","o":["患侧胸廓膨满","气管移向健侧","叩诊为鼓音","患侧呼吸音弱","听到支气管呼吸音"],"a":4,"e":"气胸时胸膜腔积气，患侧胸廓膨满、呼吸动度减弱，气管移向健侧，叩诊呈鼓音，患侧呼吸音减弱或消失，不应闻及支气管呼吸音。支气管呼吸音见于肺实变如大叶性肺炎，或胸腔积液上方压迫性肺不张处，因肺组织致密传导良好，与气胸含气增多相反，故该项错误"},{"q":"决定热型的依据是","o":["体温的高低","体温的上升速度","一定体温的持续时间","体温的曲线形态","体温的下降速度"],"a":3,"e":"将发热病人不同时间测得的体温数值记录并连成体温曲线，该曲线的不同形态即为热型，故决定热型的依据是体温曲线形态，如稽留热、弛张热、间歇热各有其特征。体温高低、上升与下降速度及持续时间仅描述曲线某方面，不能独立决定热型归属"},{"q":"抬高患者头部，观察患者双下肢是否同时屈髋屈膝，是以下哪个检查","o":["Babinski征","颈强直","kernig征","Brudzinski征","Hoffmann征"],"a":3,"e":"Brudzinski征检查时病人仰卧下肢伸直，检查者托起其枕部使头部前屈，若双髋与膝关节同时屈曲即为阳性，属脑膜刺激征。Babinski征为划足底外侧致拇趾背伸的病理反射；颈强直为被动屈颈受限；Kernig征为伸膝受限伴疼痛；Hoffmann征为上肢病理反射，均非此检查"},{"q":"下列各项是器质性心脏病的体征，但应除外","o":["抬举性心尖冲动","心前区触及震颤","心尖部听到舒张期杂音","心尖部听到3/6级收缩期杂音","胸骨左缘2肋间听到连续性杂音"],"a":3,"e":"心尖部3/6级收缩期杂音可为功能性，常见于发热、贫血、甲亢等高动力状态，不能据此判定器质性心脏病。抬举性心尖冲动提示心室肥厚；心前区震颤由器质性狭窄或异常通道产生；心尖部舒张期杂音与胸骨左缘第2肋间连续性杂音均为病理性，属器质性心脏病体征"},{"q":"Austin-Flint杂音为何种杂音","o":["相对性三尖瓣关闭不全杂音","器质性主动脉瓣狭窄杂音","相对性二尖瓣狭窄杂音","器质性肺动脉瓣狭窄杂音","功能性二尖瓣关闭不全杂音"],"a":2,"e":"Austin-Flint杂音见于中重度主动脉瓣关闭不全，因舒张期大量血液反流使二尖瓣处于半关闭状态、形成相对性狭窄，于心尖区产生柔和、递减型舒张中晚期隆隆样杂音。相对性三尖瓣关闭不全杂音位于胸骨左下缘；主动脉瓣狭窄为收缩期喷射性杂音；器质性肺动脉瓣狭窄及功能性二尖瓣关闭不全均非此杂音"},{"q":"毛细血管搏动征最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","肺动脉瓣狭窄","肺动脉瓣关闭不全","二尖瓣狭窄"],"a":0,"e":"毛细血管搏动征是周围血管征之一，因脉压增大，轻压指甲或口唇黏膜可见红白交替的搏动，最常见于主动脉瓣关闭不全，尚可有枪击音、Duroziez双重杂音。主动脉瓣狭窄与肺动脉瓣狭窄使脉压减小；肺动脉瓣关闭不全与二尖瓣狭窄一般不产生明显周围血管征"},{"q":"下列对肺下界的体表位置描述正确的是","o":["锁骨中线第5肋间隙，腋中线第7肋间隙","锁骨中线第5肋间隙，腋中线第8肋间隙","锁骨中线第6肋间隙，腋中线第7肋间隙","锁骨中线第6肋间隙，腋中线第8肋间隙","锁骨中线第6肋间隙，腋中线第9肋间隙"],"a":3,"e":"平静呼吸时两侧肺下界大致相同，位于锁骨中线第6肋间隙、腋中线第8肋间隙、肩胛线第10肋间隙。锁骨中线第5肋间隙及腋中线第7或第9肋间隙的定位均与正常肺下界不符，偏高或偏低，故只有第6与第8肋间隙的组合正确"},{"q":"诊断过程中，进一步检查的选择原则，下列错误的是","o":["首先考虑可能性小的诊断","首先考虑简易的诊断方法","首先考虑对患者无创的检查","首先考虑证实诊断的措施","首先考虑可能性大的诊断"],"a":0,"e":"进一步检查选择应首先考虑可能性大的诊断，并结合简便、无创及可证实诊断的措施，以提高效率并减少患者负担。优先选择可能性小的诊断违背概率原则，易造成漏诊误诊与资源浪费；先简易方法、先无创检查、先证实诊断的措施均符合诊断思维基本原则"},{"q":"腹部叩诊鼓音，可出现于","o":["穿透性溃疡","不完全肠梗阻","大量腹水","巨大卵巢囊肿","胃肠穿孔"],"a":4,"e":"胃肠穿孔时气体进入腹腔形成气腹，游离气体积聚于膈下，使肝浊音界缩小或消失，鼓音范围明显增大并出现于不应有鼓音的部位，是急腹症的重要体征。穿透性溃疡尚未穿孔时无气腹；不完全肠梗阻以肠鸣音亢进为主；大量腹水与巨大卵巢囊肿叩诊为浊音或实音，均非鼓音"},{"q":"下列情况凝血酶凝固时间延长，但应除外","o":["严重肝脏病","弥散性血管内凝血","血友病","纤维蛋白原少","AT-Ⅲ活性增高"],"a":2,"e":"凝血酶时间（TT）反映纤维蛋白原转变为纤维蛋白的过程，延长见于纤维蛋白原减少、严重肝病、弥散性血管内凝血及抗凝物质如肝素或AT-Ⅲ活性增高。血友病为因子Ⅷ或Ⅸ缺乏，影响内源性凝血途径使APTT延长，但纤维蛋白原与凝血酶时间正常，故不出现TT延长"},{"q":"水肿患者，下列伴随症状中考虑心源性可能性大的是","o":["颜面水肿","肝颈静脉反流征阳性","肝大","腹水","伴胸腔积液和肺部啰音"],"a":1,"e":"肝颈静脉回流征阳性是右心衰竭的特征，压迫淤血肝脏使回心血量增加，而衰竭右心不能接纳，致颈静脉压进一步升高，强烈提示心源性水肿。颜面水肿多见于肾源性；肝大与腹水可由肝病引起；胸腔积液伴肺部啰音也可见于肺源性疾病，均不如肝颈静脉回流征特异"},{"q":"下列情况均可见中性粒细胞增多，除外","o":["高温或严寒","流感","化脓菌引起的感染","手术创伤","脾破裂"],"a":1,"e":"化脓菌感染、手术创伤、高温严寒及脾破裂致组织损伤时，中性粒细胞常反应性增多。流感等病毒感染则相反，白细胞总数与中性粒细胞多减少，淋巴细胞相对增多，故不属于中性粒细胞增多的情况。脾破裂等急性失血与组织坏死可致中性粒细胞增多"},{"q":"主动脉瓣关闭不全合并器质性二尖瓣狭窄时，最有诊断意义的心脏杂音是主动脉瓣区舒张期叹气样杂音加上","o":["肺动脉瓣第二心音亢进","心尖部第一心音亢进","二尖瓣开放拍击音","心尖部舒张期隆隆样杂音","心尖部Austin Flint杂音"],"a":3,"e":"主动脉瓣关闭不全合并器质性二尖瓣狭窄时，除主动脉瓣区舒张期叹气样杂音外，心尖部可闻及舒张期隆隆样杂音，提示同时存在二尖瓣狭窄；它与Austin-Flint杂音不同，后者无开瓣音、S1不亢进。肺动脉瓣第二心音亢进与心尖第一心音亢进仅为伴随体征；二尖瓣开放拍击音提示瓣叶活动好，单独不足以确诊器质性狭窄"},{"q":"下列关于左室舒张早期奔马律的叙述均正确，但应除外","o":["见于器质性心脏病病人","心率常大于100次/min","体位改变时可消失","声音较响，距S2较远","听诊心尖部最清楚"],"a":2,"e":"舒张早期奔马律是病理性额外心音，提示严重器质性心脏病，常见于心力衰竭、急性心肌梗死、重症心肌炎与扩张型心肌病，心率常超过100次/min，音调较低、距S2较远，在心尖区稍内侧听诊最清楚。体位改变时消失是生理性第三心音的特点，坐位或立位时S3可消失，病理性奔马律不因体位改变而消失"},{"q":"缺铁性贫血与铁粒幼细胞贫血的鉴别要点是","o":["血清总铁结合力","骨髓铁染色","红细胞内游离原卟啉测定","血清铁","MCV、MCH、MCHC测定"],"a":1,"e":"缺铁性贫血与铁粒幼细胞贫血均呈小细胞低色素性，鉴别关键在于骨髓铁染色：缺铁性贫血细胞外铁消失、铁粒幼细胞减少，铁粒幼细胞贫血则细胞外铁增多并可见环形铁粒幼细胞。血清铁与总铁结合力虽有差异，但骨髓铁染色最可靠；MCV、MCH、MCHC两者相似，无法鉴别，Rous与Ham试验则用于溶血性疾病"},{"q":"呼吸浅快不易见于","o":["呼吸肌麻痹","严重鼓肠","腹水","肺炎","镇静剂过量"],"a":3,"e":"官方答案为【肺炎】，但依据教材，正确答案为【镇静剂过量】。呼吸浅快见于呼吸肌麻痹、严重肠胀气、腹水及肺炎、胸膜炎等肺部疾病；而麻醉剂或镇静剂过量抑制呼吸中枢，表现为呼吸浅慢，而非浅快。将肺炎排除于呼吸浅快之外与教材相悖，肺炎本身就是浅快的常见病因"},{"q":"免疫性溶血性贫血首选的筛选试验是","o":["Rous试验","Ham试验","Coombs试验","Heinz小体检查","网织红细胞测定"],"a":2,"e":"免疫性溶血性贫血由红细胞表面不完全抗体介导，抗球蛋白试验即Coombs试验可直接检测红细胞表面结合的抗体，是首选筛选试验，阳性见于自身免疫性溶血性贫血与新生儿溶血病。Rous试验检尿含铁血黄素，提示慢性血管内溶血；Ham试验用于阵发性睡眠性血红蛋白尿；Heinz小体与网织红细胞均非免疫性病因特异检查"},{"q":"直肠指检一般能够发现直肠癌总数的","o":["40%～49%","50%～59%","60%～69%","70%～79%","80%～89%"],"a":3,"e":"直肠癌多发生于直肠中下段，位置较低，约70%～79%可通过直肠指检触及，指检是筛查直肠癌简便而重要的方法。40%～69%的比例偏低，低估了指检的检出价值；80%～89%又偏高。故约七成至八成的检出率最符合临床实际"},{"q":"血尿伴尿频、尿急、尿痛，最常见于","o":["急性膀胱炎","肾肿瘤","神经源性膀胱","丝虫病","多囊肾"],"a":0,"e":"血尿伴明显尿频、尿急、尿痛即膀胱刺激征，最常见于急性膀胱炎，因膀胱三角区及后尿道炎症刺激所致，尿液镜检可见炎性细胞。肾肿瘤多为无痛性全程血尿；神经源性膀胱尿频但不伴明显尿痛、镜检无炎性细胞；丝虫病与多囊肾均以其他表现为主，无典型膀胱刺激征"},{"q":"下列触诊肝脏的方法不正确的是","o":["检查者右手中间三指并拢，掌指关节弯曲","被检查者深呼气时，检查者手指压向深部触诊肝脏","被检查者深吸气时，检查者手指向前上触诊肝缘","检查者左手托住被检查者右腰部，拇指置于肋部","有腹水者可应用浮沉触诊法（冲击触诊法）"],"a":0,"e":"单手触诊肝脏时检查者右手四指并拢、掌指关节伸直，与肋缘大致平行置于右上腹，随呼气压向深部、吸气时迎触下移的肝缘，故掌指关节弯曲的描述错误。被检者深呼气时手指向深部、深吸气时向前上触肝缘为正确手法；左手托右腰、拇指置于肋部为双手触诊配合；有腹水者用浮沉触诊法"},{"q":"血清钙的正常参考值为","o":["0.97～1.61mmol/L","1.29～1.94mmol/L","2.25～2.75mmol/L","3.9～5.6mmol/L","9.0～11.0mmol/L"],"a":2,"e":"健康成人血清总钙正常参考范围为2.25～2.75mmol/L，低于2.25mmol/L为低钙血症，高于2.58mmol/L为高钙血症。0.97～1.61及1.29～1.94mmol/L明显偏低，不符合总钙水平；3.9～5.6mmol/L过高；9.0～11.0mmol/L数值单位混乱，均非血清总钙正常值"},{"q":"下列各项是医生用视诊方法了解患者身体局部改变的内容，但不包括哪一项","o":["皮肤","黏膜","舌苔","湿度","毛发"],"a":3,"e":"局部视诊通过肉眼观察了解皮肤、黏膜、眼、舌苔、毛发、头颈、胸廓及腹形等外表的改变。皮肤湿度需用手触摸感知，属触诊内容，不能单凭视诊判断，故为不包括项。皮肤、黏膜、舌苔与毛发均可直接视诊观察其颜色、形态与分布异常"},{"q":"生长发育成熟前腺垂体功能减退可导致","o":["生长激素缺乏性侏儒症","巨人症","呆小病","佝偻病","阉人症"],"a":0,"e":"生长发育成熟前腺垂体功能减退，生长激素分泌不足致体格发育停滞、身材异常矮小，即生长激素缺乏性侏儒症（垂体性侏儒）。巨人症为青春期前腺垂体功能亢进；呆小病为先天性甲状腺功能减退；佝偻病与维生素D缺乏相关；阉人性腺功能减退表现第二性征发育障碍，均非生长激素缺乏所致"},{"q":"急性肾盂肾炎所致腰背痛的特点不包括","o":["伴肾区叩痛","尿检异常","伴有尿频尿急","常伴腰部、腹股沟区绞痛感","伴有高热、寒战等全身中毒症状"],"a":3,"e":"急性肾盂肾炎为肾实质与肾盂的急性感染，表现为发热寒战等全身中毒症状、腰痛与肾区叩痛，伴尿频尿急及尿检异常。腰部并向下放射至腹股沟的剧烈绞痛是肾结石肾绞痛的特点，因输尿管梗阻痉挛所致，并非肾盂肾炎的疼痛性质，故不包括"},{"q":"核左移是指外周血中中性粒细胞","o":["细胞体积变小","细胞核偏位，常常位于左侧","分叶超过5叶以上者超过3%","杆状核粒细胞增多或（和）出现更早阶段的粒细胞","细胞数明显增高"],"a":3,"e":"核左移指外周血中非分叶核中性粒细胞增多，包括杆状核粒细胞及晚幼粒、中幼粒甚至更早期粒细胞，百分率超过5%，提示骨髓造血活跃、感染等应激状态。细胞体积变小、核偏位并非核左移定义；分叶超过5叶者超过3%为核右移；细胞数明显增高仅表示白细胞增多，与核象改变无关"},{"q":"二尖瓣脱垂综合征是指","o":["收缩中期喀喇音合并收缩晚期杂音","收缩晚期喀喇音合并收缩中期杂音","收缩早期喀喇音合并收缩中期杂音","收缩晚期喀喇音合并收缩早期杂音","收缩中期喀喇音合并收缩早期杂音"],"a":0,"e":"二尖瓣脱垂时瓣叶于收缩中、晚期脱入左房，腱索突然拉紧产生喀喇音，多在S1后0.08秒出现者为收缩中期喀喇音；因脱垂伴关闭不全，左室血液反流至左房，继以收缩晚期杂音，二者合成二尖瓣脱垂综合征。收缩早期喀喇音及收缩中期杂音的组合不符合其发生机制"},{"q":"下列为瞳孔的调节反射检查法，哪项不正确","o":["置右手示指于病人视线1m以外处为目标","嘱病人平视1m以外的目标","右手示指慢慢移近病人眼球约20cm处","右手示指迅速移近病人眼球约20cm处","观察病人的瞳孔是否逐渐缩小"],"a":2,"e":"官方答案为【右手示指慢慢移近病人眼球约20cm处】，但依据教材，正确答案为【右手示指迅速移近病人眼球约20cm处】。调节反射检查须嘱病人平视1m以外目标，将示指逐渐缓慢移近眼球至约20cm，观察瞳孔随之逐渐缩小；迅速移近不能引出该反射，属错误操作。置示指于1m以外作目标、观察瞳孔是否逐渐缩小两项均为规范步骤"},{"q":"在心脏杂音产生的主要机制中，应除外哪一项","o":["血流加速","血液黏稠度下降","瓣膜口狭窄或关闭不全","人工瓣膜","心腔内漂浮物"],"a":3,"e":"心脏杂音源于血流由层流转为湍流，主要机制包括血流加速、瓣口狭窄或关闭不全、异常通道及心腔内漂浮物；血液黏稠度下降使雷诺数增大，易形成湍流而产生杂音。人工瓣膜置换后产生的金属瓣膜开闭音属额外心音，并非杂音形成机制。血流加速项指贫血、甲亢等高动力状态，心腔内漂浮物项指赘生物、腱索断裂残端等，均可成为湍流源"},{"q":"尿内尿胆原明显增高是","o":["梗阻性黄疸","肝细胞性黄疸","溶血性黄疸","红细胞寿命正常","体内胆红素生成正常且胆管通畅"],"a":2,"e":"溶血时红细胞大量破坏，非结合胆红素生成过多，肝细胞将其转化为结合胆红素后排入肠道，肠内尿胆原生成增多并被重吸收，故尿胆原明显增高，尿胆红素阴性。梗阻性黄疸结合胆红素反流入血、尿胆红素强阳性而尿胆原减少或缺如。肝细胞性黄疸尿胆原正常或轻度增加。红细胞寿命正常、胆红素生成正常且胆管通畅均属正常代谢，不出现尿胆原明显增高"},{"q":"伤寒的特征性皮疹是","o":["斑疹","玫瑰疹","丘疹","斑丘疹","荨麻疹"],"a":1,"e":"玫瑰疹为鲜红色圆形斑疹，直径2～3mm，系病灶周围血管扩张所致，压之褪色、松开复现，多见于胸腹部，是伤寒与副伤寒的特征性皮疹。斑疹仅局部发红不凸出皮面，见于斑疹伤寒、丹毒。丘疹凸出皮面，见于药物疹、麻疹。斑丘疹为丘疹周围有红晕底盘，荨麻疹为风团样皮疹，均非伤寒特征"},{"q":"下列各项均可出现肝浊音界缩小，但除外","o":["右心功能不全","胃肠穿孔","暴发性肝衰竭","暴发肝炎","肝硬化"],"a":0,"e":"肝浊音界缩小源于肝体积缩小或膈下积气：胃肠穿孔后气体积聚膈下使肝浊音界缩小或消失；暴发性肝衰竭、暴发肝炎致肝细胞大片坏死、肝脏萎缩；肝硬化肝实质纤维化回缩亦可缩小。右心功能不全时肝脏淤血肿大，肝浊音界反而增大，故为除外项。上述机制中气体与实质回缩是两类不同的缩小原因"},{"q":"低血压的定义为血压低于","o":["90/60mmHg","100/60mmHg","90/50mmHg","80/60mmHg","100/50mmHg"],"a":0,"e":"低血压指收缩压低于90mmHg和/或舒张压低于60mmHg，即血压低于90/60mmHg。100/60mmHg与100/50mmHg收缩压未达低血压界值，90/50mmHg仅舒张压偏低而收缩压在界值。诊室血压≥140/90mmHg为高血压阈值，白大衣高血压、隐匿性高血压均以该界值判定，与低血压定义不同"},{"q":"关于成人尿量，下列说法错误的是","o":["24h尿量大于2000ml称为多尿","24h尿量少于400ml称为少尿","24h尿量少于100ml称为无尿","每小时尿量少于17ml称为少尿","正常尿量为每天1000～2000ml"],"a":0,"e":"成人多尿定义为24小时尿量超过2500ml，而非超过2000ml，2000ml仍属正常高限，故该表述错误。24小时尿量少于400ml或每小时少于17ml为少尿，少于100ml为无尿，正常尿量为1000～2000ml/24h。精神性多饮、饮水过多所致属生理性多尿，尿崩症、糖尿病等属病理性多尿，其界值均以2500ml为准"},{"q":"下列缓冲对中哪一对的pH不是7、4","o":["[HCO3－]/[H2CO3]为2mol/L/0.1mol/L","[HCO3－]/[H2CO3]为1mol/L/0.05mol/L","[HPO42－]/[H2PO4-]为2mol/L/0.5mol/L","[HPO42－]/[H2PO4-]为1mol/L0.25mol/L","[HCO3－]/[H2CO3]为1mol/L/0.04mol/L"],"a":4,"e":"按Henderson-Hasselbalch公式，碳酸氢盐缓冲对pKa约6.1，[HCO3-]/[H2CO3]需维持20∶1其pH方为7.4。2mol/L比0.1mol/L与1mol/L比0.05mol/L比值均为20，pH均为7.4。磷酸盐缓冲对pKa约6.8，比值4∶1时pH亦为7.4，2比0.5与1比0.25符合。1mol/L比0.04mol/L比值为25，pH约7.5，故不是7.4"},{"q":"下列是构成心脏左界的成分，但应除外","o":["主动脉结","肺动脉段","升主动脉根部","左心房","左心室"],"a":2,"e":"心脏左界自主动脉结、肺动脉段、左心耳延续至左心室，构成左界主要成分。升主动脉根部位于胸骨右缘第2肋间水平，参与构成心脏右界上部而非左界。右界第2肋间为升主动脉与上腔静脉，第3肋间以下为右心房。左心房增大使心腰消失、心界呈梨形，主动脉结突出则使左界上部外移，均为左界改变的典型表现"},{"q":"中输尿管点的位置是在","o":["髂前上棘水平腹直肌外缘","脐水平线上腹直肌外缘","腹直肌外缘与肋弓交点","右侧位置稍低相当于肾盂位置","相当于输尿管第一狭窄处"],"a":0,"e":"中输尿管点位于髂前上棘水平腹直肌外缘，相当于输尿管第二狭窄处，压痛提示输尿管结石等病变。脐水平线上腹直肌外缘为上输尿管点，对应第一狭窄；腹直肌外缘与肋弓交点为季肋点。右侧位置稍低、相当于肾盂位置的是肋脊点附近的肾脏投影，并非中输尿管点"},{"q":"下消化道内镜检查的并发症不包括","o":["术后发热","肠穿孔","肠出血","肠系膜裂伤","心脑血管意外"],"a":0,"e":"下消化道内镜检查并发症以肠穿孔、肠出血、肠系膜裂伤及心脑血管意外为主，均与注气、活检、牵拉或病人基础状态相关。术后发热多见于支气管镜检查后，可继发肺部细菌感染甚至败血症，不属结肠镜常规并发症。穿孔多因活检过深或注气压力过高，出血与电凝切除相关，心脑血管意外与检查中迷走神经刺激及紧张有关"},{"q":"下列各项为真性内脏痛，但应除外","o":["钝痛","酸痛","烧灼痛","刺痛","绞痛"],"a":2,"e":"真性内脏痛由内脏神经传导，多为钝痛、酸痛、绞痛等，定位模糊，常伴恶心、出汗等自主神经反应。烧灼痛系黏膜受化学刺激或神经末梢受累所致，见于食管炎、带状疱疹及肋间神经痛，属假性内脏痛或躯体痛范畴。钝痛、酸痛、绞痛分别与空腔脏器痉挛、实质脏器包膜张力及平滑肌强烈收缩相关，均属真性内脏痛"},{"q":"下列各项均是肝脏检查内容，但除外","o":["肝下缘位置","质地","表面","搏动","Mc Burney点压痛"],"a":4,"e":"肝脏检查包括测量肝下缘位置、质地、表面形态及有无搏动等，均以触诊与叩诊完成。McBurney点位于右下腹，是阑尾根部的体表投影，其压痛为急性阑尾炎的重要体征，属阑尾检查内容。肝下缘位置反映肝大小，质地硬提示肝硬化或肝癌，表面结节提示肝癌，肝搏动则提示三尖瓣关闭不全等"},{"q":"腹部检查时发现胆囊肿大，无压痛，但伴有皮肤巩膜明显黄染，首先考虑的病变是","o":["胰头癌","胰体癌","急性胆囊炎","急性胆管炎","急性黄疸性肝炎"],"a":0,"e":"胆总管梗阻致胆汁排入肠道受阻，结合胆红素反流入血造成皮肤巩膜黄染；胆管内压力持续升高使胆囊被动扩张，因无急性炎症故无压痛，此即Courvoisier征阳性，最常见于胰头癌。胰体癌远离胆总管，多无黄疸。急性胆囊炎、急性胆管炎均有明显右上腹压痛。急性黄疸性肝炎肝细胞受损，胆囊不肿大"},{"q":"S1强弱不等可见于下列情况，但除外","o":["窦性心动过速","室性心动过速","心房颤动","频发期前收缩","三度房室传导阻滞"],"a":0,"e":"第一心音强弱不等源于心室收缩间期与房室瓣位置的不恒定，见于心房颤动、三度房室传导阻滞、频发期前收缩及室性心动过速，后者可出现大炮音。窦性心动过速心律规整、PR间期恒定，每搏S1强度基本一致，故为例外。房颤时RR间期长短不一使S1强弱变化，三度房室阻滞心房心室几乎同步收缩时S1显著增强"},{"q":"有关诊断思维的基本原则，不正确的是","o":["首先考虑常见病与多发病","应当考虑当地流行和发生的传染病与地方病","首先应考虑器质性疾病","首先应考虑可治性疾病","尽量考虑少发病的常见表现而不是常见疾病的特别表现"],"a":4,"e":"临床诊断思维要求首先考虑常见病、多发病，兼顾当地流行病学，先考虑器质性与可治性疾病。正确原则是尽量用常见病的常见表现解释病情，而非以少发病的常见表现替代常见病的特殊表现。后者违背概率分布基本原理，会显著增加误诊率。按常见病优先、先器质后功能、先可治后难治的顺序构建鉴别诊断，是减少失误的核心方法"},{"q":"反映肝硬化肝脏合成功能减退的指标是","o":["碱性磷酸酶","丙氨酸氨基转移酶","乳酸脱氢酶","白蛋白","γ谷氨酰转肽酶"],"a":3,"e":"血清总蛋白与全部白蛋白均由肝脏合成，白蛋白半衰期约19～21天，其血中浓度直接反映肝脏合成功能；肝硬化时功能性肝细胞减少，白蛋白降低。碱性磷酸酶、γ谷氨酰转肽酶主要反映胆道梗阻或胆汁淤积。丙氨酸氨基转移酶反映肝细胞损伤，乳酸脱氢酶特异性低，均不直接体现合成功能"},{"q":"方肩最常见于","o":["肩关节脱位","先天性肩胛高耸症","脊柱侧弯","锁骨骨折","外伤性肩锁关节脱位"],"a":0,"e":"肩关节脱位时肱骨头脱出关节盂，肩峰异常突出，肩部正常弧形轮廓消失而呈方形，称方肩，常伴Dugas征阳性。先天性肩胛高耸症与脊柱侧弯表现为双肩一高一低、颈短耸肩。锁骨骨折远端下垂、局部畸形如戴肩章状，见于外伤性肩锁关节脱位，均不形成方肩。三角肌萎缩也可致方肩，但无外伤及弹性固定"},{"q":"抗凝血酶Ⅲ活性增高见于","o":["妊娠","新生儿","弥散性血管内凝血","血友病","脑梗死"],"a":3,"e":"抗凝血酶Ⅲ属于生理性抗凝因子，血友病、白血病及再生障碍性贫血急性出血期可增高，口服抗凝药治疗亦可见增高。妊娠、新生儿及弥散性血管内凝血、脑梗死等血栓前状态多为抗凝血酶Ⅲ减低，因为凝血激活中抗凝血酶被大量消耗。血友病为凝血因子缺乏，抗凝因子相对升高，故与其他选项方向相反"},{"q":"代谢性酸中毒时","o":["NaHCO3/H2CO3＜20/1，继发性H2CO3↑","NaHCO3/H2CO3＞20/1，继发性H2CO3↑","NaHCO3/H2CO3＜20/1，继发性H2CO3↓","NaHCO3/H2CO3＞20/1，继发性H2CO3↓","NaHCO3/H2CO3＜10/1，继发性H2CO3↓"],"a":2,"e":"代谢性酸中毒以HCO3-原发性减少为特征，[NaHCO3]/[H2CO3]比值小于20/1致pH下降；机体通过深快呼吸排出CO2代偿，使继发性H2CO3降低。比值大于20/1是代谢性碱中毒的改变。继发性H2CO3升高则提示呼吸性酸中毒或代谢性碱中毒的呼吸代偿，与代酸方向相反。比值小于10/1并非代酸的诊断界值"},{"q":"发热激活物又称EP诱导物，包括","o":["IL-1和TNF","CRH和NOS","内生致热原和某些体外代谢产物","前列腺素和其体内代谢产物","外致热原和某些体内产物"],"a":4,"e":"发热激活物又称EP诱导物，包括外致热原与某些体内产物，前者如细菌、病毒及其毒素、炎性渗出物，后者如抗原抗体复合物、类固醇代谢产物。IL-1、TNF属内源性致热原，由激活的免疫细胞产生，并非激活物本身。CRH、NOS及前列腺素为发热中枢介质或调节物。外源性致热原须经激活产EP细胞才能引起发热"},{"q":"有关病历书写不正确的是","o":["首次病程由经管的住院医师书写","病程记录一般可2～3天记录1次","危重病人需每天或随时记录","会诊意见应记录在病历中","不需要记录各项检查结果及分析意见"],"a":4,"e":"病程记录须包含病情变化、重要辅助检查结果及分析意见、上级医师查房与会诊意见、诊疗措施及效果等，不得省略检查结果及分析。首次病程记录由经管的住院医师或值班医师书写，一般2～3天记录一次，危重病人每天或随时记录，会诊意见亦应记录。省略检查结果与分析违背病程记录真实、及时、完整的要求"},{"q":"关于尿胆红素测定，下列叙述正确的是","o":["正常可出现阳性反应","肝细胞黄疸时，尿胆红素中度增加","梗阻性黄疸时，尿胆红素阴性","溶血性黄疸时，尿胆红素明显增加","严重肾损伤时，尿胆红素明显增加"],"a":1,"e":"结合胆红素为水溶性，血中升高时可经尿排出，肝细胞性黄疸时肝细胞摄取、结合与排泄均受损，血中结合胆红素中度增加，尿胆红素呈阳性即中度增加。正常人尿胆红素阴性。梗阻性黄疸结合胆红素明显升高，尿胆红素强阳性。溶血性黄疸以非结合胆红素升高为主，不通过肾脏，尿胆红素阴性。严重肾损伤不影响胆红素代谢"},{"q":"下列左心衰竭时呼吸困难的描述，错误的是","o":["主要是体循环淤血所致","可出现阵发性呼吸困难","多在夜间睡眠时发生","重者气喘、出汗、有哮鸣音","重者两肺底部有湿啰音"],"a":0,"e":"左心衰竭呼吸困难源于肺淤血、肺泡张力增高及肺循环压力升高，可表现为劳力性、夜间阵发性呼吸困难与端坐呼吸，重者气喘、出汗、哮鸣音及两肺底湿啰音。体循环淤血是右心衰竭呼吸困难的主要机制，而非左心衰竭。阵发性、夜间发作与重者肺部啰音均为左心衰竭肺淤血的典型表现"},{"q":"全腹肌紧张触之如板状腹，见于","o":["急性弥漫性腹膜炎","急性胆囊炎","急性肠炎","急性胃炎","结核性腹膜炎"],"a":0,"e":"急性胃肠穿孔或脏器破裂致急性弥漫性腹膜炎，胃酸、肠液强烈刺激腹膜引起腹肌痉挛，腹壁强直硬如木板，称板状腹。急性胆囊炎体征局限于右上腹，Murphy征阳性。急性肠炎、胃炎无腹膜刺激征，腹壁柔软。结核性腹膜炎发展缓慢，腹壁呈柔韧感而非板状硬"},{"q":"心电图ST段抬高出现于心肌梗死的","o":["超级损伤期","急性期","亚急性期","陈旧期","全程"],"a":1,"e":"急性心肌梗死心电图演变中，急性期以ST段弓背向上型抬高为突出表现，并逐步出现病理性Q波与T波倒置。超急性期以高大直立T波与ST段上斜型抬高为主，持续时间短暂。亚急性期抬高的ST段已恢复至基线，以坏死Q波与缺血性T波演变为特征。陈旧期ST段与T波恢复正常或恒定倒置，仅残留Q波"},{"q":"心电图V1、V2导联R波≥0.04秒和R/S≥1且T波正向，提示心肌梗死部位为","o":["前壁","侧壁","广泛前壁","下壁","后壁"],"a":4,"e":"正后壁心肌梗死时V7～V9导联出现异常Q波，对应性改变表现为V1、V2导联R波增高、R/S≥1、R波宽≥0.04秒及T波高大直立。前壁梗死在V3～V5出现异常Q波，广泛前壁为V1～V5，下壁在Ⅱ、Ⅲ、aVF，侧壁在Ⅰ、aVL、V5、V6。V1、V2的R波高大与T波正向恰是后壁梗死的镜像改变，其余部位均无此表现"},{"q":"增生性脊柱炎的腰背痛特点不正确的是","o":["多见于50岁以上的患者","晨起感腰痛，酸胀、僵直","过多活动后腰痛减轻","疼痛以傍晚明显","腰椎无明显压痛"],"a":2,"e":"增生性脊柱炎多见于50岁以上，晨起腰痛、酸胀、僵直，活动后减轻，但活动过多则加重，傍晚明显，平卧缓解，叩击腰部反有舒适感。过多活动后腰痛减轻仅见于晨起初次活动，持续或过量活动必使疼痛再加重，故该表述错误。其腰椎无明显压痛、无神经根刺激征，可与强直性脊柱炎及腰椎间盘突出鉴别"},{"q":"检查抗核抗体常用方法是","o":["直接荧光抗体试验","间接荧光抗体试验","胶乳凝集试验","ELISA法","免疫比浊法"],"a":1,"e":"抗核抗体筛查以间接荧光抗体试验为常用方法，用HEp-2细胞等基质检测血清中自身抗体并观察荧光核型，均质型、颗粒型等对应不同抗原。直接荧光抗体试验多用于衣原体等病原体抗原检测。胶乳凝集试验常用于类风湿因子，ELISA与免疫比浊法用于定量检测特定抗体，均非ANA常规筛查手段"},{"q":"书写日常病程记录时，对病情稳定的患者，至少（ ）天记录一次病程记录","o":["1","2","3","4","5"],"a":2,"e":"日常病程记录对病情稳定病人至少每3天记录一次；病危者随病情变化随时记录、每天至少一次，病重者至少2天一次。首次病程记录须在入院8小时内完成。以1天或2天作为稳定病人的最低频次过密，4天以上则过疏，均不符合规范。频次差异体现病情轻重与记录及时性的要求"},{"q":"反映远曲小管和集合管功能的试验是","o":["浓缩稀释试验","PSP排泄试验","血肌酐尿素测定","内生肌酐清除率","同位素肾图"],"a":0,"e":"浓缩稀释试验通过测定昼夜尿量与尿比密，评估远端肾小管稀释功能与集合管浓缩功能，是反映远曲小管和集合管功能的经典试验。PSP排泄试验与内生肌酐清除率、血肌酐尿素测定主要反映肾小球滤过功能或肾血浆流量。同位素肾图用于分肾功能及尿路梗阻判断，不专门评价肾小管浓缩稀释"},{"q":"气管移向患侧的疾病是","o":["肺实变","肺气肿","胸腔积液","气胸","胸膜粘连"],"a":4,"e":"一侧胸膜粘连、增厚或肺不张时，患侧胸腔容积缩小、负压增大，牵拉气管与纵隔移向患侧。胸腔积液、气胸使患侧压力增高，将气管推向健侧，是移向健侧的典型原因。肺实变、肺气肿一般不引起气管明显移位。故气管移向患侧与移向健侧的病变方向相反，是判断胸膜腔压力变化的重要体征"},{"q":"下列哪种情况导致QT间期延长的可能最小","o":["服用西沙比利","服用阿奇霉素","血钾2.8mmol/L","血钠160mmol/L","伊布利特复律治疗"],"a":3,"e":"QT间期延长与心肌复极延迟相关，西沙比利、阿奇霉素及伊布利特均可阻滞钾通道、延长动作电位时程而致QT延长；血钾2.8mmol/L低钾同样使复极延迟、QT延长。血钠160mmol/L主要影响渗透压与神经精神状态，对心室复极时程影响很小，故致QT延长可能最小。临床纠正低钾、低镁是预防尖端扭转型室速的关键"},{"q":"关于肾脏正常位置，正确的是","o":["肾上极相当于第10胸椎","肾下极相当于第4腰椎","肾门对第12胸椎平面","在后腹膜前","右肾较左肾约低1～2cm"],"a":4,"e":"正常人右肾较左肾低1～2cm，因肝脏占据右上腹使右肾位置下移。肾上极约平第11胸椎、下极约平第2腰椎，肾门平第1腰椎水平，故肾上极相当第10胸椎、下极相当第4腰椎、肾门对第12胸椎均不准确。肾脏位于腹膜后隙而非后腹膜前方，此解剖关系亦为定位要点"},{"q":"35岁男性，腹痛半个月，既往史应关注的问题，除外","o":["有无肝炎病史","有无胆囊炎病史","有无腹部手术史","有无过敏史","有无恶心、呕吐史"],"a":4,"e":"既往史着重询问与当前疾病可能相关的既往疾病、手术及过敏情况，肝炎史、胆囊炎史、腹部手术史均与腹痛病因相关，过敏史亦属必须记录的内容。恶心、呕吐是本次发病的伴随症状，属现病史范畴，不应列入既往史。将现病史症状混入既往史会混淆发病时序，影响诊断判断"},{"q":"不常见腕关节变形的疾病是","o":["尺神经损伤","强直性脊柱","骨折","腱鞘囊肿","桡神经损伤"],"a":1,"e":"腕关节变形常见于桡神经损伤所致腕垂症、尺神经损伤所致爪形手、骨折所致餐叉样畸形及腱鞘囊肿局部隆起。强直性脊柱炎主要累及脊柱与骶髂关节，表现为脊柱弧形后凸与强直固定，较少形成腕关节特征性畸形。其外周关节受累以髋、肩等大关节为主，故为不常见腕关节变形的疾病"},{"q":"低热的体温在","o":["37.2～38℃","37.3～38℃","37.3～38、1℃","37.2～38、1℃","37.1～38℃"],"a":1,"e":"以口腔温度为标准，低热为37.3～38℃，中等度热38.1～39℃，高热39.1～41℃，超高热41℃以上。37.2℃尚未达低热下限，38.1℃已进入中等度热范围，故37.2～38℃与37.1～38℃均不符合分度标准。发热分度用于判断病情严重程度与处理优先级，界限值须严格掌握"},{"q":"二尖瓣狭窄第一心音亢进是因为","o":["心脏开始收缩时，二尖瓣前叶处于最低位置","心脏开始收缩时，二尖瓣后叶关闭延迟","心脏收缩力加强","二尖瓣前叶增厚","乳头肌功能失调"],"a":0,"e":"二尖瓣狭窄时左室充盈受限以减少，心室开始收缩时二尖瓣前叶处于最低位置，收缩时室内压上升迅速，瓣膜关闭振动幅度大，故第一心音亢进。后叶关闭延迟、前叶增厚或乳头肌功能失调均非此机制；前叶显著纤维化、钙化时瓣叶僵硬，S1反而减弱。心肌收缩力增强如高热、贫血、甲亢亦可致S1增强，但机制不同"},{"q":"下列心音均属于舒张期额外心音，但除外","o":["肿瘤扑落音","开瓣音","奔马律","肺动脉喷射音","四音律"],"a":3,"e":"舒张期额外心音包括开瓣音、奔马律、心包叩击音及肿瘤扑落音等，均出现于第二心音之后。肺动脉喷射音即收缩早期喀喇音，紧接第一心音后0.05～0.07秒出现，属收缩期额外心音。四音律为舒张早期与晚期奔马律并存。开瓣音位于S2后0.05～0.06秒，是二尖瓣狭窄瓣膜柔软的标志"},{"q":"主动脉瓣听诊区第二心音增强，最常见于","o":["二尖瓣狭窄","二尖瓣关闭不全","高血压","左心功能不全","主动脉瓣关闭不全"],"a":2,"e":"主动脉瓣区第二心音即A2增强最常见于高血压与主动脉硬化，因主动脉压升高使主动脉瓣关闭有力、振动增强。二尖瓣狭窄主要致P2亢进，病变在肺动脉瓣区。二尖瓣关闭不全使A2减弱。左心功能不全多表现为S1减弱与舒张早期奔马律。主动脉瓣关闭不全时A2减弱而非增强，杂音为舒张期叹气样"},{"q":"下列体征适用于深部触诊法检查，除了","o":["胆囊点压痛","乙状结肠包块","板状腹","大量腹水时的肝脏冲击触诊","阑尾点反跳痛"],"a":2,"e":"深部触诊法包括深部滑行、双手、深压及冲击触诊，用于腹腔深部病变与脏器：乙状结肠包块用深部滑行触诊，大量腹水时肝脏用冲击触诊，胆囊点压痛与阑尾点反跳痛用深压触诊。板状腹是急性弥漫性腹膜炎时腹肌痉挛所致的腹壁强直，属腹壁紧张度检查，并非深部触诊法的适用体征"},{"q":"不含血红素的物质是","o":["肌红蛋白","铜蓝蛋白","血红蛋白","细胞色素酶","过氧化物酶"],"a":1,"e":"血红素为辅基存在于肌红蛋白、血红蛋白、细胞色素酶及过氧化物酶中，均属含血红素蛋白。铜蓝蛋白为肝细胞合成的单链糖蛋白，电泳位于α2球蛋白区，以铜离子为辅基参与铜代谢，不含血红素。其与转铁蛋白、结合珠蛋白同属血清运输蛋白，在抗原特异性上存在差异"},{"q":"Kussmaul呼吸是指","o":["剧烈运动，呼吸深快","酮症酸中毒深长呼吸","呼吸衰竭潮式呼吸","巴比妥中毒间停呼吸","忧郁叹息样呼吸"],"a":1,"e":"Kussmaul呼吸即酸中毒深大呼吸，严重代谢性酸中毒时细胞外液HCO3-不足、pH降低，通过深快呼吸排出CO2代偿，见于糖尿病酮症酸中毒与尿毒症酸中毒。剧烈运动呼吸深快为生理性反应。潮式呼吸见于呼吸衰竭、脑部病变。间停呼吸多因巴比妥类药物中毒抑制呼吸中枢。叹息样呼吸常见于忧郁、焦虑等功能性状态"},{"q":"图像中的ECG诊断不考虑下列哪一项","o":["一度房室传导阻滞","病理性Q波","频发室性期前收缩","多源性室性期前收缩","急性心肌梗死"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。宽QRS波心动过速的鉴别在于室性期前收缩能否确认：频发、多源性室早表现为提前出现的宽大畸形QRS，一度房室传导阻滞为PR间期延长，病理性Q波提示心肌坏死，这些均可从心电图直接判读。急性心肌梗死的诊断须结合ST段弓背抬高及动态演变、异常Q波定位与心肌损伤标志物，单凭缺乏图像的描述无法确认，故为不予考虑项\n\n官方题库中缺失图片"},{"q":"关于肺前界的叩诊，正确的是","o":["正常肺前界相当于心的相对浊音界","右肺前界相当于胸骨旁2cm的位置","左肺前界相当于胸骨线第4～6肋间隙位置","心脏扩大时，左右两肺前界间浊音区扩大","肺气肿时，左右两肺前界间浊音区扩大"],"a":3,"e":"心脏扩大时心浊音界增宽，使左右肺前界之间浊音区相应扩大，是肺前界叩诊的正确应用。正常肺前界相当于心的绝对浊音界而非相对浊音界；右肺前界相当于胸骨线、非胸骨旁2cm；左肺前界位于胸骨旁线第4～6肋间隙。慢性阻塞性肺疾病、肺气肿时心界变小，两肺前界间浊音区缩小而非扩大"},{"q":"杂音最响的部位，主要取决于","o":["瓣膜的解剖位置及其在体表投影的一致性","瓣膜损害的程度","杂音产生的部位及血流方向","呼吸的影响","体位的改变"],"a":2,"e":"杂音最响部位取决于杂音产生的部位及血流方向，如心尖部最响提示二尖瓣病变，主动脉瓣区最响提示主动脉瓣病变，胸骨左缘第3、4肋间粗糙收缩期杂音提示室间隔缺损。瓣膜损害程度决定杂音强度与时限，不决定最响部位。呼吸与体位通过改变回心血量影响杂音强弱，亦非主要决定因素"},{"q":"心脏叩诊时卧位时较立位时心底部浊音区增宽，常见于","o":["全心衰竭","心肌病","心包积液","心肌炎","上纵隔肿物"],"a":2,"e":"心包积液时心浊音界向两侧扩大且随体位改变：坐位呈三角形烧瓶样、心尖部增宽，卧位时液体回流使心底部浊音界增宽。全心衰竭、心肌病、心肌炎所致心界扩大为器质性心腔增大，不随体位明显变化。上纵隔肿物可使上纵隔增宽，但无心包积液体征与心音遥远等表现"},{"q":"下腔静脉阻塞时，腹壁静脉的血流方向是","o":["脐以上，静脉血流自下向上","脐以上，静脉血流自上向下","脐以下，静脉血流自上向下","脐上、下，静脉血流自下向上","脐上、下，静脉血流自上向下"],"a":3,"e":"下腔静脉阻塞时，脐水平以上与以下的腹壁静脉血流方向均转流向上，即自下而上，以绕过阻塞段经上腔静脉回流。正常时脐以上自下而上、脐以下自上而下。上腔静脉阻塞则相反，脐上、下血流均自上而下，经下腔静脉回流。门静脉高压时血流以脐为中心向四周放射，形成水母头，方向判读是鉴别关键"},{"q":"患者，男，38岁，超声心动图显示二尖瓣脱垂。查体可发现","o":["收缩早期喀喇音","开瓣音","收缩前期奔马律","收缩中晚期喀喇音","舒张中晚期喀喇音"],"a":3,"e":"二尖瓣脱垂时瓣叶于收缩中晚期脱入左房、腱索突然拉紧产生振动，形成收缩中晚期喀喇音，可伴收缩晚期杂音，称二尖瓣脱垂综合征。收缩早期喀喇音为主动脉或肺动脉瓣开放受限所致，紧接S1出现。开瓣音位于舒张早期S2后，是二尖瓣狭窄表现。奔马律为舒张期额外心音，均与瓣膜脱垂机制无关"},{"q":"合成补体的主要细胞是","o":["骨髓细胞和胸腺细胞","骨髓细胞和B细胞","胸腺细胞和B细胞","T细胞和B细胞","肝细胞、巨噬细胞"],"a":4,"e":"补体成分主要由肝细胞合成，巨噬细胞亦可产生，是血清补体的主要来源。骨髓与胸腺为免疫细胞分化成熟场所，不合成补体。B细胞、T细胞产生抗体与细胞因子而非补体。胸腺细胞参与T细胞发育，与补体合成无关。肝功能衰竭时补体水平下降，佐证肝脏的合成地位"},{"q":"下列均为胆囊肿大的体征，除外","o":["右上腹压痛","梨形或圆形肿物","随呼吸移动","自左向右蠕动","囊性感"],"a":3,"e":"胆囊肿大表现为右上腹梨形或圆形肿物，随呼吸上下移动，触之有囊性感，伴压痛提示急性胆囊炎、胆总管梗阻等。自左向右蠕动是胃蠕动波的方向，由左肋缘下缓慢推向幽门区，属胃梗阻体征，与胆囊无关。胆囊肿大不产生蠕动波"},{"q":"正常人的血钾浓度（mmol/L）为","o":["3","5","6","7","7.5"],"a":1,"e":"正常血清钾浓度为3.5～5.5mmol/L，选项所列的3偏低、6、7及7.5均属高钾范围，只有5在正常区间内。高钾时可见T波高尖、QT缩短，超过6.5mmol/L则QRS增宽、PR与QT延长。低钾则致T波低平、U波增高与QT延长。血钾测定是心律失常、高血压及利尿剂使用者的重要监测项目"},{"q":"关于心前区震颤的叙述，下列哪项是正确的","o":["狭窄越重，杂音越强","有震颤则肯定有器质性心脏病","一般情况下，震颤的强弱与血流速度成反比","震颤是视诊时看到的一种细小振动","只有瓣膜口狭窄才产生震颤"],"a":1,"e":"震颤为触诊所得的细小振动，其产生提示器质性心脏病，见于狭窄性瓣膜病、先天性心血管病及重度房室瓣关闭不全，凡触及震颤多可闻及响亮杂音。震颤强弱与血流速度成正比而非反比，重度狭窄时血流减少杂音反而减弱。震颤属触诊而非视诊体征，且瓣膜关闭不全、室缺、动脉导管未闭亦可产生，并非仅见于瓣口狭窄"},{"q":"诊断肝纤维化最有意义的指标是","o":["MAO（单胺氧化酶）","GGT","ALT","AFP","ALP"],"a":0,"e":"单胺氧化酶及脯氨酰羟化酶活性与肝纤维组织增生相关，肝脏纤维化时血清MAO升高，中重度慢性肝炎约半数升高，是诊断肝纤维化最有意义的指标。ALT主要反映肝细胞损伤，GGT与ALP反映胆道梗阻或胆汁淤积，AFP为肝癌标志物，均不直接指示纤维化程度"},{"q":"对多话与唠叨的患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":2,"e":"对多话与唠叨的病人，应分次进行问诊并告知问诊内容与时间限制，以礼貌、诚恳的方式控制节奏，避免遗漏重点。适当鼓励讲述感受适用于有顾虑者。坦然、理解、不卑不亢的态度用于愤怒与敌意病人。语言通俗、必要重复适用于理解力差者。由家属代述会丧失病人第一手信息，均非该情形的处理原则"},{"q":"某些典型症状的鉴别诊断可利用诊断流程图，这属于哪种临床思维方式","o":["演绎推理","归纳推理","类比推理","模式识别","横向列举"],"a":0,"e":"诊断流程图以二分法逐步展开，把病人主要临床表现代入预设提纲逐项排查，属从一般性原理推论个别结论的演绎推理，又称逻辑树。归纳推理由个别事实概括一般规律。类比推理据相似性疾病推断。模式识别为直觉性整体判断。横向列举仅为罗列鉴别可能，不具备层次推理结构"},{"q":"中度昏迷与深度昏迷最有价值的鉴别是","o":["对各种刺激均无反应","眼球无转动","大小便失禁","肌张力增高","深浅反射均消失"],"a":4,"e":"深昏迷时深、浅反射均消失，对任何强刺激无反应，肌张力低下，生命体征可有改变；中度昏迷对强刺激可有防御反应，角膜反射、瞳孔对光反射及深反射仍存在。眼球无转动、大小便失禁在二者均可出现，无鉴别价值。深浅反射是否存在是区分昏迷深度最具价值的体征"},{"q":"关于第一心音的正确叙述中，应除外","o":["标志着心室收缩的开始","房室瓣突然关闭瓣叶突然紧张引起的振动","第一心音与心尖冲动同时出现","半月瓣突然关闭引起瓣膜振动","第一心音在心尖部听诊最清楚"],"a":3,"e":"第一心音标志心室收缩开始，由二尖瓣与三尖瓣关闭、瓣叶突然紧张振动产生，音调低钝、历时约0.1秒，与心尖冲动同步，心尖部听诊最清楚。半月瓣突然关闭及血流在主动脉、肺动脉内减速引起振动是第二心音的产生机制，不属于第一心音。房室瓣关闭形成S1的第二、三成分，半月瓣开放仅参与S1形成"},{"q":"下列疾病脉压减低的是","o":["严重贫血","甲状腺功能亢进症","主动脉瓣关闭不全","缩窄性心包炎","动脉导管未闭"],"a":3,"e":"缩窄性心包炎因心脏舒张受限、每搏输出量下降，收缩压降低而舒张压相对升高，脉压减小，伴奇脉与颈静脉怒张。严重贫血、甲状腺功能亢进、动脉导管未闭及主动脉瓣关闭不全均因高动力状态或舒张期反流使脉压增大，可见水冲脉、毛细血管搏动等周围血管征，方向截然不同"},{"q":"水冲脉最常见于下列何种疾病","o":["甲状腺功能亢进症","贫血","高热","主动脉瓣关闭不全","主动脉瓣狭窄"],"a":3,"e":"主动脉瓣关闭不全时舒张期主动脉血液反流入左室，舒张压显著下降而收缩压因每搏量增加而升高，脉压增大，出现水冲脉、De-Musset征、毛细血管搏动及枪击音等周围血管征。甲状腺功能亢进、贫血、高热虽也可致脉压增大，但非水冲脉最常见病因。主动脉瓣狭窄脉压减小，无此表现"},{"q":"下列哪项是收缩期额外心音","o":["奔马律","开瓣音","喀喇音","心包叩击音","肿瘤扑落音"],"a":2,"e":"喀喇音为收缩期额外心音，包括收缩早期喷射音及收缩中晚期二尖瓣脱垂喀喇音。奔马律、开瓣音、心包叩击音与肿瘤扑落音均出现于舒张期，其中开瓣音位于S2后0.05～0.06秒，是二尖瓣狭窄瓣叶柔软的标志。肿瘤扑落音出现于S2后0.08～0.12秒且随体位改变。收缩期与舒张期额外心音的分界以S2为标志"},{"q":"细胞内液的主要阳离子是","o":["Na＋","Mg2＋","K＋","Ca2＋","Mn2＋"],"a":2,"e":"细胞内液主要阳离子为K+，约98%的钾分布于细胞内，是维持细胞内渗透压、静息膜电位与酶活性的关键离子。Na+是细胞外液主要阳离子，Cl-为细胞外液主要阴离子。Mg2+虽在细胞内含量较多但居次位，Ca2+主要储存于肌浆网与骨，Mn2+为微量元素，均非细胞内液主要阳离子"},{"q":"一患者以斜颈、垂肩来诊，查双肩抬肩动作减弱。此见于","o":["舌咽神经损伤","前庭神经损伤","迷走神经损伤","副神经损伤","面神经损伤"],"a":3,"e":"副神经为第Ⅺ对脑神经，支配胸锁乳突肌与斜方肌，损伤后胸锁乳突肌麻痹致斜颈，斜方肌麻痹致垂肩、抬肩及耸肩动作减弱。舌咽神经支配舌后1/3感觉与味觉，迷走神经支配咽喉肌与内脏，面神经支配面部表情肌，前庭神经司平衡，损伤后均不出现斜颈与垂肩"},{"q":"下列哪项不是手术同意书包含的内容","o":["术前诊断","上级医师查房意见","术中或术后可能出现的并发症、手术风险","手术名称","患者签署意见并签名"],"a":1,"e":"手术同意书须载明术前诊断、手术名称、术中或术后可能出现的并发症与风险、患者签署意见并签名等内容，体现知情同意。上级医师查房意见属病程记录范畴，记录病情分析与诊疗计划，不列入手术同意书。二者文书性质与签署对象不同，前者为告知文件，后者为医疗过程记录"},{"q":"腹部胀大在耻骨上方叩诊出现弧形上缘凹向脐部的浊音区，应见的病征是","o":["尿潴留","腹水","妊娠子宫","子宫肌瘤","卵巢囊肿"],"a":1,"e":"腹腔积液在耻骨上方叩诊呈浊音区，其弧形上缘凹向脐部，因液体随体位向两侧流动、中央脐部相对翘起。膀胱胀大时浊音区弧形上缘凸向脐部，排尿或导尿后浊音转鼓音可资鉴别。妊娠子宫、子宫肌瘤及卵巢囊肿均可致该区浊音，但形态与妇科检查、超声不同，且无移动性浊音"},{"q":"有关叩诊方法的叙述，下列错误的是","o":["叩诊胸部时可取坐位或卧位","叩诊腹部时常取仰卧位","确定有无腹水或腹水量很少时，可嘱患者取肘膝位","一般叩诊可达到的深度约为2～3cm","有直接叩诊法和间接叩诊法两种"],"a":3,"e":"一般叩诊可达到的深度约5～7cm，过浅的叩诊力量不能探及深部病灶，故2～3cm的说法错误。叩诊胸部可取坐位或卧位，腹部常取仰卧位，腹水少量时取肘膝位叩诊。叩诊分直接叩诊法与间接叩诊法，后者更常用，操作时应注意对称部位比较及震动感差异"},{"q":"病原菌侵入血流并在其中大量繁殖，产生毒性代谢产物，引起严重的全身中毒症状，称为","o":["毒血症","败血症","菌血症","脓毒血症","内毒素血症"],"a":1,"e":"败血症指病原菌侵入血流并大量繁殖、产生毒性代谢产物，引起寒战、高热、毒血症症状及多器官损害，血培养可阳性。毒血症仅为毒素入血而无细菌在血中繁殖。菌血症为细菌一过性入血、无明显中毒症状。脓毒血症伴迁徙性脓肿。内毒素血症仅指内毒素入血，均不等同于败血症"},{"q":"下列血浆离子浓度的变化能帮助诊断代谢性碱中毒的是","o":["[HCO3－]升高，伴有[K＋]下降，[Cl－]相对下降","[HCO3－]升高，伴有[K＋]升高，[Cl－]相对下降","[HCO3－]升高，伴有[K＋]下降，[Cl－]相对升高","[HCO3－]下降，伴有[K＋]升高，[Cl－]相对升高","[HCO3－]下降，伴有[K＋]下降，[Cl－]相对下降"],"a":0,"e":"代谢性碱中毒以HCO3-原发性升高为特征，常伴低钾与低氯：低钾时细胞内H+外移、肾小管排H+保Na+增强，低氯使肾小管重吸收HCO3-增加，故[Cl-]相对下降。HCO3-下降或K+升高均为代谢性酸中毒或肾衰竭等改变，不符合代谢性碱中毒的离子特征。低氯低钾性碱中毒常见于呕吐、胃肠减压与利尿剂使用"},{"q":"正常成人粪便中的主要菌群是","o":["产气杆菌","变形杆菌","芽孢菌","大肠埃希氏菌","肠球菌"],"a":3,"e":"正常成人粪便中主要菌群为大肠埃希菌、厌氧杆菌与肠球菌。产气肠杆菌、变形杆菌、铜绿假单胞菌多为过路菌，数量少且不稳定。芽孢菌非常住主要菌群。大肠埃希菌在肠道中参与维生素合成并抑制致病菌，其数量变化与腹泻、肠道菌群失调相关，也是粪便细菌学检查的重点"},{"q":"肝硬化门脉高压最突出的临床表现是","o":["食管-胃底静脉曲张","腹水","脾大","脐周及腹壁静脉曲张","脾功亢进"],"a":1,"e":"肝硬化失代偿期门静脉高压最突出的临床表现是腹腔积液，其形成与门静脉压力升高、低蛋白血症、肝淋巴液回流障碍及继发性醛固酮增多有关。食管胃底静脉曲张、脾大、脾功能亢进及腹壁静脉曲张亦为门脉高压表现，但腹水出现晚且最显著，标志肝功能失代偿，治疗的难点亦在于此"},{"q":"常见总胆红素、结合胆红素和非结合胆红素均增高的疾病是","o":["溶血性贫血","胆道完全阻塞","胆道部分阻塞","肾脏功能障碍","肝细胞严重损伤"],"a":4,"e":"肝细胞严重损伤时，肝细胞对非结合胆红素的摄取与结合功能降低使UCB增加，未受损肝细胞仍可转化部分UCB为CB，同时肿胀肝细胞及炎性浸润压迫毛细胆管致CB反流入血，故总胆红素、结合与非结合胆红素三者均增高。溶血性贫血以UCB升高为主，胆道阻塞以CB升高为主，肾脏疾病不影响胆红素代谢"},{"q":"在CH50检测中，灭活补体的温度和时间是","o":["37℃ 1h","50℃ 30min","56℃ 30min","56℃ 1h","60℃ 30min"],"a":2,"e":"CH50检测总补体溶血活性前须灭活受检血清中的补体，常用56℃30分钟，使补体成分失活而保留待测抗体，避免补体自身溶血干扰。50℃30分钟为补体旁路B因子的灭活条件，温度不足。37℃为抗原抗体反应的常用温度。60℃30分钟温度过高，可破坏抗体及其他蛋白成分"},{"q":"血浆凝血酶原时间延长，见于","o":["血小板减少症","血小板无力症","血友病","严重肝病","因子Ⅻ缺乏"],"a":3,"e":"凝血酶原时间反映外源性凝血途径，肝脏合成因子Ⅱ、Ⅶ、Ⅹ、Ⅴ及纤维蛋白原，严重肝病时这些因子合成减少，PT显著延长，同时伴出血倾向。血小板减少症与血小板无力症影响血小板功能，PT正常。血友病为内源性因子Ⅷ、Ⅸ缺乏，表现为APTT延长。因子Ⅻ缺乏亦影响内源性途径，PT不受累"},{"q":"下列哪种属于病理性多尿","o":["慢性肾炎水肿应用利尿剂后","静脉输入多量液体后","大量饮水后","慢性肾盂肾炎","慢性心衰水肿应用利尿剂后"],"a":3,"e":"慢性肾盂肾炎致肾间质受损、肾小管重吸收功能障碍，引起肾小管浓缩功能减退而出现病理性多尿。慢性肾炎水肿用利尿剂后、静脉输入多量液体后、大量饮水后均属外源性或生理性多尿，去除诱因后尿量恢复，不属疾病本身所致。病理性多尿还见于尿崩症、糖尿病及原发性醛固酮增多症"},{"q":"脊柱后凸成畸形一般不见于","o":["佝偻病","强直性脊柱炎","结核病","类风湿性关节炎","脊髓退行性变"],"a":3,"e":"脊柱后凸畸形常见于佝偻病、强直性脊柱炎、脊柱结核及脊髓退行性变，分别因骨质软化、韧带骨化、椎体破坏压缩及退行性改变所致。类风湿关节炎主要累及外周小关节，表现为对称性肿痛、晨僵与关节畸形，很少引起脊柱后凸。其颈椎受累亦多为寰枢关节半脱位而非成角后凸"},{"q":"胸骨右缘第2肋间触及收缩期震颤，最常见于","o":["主动脉瓣狭窄","主动脉瓣关闭不全","肺动脉瓣狭窄","肺动脉瓣关闭不全","动脉导管未闭"],"a":0,"e":"胸骨右缘第2肋间为主动脉瓣区，该处收缩期震颤最常见于主动脉瓣狭窄，因血流通过狭窄瓣口形成湍流所致，伴粗糙喷射性收缩期杂音并向颈部传导。胸骨左缘第2肋间收缩期震颤为肺动脉瓣狭窄。胸骨左缘第3、4肋间为室间隔缺损。连续性杂音伴震颤见于动脉导管未闭。关闭不全极少产生震颤"},{"q":"12对脑神经属于单纯感觉神经的有","o":["嗅神经、前庭蜗神经、视神经","动眼神经、面神经、迷走神经","视神经、舌下神经、迷走神经","视神经、舌下神经、舌咽神经","前庭蜗神经、三叉神经、迷走神经"],"a":0,"e":"12对脑神经中单纯感觉神经为嗅神经、视神经与前庭蜗神经，分别司嗅觉、视觉与听平衡觉。动眼神经、迷走神经为运动性或混合性，面神经含运动与味觉纤维，舌咽神经为混合性，三叉神经为混合性，舌下神经为纯运动神经。按纤维成分分类是判断神经损伤表现的基础"},{"q":"下述是问诊的方法，但应除外","o":["医生先与病人过渡性交谈","问诊一般先由主诉开始","问诊一般先由医生做些疾病的提示开始","问诊先由简易问题开始","问诊时医生的态度要诚恳友善"],"a":2,"e":"问诊应由医生先与病人作过渡性交谈以缓和气氛，一般从主诉开始、由简易问题入手，态度诚恳友善。以疾病提示开始属诱导性或暗示性提问，措辞中已暗示期望答案，易使病人默认附和而获得错误信息，故应除外。重点问诊虽可围绕主要问题展开，仍须避免暗示性措辞"},{"q":"使纤维蛋白降解为FDP的物质是","o":["因子Ⅻ","活化素","凝血酶","纤维蛋白单体","纤溶酶"],"a":4,"e":"纤溶酶可降解纤维蛋白与纤维蛋白原，生成纤维蛋白降解产物FDP及D-二聚体，是纤溶亢进的核心酶。凝血酶使纤维蛋白原转变为纤维蛋白单体并促其交联，作用方向相反。活化素为纤溶酶原激活物，通过激活纤溶酶原间接发挥作用。因子Ⅻ参与内源性凝血启动，纤维蛋白单体为降解底物而非降解酶"},{"q":"吸气性呼吸困难的典型体征为","o":["肋间隙增宽","呼吸动度减小","端坐呼吸","三凹征","发绀"],"a":3,"e":"吸气性呼吸困难见于喉、气管及大支气管狭窄或阻塞，吸气时呼吸肌极度用力、胸腔负压显著增加，出现胸骨上窝、锁骨上窝及肋间隙明显凹陷，称三凹征，伴高调吸气性喉鸣。肋间隙增宽、呼吸动度减小为非特异性表现。端坐呼吸多见于左心衰竭。发绀为缺氧的共同表现，均非吸气性呼吸困难的特异体征"},{"q":"PR段反映心脏哪些结构的电活动","o":["心房除极和复极的过程","心房除极、复极过程及房室结电活动","心房复极过程及房室结、希氏束电活动","心房复极过程及房室结、希氏束、束支的电活动","心房除极、复极过程及房室结、希氏束、束支电活动"],"a":3,"e":"PR段实为PQ段，反映心房复极过程及房室结、希氏束、束支的电活动，位于P波之后、QRS波群之前。P波本身才代表心房除极，故仅列心房除极或同时包含除极的选项均不准确。遗漏束支电活动的选项范围不完整。PR间期则包含P波与PR段，代表心房开始除极至心室开始除极的时间"},{"q":"二尖瓣狭窄时，哪种体征提示可行球囊扩张术","o":["第一心音亢进","P2亢进","心尖区舒张期杂音有后期增强","二尖瓣开放拍击音","第一心音亢进及二尖瓣开放拍击音"],"a":4,"e":"二尖瓣球囊扩张术要求瓣膜柔软、活动度好、无明显钙化及腱索严重病变；第一心音亢进提示瓣叶位置低垂、活动良好，二尖瓣开放拍击音提示瓣叶弹性尚存，二者并存是瓣膜条件适合的有力证据。P2亢进仅反映肺动脉高压，心尖区舒张期杂音后期增强可见于心房颤动时舒张期缩短，均不能单独提示瓣膜可扩张"},{"q":"下列各项叩诊均能产生浊鼓音，但应除外","o":["肺不张","肺炎充血期","肺炎实变期","肺炎消散期","肺水肿"],"a":2,"e":"浊鼓音是兼有浊音与鼓音特点的混合性叩诊音，见于肺泡壁松弛、含气量减少时，如肺不张、肺炎充血期、消散期及肺水肿。肺炎实变期肺泡内充满炎性渗出物、含气量显著减少，叩诊呈浊音或实音，同时语颤增强并可闻支气管呼吸音，不出现浊鼓音。气胸则叩诊为鼓音"},{"q":"主动脉瓣关闭不全的舒张期杂音，最易听到的部位","o":["胸骨右缘第2肋间","胸骨左缘第2肋间","胸骨左缘第3、4肋间","心尖部","胸骨下端左、右缘"],"a":2,"e":"主动脉瓣第二听诊区位于胸骨左缘第3、4肋间，是主动脉瓣关闭不全舒张期叹气样杂音最易听清的部位，前倾坐位、深呼气后暂停呼吸时更清楚。胸骨右缘第2肋间为主动脉瓣区，胸骨左缘第2肋间为肺动脉瓣区，心尖部为二尖瓣区，胸骨下端左右缘为三尖瓣区，均非该杂音最佳听诊处"},{"q":"鉴别肝细胞性黄疸与梗阻性黄疸时，下列检查哪项是错误的","o":["尿胆红素","谷丙转氨酶","血清非结合胆红素定量","尿胆原","碱性磷酸酶"],"a":0,"e":"肝细胞性黄疸与梗阻性黄疸尿胆红素均阳性，前者中度增加、后者强阳性，单项测定不能有效区分，故该项检查价值有限。尿胆原在梗阻性明显减少或缺如、肝细胞性正常或轻度增加。ALT在肝细胞性显著升高、梗阻性仅轻度增高。ALP在梗阻性明显升高。血清非结合胆红素二者增高程度亦有差别"},{"q":"咳浆液性粉红色泡沫样痰的疾病是","o":["肺栓塞","急性肺水肿","白血病","粟粒样肺结核","重症肺炎"],"a":1,"e":"急性肺水肿时肺毛细血管压力骤升，血浆成分与红细胞渗入肺泡，咳出大量浆液性粉红色泡沫样痰，伴端坐呼吸、大汗与两肺湿啰音，为左心衰竭急症。肺栓塞多为血痰或咯血。白血病、粟粒型肺结核咯血多为血丝痰。重症肺炎的铁锈色痰或脓痰不同，均非粉红色泡沫痰"},{"q":"恶心时迷走神经兴奋常伴有下列症状，但除外","o":["皮肤苍白","出汗","血压降低","寒战","心动过缓"],"a":3,"e":"恶心时迷走神经兴奋，表现为皮肤苍白、出汗、流涎、血压降低及心动过缓等，常为呕吐前奏。寒战是体温上升期产热增加的表现，由致热原作用于体温调定点所致，与迷走神经兴奋无关，故为例外。卧立位试验中由立位到卧位脉率减慢超过12次/分提示迷走神经兴奋性增高，可佐证上述机制"},{"q":"下列为急性病容所见，但不包括","o":["面色潮红","兴奋不安","鼻翼翕动","面容憔悴","口唇疱疹"],"a":3,"e":"急性病容表现为面色潮红、兴奋不安、鼻翼扇动、口唇疱疹及表情痛苦，多见于肺炎球菌肺炎、疟疾等急性感染性疾病。面容憔悴、面色晦暗或苍白无华、目光暗淡、表情忧虑是慢性病容，见于恶性肿瘤、肝硬化、严重结核病等慢性消耗性疾病，不属急性病容"},{"q":"病历书写的基本规则和要求不包括","o":["病历应当按照规定的内容书写，并有相应医务人员签名","病历要正规、真实、准确、完整，重点突出、层次分明","实习医师和毕业后第1年住院医师要书写住院病历和首次病程记录","住院病历最迟应于患者入院后24h内完成","书写应使用中文和医学术语"],"a":2,"e":"病历书写要求按规定内容书写并由相应医务人员签名，做到正规、真实、准确、完整、重点突出、层次分明，使用中文和医学术语，住院病历最迟入院后24小时内完成。首次病程记录由住院医师或值班医师书写并在入院8小时内完成；实习医务人员所写病程须由住院医师签名，故该表述不符规则"},{"q":"下列均为腹部体表标志，但除外","o":["腹上角","髂前上棘","脊肋角","髂后上棘","腹中线"],"a":3,"e":"腹部体表标志包括腹上角、髂前上棘、脊肋角、腹中线、脐、髂嵴、耻骨联合及腹股沟韧带等，用于描述体征位置。髂后上棘位于骶椎两侧、臀部上方，是骨髓穿刺的常用部位，不参与腹部分区与体表定位，故不属腹部体表标志。腹上角用于判断体型，脊肋角即肋脊角，为肾脏压痛区"},{"q":"张先生因为消化道出血在某医院第2次住院，入院后6小时死亡，住院医生应完成下列哪种病历记录","o":["再次入院记录","表格式入院病历","24小时内入院死亡记录","入院记录","死亡记录"],"a":2,"e":"病人入院不足24小时即死亡，应书写24小时内入院死亡记录，内容参照24小时内入出院记录，但将出院诊断改为死亡原因与死亡诊断，并在死亡后24小时内完成。普通死亡记录适用于住院超过24小时者。再次或多次入院记录、入院记录、表格式入院病历均不针对短时间内死亡的特定情形"},{"q":"室性期前收缩引起的心悸感觉是","o":["恐惧感","紧缩感","停跳感","压榨感","灼热感"],"a":2,"e":"室性期前收缩因提前出现的心室搏动使下一次心搏代偿间歇，病人常描述为心悸、停跳感或落空感，与脉搏间歇相对应。恐惧感多与心律失常伴血流动力学障碍相关。紧缩感、压榨感是心绞痛的典型描述。灼热感见于反流性食管炎，均与期前收缩的机械感受不符"},{"q":"叩诊肝脏的绝对浊音界，其叩诊音改变为","o":["清音→浊音","清音→实音","浊音→实音","浊音→清音","浊音→鼓音"],"a":2,"e":"叩诊肝脏上界时自肺区向下叩，清音转为浊音处为肝相对浊音界；继续向下叩1～2肋间，浊音转为实音，此处肝脏不被肺遮盖而直接贴近胸壁，为肝绝对浊音界，亦为肺下界。清音转浊音对应相对浊音界而非绝对浊音界。确定肝下界则由腹部鼓音区向上叩，鼓音转浊音处即为肝下缘"},{"q":"外源性致热原的特点，正确的是","o":["分子量小","致热性可被蛋白酶类水解","能激活血液中的中性粒细胞","直接作用体温调节中枢","在体内最终由肝、肾灭活和排泄"],"a":2,"e":"外源性致热原多为大分子物质，细菌内毒素分子量尤其大，不能通过血脑屏障直接作用于体温调节中枢，而是通过激活血液中中性粒细胞、嗜酸性粒细胞与单核巨噬细胞系统，使其产生释放内源性致热原而致发热。分子量小、直接作用于中枢、可被蛋白酶水解等均不符合其特性。最终灭活排泄亦非其主要作用方式"},{"q":"类风湿因子测定最常用于","o":["类风湿性关节炎","系统性红斑狼疮（SLE）","硬皮病","皮肌炎","风湿性心脏病"],"a":0,"e":"类风湿因子是变性IgG刺激机体产生的自身抗体，主要存在于类风湿关节炎病人的血清与关节液中，是该病的重要血清学指标，结合对称性小关节肿痛与晨僵可支持诊断。系统性红斑狼疮以抗核抗体、抗dsDNA抗体为特征。硬皮病、皮肌炎各有特异性抗体。风湿性心脏病与链球菌感染相关，不以RF为主要依据"},{"q":"下列各项均是用叩诊法确定肝上界的内容，但除外","o":["一般沿右锁骨中线叩","由肺区向腹部叩诊","用重叩诊法","当清音转浊音时为肝上界","肝上界称肝相对浊音界"],"a":2,"e":"叩诊确定肝上界一般沿右锁骨中线、右腋中线及右肩胛线，由肺区向下叩向腹部，叩指用力须适当、勿过轻或过重，清音转浊音处即肝上界，相当于被肺遮盖的肝顶部，称肝相对浊音界。重叩诊法会使震动传导过深、边界判断失真。肝上界明显降低而上下径正常提示肝脏下移，如肺气肿或右侧大量胸腔积液"},{"q":"肾下垂的检体诊断标准是","o":["深呼气时触到1/2以上的肾","深吸气时触到1/2以上的肾","平静呼吸时触到1/2以上的肾","深呼气时触到肾下极","深吸气时触到肾下极"],"a":1,"e":"肾下垂指在深吸气时能触到1/2以上的肾脏，因吸气时膈肌下降推动肾脏下移所致；正常人仅偶可触及右肾下极。平静呼吸或深呼气时肾脏位置较高，触及机会少。右肾下垂易误认为肝肿大，左肾下垂易误认为脾肿大，须结合体位改变与超声鉴别"},{"q":"下列舒张早期奔马律的特点，但应除外","o":["又称第三心音奔马律","也称室性奔马律","常出现在有严重器质性心脏病的病人","多在心率较快时出现","不受呼吸的影响"],"a":4,"e":"舒张早期奔马律又称第三心音奔马律或室性奔马律，出现在心率较快时，提示严重器质性心脏病，见于心力衰竭、急性心肌梗死、重症心肌炎与扩张型心肌病。左室奔马律在心尖区稍内侧、呼气时较清楚，右室奔马律在剑突下、吸气时较响，故受呼吸影响，并非不受影响"},{"q":"下列左心衰竭引起呼吸困难的特点均正确，但除外","o":["活动时出现或加重","休息时减轻或缓解","仰卧时加重","坐位时减轻","与体位无关"],"a":4,"e":"左心衰竭呼吸困难具体位相关性：活动时出现或加重，休息后减轻，仰卧位因回心血量增加而加重，坐位或端坐位因肺淤血减轻而缓解，可出现夜间阵发性呼吸困难。与体位无关的表述违背其肺淤血机制，故为例外。右心衰竭呼吸困难程度较轻，主要源于体循环淤血"},{"q":"尿频可见于以下哪种情况","o":["生理性尿频","急性肾小球肾炎","IgA肾病","紫癜性肾炎","慢性肾炎"],"a":0,"e":"生理性尿频见于饮水过多、精神紧张或气候寒冷，特点是每次尿量不少、不伴尿急尿痛，属于正常现象。急性肾小球肾炎、IgA肾病、紫癜性肾炎及慢性肾炎主要表现为血尿、蛋白尿、水肿与高血压，尿量改变以少尿为主，并非尿频的常见原因。炎症性尿频则伴尿急尿痛且每次尿量少，见于膀胱炎、尿道炎"},{"q":"焦虑患者常常伴有的生理症状不包括","o":["心悸","血压升高","皮肤红润","尿频","腹泻"],"a":2,"e":"焦虑状态伴交感神经兴奋，常见心悸、血压升高、出汗、尿频、腹泻等自主神经症状。皮肤红润不符合焦虑时的血管反应，因外周血管收缩多表现为面色苍白或潮红交替，而非持续红润，故为例外。皮肤红润更常见于发热、饮酒或环境温度升高所致血管扩张"},{"q":"支气管舒张试验主要用于诊断","o":["肺气肿","哮喘","肺炎","肺不张","肺纤维化"],"a":1,"e":"支气管舒张试验通过吸入支气管舒张剂后肺功能指标的改善，判断气流受限的可逆性，主要用于支气管哮喘的诊断与鉴别，尤其对咳嗽变异性哮喘及缓解期肺功能正常者有价值。肺气肿、肺不张、肺纤维化为结构性病变，气流受限多不可逆。肺炎为急性感染，均非该试验适应证。支气管激发试验则用于测定气道高反应性"},{"q":"年轻人出现“冠状T波”，除考虑冠状动脉粥样硬化性心脏病外，首先应排除","o":["扩张型心肌病","肥厚型心肌病","心肌炎","心包炎","先天性心脏病"],"a":1,"e":"年轻病人出现冠状T波即心外膜下心肌缺血性T波深倒置，除冠心病外首先应排除肥厚型心肌病，尤其心尖肥厚型心肌病可有显著T波倒置而被误认为心肌缺血或梗死，结合超声心动图可鉴别。扩张型心肌病以心腔扩大与收缩功能减低为主。心肌炎、心包炎多有前驱感染与广泛ST-T改变。先天性心脏病依类型有相应杂音与血流动力学表现"},{"q":"心尖冲动减弱并弥散常见于","o":["心包大量积液","缩窄性心包炎","心肌炎或心肌病","左侧胸腔积液","肥胖"],"a":2,"e":"心尖冲动减弱并弥散见于心肌炎、心肌病等心肌收缩力显著减弱的疾病，扩张型心肌病心腔扩大使搏动弥散且增强不明显。心包大量积液与缩窄性心包炎因心脏与前胸壁距离增加或舒张受限致心尖搏动减弱甚至消失，但不呈弥散增强。左侧胸腔积液、肥胖亦使搏动减弱，机制为传导障碍而非心肌本身病变"},{"q":"正常心尖冲动位置在","o":["胸骨左缘第4肋间锁骨中线内侧0.5～1cm处","胸骨左缘第5肋间锁骨中线内侧1.5～2cm处","胸骨左缘第6肋间锁骨中线内侧1～2cm处","胸骨左缘第5肋间锁骨中线内侧0.5～1cm处","胸骨左缘第5肋间锁骨中线外侧1～2cm处"],"a":3,"e":"正常成人心尖冲动位于胸骨左缘第5肋间、左锁骨中线内侧0.5～1cm处，搏动范围直径约2～2.5cm。第4肋间或第6肋间位置有误，锁骨中线外侧1～2cm提示心界向左扩大，内侧1.5～2cm亦偏离正常。左心室肥厚时心尖搏动向左下移位且有力，呈抬举样"},{"q":"诊断麻痹性肠梗阻时腹部持续听诊至少","o":["30～50s","1～2min","2～3min","3～5min","5～10min"],"a":3,"e":"诊断麻痹性肠梗阻须持续听诊腹部至少3～5分钟，若无肠鸣音，再以手指轻叩或搔弹腹部仍未闻及，方可判定肠鸣音消失。短时间听诊易将间歇性肠鸣音误判为消失。机械性肠梗阻肠鸣音亢进、呈金属音，与麻痹性相反。麻痹性肠梗阻常见于腹部大手术后、急性弥漫性腹膜炎、腹膜后出血及低钾血症"},{"q":"下列主动脉瓣关闭不全引起周围血管征的叙述正确的是","o":["有效循环血量增加，致水冲脉","舒张期主动脉血液反流、脉压增大","收缩压升高幅度大于舒张压升高幅度","静脉压升高致De-Musset征","毛细血管扩张导致毛细血管搏动"],"a":1,"e":"主动脉瓣关闭不全的周围血管征源于舒张期主动脉血液反流入左室，致舒张压显著降低、脉压增大，出现水冲脉、点头运动、毛细血管搏动、枪击音及Duroziez双重杂音。有效循环血量增加并非其机制，实际为脉压增大。静脉压升高致颈静脉怒张，与De-Musset征无关。毛细血管搏动源于脉压增大而非毛细血管扩张"},{"q":"视诊的内容包括下列各项，但应除外","o":["面容","表情","体位","步态","波动"],"a":4,"e":"视诊通过肉眼观察病人的一般状态与体征，包括面容、表情、体位、步态、发育营养及皮肤黏膜等。波动感又称波动，需用手触压液体充盈的腔隙才能感知，属触诊内容，可协助判断脓肿、囊肿或腹水。体温、湿度、震颤、压痛、摩擦感及包块性质等亦均须触诊确定"},{"q":"不符合干性啰音听诊特点的是","o":["吸气、呼气均可听到","部位易变性大","吸气时音强而高","咳嗽时可多可少","不同性质的干性啰音可同时存在"],"a":2,"e":"干性啰音为气流通过狭窄或部分阻塞的气道产生，吸气与呼气均可闻及，部位易变，咳嗽后可增多或减少，不同性质可同时存在；因呼气时气道口径更小、气流更快，故呼气时音强而高调，而非吸气时音强而高。呼气时音强而高是支气管呼吸音的听诊特点，支气管呼吸音于喉部、胸骨上窝及背部颈胸椎附近可闻及"},{"q":"痢疾患者的粪便为","o":["黏液便","干结便","脓血便","米泔水样便","白陶土样便"],"a":2,"e":"痢疾由志贺菌或阿米巴原虫感染结肠黏膜，造成黏膜坏死、溃疡与出血，粪便呈脓样、黏液脓血样，伴里急后重及腹痛。黏液便多见于肠道炎症或受刺激。干结便见于便秘。米泔水样便为霍乱特征。白陶土样便见于胆道梗阻致胆汁不能入肠，均非痢疾表现"},{"q":"检查视力时，针孔视力较裸眼视力有明显提高，说明患者的视力下降可能为下列何种原因所致","o":["精神因素","结膜炎","屈光不正","视神经疾病","黄斑疾病"],"a":2,"e":"针孔视力较裸眼视力明显提高，说明成像模糊源于屈光不正，针孔可阻挡周边散射光线、减少像差而提高清晰度，通常需戴镜矫正。结膜炎以分泌物、充血为主。视神经疾病、黄斑疾病属器质性病变，针孔不能改善。精神因素所致视力下降与屈光间质、视网膜功能无关，针孔试验无变化"},{"q":"下列为心房颤动听诊的特点，但应除外","o":["心律绝对不规则","第一心音强弱不等","脉率少于心率","吸气时心率快，呼气时心率慢","脉搏短绌"],"a":3,"e":"心房颤动听诊特点为心律绝对不规则、第一心音强弱不等、脉率少于心率即脉搏短绌。吸气时心率快、呼气时心率慢是窦性心律不齐的表现，常见于青少年，与呼吸周期相关，不属房颤。房颤的节律完全无序，不受呼吸影响，心电图上P波消失、代以f波，RR绝对不齐"},{"q":"本例心电图最可能的诊断是","o":["左室肥厚","右室增大","左房增大","右房增大","房室内径正常"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心室肥厚的心电图判断依赖QRS电压与胸导联R/S比值：左室肥厚表现为V5、V6导联R波增高、R/S＞1及电轴左偏，常伴ST-T继发性改变；右室增大表现为V1导联R波为主、电轴右偏。左房增大以P波增宽呈双峰、V1导联PtfV1增大为特征，右房增大表现为Ⅱ、Ⅲ、aVF导联P波高尖。无具体图形与测量数据无法判定类型\n\n官方题库中缺失图片"},{"q":"下列各项均有肾区叩痛，但除外","o":["肾结石","肾盂肾炎","肾衰竭","肾炎","肾周围炎"],"a":2,"e":"肾区叩痛见于肾脏及肾周急性病变，如肾结石、肾盂肾炎、肾炎及肾周围炎，因炎症或梗阻使肾包膜张力增加、肾盂内压升高。肾衰竭是肾功能进行性减退的综合征，可由多种慢性肾病发展而来，本身不产生肾区叩痛，除非合并急性感染或梗阻，故为除外项。肾结核、肾脓肿亦可有叩痛"},{"q":"淤血性周围性发绀常见于哪种疾病","o":["严重休克","上腔静脉压迫综合征","急性呼吸窘迫综合征","弥漫性肺间质纤维化","法洛四联症"],"a":1,"e":"淤血性周围性发绀源于体循环淤血、周围血流缓慢，常见于右心衰竭、缩窄性心包炎、血栓性静脉炎及上腔静脉阻塞综合征，发绀见于肢体末端与下垂部位，皮肤冰冷，按摩加温后可消退。严重休克为缺血性周围性发绀。ARDS与弥漫性肺间质纤维化为肺性发绀。法洛四联症为中央性发绀，均不属淤血性周围性发绀"},{"q":"正常人尿中可见到下列细胞，但除外","o":["红细胞","白细胞","小圆上皮细胞","表层移行上皮细胞","扁平上皮细胞"],"a":2,"e":"正常人尿中可偶见红细胞、白细胞、表层移行上皮细胞及扁平上皮细胞，后者多来自外阴或尿道口污染。小圆上皮细胞来自肾小管上皮，正常人尿中不见或极罕见，出现提示肾小管病变如急性肾小管坏死或肾小管间质损害，故为例外。管型形成亦提示肾实质受累，须结合临床判断"},{"q":"重搏脉最常见于","o":["伤寒病","心包积液","左心衰竭","贫血","高热"],"a":0,"e":"重搏脉又称双峰脉，指脉搏波在主波之后出现一次较小的重复波，与主动脉瓣关闭后血液冲击闭锁的主动脉瓣产生反向波有关，最常见于伤寒病，亦可见于长期发热或其他消耗性疾病。心包积液致奇脉，左心衰竭致交替脉，贫血致水冲脉，高热致洪脉，脉搏形态各不相同"},{"q":"下列关于主动脉瓣狭窄的说法正确的是","o":["常见水冲脉","常伴有S2固定分裂","杂音向颈根部传导","可导致A2增强","为主动脉瓣副区最响的收缩期递增递减型杂音"],"a":2,"e":"主动脉瓣狭窄的杂音为胸骨右缘第2肋间粗糙的收缩中期喷射性杂音，呈递增递减型，沿血流方向向颈部及颈根部传导，伴A2减弱与收缩期震颤。水冲脉是主动脉瓣关闭不全的周围血管征。S2固定分裂见于房间隔缺损。A2增强见于高血压，狭窄时反而减弱。主动脉瓣副区为听诊区之一，但最响仍在主动脉瓣区"},{"q":"所谓一元论，就是指","o":["只考虑一种疾病","所有病史资料只能用一种疾病解释","所有病史资料尽量用一种疾病解释","诊断不明确时，可考虑按功能性疾病治疗","只能考虑一种疾病"],"a":2,"e":"一元论是临床诊断思维的基本原则，指尽量用一种疾病解释病人的全部病史资料与临床表现，以简化诊断、提高正确性。只有确实无法用一种疾病解释时，才考虑多种疾病并存。只考虑一种疾病或所有资料只能用一种疾病解释均过于绝对。诊断不明确时按功能性疾病治疗违背实事求是原则，可能导致漏诊"},{"q":"下列疾病引起发热均为感染性，但应除外","o":["细菌侵入机体后","病毒侵入机体后","支原体侵入机体后","感染后低热","寄生虫侵入机体后"],"a":3,"e":"细菌、病毒、支原体、寄生虫侵入机体后引起的急性、亚急性或慢性感染，不论局部或全身，均属感染性发热。感染后低热是原发感染治愈后体温调节功能尚未恢复所致，属功能性低热范畴，并非当前仍有病原体感染，故为例外。其与潜在病灶活动或新感染所致发热须鉴别"},{"q":"PaO2显著下降而PaCO2无增加的疾病主要见于","o":["COPD所致呼吸衰竭","气道阻塞所致呼吸衰竭","ARDS所致呼吸衰竭","低通气综合征所致呼吸衰竭","延髓中枢受损所致呼吸衰竭"],"a":2,"e":"ARDS所致呼吸衰竭以肺泡弥散障碍与肺内分流为主要机制，表现为PaO2显著下降而PaCO2正常或降低，属Ⅰ型呼吸衰竭。COPD、气道阻塞、低通气综合征及延髓中枢受损均导致肺泡通气不足，PaCO2升高，属Ⅱ型呼吸衰竭。区分Ⅰ型与Ⅱ型的关键在于PaCO2是否超过50mmHg"},{"q":"下列哪一项不属于神经源性膀胱","o":["多发性硬化","脑梗死","帕金森病","前列腺肿瘤","颅内肿瘤"],"a":3,"e":"神经源性膀胱由中枢或周围神经系统病变导致膀胱逼尿肌与尿道括约肌功能障碍，见于多发性硬化、脑梗死、帕金森病及颅内肿瘤，常伴便秘、大便失禁等排便功能紊乱。前列腺肿瘤属机械性梗阻，直接压迫尿道引起进行性排尿困难，不属神经源性。尿动力学检查可区分二者"},{"q":"骨髓涂片检查中正常人粒红比值M∶E是","o":["（1～3）∶1","（2～4）∶1","（2～5）∶1","（3～5）∶1","（4～10）∶1"],"a":1,"e":"骨髓涂片正常人粒红比值即粒系与红系细胞之比为2～4∶1，反映粒系生成略多于红系。比值增高见于粒细胞增多或红系受抑，如感染、白血病或单纯红细胞再生障碍；比值降低见于红系增生如溶血性贫血、巨幼细胞贫血或粒系受抑。昼夜尿比密比值、尿血浆渗量比值为肾脏浓缩功能指标，A/G为血清蛋白比值，均与粒红比值无关"},{"q":"下列患者于安静状态下均可见到颈动脉的明显搏动，除外","o":["主动脉瓣狭窄","主动脉瓣关闭不全","高血压","甲状腺功能亢进症","严重贫血"],"a":0,"e":"安静状态下出现颈动脉明显搏动见于脉压增大的情况，如主动脉瓣关闭不全、高血压、甲状腺功能亢进及严重贫血，因心搏出量增加或舒张压降低致搏动增强。主动脉瓣狭窄使心搏出量减少、脉压减小，颈动脉搏动减弱而非增强。颈动脉与颈静脉搏动部位相近，须据搏动性质与指压试验鉴别"},{"q":"帕金森病的面容是","o":["面部呆板，无表情","面色苍黄，反应迟钝","牙关经闭，面肌痉挛","面色苍白，表情疲惫","面容惊愕，眼裂增宽"],"a":0,"e":"帕金森病面容称面具面容，表现为面部呆板、无表情、眨眼减少，因黑质多巴胺能神经元变性致运动迟缓与肌张力增高所致。面色苍黄、反应迟钝见于甲状腺功能减退等。牙关紧闭、面肌痉挛为破伤风苦笑面容。面色苍白、表情疲惫为贫血面容。面容惊愕、眼裂增宽为甲状腺功能亢进面容"},{"q":"Q-T间期的正常值是","o":["0.18～0.24秒","0.24～0.32秒","0.32～0.44秒","0.44～0.52秒","0.52～0.66秒"],"a":2,"e":"QT间期指QRS波群起点至T波终点，代表心室肌除极与复极全过程所需时间，心率60～100次/分时正常范围为0.32～0.44秒。其长短与心率密切相关，心率越快越短，反之越长，故须按心率校正。0.18～0.24秒、0.24～0.32秒过短，0.44秒以上延长，可见于低钾、低钙、药物或心肌缺血"},{"q":"高血压患者心脏听诊心音变化特点为","o":["心尖部第一心音亢进","心尖部第一心音减弱","剑突下第一心音减弱","胸骨右缘第2肋间第二心音亢进","胸骨左缘第2肋间第二心音亢进"],"a":3,"e":"高血压患者主动脉内压力持续升高，主动脉瓣关闭有力、振动增强，致主动脉瓣区即胸骨右缘第2肋间第二心音亢进，为A2增强。心尖部第一心音亢进主要见于二尖瓣狭窄，减弱见于二尖瓣关闭不全。剑突下听诊主要反映右心。胸骨左缘第2肋间为肺动脉瓣区，P2亢进见于二尖瓣狭窄、肺心病等"},{"q":"心肌梗死后较易闻及大炮音的是","o":["急性前壁心肌梗死","急性广泛前壁心肌梗死","急性下壁心肌梗死","急性前间壁心肌梗死","急性高侧壁心肌梗死"],"a":2,"e":"急性下壁心肌梗死常累及右冠状动脉，而房室结血供多来自右冠状动脉，故易并发房室传导阻滞；当心房与心室几乎同步收缩、房室瓣处于关闭状态时心室收缩力骤增，产生响亮的第一心音即大炮音。前壁、广泛前壁及前间壁梗死多由左前降支闭塞所致，较少累及房室结。高侧壁梗死由回旋支供血，亦少并发"},{"q":"系统回顾的重要性不包括","o":["是问诊的内容之一","避免忽略或遗漏问诊内容","帮助医生短时间内了解病人其他系统尚存或痊愈的疾病","有助于了解病人的社会经历，职业及工作条件","了解本次患病与其他疾病的因果关系"],"a":3,"e":"系统回顾是问诊的重要组成部分，用于避免遗漏问诊内容、了解其他系统尚存或痊愈的疾病，并判断本次患病与其他疾病的因果关系，可在短时间内建立完整病史框架。了解病人的社会经历、职业及工作条件属个人史内容，不在系统回顾范畴。个人史还包括生活习惯、嗜好及不洁性生活史等"},{"q":"风湿性心脏病二尖瓣狭窄的典型面容是","o":["面色潮红，表情痛苦","面色晦暗，双颊发红，口唇发绀","面色苍白，表情疲惫","面色晦暗，额部有褐色色素沉着","表情淡漠，反应迟钝，呈无欲状态"],"a":1,"e":"风湿性心脏病二尖瓣狭窄的典型面容称二尖瓣面容，表现为面色晦暗、双颊紫红或发红、口唇轻度发绀，因肺淤血与周围循环淤血所致。面色潮红、表情痛苦为急性病容。面色苍白、表情疲惫为贫血面容。面色晦暗、额部褐色色素沉着为肝病面容。表情淡漠、反应迟钝、无欲状态为甲状腺功能减退面容"},{"q":"关于核左移，下列正确的是","o":["见于巨幼细胞贫血","见于应用抗代谢药物治疗后","常见于化脓菌引起的感染","是由于缺乏造血物质使DNA合成障碍","表示机体反应性低下"],"a":2,"e":"核左移指外周血中性粒细胞杆状核增多或出现更幼稚细胞，是机体对感染的应激反应，常见于化脓菌引起的急性感染、急性失血及急性中毒，粒系释放加速所致。巨幼细胞贫血及抗代谢药物治疗后致DNA合成障碍，表现为核右移。缺乏造血物质导致DNA合成障碍亦为核右移机制。机体反应性低下时白细胞生成受抑，不出现明显核左移"},{"q":"明确诊断为右侧大量胸腔积液的患者，查体可见","o":["右胸胸廓塌陷，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动增强，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤增强，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤消失，叩诊鼓音，呼吸音消失"],"a":1,"e":"大量胸腔积液使患侧胸廓饱满、呼吸运动受限，液体隔绝声波传导致语颤消失、叩诊实音、呼吸音消失，积液区上方有时可闻支气管呼吸音。胸廓塌陷见于肺不张或胸膜增厚粘连，而非大量积液。呼吸运动增强、语颤增强均不符合积液物理特性。叩诊鼓音见于气胸，与液体叩诊实音截然不同"},{"q":"临床习惯上对营养不良做如下描述，但应除外","o":["皮肤黏膜干燥，弹性减低","皮下脂肪菲薄","肌肉松弛无力","指甲粗糙无光泽","甲床下有紫红色出血"],"a":4,"e":"营养不良表现为皮肤黏膜干燥、弹性减低、皮下脂肪菲薄、肌肉松弛无力及指甲粗糙无光泽，均为长期能量与蛋白质摄入不足的体征。甲床下紫红色出血为甲下出血或裂片状出血，常见于感染性心内膜炎、血液病或外伤，与营养状态无关，故应除外。上述营养体征在消瘦型营养不良尤为明显"},{"q":"下列哪项是构成心脏右界的主要成分","o":["下腔静脉","右心房","右心室","降主动脉","肺动脉段"],"a":1,"e":"心脏右界自第2肋间相当于升主动脉与上腔静脉，第3肋间以下为右心房，故右心房是构成右界的主要成分。下腔静脉位于膈下，不参与心界构成。右心室增大主要使心界向左或两侧扩大。降主动脉位于后纵隔，不形成心界。肺动脉段构成心左界上部，突出时心腰消失"},{"q":"下列描述符合正常心电图表现，除了","o":["V1导联p波可以是直立的，也可以双向","QRS波宽度不应超过0.12s","V2～V3导联Q波宽度可达0.04s","V1导联R波在成人不应超过1.0mV","V1导联可出现孤立的QS波或Qr波"],"a":2,"e":"正常人V1、V2导联不应出现Q波，偶尔可呈QS波，V2～V3导联Q波宽达0.04秒属异常，提示前间壁病变。V1导联P波可直立或双向。QRS波宽度正常不超过0.12秒。成人V1导联R波不超过1.0mV，V1呈孤立QS波或Qr波可见于正常变异。Ⅲ导联Q波宽达0.04秒及aVR呈QS波均属正常"},{"q":"弛张热最常见于","o":["大叶性肺炎","疟疾","霍奇金病","支气管肺炎","败血症"],"a":4,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时内波动范围超过2℃，但最低体温仍高于正常，最常见于败血症，亦见于风湿热、重症肺结核及化脓性感染。大叶性肺炎为稽留热，24小时波动不超过1℃。疟疾为间歇热，寒战高热与无热期交替。霍奇金病可呈周期热。支气管肺炎热型不规则"},{"q":"下列物质中属于舒血管物质的是","o":["儿茶酚胺","血栓烷A2","肾上腺素","前列环素","纤维蛋白肽A"],"a":3,"e":"前列环素即PGI2，由血管壁生成，能舒张血管平滑肌并抑制血小板聚集，与血栓烷A2作用相反、互为平衡。儿茶酚胺、肾上腺素通过α受体使血管收缩。血栓烷A2有强烈促血管收缩与促血小板聚集作用。纤维蛋白肽A为凝血酶裂解纤维蛋白原的产物，反映凝血激活，均无舒血管作用"},{"q":"每天咯血量为多少时属于大量咯血","o":["＞100ml","＞500ml","100～500ml","＞300ml","＞600ml"],"a":1,"e":"咯血量分级以每日计算：100ml以内为小量，100～500ml为中等量，500ml以上或一次咯血100～500ml为大量咯血。大量咯血主要见于空洞型肺结核、支气管扩张与慢性肺脓肿，因病灶侵蚀较大血管所致。超过100ml或300ml的界值不符合分级标准，超过600ml则门槛过高"},{"q":"关于嗅神经检查，下列叙述哪项不正确","o":["嗅觉的灵敏度可通过问诊了解","检查时双侧鼻孔同时进行","用醋、酒、香皂等分别放于鼻孔前，要求辨认气味","嗅觉正常时可明确分辨测试物品气味","如一侧嗅觉减退或丧失提示同侧嗅神经损害"],"a":1,"e":"嗅神经检查须先确认鼻孔通畅、无鼻黏膜病变，嘱病人闭目，压住一侧鼻孔，将熟悉而无刺激性的物品如杏仁、牙膏、香皂置于另一侧鼻孔下辨识，再换对侧比较，不能双侧同时检查，否则无法判断单侧嗅觉障碍。嗅觉可经问诊初步了解。一侧嗅觉减退或丧失，排除鼻黏膜病变后提示同侧嗅神经损害"},{"q":"检查腹腔深部包块时最适宜的触诊方法是","o":["浅部触诊法","深部滑行触诊法","双手触诊法","深压触诊法","冲击触诊法"],"a":2,"e":"腹腔深部包块最适宜双手触诊法，左手掌托起包块后方并向右手方向推起，使包块位于双手之间更接近体表，右手配合腹式呼吸触诊，用于肝、脾、肾及腹腔肿物。浅部触诊仅及体表1cm，用于浅在病变。深压触诊用于探测深在压痛点如阑尾点。冲击触诊用于大量腹水时触诊肝脏。深部滑行触诊用于肠道病变"},{"q":"王先生因全身水肿1个月，拟诊肾病综合征入院。他自述10年前患过过敏性紫癜性肾炎，这段病史应该属于","o":["现病史","既往史","个人史","家族遗传史","视情况而定"],"a":0,"e":"现病史记录本次疾病的发生、发展与诊疗经过，并包含与本次发病有密切关系的既往疾病；10年前过敏性紫癜性肾炎可能是本次肾病综合征的病因或基础，与全身水肿直接相关，应列入现病史。既往史记录与现病无直接关系的其他疾病史，二者按与本次发病的关联度划分。个人史、家族遗传史分别涉及生活经历与家族遗传病"},{"q":"在无水代谢紊乱的情况下，测定尿渗量可粗略地反映","o":["肾小球的滤过功能","肾小管的浓缩稀释功能","肾小管的分泌功能","肾小管上皮细胞对ADH的敏感性","下丘脑对水的调节功能"],"a":1,"e":"尿渗量反映尿中溶质颗粒浓度，在无水代谢紊乱的条件下可粗略反映肾小管尤其远端肾小管与集合管的浓缩稀释功能；禁饮尿渗量低于300mOsm/kg为低渗尿，提示浓缩功能障碍。肾小球滤过功能以肌酐清除率、血肌酐评估。肾小管分泌功能以酚红排泄试验等判断。ADH敏感性与下丘脑调节须借助特殊试验，不能由尿渗量单独判定"},{"q":"二尖瓣区收缩期器质性杂音，除见于风湿性二尖瓣关闭不全外，还可见于","o":["乳头肌功能失调","扩张型心肌病","贫血性心脏病","高血压心脏病","主动脉瓣关闭不全"],"a":0,"e":"二尖瓣区收缩期器质性杂音除风湿性二尖瓣关闭不全外，还见于冠心病乳头肌功能失调、二尖瓣脱垂及老年性二尖瓣退行性变。乳头肌功能失调使收缩期瓣叶对合不良、血液反流产生杂音。扩张型心肌病所致为左室扩大引起的相对性关闭不全。贫血性心脏病、高血压心脏病多为功能性杂音。主动脉瓣关闭不全产生舒张期杂音，不在此列"},{"q":"下列关于甲状腺肿大的叙述均正确，但除外哪一项","o":["女性在青春发育期可略增大","女性在更年期可略增大","不能看出肿大，能触及者为Ⅰ度肿大","能看出肿大，又能触及，但在胸锁乳突肌内为Ⅱ度肿大","能看出肿大，又能触及，超过胸锁乳突肌为Ⅲ度肿大"],"a":1,"e":"正常甲状腺外观不突出，女性在青春发育期可略有增大，妊娠期亦可增大；更年期甲状腺多趋缩小或无明显变化，故该叙述错误。甲状腺肿大分度：不能看出但能触及为Ⅰ度；能看出又能触及但不超过胸锁乳突肌为Ⅱ度；超过胸锁乳突肌外缘为Ⅲ度，分度标准叙述均正确"},{"q":"下列疾病常可引起大咯血，但需除外","o":["肺梗死","肺结核空洞","慢性肺脓肿","支气管扩张","肺血管瘤破裂"],"a":0,"e":"大咯血常见于空洞型肺结核、支气管扩张与慢性肺脓肿，分别因空洞壁血管破裂、支气管壁血管扩张破裂及脓肿侵蚀血管所致。肺结核空洞即其典型病因。肺血管瘤破裂亦可致大咯血。肺梗死多表现为血痰或少量咯血，伴胸痛与呼吸困难，不属大咯血的常见病因，故为例外"},{"q":"下列有利于室性心动过速与室上性心动过速的鉴别的是","o":["心室率160次/min","心电图QRS波宽大畸形","既往心电图反复发现室性期前收缩","心肌缺血病史","心电图有心室夺获及室性融合波"],"a":4,"e":"室性心动过速与室上性心动过速伴心室内差异性传导均可表现为宽QRS波心动过速，心室夺获与室性融合波是心房激动下传夺获心室或与室性激动融合所致，为室速的确诊依据。QRS宽大畸形虽提示室速，但差传亦可出现。心室率160次/分无鉴别价值。既往室早、心肌缺血病史仅提供线索，均非直接证据"},{"q":"心血管疾病中，不会引起咯血的原因是","o":["肺动脉高压","二尖瓣狭窄","高血压病","肺血管炎","肺栓塞"],"a":2,"e":"二尖瓣狭窄致肺淤血、肺静脉压升高，肺泡壁或支气管黏膜血管破裂可引起咯血；肺动脉高压、肺血管炎、肺栓塞均累及肺血管或致肺梗死而出现咯血。高血压病主要引起体循环小动脉硬化，血压升高本身不直接损伤肺泡或支气管血管，故不会引起咯血。其并发症如急性肺水肿除外"},{"q":"慢性肺源性心脏病患者心电图一般不会出现下列哪项","o":["P波高尖","低电压","显著顺钟向转位","右室肥大","U波高大"],"a":4,"e":"慢性肺源性心脏病因长期缺氧与二氧化碳潴留，心电图可见Ⅱ、Ⅲ、aVF导联P波高尖即肺型P波，肢体导联低电压，显著顺钟向转位及右室肥大改变。U波高大主要见于低钾血症、洋地黄或奎尼丁作用，与肺心病无直接关联，一般不会出现。上述肺心病改变源于右心负荷增加与肺气肿所致心脏顺钟向转位"},{"q":"凝血酶时间（TT）是测定在受检血浆中加入“标准化”凝血酶溶液，到开始出现纤维蛋白丝所需的时间，一般正常值是","o":["10～16秒","15～19秒","16～18秒","20～23秒","23～25秒"],"a":2,"e":"凝血酶时间是在受检血浆中加入标准化凝血酶溶液，至开始出现纤维蛋白丝所需时间，手工法参考区间为16～18秒，超过正常对照3秒以上为延长。延长提示纤维蛋白原减少或异常、肝素或类肝素物质增多及FDP增高。10～16秒、15～19秒等区间均偏离标准参考值"},{"q":"下列是二尖瓣关闭不全杂音听诊的特征，但应除外","o":["心尖部闻及3/6级以上收缩期杂音","性质粗糙","向左腋下传导","收缩期杂音可掩盖第一心音","呼气时杂音明显增强"],"a":4,"e":"二尖瓣关闭不全杂音为心尖区粗糙的全收缩期吹风样杂音，强度多在3/6级以上，向左腋下及左肩胛下传导，常掩盖第一心音，是器质性病变的典型表现。呼气时杂音明显增强并非其听诊特征，呼吸周期改变更多用于辨别右心杂音吸气增强的规律，不构成该杂音的诊断要点。杂音强度与反流量相关，但极重度反流时因跨瓣压差减小反而减弱"},{"q":"属于暗示性或诱导性提问的是","o":["什么情况下感觉加重","什么时候发病的","您哪儿不舒服","胸部疼痛向左肩部放射吗","哪儿疼痛"],"a":3,"e":"诱导性提问在措辞中已暗示期望答案，使患者易于默认附和，如问胸痛是否向左肩放射即把放射部位强加给患者。正确问诊应用开放式提问，如您哪儿不舒服、什么情况下加重，让患者用自己的话描述。何时发病、哪里疼痛属一般性提问，不预设结论"},{"q":"IgE的主要特征是","o":["在生物进化过程中最先出现","分子量最大","主要存在血管内","可通过胎盘","与超敏反应有关"],"a":4,"e":"IgE是血清中含量最少的免疫球蛋白，为亲细胞性抗体，介导Ⅰ型超敏反应，与寄生虫感染及皮肤过敏相关。进化中最先出现的是IgM，分子量最大的也是IgM，主要存在血管内的是IgM，能通过胎盘的是IgG，这些均非IgE特征"},{"q":"第二心音反常分裂，最常见于","o":["完全性右束支传导阻滞","二尖瓣狭窄","完全性左束支传导阻滞","肺动脉高压","Ebstein畸形"],"a":2,"e":"反常分裂又称逆分裂，主动脉瓣关闭迟于肺动脉瓣，呼气时分裂明显，见于完全性左束支传导阻滞，亦可见于主动脉瓣狭窄和重度高血压。右束支传导阻滞和肺动脉高压使三尖瓣关闭延迟，引起的是S1分裂；二尖瓣狭窄主要引起S2亢进及开瓣音"},{"q":"关于病程记录的书写，错误的是","o":["主治医师首次查房记录应于患者入院48h内完成","首次病程记录应当包括病例特点、拟诊讨论及诊疗计划","抢救记录应当在抢救结束后6h内补记","接班记录应由接班医师在24h内完成","有创诊疗操作记录应当在完成操作后8h内完成"],"a":4,"e":"有创诊疗操作记录须在操作完成后即刻书写，而非8小时内，故该项时限错误。首次病程记录含病例特点、拟诊讨论与诊疗计划，入院8小时内完成；接班记录由接班医师24小时内完成；抢救记录须及时完成并具体到分钟"},{"q":"下列发热性疾病中，不伴有肝脾大的是","o":["急性ITP","传染性单核细胞增多症","病毒性肝炎","淋巴瘤","白血病"],"a":0,"e":"急性ITP为自身免疫性血小板破坏增多，临床仅表现为皮肤黏膜出血，无肝脾肿大。传染性单核细胞增多症、病毒性肝炎、淋巴瘤、白血病均可伴肝脾大，其中淋巴瘤和白血病常有脾大，病毒性肝炎急性期可有肝大"},{"q":"下列关于心房颤动的叙述都正确，但除外","o":["听诊能发现的心律失常","第一心音强弱不等","心律绝对不规则","心率少于脉率","常见于二尖瓣狭窄"],"a":3,"e":"房颤时脉搏短绌表现为脉率少于心率，而非心率少于脉率，故该项错误。其听诊特点为心律绝对不规则、第一心音强弱不等；因左室充盈量不等致心音强弱变化，部分心搏无有效脉搏。房颤常见于二尖瓣狭窄"},{"q":"触及肝时，应详细描述下列内容，但除外","o":["大小","质地","压痛","表面状态、边缘","活动度"],"a":4,"e":"触诊肝脏应描述大小、质地、压痛、表面状态与边缘，并注意肝区摩擦感等；活动度并非肝触诊的常规描述内容。活动度主要用于脾脏、肾脏或腹部包块的描述，如脾大随呼吸移动、肿块可否推动等"},{"q":"下列哪项因素不可能诱发急性胃黏膜病变","o":["颅脑手术","严重外伤","剧烈呕吐","大面积烧伤","非甾体类药物"],"a":2,"e":"急性胃黏膜病变常由颅脑手术、严重创伤、大面积烧伤等应激及非甾体类药物引起，分别对应Cushing溃疡、Curling溃疡等。剧烈呕吐导致的是食管贲门黏膜撕裂综合征，表现为呕吐后呕血，不属于急性胃黏膜病变"},{"q":"头面部的疼痛的主要传导神经是","o":["三叉神经","面神经","交感神经","视神经","听神经"],"a":0,"e":"头面部痛觉主要由三叉神经传导，三叉神经痛、牙源性及鼻源性疼痛均与其相关。面神经主要支配面部表情肌运动；视神经司视觉；听神经司听觉与平衡；交感神经参与血管舒缩，均非头面部疼痛的主要传导神经"},{"q":"正常人胸部叩诊时能查到的是","o":["Skoda叩响","Traube鼓音区","Garland三角区","Grocco三角区","Damoiseau曲线"],"a":1,"e":"左侧腋前线下方因胃底含气，叩诊呈鼓音，称Traube鼓音区，正常成人可查到。Skoda叩响、Garland三角区、Grocco三角区、Damoiseau曲线均为胸腔积液等病理情况下的叩诊表现，正常人不存在"},{"q":"少尿可见于以下情况，除外","o":["大出血","休克","肾小管酸中毒","前列腺增生","肝硬化"],"a":2,"e":"肾小管酸中毒因肾小管浓缩功能不全，表现为多尿而非少尿。大出血、休克致肾血流减少，前列腺增生致尿路梗阻，肝硬化有效循环血量不足，均可引起少尿"},{"q":"关于脾脏触诊手法下列各项均正确，但除外","o":["肿大脾脏可用右手触诊和双手触诊法","患者取仰卧位也可取右侧卧位","医生右手绕过患者腹前方，手掌置于左腰第7～10肋将脾托起","医生右手掌平放于上腹部，于左锁骨中线上触诊脾脏","脾触诊时按压不要太重"],"a":3,"e":"脾脏触诊时右手掌应平放于脐部，与左肋弓大致垂直，自脐平面开始配合呼吸迎触脾尖，而非平放于上腹部沿左锁骨中线触诊。脾大位置深时用双手触诊，左手托起左腰背部，患者可取仰卧位或右侧卧位，按压不宜过重"},{"q":"Austin Flint杂音见于","o":["重度主动脉关闭不全","器质性二尖瓣狭窄","重度二尖瓣关闭不全","重度肺动脉关闭不全","重度主动脉狭窄"],"a":0,"e":"重度主动脉瓣关闭不全时，舒张期反流血液冲击二尖瓣，限制其开放，形成相对性二尖瓣狭窄，心尖区出现柔和递减型舒张中晚期隆隆样杂音，即Austin Flint杂音。器质性二尖瓣狭窄杂音粗糙、递增型，伴震颤及开瓣音；其余瓣膜病变杂音部位与性质均不同"},{"q":"帕金森病患者走路的姿态是","o":["共济失调步态","剪刀步态","慌张步态","蹒跚步态","跨阈步态"],"a":2,"e":"慌张步态表现为起步后小步急速趋行、双脚擦地、身体前倾、难以止步，见于帕金森病。共济失调步态见于脊髓病变，跨阈步态见于腓总神经麻痹，剪刀步态见于脑瘫等肌张力增高，蹒跚步态见于肌营养不良"},{"q":"FEV1 70%，FVC 75%，FEV1/FVC 65%，TLC 75%，DLCO 80%，肺功能诊断为","o":["阻塞性通气功能障碍","限制性通气功能障碍","混合性通气功能障碍","孤立性弥散功能减低","限制性通气功能障碍伴弥散功能减低"],"a":2,"e":"FEV1/FVC降低提示阻塞性通气障碍，肺容量减少提示限制性障碍；本例FEV1/FVC 65%降低而TLC、FVC下降，兼有流速与容量损害，判为混合性。单纯阻塞性TLC正常或增高，单纯限制性FEV1/FVC正常或升高，DLCO单独下降则为弥散障碍"},{"q":"分析杂音主要注意以下几点，但除外","o":["杂音的最响部位","杂音出现的时期","杂音伴有附加心音","杂音的传导方向","杂音性质和强度"],"a":2,"e":"分析心脏杂音须注意最响部位、出现时期、性质与强度、传导方向及与呼吸体位关系；附加心音属额外心音，与心脏杂音是不同体征，不列入杂音分析要点。奔马律、开瓣音等额外心音应单独描述"},{"q":"关于AFP的叙述，下列错误的是","o":["胎儿早期由肝脏和卵黄囊合成的一种血清糖蛋白","生殖腺胚胎肿瘤，妊娠增加","是原发性肝癌的标志蛋白","AFP不升高，可除外原发性肝癌","急慢性肝炎、肝硬化可增加，其升高与肝细胞坏死与再生程度相关"],"a":3,"e":"约部分原发性肝癌患者血清AFP可不升高，故AFP正常不能排除肝癌，该项叙述错误。AFP由胎儿肝脏和卵黄囊合成，是原发性肝癌的标志蛋白，生殖腺胚胎肿瘤及妊娠可升高，急慢性肝炎、肝硬化升高与肝细胞坏死再生程度相关"},{"q":"主动脉型心（靴型心），最常见于","o":["主动脉瓣关闭不全","肺源性心脏病","二尖瓣狭窄","心包积液","二尖瓣关闭不全"],"a":0,"e":"主动脉瓣关闭不全致左心室扩大、心尖向左下移位，心浊音界呈靴形，称主动脉型心。二尖瓣狭窄引起左房大、肺动脉段突出，心腰消失呈梨形；心包积液使心界向两侧扩大且随体位改变；肺源性心脏病多为右心扩大"},{"q":"关于支气管哮喘的描述，下列不正确的是","o":["胸廓呈呼气位","两肺语颤减弱","两肺叩诊呈过清音","两肺布满哮鸣音","肺下界下移"],"a":0,"e":"哮喘发作时因呼气受阻、肺过度充气，胸廓呈吸气位（桶状胸），而非呼气位，故该项错误。两肺语颤减弱、叩诊过清音、布满哮鸣音、肺下界下移均为阻塞性肺过度充气的典型体征"},{"q":"肾源性水肿的特点是","o":["多从下肢开始继而遍及全身","多从眼睑开始而遍及全身","多伴有双上肢静脉压升高","多为非凹陷性水肿","多伴有淋巴回流受阻"],"a":1,"e":"肾源性水肿因钠水潴留及低蛋白血症，早期晨起即有眼睑与颜面水肿，迅速波及全身，伴高血压、尿检异常。从下肢开始、伴静脉压升高为心源性水肿；非凹陷性水肿见于黏液性水肿或淋巴回流受阻"},{"q":"下述为对调节辐辏反射方法与结果的描述，其中错误的是","o":["嘱患者注视1m以外目标","将目标迅速移近眼球约20cm处","正常人瞳孔渐缩小","正常人瞳孔渐扩大","双眼球同时向内聚合"],"a":3,"e":"集合（辐辏）反射为注视近物时双眼内聚、瞳孔缩小，瞳孔渐扩大的描述错误。检查时先嘱注视1m外目标再移近，瞳孔缩小属调节反射的一部分；瞳孔扩大见于暗处、兴奋或昏迷时对不同刺激的反应"},{"q":"关于问诊的方法下列各项均正确，但除外","o":["医生要向病人自我介绍","问诊要有层次，有顺序","问诊要由简单问题开始","问诊要适当地诱导提问","问诊要启发病人思考回忆"],"a":3,"e":"诱导性或暗示性提问会暗示期望答案，使患者默认附和，应避免使用，故该项错误。问诊应先自我介绍，由简单开放式问题开始，有层次、有顺序，并启发患者思考回忆"},{"q":"心绞痛引起的放射痛最可能的机制是","o":["肋间神经感觉纤维受刺激","心脏交感神经的传入纤维受刺激","支配左肩，左臂的体表神经受刺激","膈神经的感觉纤维受刺激","心脏迷走神经受刺激"],"a":1,"e":"心脏痛觉传入纤维主要随交感神经进入脊髓胸段，与左肩、左臂体表传入神经会聚于同一节段，故心肌缺血痛可放射至左肩臂。肋间神经、膈神经传导胸壁或膈肌痛，迷走神经主要支配气道，均非心绞痛放射痛的主要通路"},{"q":"诊断肠梗阻最主要的根据是","o":["腹痛","腹胀","呕吐","排便、排气减少或停止","X线见多数气液平面及胀气肠袢"],"a":4,"e":"肠梗阻确诊主要依靠X线立位片见多数气液平面及胀气肠袢，可显示梗阻部位与程度。腹痛、腹胀、呕吐、停止排气排便虽为典型症状，但均非特异性，难以单独确诊"},{"q":"腹腔脏器哪项病变不引起腹痛","o":["炎症","淤血","扭转","破裂","腹水"],"a":4,"e":"腹水仅为腹腔内液体积聚，本身不引起腹痛，大量时仅致腹胀与腹部膨隆。炎症、淤血、扭转、破裂均可刺激腹膜或牵拉包膜产生腹痛，如阑尾炎、肠扭转、肝破裂等"},{"q":"判断骨髓幼红细胞增生情况最简便的方法是","o":["血红蛋白测定","周围血液涂片检查","网织红细胞计数","骨髓涂片检查","血清铁测定"],"a":2,"e":"网织红细胞是晚幼红细胞脱核后的红细胞，其计数是反映骨髓红系造血功能最简便常用的指标，增高提示增生，减少提示造血低下。骨髓涂片虽可直接观察但属有创检查；血红蛋白、血清铁、外周血涂片不能直接反映幼红细胞增生"},{"q":"下列哪项内容不包括在既往史里","o":["传染病史","预防接种史","毒物接触史","药物过敏史","输血史"],"a":2,"e":"毒物接触史属个人史中职业与工作条件的内容，不列入既往史。既往史包括既往健康状况、传染病史、预防接种史、手术外伤史、输血史及药物过敏史"},{"q":"风湿性二尖瓣关闭不全患者可有下列哪项症状","o":["咳嗽、咯血","晕厥","心绞痛","腹痛","心悸"],"a":4,"e":"二尖瓣关闭不全致左房及左室负荷增加、心输出量下降，常表现为心悸、乏力、劳力性呼吸困难。咯血多见于二尖瓣狭窄；晕厥见于主动脉瓣狭窄；心绞痛为冠心病表现；腹痛非其常见症状"},{"q":"血小板减少到什么水平，患者易有出血症状","o":["＜10×109/L","＜20×109/L","＜50×109/L","＜100×109/L","＜200×109/L"],"a":2,"e":"血小板低于50×10⁹/L时出血倾向明显，皮肤黏膜易出现瘀点瘀斑；低于20×10⁹/L可发生自发性严重出血。100×10⁹/L以上一般无症状，200×10⁹/L属正常范围"},{"q":"心电图波形与心室动作电位的关系不正确的是","o":["QRS起始同动作电位的快速上升（0期）相对应","等电位ST段与动作电位的2期（平台期）相对应","T波与动作电位的3期（快速复极期）相对应","T波结束后的等电位段与动作电位的4期（恢复期）相对应","T波与动作电位的4期（恢复期）相对应"],"a":4,"e":"T波对应心室复极3期，而非4期；4期为静息期，相当于T波后的等电位段。QRS起始对应0期快速除极，ST段对应2期平台期，T波结束后的等电位段才对应4期"},{"q":"引起S1分裂最常见的是","o":["左束支传导阻滞","右束支传导阻滞","房间隔缺损","室间隔缺损","左心衰竭"],"a":1,"e":"完全性右束支传导阻滞使右室电活动延迟，三尖瓣关闭明显迟于二尖瓣，是S1分裂最常见原因，分裂不随呼吸变化。左束支传导阻滞引起的是S2逆分裂；房间隔缺损多见S2固定分裂"},{"q":"叩诊有移动性浊音时，腹水量最少应是","o":["2000ml","1500ml","1000ml","500ml","200ml"],"a":2,"e":"腹腔游离积液超过1000ml时，改变体位可使浊音区移动，查出移动性浊音，是发现腹水的重要方法。200～500ml腹水通常不能叩出移动性浊音，需借助超声等检查"},{"q":"高热持续期热代谢特点是","o":["散热减少，产热增加，体温增高","产热减少，散热增加，体温降低","散热减少，产热增加，体温保持高水平","产热与散热在高水平上相对平衡，体温保持高水平","产热与散热在高水平上波动，体温波动"],"a":3,"e":"高热持续期体温已达上移的调定点，寒战停止，皮肤血管扩张，产热与散热在较高水平保持相对平衡，体温维持高水平。体温上升期以散热减少、产热增加为特点；退热期散热大于产热"},{"q":"病理反射中价值最大的是","o":["Babinski征","Oppenheim征","Gordon征","Gonda征","Chaddock征"],"a":0,"e":"Babinski征是病理反射中最典型、价值最大者，阳性表现为拇趾背伸、其余四趾扇形展开。Oppenheim、Gordon、Chaddock征阳性表现与Babinski征相同，临床意义一致，但典型性与价值不及"},{"q":"关于听诊，下列哪项不正确","o":["心功能不全可闻及湿啰音","肺气肿可闻及湿啰音","支气管肺炎可闻及湿啰音","支气管扩张可闻及湿啰音","肺结核可闻及湿啰音"],"a":1,"e":"肺气肿时肺泡含气增多、呼吸音减弱，一般无湿啰音；出现湿啰音提示合并感染或肺水肿。心功能不全致肺淤血、支气管肺炎、支气管扩张、肺结核均可闻及湿啰音"},{"q":"下列各项均为急性胆囊炎体征，但除外","o":["墨菲征（＋）","胆囊叩击痛","右上腹压痛","右上腹反跳痛","Courvoisier征（＋）"],"a":4,"e":"Courvoisier征为胰头癌等压迫胆总管致胆道梗阻、胆囊显著肿大但无压痛，不见于急性胆囊炎。急性胆囊炎表现为Murphy征阳性、右上腹压痛、胆囊叩击痛，重者可有反跳痛"},{"q":"弛张热最常见的疾病是","o":["伤寒","肺炎","支气管炎","败血症","布氏杆菌病"],"a":3,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时波动超过2℃但均在正常水平以上，最常见于败血症，也见于风湿热、重症肺结核。伤寒典型为稽留热，布氏杆菌病多为波状热"},{"q":"关于反跳痛的手法描述下列各项均正确，但除外","o":["首先轻轻地浅触全腹部","常常选择腹部压痛明显部位触诊","手触及压痛部位后，嘱患者深吸气","手触及压痛部位后于原处稍停片刻","手触及压痛部位后当压痛感觉稳定时迅速将手抬起"],"a":2,"e":"反跳痛检查为触及压痛处后稍停片刻，待压痛稳定时迅速抬手，观察是否出现锐痛，无需嘱患者深吸气。深吸气用于肝脾触诊等配合呼吸的检查，与反跳痛手法无关"},{"q":"最容易出现舒张早期奔马律的疾病是","o":["主动脉瓣狭窄","肺动脉瓣狭窄","心功能不全","二尖瓣狭窄","主动脉瓣关闭不全"],"a":2,"e":"舒张早期奔马律为病理性第三心音，提示心室舒张期负荷过重、心肌严重受损，最常见于心功能不全，亦见于急性心肌梗死、重症心肌炎。瓣膜狭窄或关闭不全主要产生杂音，并非奔马律典型病因"},{"q":"风湿性心脏病二尖瓣关闭不全的主要体征是","o":["Graham-Steell杂音","心尖部听到舒张期隆隆样杂音","心尖部听到吹风样全收缩期杂音，向左腋下传导","Austin-Flint杂音","Duroziez双重杂音"],"a":2,"e":"风湿性二尖瓣关闭不全收缩期血液反流左房，心尖区闻及粗糙高调的全收缩期吹风样杂音，向左腋下及左肩胛下传导。Graham Steell杂音为肺动脉瓣舒张期杂音；Austin Flint为主动脉瓣关闭不全的相对性二尖瓣狭窄杂音；Duroziez为周围血管杂音"},{"q":"咯血最常见于","o":["慢性支气管炎","肺脓肿","肺炎","肺癌","肺结核"],"a":4,"e":"在我国肺结核仍是咯血首要原因，多为浸润性、空洞型肺结核及干酪样肺炎，因毛细血管通透性增高或血管破裂所致。支气管扩张、肺脓肿、肺癌亦可咯血，但发生率低于肺结核"},{"q":"临床诊断的内容不包括","o":["病因诊断","病史诊断","病理生理诊断","疾病的分期与分型","并发症的诊断"],"a":1,"e":"临床诊断内容包括病因诊断、病理生理诊断、疾病分期与分型、并发症及伴发病诊断等，不包括病史诊断。病史是采集资料的过程，而非诊断的构成项目"},{"q":"56岁男性胸痛患者，问诊时哪个问题不合适","o":["胸痛还向指尖放射吗","胸痛是什么样的痛","胸痛的具体位置在哪","胸痛时还有其他不舒服吗","胸痛是持续性还是发作性"],"a":0,"e":"该问法预设放射至指尖，属暗示性提问，易诱导患者附和，不合适。胸痛性质、具体位置、发作或持续性及伴随不适均为开放式提问，有利于获得真实病史"},{"q":"毛细血管壁缺陷引起皮肤黏膜出血可见于下列疾病，但除外","o":["原发免疫性血小板减少症","过敏性紫癜","单纯性紫癜","老年性紫癜","机械性紫癜"],"a":0,"e":"原发免疫性血小板减少症是血小板破坏增多所致，不属毛细血管壁缺陷。过敏性紫癜、单纯性紫癜、老年性紫癜、机械性紫癜均为血管壁缺陷或通透性增加引起的出血"},{"q":"心脏叩诊的正确顺序是","o":["先右界、后左界，由上向下，由外向内","先右界、后左界，由下向上，由右向左","先左界、后右界，由下向上，由外向内","先左界、后右界，由上向下，由外向内","先左界、后右界，由上向下，由左向右"],"a":2,"e":"心脏叩诊先叩左界，自心尖搏动外2～3cm处由外向内、逐个肋间向上至第2肋间，再叩右界，先叩出肝上界后由其上一肋间向上叩诊。由下向上、由外向内、先左后右是其要点"},{"q":"下列是胸骨下角的描述，错误的是","o":["正常约80°～120°","瘦长型较小，矮胖型较大","相当于横膈的穹隆部，深吸气时可加宽","肝左叶、胃、胰在此区域","为两侧肋弓在胸骨下端汇合成的夹角"],"a":0,"e":"胸骨下角正常约90°，并非80°～120°，故该项错误。其为两侧肋弓在胸骨下端汇合形成的夹角，瘦长型较小、矮胖型较大，深吸气可加宽，该区域有肝左叶、胃、胰等器官"},{"q":"引起S2逆分裂的是","o":["二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣狭窄","主动脉瓣狭窄","右心衰竭"],"a":3,"e":"主动脉瓣狭窄致左室排血时间延长、主动脉瓣关闭明显延迟，晚于肺动脉瓣关闭，形成逆分裂，呼气时明显。完全性左束支传导阻滞亦可引起；二尖瓣狭窄主要致P2亢进，右心衰竭与肺动脉瓣狭窄不产生典型逆分裂"},{"q":"第二心音逆分裂是指","o":["吸气时第二心音分裂明显","呼气时第二心音分裂明显","第二心音分裂与呼吸无关","呼气时听不到第二心音分裂","吸气时听不到第二心音分裂"],"a":1,"e":"逆分裂时主动脉瓣成分落后于肺动脉瓣成分，吸气时两者时距缩小、分裂变窄，呼气时分裂反而明显，与生理性分裂相反。生理性分裂为吸气时明显；固定分裂不受呼吸影响"},{"q":"负性心尖搏动可见于","o":["肺气肿","缩窄性心包炎","右心室肥大","大量心包积液","左心室肥大"],"a":1,"e":"负性心尖搏动为心脏收缩时心尖部胸壁内陷，见于缩窄性心包炎或心包与周围组织广泛粘连。肺气肿、大量心包积液使心尖搏动减弱；右室肥大、左室肥大表现为搏动增强或移位"},{"q":"再次免疫应答以哪种抗体为主","o":["IgG","IgM","IgA","IgD","IgE"],"a":0,"e":"IgG是再次免疫应答的主要抗体，也是血清中含量最高、唯一能通过胎盘的免疫球蛋白。IgM是初次免疫应答最早产生的抗体；IgA与黏膜免疫有关；IgD、IgE含量极低"},{"q":"腹部检查有振水音，最有临床意义的是","o":["餐后1～2h","餐后2～4h","餐后4～6h","餐后6～8h","餐后8～10h"],"a":3,"e":"餐后或大量饮水后出现振水音属正常，若清晨空腹或餐后6～8小时以上仍存在，提示幽门梗阻或胃扩张，才有临床意义。餐后1～6小时内的振水音多为生理性"},{"q":"窄QRS波心动过速，R-P间期小于70ms，可诊断为","o":["窦性心动过速","房性心动过速","房室结折返性心动过速","房室折返性心动过速","室性心动过速"],"a":2,"e":"房室结折返性心动过速经慢径前传、快径逆传，心房与心室几乎同时激动，RP间期短，常小于70ms。房室折返性心动过速经旁路逆传，RP间期较长；窦性心动过速、房性心动过速RP更长；室性心动过速QRS宽大"},{"q":"近年来医院感染的病原体的特点为","o":["正常菌群的致病明显增多","耐药菌株减少","新的病原体不断出现","A＋C","A＋B＋C"],"a":3,"e":"医院感染病原体多为人体正常菌群或机会致病菌，正常菌群致病明显增多，且新的病原体不断出现，如嗜肺军团菌。耐药菌株是增多而非减少，故含B的选项错误"},{"q":"下列哪项属于静脉血管杂音","o":["甲亢时甲状腺侧叶的血管杂音","多发性大动脉狭窄局部的血管杂音","肝硬化门静脉高压上腹部血管杂音","冠状动静脉瘘","动脉导管未闭"],"a":2,"e":"肝硬化门静脉高压致腹壁静脉曲张，脐周或上腹部可闻及连续性静脉营营声，属静脉性杂音。甲亢甲状腺杂音、多发性大动脉炎狭窄杂音、动脉导管未闭及冠状动静脉瘘均为动脉性杂音"},{"q":"下列凝血因子中不参与内源性凝血途径的是","o":["Ⅻ因子","Ⅺ因子","Ⅸ因子","Ⅷ因子","Ⅶ因子"],"a":4,"e":"Ⅶ因子参与外源性凝血途径，与组织因子结合启动凝血，不参与内源性途径。Ⅻ、Ⅺ、Ⅸ、Ⅷ均为内源性凝血途径因子，其缺陷可致APTT延长"},{"q":"奇脉最常见于","o":["急性左心衰竭","动脉导管未闭","大量心包积液","原发性高血压","室间隔缺损"],"a":2,"e":"奇脉为吸气时脉搏明显减弱或消失，因心包积液或缩窄使心室舒张受限、回心血量减少所致，最常见于大量心包积液。急性左心衰、室缺、动脉导管未闭、高血压一般不出现奇脉"},{"q":"下列哪项是检查脑膜刺激征的","o":["Babinski征","Oppenheim征","Hoffmann征","踝阵挛","颈项强直"],"a":4,"e":"颈项强直属脑膜刺激征，见于脑膜炎、蛛网膜下腔出血及颅内压增高，还常包括Kernig征和Brudzinski征。Babinski征、Oppenheim征、Hoffmann征为病理反射；踝阵挛为深反射亢进表现"},{"q":"哪项检查宜采用深部滑行触诊法","o":["肾脏触诊","肝脏触诊","脾脏触诊","胆囊压痛点","肠管触诊"],"a":4,"e":"深部滑行触诊法用于腹腔深部包块和胃肠病变，触到肠管或条索状包块时沿其长轴垂直方向滑动触摸。肾脏、脾脏多用双手触诊；肝脏可用单手或浮沉触诊；胆囊压痛点用钩指触诊"},{"q":"连续性杂音最常发生于","o":["二尖瓣狭窄与关闭不全","主动脉瓣狭窄与关闭不全","肺动脉瓣狭窄与关闭不全","三尖瓣狭窄与关闭不全","动脉导管未闭"],"a":4,"e":"动脉导管未闭时主动脉与肺动脉间存在异常通道，胸骨左缘第2肋间闻及粗糙响亮、机器转动样连续性杂音，收缩与舒张期持续不中断。各瓣膜狭窄与关闭不全的杂音均局限于收缩期或舒张期，不贯穿整个心动周期"},{"q":"下列正常人胆红素代谢相关的检查结果，错误的是","o":["结合胆红素0～6、8μmol/L","非结合胆红素1.7～10.2μmol/L","总胆红素1.7～21.1μmol/L","尿胆原阳性","尿胆红素阴性"],"a":2,"e":"正常血清总胆红素为3.4～17.1μmol/L，1.7～21.1μmol/L并非其参考区间，故该项错误。结合胆红素0～6.8μmol/L、非结合胆红素1.7～10.2μmol/L均正确，正常人尿胆原阳性而尿胆红素阴性"},{"q":"下列属于内源性致热原的是","o":["各种微生物病原体","炎症渗出物","白细胞介素Ⅰ","某些类固醇物质","多糖体成分及淋巴细胞激活因子"],"a":2,"e":"内源性致热原又称白细胞致热原，包括白介素-1、肿瘤坏死因子和干扰素，由白细胞产生并释放，直接作用于体温调定点。微生物病原体、炎症渗出物、类固醇及多糖体成分属外源性致热原"},{"q":"以下为血红蛋白测定值，哪项符合轻度贫血","o":["＜100g/L","＜参考值低限～90g/L","90～60g/L","90～80g/L","＜110g/L"],"a":1,"e":"轻度贫血指血红蛋白低于相应组别参考区间下限但大于90g/L，症状轻微。中度60～90g/L，重度30～59g/L，极重度小于30g/L；小于参考低限至90g/L正是轻度范围"},{"q":"低钾血症的心电图表现不包括","o":["ST段压低","T波低平","U波增高","QT间期缩短","QRS波时间延长"],"a":3,"e":"低钾血症表现为T波低平或倒置、U波增高、ST段压低及QT间期延长，QT缩短并非其表现。QT缩短见于高钙血症、高钾血症早期或洋地黄效应；QRS增宽亦可见于严重高钾"},{"q":"正常双侧上肢血压差别为","o":["5～10mmHg","10～20mmHg","20～30mmHg","40～60mmHg","30～40mmHg"],"a":0,"e":"正常人双侧上肢血压可有5～10mmHg差异，超过此范围属异常，见于多发性大动脉炎或先天性动脉畸形。下肢血压一般高于上肢20～40mmHg，下肢低于上肢提示主动脉缩窄"},{"q":"前列腺增生症患者最早出现的症状为","o":["进行性排尿困难","无痛性血尿","会阴部肿胀","尿频","尿路中断"],"a":0,"e":"官方答案为【进行性排尿困难】，但依据教材，正确答案为【尿频】。前列腺增生早期因前列腺充血刺激，尿频、尿急常为首发症状，以夜尿增多为主，之后随残余尿增加才逐渐出现进行性排尿困难、尿线变细等症状，故把进行性排尿困难当作最早症状不成立"},{"q":"心前区触到心包摩擦感提示","o":["心脏增大","心包炎","瓣膜狭窄","瓣膜关闭不全","大量心包积液"],"a":1,"e":"心包摩擦感为急性心包炎时心包膜纤维素渗出致表面粗糙，心脏搏动时脏壁两层摩擦产生，胸骨左缘第3、4肋间最明显。心脏增大、瓣膜病变不产生摩擦感；大量心包积液使两层分离，摩擦感反而消失"},{"q":"关于皮肤黏膜苍白的描述错误的是","o":["可由贫血所致","可见于休克","可见于主动脉瓣关闭不全","常需观察甲床、结膜、口腔黏膜、舌质等部位","肢端苍白，可判断为贫血"],"a":4,"e":"仅肢端苍白多因肢体动脉痉挛或阻塞，如雷诺病、血栓闭塞性脉管炎，不能据此判断贫血，故该项错误。贫血、休克、主动脉瓣关闭不全所致苍白应观察甲床、结膜、口唇黏膜等部位"},{"q":"对于心肌缺血诊断相对特异的是哪种表现","o":["ST段压低","T波倒置","T波直立高耸","T波低平","ST段抬高"],"a":0,"e":"心肌缺血发作时面向缺血导联出现缺血型ST段压低，水平型或下斜型下移不小于0.1mV，对心肌缺血诊断相对特异。T波低平或倒置亦可见于缺血但特异性低；T波高耸多见于高钾；ST段抬高提示透壁性损伤或急性心肌梗死"},{"q":"左肋弓下触及一包块，下列描述符合脾大的是","o":["包块较硬，近圆形","包块随呼吸移动有切迹","包块不随呼吸移动无切迹","包块边缘钝无切迹且位置深","包块与肝右叶相连无切迹"],"a":1,"e":"脾脏为膈下器官，随呼吸上下移动，切迹是其形态特征，触到有切迹的肋弓下包块支持脾大。胰尾囊肿边缘钝、无切迹且不随呼吸移动；腹膜后肿块位置深、固定不移动"},{"q":"下列各项为影响呼吸音强弱的因素，但应除外","o":["性别","年龄","呼吸深浅","肺组织弹性大小","听诊的方法"],"a":4,"e":"呼吸音强弱受性别、年龄、呼吸深浅及肺组织弹性等生理与病理因素影响，听诊方法属检查操作，不是决定呼吸音本身强弱的因素。深呼吸时呼吸音增强，肺气肿时减弱"},{"q":"呼吸运动可影响心脏杂音强度的是","o":["主动脉瓣关闭不全","三尖瓣关闭不全","二尖瓣关闭不全","二尖瓣狭窄伴关闭不全","主动脉瓣狭窄伴关闭不全"],"a":1,"e":"吸气时胸腔内压下降，右心回心血量增多，三尖瓣关闭不全的收缩期杂音在吸气末增强，称Carvallo征。主动脉瓣及二尖瓣病变杂音多为左心来源，吸气时多减轻或不变，主动脉瓣狭窄杂音呼气时更清楚"},{"q":"关于血尿的叙述，下列正确的是","o":["每升尿液内含血量一定超过5ml","外观洗肉水样，镜下RBC＞3个/HPF，但＜15个/HPF","外观变化不明显，离心沉淀后镜检RBC＞3个/HPF称镜下血尿","外观透明，尿色深黄为肉眼血尿","外观浓茶色或酱油色，潜血试验阳性为血尿"],"a":2,"e":"镜下血尿指尿色正常，离心沉淀后镜检每高倍视野红细胞超过3个而外观无明显改变。肉眼血尿呈洗肉水色，每升尿含血量约1ml以上即可显现；浓茶色或酱油色伴潜血阳性多为血红蛋白尿"},{"q":"下列对判断幽门梗阻最有意义的是","o":["可见胃蠕动波","上腹胀满不适","大量呕吐酸酵宿食","失水及代谢性碱中毒","有胃振水音"],"a":2,"e":"幽门梗阻以反复发作性呕吐为主，多在餐后30～60分钟发生，呕吐量大，含隔夜酸酵宿食，吐后舒服，最具诊断意义。胃蠕动波、振水音、上腹胀满及代谢性碱中毒均为伴随表现，特异性不及呕吐宿食"},{"q":"下述临床诊断，根据诊断方式和步骤的不同又可分为下列各项，但应除外","o":["直接诊断","治疗试验诊断","鉴别诊断","确定诊断","确立诊断后分期和分型诊断"],"a":1,"e":"按诊断方式与步骤，临床诊断可分为直接诊断、鉴别诊断、确定诊断以及确立诊断后的分期分型诊断等。治疗试验诊断属治疗性措施验证，并非该分类中的独立诊断类型"},{"q":"长期使用解热药或激素类药后，常出现的热型是","o":["消耗热","不规则热","回归热","稽留热","弛张热"],"a":1,"e":"解热药或糖皮质激素的应用可干扰体温曲线，使原本典型的热型变得不典型或呈不规则热。稽留热、弛张热、回归热均有较固定规律，用药后少见"},{"q":"咳嗽伴双肺哮鸣音常见于","o":["支气管扩张症","急性上呼吸道感染","肺淤血","支气管哮喘","肺脓肿"],"a":3,"e":"支气管哮喘为可逆性气道阻塞，发作时双肺满布哮鸣音，伴呼气性呼吸困难，咳嗽常为首发症状。支气管扩张以脓痰为主；肺脓肿咳大量脓臭痰；上呼吸道感染多为干咳"},{"q":"患者对红霉素过敏应记录于","o":["现病史","既往史","个人史","家族史","入院诊断"],"a":1,"e":"药物过敏史属既往史内容，应记入既往史中，包括食物或药物过敏史。现病史记录本次疾病发生发展；个人史记生活习惯与职业接触；家族史记家族遗传病；入院诊断为诊断结论"},{"q":"腰背痛伴有右上腹痛最常见的疾病是","o":["胸膜炎","急性胆囊炎","肺结核","支气管扩张","颈椎病"],"a":1,"e":"急性胆囊炎疼痛可放射至右肩背部，伴右上腹压痛及Murphy征阳性，故腰背痛伴右上腹痛首先考虑。胸膜炎、肺结核疼痛与呼吸相关；支气管扩张以咳嗽咯血为主；颈椎病为颈部局部症状"},{"q":"健康人的血涂片进行瑞氏染色后，见到的白细胞中最多的是","o":["单核细胞","中性粒分叶核细胞","中性粒杆状核细胞","淋巴细胞","嗜酸性粒细胞"],"a":1,"e":"健康人白细胞分类中中性粒细胞占比最高，约50%～70%，以外周血涂片中分叶核中性粒细胞最多见。淋巴细胞次之；单核细胞、嗜酸性粒细胞比例均较低；杆状核少于分叶核"},{"q":"最常引起意识障碍的内分泌与代谢障碍性疾病是","o":["妊娠中毒症","癫痫","高血压脑病","低氯性碱中毒","高原病"],"a":0,"e":"妊娠中毒症即妊娠高血压综合征，属内分泌与代谢障碍，可出现高血压脑病及意识障碍，为选项中该类疾病的主要代表。癫痫属神经系统疾病；高血压脑病为心血管所致；低氯性碱中毒少见；高原病为缺氧性疾病"},{"q":"正常人听诊可闻及的声音，除了","o":["第一心音","肱动脉血流音","呼吸音","肠鸣音","第三心音"],"a":1,"e":"正常人听诊可闻及第一心音、呼吸音、肠鸣音，部分青少年可闻及第三心音；肱动脉处无血流杂音，听到血管音属异常。枪击音、Duroziez杂音等均为病理情况下的周围血管征"},{"q":"以下不属于中性粒细胞反应性增多的是","o":["病毒性肝炎","铜绿假单胞菌败血症","心肌梗死","急性溶血","尿毒症"],"a":0,"e":"病毒性肝炎等病毒感染常致白细胞减少或淋巴细胞相对增多，不属于中性粒细胞反应性增多。铜绿假单胞菌败血症、心肌梗死、急性溶血、尿毒症均可出现中性粒细胞反应性增高"},{"q":"下列哪项是肝硬化门静脉高压的临床表现","o":["下肢水肿","蜘蛛痣","黄疸","食管-胃底静脉曲张","肝大"],"a":3,"e":"门静脉高压使门腔静脉侧支开放，形成食管胃底静脉曲张，破裂可致呕血黑便，是其重要临床表现。下肢水肿、蜘蛛痣、黄疸、肝大可见于肝硬化，但非门静脉高压直接表现"},{"q":"下列哪种疾病时血小板减少属于血小板生成障碍","o":["系统性红斑狼疮（SLE）","过敏性药物损伤","脾大","弥散性血管内凝血","再生障碍性贫血"],"a":4,"e":"再生障碍性贫血因骨髓造血功能衰竭，巨核细胞减少，血小板生成障碍。SLE与过敏性药物损伤为免疫性破坏增多；脾大为分布异常；DIC为消耗增多"},{"q":"引起反射性呕吐的病因包括下列疾病，但除外","o":["急性胃肠炎","青光眼","尿毒症","急性心肌梗死","泌尿系结石"],"a":2,"e":"尿毒症呕吐源于代谢废物刺激中枢及胃肠道，属中枢性或代谢性，不属反射性呕吐。急性胃肠炎刺激胃肠道、青光眼眼压增高、急性心肌梗死迷走反射、泌尿系结石刺激均可引起反射性呕吐"},{"q":"Austin Flint杂音可发生于下列哪种疾病","o":["动脉导管未闭","肺动脉瓣狭窄","肺动脉瓣关闭不全","主动脉瓣狭窄","主动脉瓣关闭不全"],"a":4,"e":"Austin Flint杂音见于中重度主动脉瓣关闭不全，反流血液限制二尖瓣开放形成相对性狭窄，心尖区舒张中晚期隆隆样杂音。动脉导管未闭为连续性杂音；肺动脉瓣病变杂音在胸骨左缘；主动脉瓣狭窄为收缩期喷射性杂音"},{"q":"下列哪项不是血小板功能试验","o":["血块退缩试验","血小板黏附试验","血小板聚集试验","血小板计数","PF3有效性检测"],"a":3,"e":"血小板计数反映血小板数量，不属于功能试验。血小板黏附试验、聚集试验、血块退缩试验及PF3有效性检测均反映血小板黏附、聚集、释放及促凝功能"},{"q":"急性内脏穿孔引起急性弥漫性腹膜炎的腹痛特点为","o":["全腹持续性剧烈疼痛","阵发性绞痛","钻顶样疼痛","烧灼样疼痛","间歇性钝痛"],"a":0,"e":"内脏穿孔后胃肠内容物进入腹腔，刺激腹膜产生持续性广泛剧烈腹痛，伴板样强直及压痛反跳痛。阵发性绞痛见于肠梗阻；钻顶样痛见于胆道蛔虫；烧灼样痛多为胃十二指肠溃疡；间歇性钝痛程度较轻"},{"q":"胸腔积液患者的胸膜摩擦音消失提示","o":["胸腔积液增多","胸腔积液减少","胸腔积液不变","出现肺炎","胸腔积液完全消失"],"a":0,"e":"胸膜摩擦音因脏壁两层胸膜摩擦产生，积液增多使两层分开，摩擦音消失，故提示积液增多而非减少或消失。积液减少时两层重新接近，摩擦音可再次出现"},{"q":"成年女性尿中易见","o":["小圆细胞","表层移行上皮细胞","中层移行上皮细胞","底层移行上皮细胞","扁平上皮细胞"],"a":4,"e":"尿中扁平上皮细胞即鳞状上皮细胞，女性尿道口及阴道污染常见，参考区间女性3～5个/HPF。小圆细胞、移行上皮细胞来自尿路深层，正常尿中无或偶见，出现增多提示病变"},{"q":"下列疾病均出现脾浊音区扩大，但除外","o":["胰腺炎","肝硬化","肝癌","柏-查综合征","慢性粒细胞白血病"],"a":0,"e":"肝硬化、肝癌、柏-查综合征、慢性粒细胞白血病均可致脾大，使脾浊音区扩大。胰腺炎主要累及胰腺，表现为上腹痛及淀粉酶升高，一般不引起脾大"},{"q":"慢性腹泻是指腹泻时间超过","o":["1个月","2个月","3个月","4个月","5个月"],"a":1,"e":"腹泻病程超过2个月为慢性腹泻，2个月内为急性腹泻。该时限用于区分急性与慢性腹泻，对病因判断有指导意义"},{"q":"下列不属于大细胞性贫血的是","o":["叶酸、维生素B12缺乏所致巨幼细胞贫血","妊娠期所致巨幼细胞贫血","婴儿期所致巨幼细胞贫血","地中海贫血","恶性贫血"],"a":3,"e":"地中海贫血因珠蛋白合成障碍，呈小细胞低色素性贫血，不属大细胞性贫血。叶酸、维生素B12缺乏及妊娠期、婴儿期巨幼细胞贫血和恶性贫血均属大细胞性贫血"},{"q":"引起发热最常见的病因是","o":["真菌感染","恶性肿瘤","变态反应","细菌感染","病毒感染"],"a":3,"e":"发热病因以感染最常见，其中细菌感染最为多见，严重全身性细菌感染时PCT显著升高。病毒感染、真菌感染、恶性肿瘤及变态反应亦可致发热，但发生率低于细菌感染"},{"q":"以下可鉴别右心衰竭和肝硬化的体征是","o":["双下肢凹陷性水肿","肝颈静脉反流征阳性","肝大","脾大","腹水"],"a":1,"e":"右心衰竭致体循环淤血，压迫肝脏时颈静脉怒张更明显，肝颈静脉反流征阳性；肝硬化无此征。双下肢水肿、肝大、脾大、腹水在两者均可出现，鉴别价值有限"},{"q":"梗阻性黄疸的表现不包括","o":["结合胆红素明显增高","非结合胆红素轻度增高","总胆红素明显增高","尿胆原增高","尿胆红素强阳性"],"a":3,"e":"梗阻性黄疸时结合胆红素反流入血，尿胆红素强阳性，因胆道梗阻尿胆原减少或消失，故尿胆原增高不属于其表现。尿胆原增高多见于溶血性黄疸"},{"q":"下列因素对体温均有影响，除了","o":["妊娠","哺乳","月经","运动","进食"],"a":1,"e":"妊娠、月经、运动、进食均可使体温略有升高，属影响体温的生理因素；哺乳一般不作为体温波动的常见影响因素。正常体温下午较早晨稍高，波动不超过1℃"},{"q":"下列关于听诊的叙述均正确，但除外哪一项","o":["听诊可分为直接听诊和间接听诊两种","听诊时环境要安静、温暖、避风","间接听诊法还可听取皮下气肿音、肌束颤动音等","膜型听诊器适用于听取低调声音","听诊器的体件要紧贴于被检查的部位"],"a":3,"e":"膜型体件能滤过低音调，适用于高音调声音，如主动脉瓣舒张期叹气样杂音、呼吸音、肠鸣音；钟型体件才适用于低调声音，如二尖瓣狭窄的隆隆样杂音。听诊环境应安静温暖，体件须紧贴皮肤"},{"q":"血清总胆固醇降低见于","o":["甲状腺功能减退症","冠心病","肾病综合征","贫血","妊娠期"],"a":3,"e":"贫血、甲状腺功能亢进、严重肝病等可使血清总胆固醇降低。甲状腺功能减退、冠心病、肾病综合征常伴胆固醇升高；妊娠期血脂可升高"},{"q":"前列腺位于膀胱下方，其位于耻骨联合后约","o":["1cm","2cm","3cm","4cm","5cm"],"a":2,"e":"官方答案为【3cm】，但依据教材，正确答案为【2cm】。教材明确记载前列腺位于膀胱下方、耻骨联合后约2cm处，形如栗子，中间有纵行浅沟，故耻骨联合后3cm的说法与教材不符"},{"q":"下列有关发热概念的叙述，哪项正确","o":["体温超过正常值0、6℃","产热过程超过散热过程","是临床上常见的疾病","由体温调节中枢调定点上移引起的体温升高","由体温调节中枢调节功能障碍引起的体温升高"],"a":3,"e":"发热是在致热原作用下，体温调节中枢调定点上移引起的体温升高，超出正常范围。体温超过正常值0.5℃表述不严谨；产热大于散热仅见于体温上升期；发热是症状而非独立疾病；调节功能障碍所致体温升高并非典型发热定义"},{"q":"脾于肋下3cm，属于","o":["轻度肿大","中度肿大","高度肿大","巨脾","正常"],"a":1,"e":"脾缘超过肋下2cm、在脐水平线以上为中度肿大，故肋下3cm属中度。不超过肋下2cm为轻度；超过脐水平线或前正中线为高度肿大即巨脾"},{"q":"成年男性血红蛋白参考值为","o":["110～150g/L","120～160g/L","110～140g/L","120～150g/L","120～140g/L"],"a":1,"e":"常用教材参考区间中成年男性血红蛋白约120～160g/L，成年女性约110～150g/L。其余选项上限多为150g/L或下限偏低，不符合成年男性标准"},{"q":"下列为肺下界叩诊的正确描述，但应除外","o":["两侧肺下界大致相同","平静呼吸时位于锁骨中线上第6肋间隙","平静呼吸时位于腋中线上第8肋间隙","平静呼吸时位于肩胛线上第10肋间隙","体型和发育情况不同，肺下界位置无差异"],"a":4,"e":"肺下界位置因体型发育而异，矮胖者可上升一肋间隙，瘦长者可下降一肋间隙，故无差异的说法错误。两侧肺下界大致相同，平静呼吸时锁骨中线第6肋间、腋中线第8肋间、肩胛线第10肋间"},{"q":"直接作用于体温调节中枢引起发热的是","o":["病原体产生的外源性致热源","病原体产生的内源性致热源","血液中的白细胞产生的外源性致热源","血液中的白细胞产生的内源性致热源","血液中的白细胞及病原体产生的代谢产物"],"a":3,"e":"外源性致热原分子量大，不能通过血脑屏障，须激活白细胞等释放内源性致热原，后者才直接作用于下丘脑体温调定点引起发热。病原体本身及代谢产物均属外源性，不能直接作用"},{"q":"出现下列哪项表现最可确诊为器质性心脏病","o":["心尖部第三心音","心前区震颤","心率120次/min","肺动脉瓣区第二心音分裂","心尖部收缩期吹风样杂音2/6级"],"a":1,"e":"心前区震颤为器质性心脏病的特征性体征，触及震颤即可确定有器质性病变，如瓣膜狭窄、室缺、动脉导管未闭。第三心音、功能性杂音、心率增快及P2分裂均可见于健康人或功能性情况"},{"q":"以下为血红蛋白测定值，其中符合极重度贫血的是","o":["＜30g/L","＜20g/L","＜40g/L","＜50g/L","＜10g/L"],"a":0,"e":"血红蛋白小于30g/L为极重度贫血，休息时即有严重心慌气短。轻度大于90g/L，中度60～90g/L，重度30～59g/L"},{"q":"关于弛张热的描述，不正确的是","o":["又称败血症热型，常见于败血症、风湿热","体温常在39℃以上","波动幅度大","有时达正常水平","24小时内波动范围超过2℃"],"a":3,"e":"弛张热体温常在39℃以上，24小时波动超过2℃，但始终在正常水平以上，故有时达正常水平的描述错误。体温可降至正常水平、高热与无热期交替的是间歇热"},{"q":"肝颈静脉反流征阳性是由于","o":["腹主动脉搏动传导所致","右心室的收缩搏动通过右心房、下腔静脉传导","右心衰竭引起肝淤血","左心室收缩搏动","左心衰竭"],"a":2,"e":"右心衰竭时肝淤血肿大，压迫肝脏使回心血量增加，充血的右心房不能容纳，颈静脉压升高而怒张更明显。腹主动脉搏动、左心衰竭及单纯心脏搏动传导均非其机制"},{"q":"下列可见到负性心尖冲动的是","o":["扩张型心肌病","严重贫血患者","肺气肿患者","粘连性心包炎","高血压心脏病"],"a":3,"e":"负性心尖搏动为收缩期心尖部胸壁内陷，见于粘连性心包炎或心包与周围组织广泛粘连，也可见于重度右室肥厚致心脏顺钟向转位。扩张型心肌病、严重贫血、高血压心脏病多表现为搏动增强，肺气肿为搏动减弱"},{"q":"消瘦的含义正确的是","o":["体重减轻到低于正常的5%","体重减轻到低于正常的10%","体重减轻到低于正常的15%","体重减轻到低于正常的20%","体重减轻到低于正常的25%"],"a":1,"e":"体重低于标准体重10%即可诊断消瘦，BMI小于18.5kg/m²亦为消瘦标准。5%未达诊断标准，15%、20%已属明显或重度消瘦，非诊断界值"},{"q":"关于急性白血病特点的叙述，下列中不符合的是","o":["大多起病急骤","每有发热、贫血、出血表现","血浆中血小板大都减少","骨髓中主要是接近成熟阶段细胞","骨髓中原幼细胞恶性变明显"],"a":3,"e":"急性白血病骨髓中以原始及幼稚细胞恶性增生为主，接近成熟阶段细胞为主是慢性白血病的特点，故该项不符合。急性白血病多起病急，有发热、贫血、出血及血小板减少，原幼细胞恶性变明显"},{"q":"对下面心电图诊断正确的是","o":["左房增大","右房增大","左室肥厚","右室肥厚","心电图正常"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。该题须依据所给心电图波形判断左房或右房增大、左右室肥厚，但题面未提供图形。左室肥厚表现为V5导联R波增高、R/S大于1及电轴左偏；右室肥厚以V1导联R波为主、电轴右偏；左房增大见P波增宽呈双峰，右房增大见P波高尖\n\n官方题库中缺失图片"},{"q":"高位小肠梗阻的特点是","o":["腹部可见明显肠型","腹胀明显","呕吐频繁","水电解质紊乱出现较慢","呕吐物常有粪臭"],"a":2,"e":"高位小肠梗阻呕吐出现早且频繁，量较大，可吐出胃肠液及胆汁，腹胀不明显。低位小肠梗阻呕吐晚，可吐粪臭味内容物；水电解质紊乱在高位梗阻出现较快而非较慢"},{"q":"下列凝血因子在转变为活化凝血因子过程中不需要Ca2＋参与的是","o":["Ⅻ→Ⅻa","Ⅺ→Ⅺa","Ⅹ→Ⅹa","Ⅱ→Ⅱa","ⅩⅢ→ⅩⅢa"],"a":0,"e":"Ⅻ因子通过接触激活启动内源性凝血，其活化不依赖Ca²⁺；其余凝血因子活化多需Ca²⁺参与。Ⅹ→Ⅹa、Ⅱ→Ⅱa均需在Ca²⁺参与的复合物上进行，ⅩⅢ→ⅩⅢa亦由凝血酶在Ca²⁺作用下完成"},{"q":"腹腔渗出液常见于以下哪种疾病","o":["慢性心功能不全","结核性腹膜炎","重度营养不良","肾病综合征","肝硬化"],"a":1,"e":"结核性腹膜炎为腹膜炎症，产生渗出液，SAAG小于11g/L。慢性心功能不全、肾病综合征、肝硬化所致腹水为漏出液，重度营养不良亦为漏出性"},{"q":"鸡鸣样咳嗽见于","o":["纵隔肿瘤","严重肺气肿","声带麻痹","肺肿瘤压迫喉返神经","百日咳"],"a":4,"e":"鸡鸣样咳嗽表现为连续阵发性剧咳伴高调吸气回声，多见于百日咳，也可见于会厌喉部疾病或气管受压。金属音咳嗽见于纵隔肿瘤或肺癌；咳嗽低微无力见于严重肺气肿、声带麻痹"},{"q":"临床诊断思维的基本原则，下列错误的是","o":["实事求是","“一元论”原则","“首先考虑少发病”的原则","“首先考虑器质性疾病存在”的原则","“首先考虑可治疾病的诊断”的原则"],"a":2,"e":"临床诊断应首先考虑常见病、多发病，符合概率分布原理，首先考虑少发病的原则错误。实事求是、一元论、首先考虑器质性疾病及首先考虑可治性疾病均为基本原则"},{"q":"内源性致热原的作用部位是","o":["中性粒细胞","下丘脑体温调节中枢","骨骼肌","皮肤","外周血管"],"a":1,"e":"内源性致热原通过血脑屏障直接作用于下丘脑体温调节中枢的体温调定点，使其上移而致发热。中性粒细胞是产生释放内源性致热原的细胞；骨骼肌、皮肤、外周血管是发热效应部位，并非其作用部位"},{"q":"引起腹痛的胃肠神经功能紊乱见于下列疾病，但除外","o":["功能性消化不良","胃神经官能症","慢性胰腺炎","胆道运动功能障碍","肠易激综合征"],"a":2,"e":"慢性胰腺炎属腹腔脏器慢性炎症，为器质性病变，不属于胃肠神经功能紊乱。功能性消化不良、胃神经官能症、胆道运动功能障碍、肠易激综合征均为胃肠动力或神经功能异常所致"},{"q":"血浆凝血酶原时间明显延长缺乏的凝血因子是","o":["Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅷ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅸ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅺ","Ⅰ、Ⅱ、Ⅴ、Ⅷ、Ⅻ"],"a":2,"e":"PT是外源性凝血系统的筛选试验，延长见于因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及低纤维蛋白原血症，故为Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ。因子Ⅷ、Ⅸ、Ⅺ、Ⅻ属内源性途径，缺乏时APTT延长而PT正常"},{"q":"正常体温在24小时内波动范围一般不超过","o":["0.5℃","1.0℃","1.5℃","2.0℃","2.5℃"],"a":1,"e":"正常体温下午较早晨稍高，运动或进餐后可略升，但24小时内波动范围一般不超过1℃。稽留热24小时波动亦不超过1℃，但其体温处于39～40℃以上高水平"},{"q":"关于鼻咽部的描述，下列哪项是错误的","o":["鼻咽位于软腭平面之上、鼻腔后方","儿童期，鼻咽部淋巴结组织丰富","儿童期后，腺样体逐渐萎缩","腺样体过度肥大，可导致语音单调","鼻咽部一侧有血性分泌物和耳鸣、耳聋，应考虑鼻咽癌"],"a":2,"e":"鼻咽部淋巴组织在儿童时期丰富称腺样体，青春期前后才逐渐萎缩，故儿童期后即萎缩的说法不准确。鼻咽位于软腭平面之上鼻腔后方；腺样体过度肥大可致鼻塞、语音单调；一侧血性分泌物伴耳鸣耳聋应警惕鼻咽癌"},{"q":"心包摩擦音不会出现于","o":["肺动脉栓塞","室间隔穿孔","心室壁破裂","心肌梗死后综合征","纤维素性心包炎"],"a":1,"e":"室间隔穿孔为心肌梗死后机械并发症，产生收缩期杂音，不引起心包摩擦音。纤维素性心包炎、心肌梗死后综合征可致心包炎出现摩擦音；肺动脉栓塞累及心包、心室壁破裂血液进入心包亦可出现"},{"q":"胆红素在肝内的结合主要是指","o":["与白蛋白的结合","与葡萄糖醛酸的结合","与硫酸基的结合","与甘氨酸甲基的结合","与Y或Z胞浆载体的结合"],"a":1,"e":"非结合胆红素被肝细胞摄取后，在葡萄糖醛酸转移酶催化下与葡萄糖醛酸结合，形成结合胆红素，此为肝内结合的主要形式。与白蛋白结合发生在血液运输中；与Y、Z蛋白结合是肝细胞内转运；与硫酸基结合非主要途径"},{"q":"易合并肢端肥大症的疾病是","o":["腺垂体功能亢进","风湿性心脏病","先天性心脏病","支气管扩张","慢性肺脓肿"],"a":0,"e":"成年后腺垂体功能亢进、生长激素分泌过多致肢端肥大症，青春期前发病则为巨人症。风湿性心脏病、先天性心脏病、支气管扩张、慢性肺脓肿均为心肺疾病，与生长激素无关"},{"q":"肌力检查记录分（ ）个等级","o":["5","2","3","4","6"],"a":4,"e":"肌力按0～5级共6个等级记录：0级完全瘫痪，1级可见肌肉收缩，2级可水平移动，3级可抗重力抬起，4级可抗阻力，5级正常"},{"q":"关于心脏听诊，说法正确的是","o":["心脏瓣膜听诊区就是瓣膜的解剖部位所在区域","钟型听诊体件更适宜听高音调的杂音","主动脉瓣舒张期叹气样杂音更适宜用模型体件听诊","心脏听诊区域对每个个体都是固定不变的","怀疑二尖瓣狭窄患者取坐位前倾位更易闻及"],"a":2,"e":"膜型体件能滤过低音调，适用于高音调声音，主动脉瓣舒张期叹气样杂音宜用膜型。瓣膜听诊区不在瓣膜解剖投影处且个体差异存在；钟型体件适于低调杂音；二尖瓣狭窄杂音左侧卧位更清楚"},{"q":"下列指标可诊断伤寒、副伤寒的是","o":["TO＞1∶80，TH＜1∶160，甲、乙、丙H凝集价＜1∶80","TO＞1∶80，TH＞1∶160，甲、乙、丙H凝集价＞1∶80","TO＞1∶80，TH＜1∶160，甲、乙、丙H凝集价＞1∶80","TO＜1∶80，TH＜1∶160，甲、乙、丙H凝集价＜1∶80","TO＜1∶80，TH＜1∶160，甲、乙、丙H凝集价＞1∶80"],"a":1,"e":"肥达反应中O效价大于1∶80、H效价大于1∶160，副伤寒甲、乙、丙H凝集价大于1∶80有诊断意义，动态升高4倍以上价值更大。仅TO升高或各项均低不能确诊伤寒副伤寒"},{"q":"下列疾病可出现Kussmaul呼吸的是","o":["贫血","左心衰竭","右心衰竭","酮症酸中毒","吗啡中毒"],"a":3,"e":"严重代谢性酸中毒时细胞外液碳酸氢根不足、pH降低，通过深快呼吸排出CO₂代偿，称Kussmaul呼吸，见于糖尿病酮症酸中毒和尿毒症酸中毒。贫血、心衰、吗啡中毒多表现为其他类型呼吸困难或呼吸抑制"},{"q":"关于梨形心，下列说法正确的是","o":["可见于高血压患者","可见于升主动脉扩张","心腰凹陷，加深明显","同左心房扩大有关","以胸骨右缘心界扩大为主"],"a":3,"e":"二尖瓣狭窄致左房扩大、肺动脉段突出，心腰消失，心浊音界呈梨形。高血压、升主动脉扩张致左室扩大呈靴形心；心界扩大不以胸骨右缘为主"},{"q":"下列可以传导颅内外痛觉的脑神经是","o":["第1/2对脑神经","第3/4/7对脑神经","第6/7/8对脑神经","第5/9/10对脑神经","第11/12对脑神经"],"a":3,"e":"传导颅内外痛觉的脑神经主要为三叉神经、舌咽神经和迷走神经，即第5、9、10对，尚包括面神经及颈1～3神经。第1、2对为嗅、视神经；第3、4、7对中动眼滑车司眼球运动；第6、8对为展神经和听神经"},{"q":"对骨关节炎描述错误的是","o":["多见于中老年人","晨僵时间常大于60min","爬楼、久站后疼痛加剧","休息能缓解疼痛","好发于负重较大的关节，如膝关节、髋关节"],"a":1,"e":"骨关节炎晨僵时间短，一般不超过30分钟，活动后缓解；晨僵超过60分钟是类风湿关节炎的特点，故该项错误。骨关节炎多见于中老年人，好发负重关节，久站爬楼痛甚，休息可缓解"},{"q":"对触觉较为敏感的部位是","o":["手指指腹","掌指关节面掌部","手背皮肤","小鱼际","大鱼际"],"a":0,"e":"手指指腹皮肤对触觉较为敏感，掌指关节掌面皮肤对震动敏感，手背皮肤对温度敏感，触诊时应据检查目的合理选用部位"},{"q":"心尖部触及舒张期震颤，最常见于","o":["法洛四联症","二尖瓣狭窄","二尖瓣脱垂","室间隔缺损","三尖瓣狭窄"],"a":1,"e":"心尖区舒张期震颤是二尖瓣狭窄的典型体征，因舒张期血流通过狭窄瓣口产生湍流所致，左侧卧位更明显。室间隔缺损震颤在胸骨左缘第3、4肋间收缩期；法洛四联症、三尖瓣狭窄部位与时相均不同"},{"q":"下列为血管内液与组织液之间保持动态平衡的主要因素，但应除外","o":["毛细血管血压","血浆胶体渗透压","毛细血管通透性","组织液静水压","组织液的胶体渗透压"],"a":2,"e":"血管内液与组织液间的动态平衡依赖Starling forces，即毛细血管血压、血浆胶体渗透压、组织液静水压及组织液胶体渗透压；毛细血管通透性影响物质交换但不属维持平衡的主要因素"},{"q":"肝颈静脉回流征是指","o":["用手压迫肝，使颈静脉怒张消失","用手压迫肝，使颈静脉怒张明显","用手压迫肝，颈静脉怒张无改变","用手压迫肝，颈静脉出现搏动","用手压迫肝，颈静脉出现震颤"],"a":1,"e":"肝颈静脉回流征指压迫淤血肿大的肝脏使回心血量增加，颈静脉怒张更明显，见于右心衰竭。压迫后怒张消失、无改变或出现搏动震颤均非该征定义"},{"q":"导致脉压增大的疾病是","o":["主动脉瓣狭窄","心力衰竭","低血压","主动脉瓣关闭不全","缩窄性心包炎"],"a":3,"e":"主动脉瓣关闭不全时舒张期血液反流，舒张压显著下降，收缩压升高，脉压增大，可伴枪击音等周围血管征。主动脉瓣狭窄、心力衰竭、低血压、缩窄性心包炎均使脉压减小"},{"q":"下列可引起混合性呼吸困难的是","o":["气管异物","喉痉挛","慢性阻塞性肺气肿","支气管哮喘","重症肺炎"],"a":4,"e":"重症肺炎时肺实变范围广、通气与换气功能均受损，吸气与呼气均费力，表现为混合性呼吸困难。气管异物、喉痉挛为吸气性；慢性阻塞性肺气肿、支气管哮喘为呼气性"},{"q":"神经浅反射不包括","o":["角膜反射","腱反射","提睾反射","跖反射","肛门反射"],"a":1,"e":"腱反射即深反射，刺激骨膜肌腱经深部感受器完成，如肱二头肌、膝腱、跟腱反射。角膜反射、提睾反射、跖反射、肛门反射均属浅反射"},{"q":"主动脉瓣听诊区第二心音减弱，最常见于","o":["主动脉瓣狭窄","二尖瓣狭窄","高血压","主动脉粥样硬化","肺动脉瓣狭窄"],"a":0,"e":"主动脉瓣狭窄或关闭不全致半月瓣钙化、活动受限，A2减弱。高血压、动脉粥样硬化使A2亢进；二尖瓣狭窄不影响主动脉瓣成分；肺动脉瓣狭窄影响P2"},{"q":"下列关于消化性溃疡的症状均正确，但除外","o":["上腹痛","恶心呕吐","食欲缺乏","反酸嗳气","腹泻"],"a":4,"e":"消化性溃疡以上腹痛为主要症状，伴恶心呕吐、食欲缺乏、反酸嗳气等消化不良表现；腹泻不属其典型症状，多为肠道疾病所致"},{"q":"胸骨左缘第3～4肋间触及收缩期震颤，最常见的是","o":["房间隔缺损","动脉导管未闭","室间隔缺损","二尖瓣脱垂","二尖瓣关闭不全"],"a":2,"e":"胸骨左缘第3、4肋间收缩期震颤是室间隔缺损的典型体征，由左向右分流产生湍流所致。房间隔缺损多为S2固定分裂；动脉导管未闭为胸骨左缘第2肋间连续性杂音；二尖瓣病变震颤在心尖区"},{"q":"单纯性紫癜导致皮肤黏膜出血的机制是","o":["血小板数量和/或功能异常","毛细血管壁缺陷","凝血因子缺陷","抗凝物质增加","纤维蛋白溶解亢进"],"a":1,"e":"单纯性紫癜因毛细血管壁先天缺陷或损伤，不能正常收缩止血而致皮肤黏膜出血，与过敏性紫癜、老年性紫癜同属血管壁缺陷。血小板数量功能异常、凝血因子缺陷、抗凝物质增加及纤溶亢进为其他出血机制"},{"q":"以下味觉检查方法有误的是","o":["应用不同味觉物质测试","避免有害物质进行测试","每次检查先检查患侧","每次检查先检查正常侧","患者不能讲话"],"a":3,"e":"味觉检查应先查患侧，以正常侧作对照比较，先查正常侧的设置错误。检查应用不同味觉物质，避免有害物质，患者不能讲话，以手势表达感受"},{"q":"以下不符合左心衰竭心脏体征的是","o":["心脏扩大","相对性二尖瓣关闭不全的反流性杂音","肺动脉瓣区第二心音亢进","舒张期奔马律","收缩期奔马律"],"a":4,"e":"左心衰竭可见心脏扩大、相对性二尖瓣关闭不全的反流性杂音、P2亢进及舒张期奔马律；并无所谓收缩期奔马律，故该项不符合。舒张晚期奔马律又称收缩期前奔马律，属舒张期额外心音"},{"q":"S2固定分裂见于哪种疾病","o":["二尖瓣关闭不全","室间隔缺损","房间隔缺损","动脉导管未闭","法洛四联症"],"a":2,"e":"房间隔缺损时虽有呼气时右房回血减少，但左房向右房分流持续存在，右心排血时间延长，肺动脉瓣关闭明显延迟，S2分裂不受呼吸影响而固定。室缺、动脉导管未闭多为左向右分流但无固定分裂；法洛四联症P2减弱"},{"q":"血小板破坏或消耗亢进，不包括","o":["系统性红斑狼疮","弥散性血管内凝血","病毒感染","先天性血小板减少症","慢性粒细胞性白血病"],"a":4,"e":"血小板破坏或消耗亢进见于SLE产生自身抗体、DIC大量消耗及病毒感染等；慢性粒细胞性白血病骨髓巨核细胞增生，血小板常正常或增高，不属此类"},{"q":"脾脏高度肿大时，脾脏大小为","o":["脾缘超过左肋下2cm以上","脾缘超过左肋下5cm以上","脾缘刚达到脐平","脾缘超过前正中线","脾缘超过左肋下6cm以上"],"a":3,"e":"脾缘超过脐水平线或前正中线为高度肿大即巨脾；超过肋下2cm至脐水平线以上为中度；不超过肋下2cm为轻度"},{"q":"急性心包炎的诊断最具特征性的体征是","o":["心界随体位而变","心音减弱","奇脉","大循环淤血征","心包摩擦音"],"a":4,"e":"心包摩擦音为急性心包炎最具特征性的体征，因纤维素渗出致心包脏壁层粗糙，随心脏搏动摩擦产生，胸骨左缘第3、4肋间明显，屏气时仍存在。心界随体位改变、心音减弱、奇脉及淤血征多见于大量心包积液或缩窄，非急性心包炎早期特征"},{"q":"膀胱刺激征是指","o":["尿频、尿急、尿痛","血尿、尿频、尿急","脓尿、尿急、尿频","尿频、尿痛、脓尿","尿频、尿痛、血尿"],"a":0,"e":"膀胱刺激征是膀胱、尿道黏膜受刺激所产生的一组症状，典型三联为尿频、尿急、尿痛，常见于膀胱炎和尿道炎。血尿、脓尿虽可伴随出现，但不属于刺激征本身。B项血尿为尿色异常；C、D项脓尿提示化脓性感染；E项血尿均为伴随表现而非刺激征的组成"},{"q":"尿三杯试验中如第一杯为血尿，则病变部位在","o":["前尿道","后尿道","膀胱三角区","输尿管","肾脏"],"a":0,"e":"尿三杯试验依血尿出现时段定位：起始段即第一杯血尿提示前尿道病变，因排尿之初尿流冲刷尿道所致。终末段血尿多指向膀胱三角区、后尿道或前列腺；全程血尿则提示肾脏、输尿管或膀胱本体病变。B、C项对应终末血尿，D、E项对应全程血尿，均非第一杯血尿的定位"},{"q":"下列疾病均表现为干性咳嗽，除外","o":["急性咽喉炎","慢性支气管炎","胸膜炎","轻症肺结核","急性支气管炎初期"],"a":1,"e":"干性咳嗽指无痰或痰量极少，见于急性咽喉炎、胸膜炎、轻症肺结核及急性支气管炎初期。慢性支气管炎以长期反复咳痰为特征，每日痰量常超过10ml，属湿性咳嗽，故为例外。急性支气管炎初期虽可干咳，随病程进展多转为湿性，但不改变本题判断"},{"q":"关于正常心脏浊音界的叙述，下列正确的是","o":["心左界在第2肋间几乎与胸骨左缘一致","心右界在第5肋间处稍偏离胸骨右缘","在第3肋间心左界与前正中线距离3～4cm","在第4肋间心右界与前正中线距离4～5cm","在第5肋间心左界与前正中线距离8～10cm"],"a":0,"e":"正常心浊音界左界自第2肋间起向外渐成内凹弧形，第2肋间处几乎与胸骨左缘一致；右界各肋间几乎与胸骨右缘一致，仅第4肋间稍超过。B项右界第5肋间并不偏离胸骨右缘；D项第4肋间右界仅约3～4cm；E项第5肋间左界约7～9cm，均非8～10cm。C项第3肋间左界约3.5～4.5cm"},{"q":"下列各项是腹部触诊内容，但除外","o":["腹壁肌紧张","压痛与反跳痛","腹部肿块","移动性浊音","振水音"],"a":3,"e":"腹部触诊内容主要包括腹壁肌紧张、压痛与反跳痛、腹部肿块及振水音等，靠手感判断。移动性浊音是检查腹腔积液的叩诊方法，需变换体位并叩击腹部，属叩诊而非触诊。B项反跳痛为腹膜刺激征的触诊表现；E项振水音在本题归入触诊内容，均不属例外"},{"q":"主动脉瓣狭窄时，心脏最主要的代偿机制是","o":["心率加快","左心室肥厚","回心血量增加","左心室扩张","交感神经兴奋"],"a":1,"e":"主动脉瓣狭窄使左室排血受阻、后负荷增高，左心室以心肌肥厚增强收缩力维持心排血量，这是最主要代偿机制；但肥厚使顺应性下降、舒张末压升高。心率加快与交感兴奋仅为次要反应；左室扩张属失代偿阶段表现，回心血量增加并非针对梗阻的代偿"},{"q":"患者，女，22岁。因“腹泻3天”入院。在问诊伴随症状时，还应关注除外","o":["有无呕吐","有无腹痛","有无胸痛","有无发热","有无里急后重"],"a":2,"e":"腹泻伴随症状是鉴别病因的线索，应关注有无呕吐、腹痛、发热及里急后重：腹痛提示肠道炎症或痉挛，里急后重提示直肠受累，发热提示感染。胸痛与腹泻无明显关联，多指向心肺疾病，不属腹泻常规问诊的伴随症状。A、B、D、E项均为腹泻问诊的常规内容"},{"q":"下列是关于色觉的正确叙述，但应除外哪一项","o":["色觉的异常可分为色弱和色盲两种","色盲是对颜色识别能力的丧失","色弱是对颜色识别能力的减弱","色觉的检查被列为检体的常规项目之一","色盲为先天性遗传性疾病"],"a":4,"e":"色觉异常分色弱与色盲，色弱为识别能力减低，色盲为识别能力丧失，色觉检查列为常规检体项目。色盲有先天性与后天性两类，仅先天性色盲属遗传性疾病，以红绿色盲最常见、伴性遗传；后天性色盲由眼病或药物引起。故将色盲一概断为先天性遗传病错误"},{"q":"关于消化道出血，下列叙述正确的是","o":["呕血血中混有物呈碱性","上消化道出血不包括胰腺出血","鼻腔出血咽下后呕出亦称为呕血","消化性溃疡呕血后疼痛减轻","呕血后不一定有便血"],"a":3,"e":"消化性溃疡慢性上腹痛呈周期性、节律性，出血后血液中和胃酸、降低酸刺激，疼痛可减轻，为其特点。呕血混有食物残渣与胃液、呈酸性而非碱性，A错；上消化道出血包括胆道、胰腺等部位，B错；鼻腔出血咽下再呕出属假性呕血，C错；呕血常伴黑便，E错"},{"q":"胸骨左缘第二肋间连续性机械样杂音最常见于","o":["主动脉瘤破裂","动静脉瘘","动脉导管未闭","主肺动脉间隔缺损","升主动脉夹层动脉瘤"],"a":2,"e":"动脉导管未闭时主动脉与肺动脉间持续存在压力阶差，收缩期与舒张期均产生分流，故胸骨左缘第2肋间可闻及粗糙响亮、似机器转动的连续性杂音，常伴震颤。主动脉瘤破裂、动静脉瘘、主肺动脉间隔缺损的杂音部位或性质不同；主动脉夹层动脉瘤多为舒张期杂音"},{"q":"心肌缺血时不可能的心电图改变是","o":["ST段抬高","ST段压低","T波高尖","T波倒置","P-R间期缩短"],"a":4,"e":"心肌缺血主要影响心室复极，可表现为ST段抬高或压低、T波高尖或倒置，故A～D均可出现。PR间期反映心房至心室的传导时间，缩短见于预激综合征或心动过速，与心肌缺血无直接关系；缺血累及传导系统时可致PR延长而非缩短，故PR间期缩短为不可能的改变"},{"q":"Traube区叩诊音应为下列哪项","o":["清音","过清音","鼓音","浊鼓音","空瓮音"],"a":2,"e":"Traube区即胃泡鼓音区，位于左前胸下部肋缘以上，因胃底穹窿含气，叩诊呈鼓音，其大小受胃内含气量影响。过清音见于肺气肿等含气量增多；空瓮音为巨大空洞或张力性气胸的金属性鼓音；浊鼓音为浊音与鼓音混合，见于肺不张、肺水肿，均非本区正常叩诊音"},{"q":"以下疾病不会引起多尿性尿频的是","o":["应用利尿剂","尿崩症","急性肾衰竭多尿期","糖尿病","淋菌性尿道炎"],"a":4,"e":"多尿性尿频表现为排尿次数增多而每次尿量不少、全天总尿量增多，见于糖尿病、尿崩症、精神性多饮、急性肾衰竭多尿期及应用利尿剂。淋菌性尿道炎属炎症性尿频，尿频而每次尿量少，伴尿急、尿痛及脓尿，尿总量并不增多，故为例外"},{"q":"机体的止血功能是由四大系统共同完成的，四大系统分别是","o":["血小板、凝血系统、血管内皮系统、纤溶系统","血小板、凝血系统、血管内皮系统、抗凝系统","血小板、凝血系统、抗凝系统、纤溶系统","凝血系统、抗凝系统、纤溶系统、血管内皮系统","血小板、抗凝系统、纤溶系统、血管内皮系统"],"a":0,"e":"机体止血由血管内皮系统、血小板、凝血系统与纤溶系统四大系统协同完成：内皮损伤与血管收缩启动止血，血小板黏附聚集形成初步血栓，凝血系统生成纤维蛋白加固，纤溶系统溶解血栓保持通畅。抗凝系统参与凝血调节但不在本题四大止血系统之列，含抗凝系统的组合均不准确"},{"q":"一临床医师给患者进行了一系列神经系统查体，不属于脑神经检查内容的是","o":["视力检查","瞳孔检查","咽反射检查","胸锁乳突肌力量检查","肩部肌肉力量检查"],"a":4,"e":"脑神经检查包括视力（视神经）、瞳孔（动眼神经等）、咽反射（舌咽、迷走神经）及胸锁乳突肌力量（副神经）。肩部肌肉力量主要由腋神经等臂丛神经支配，属脊神经范畴。A、B、C、D四项分别对应第Ⅱ、Ⅲ、Ⅸ与Ⅹ、Ⅺ对脑神经，均属脑神经检查内容"},{"q":"关于舌下神经检查，下列叙述哪项正确","o":["嘱患者张口发“a”音，观察两侧软腭上抬是否有力","嘱患者伸舌，观察有无偏斜","观察患者腭垂是否居中","观察鼻唇沟及口角两侧是否对称","检查患者是否吞咽困难、饮水呛咳"],"a":1,"e":"舌下神经支配舌肌，检查时嘱患者伸舌，观察有无偏斜、舌肌萎缩及肌束颤动；单侧麻痹时舌尖偏向病侧。张口发音观察软腭上抬及腭垂居中、询问吞咽困难与饮水呛咳属舌咽和迷走神经检查；观察鼻唇沟及口角是否对称为面神经检查"},{"q":"溃疡性结肠炎的内镜下表现是","o":["黏膜广泛充血、水肿、糜烂，表面有脓苔","跳跃式分布的纵形或匍行性深溃疡","黏膜呈鹅卵石样增生，肠腔明显狭窄","黏膜隆起呈息肉状、有蒂","黏膜破裂出血"],"a":0,"e":"溃疡性结肠炎病变连续弥漫，内镜下见黏膜广泛充血、水肿、糜烂或表浅溃疡，表面覆脓苔与渗出物，并伴炎性息肉形成。跳跃式分布的纵行或匍行性深溃疡、鹅卵石样增生伴肠腔狭窄是克罗恩病特征；息肉状隆起有蒂多为炎性或腺瘤性息肉，非本病特异表现"},{"q":"关于甲状腺的检查，说法错误的是","o":["观察甲状腺的大小及对称性","触诊比视诊更能明确甲状腺的轮廓及病变的性质","当触及甲状腺肿大时，选用钟型听诊器直接放在肿大的甲状腺上进行听诊","被检查者双手放于枕后，头后仰的动作不利于甲状腺的观察","触诊甲状腺侧叶时，应配合被检查者吞咽动作，重复检查"],"a":3,"e":"甲状腺视诊观察大小与对称性，不易辨认时嘱患者双手放于枕后、头后仰，可使甲状腺显示更明显，有利于观察，故该说法错误。触诊比视诊更能明确轮廓与性质；触及肿大时用钟型听诊器直接听诊；触诊侧叶需配合吞咽动作，甲状腺随吞咽上移，均属正确操作"},{"q":"以下情况可以做结肠镜检查的是","o":["急性肠道感染","严重的肺功能不全者","大量便鲜血者","肠粘连者","精神、心理原因不能配合检查者"],"a":2,"e":"结肠镜适应证包括便血、排便异常、腹泻、腹部不适等下消化道症状而诊断不明者，大量便鲜血可借检查明确出血部位与病因。急性肠道感染、严重肺功能不全、肠粘连及精神心理原因不能配合者均属禁忌或难以耐受，不宜行结肠镜检查"},{"q":"可反映外周红细胞大小不一的参数是","o":["RDW","MCV","MCH","MCHC","Hb"],"a":0,"e":"RDW即红细胞体积分布宽度，由血细胞分析仪测得，反映外周血红细胞体积的异质性，即大小不均，常以变异系数RDW-CV或标准差RDW-SD表示。MCV为红细胞平均体积，反映细胞大小的整体水平；MCH为平均血红蛋白量，MCHC为平均血红蛋白浓度，Hb为血红蛋白量，均不反映体积差异"},{"q":"下列各项均是肝硬化门静脉高压的表现，但除外","o":["脾大及脾功亢进","脐周及腹壁静脉曲张","腹水","黄疸","食管-胃底静脉曲张"],"a":3,"e":"肝硬化门静脉高压主要表现为脾大及脾功能亢进、脐周与腹壁静脉曲张、腹水、食管胃底静脉曲张，是门脉压力升高和侧支循环建立的结果。黄疸源于肝细胞损害或胆汁淤积，属肝功能减退表现，并非门静脉高压直接所致，故为例外。B、C、E三项均为门脉高压典型体征"},{"q":"不属于现病史内容的是","o":["手术史","起病时的情况","病情的发展与演变","主要症状及伴随症状","诊治经过"],"a":0,"e":"现病史记录本次疾病的发生、发展与诊治全过程，包括起病时情况、主要症状及伴随症状、病情的发展与演变以及诊治经过。手术史属既往史内容，按发生时间先后另行记录，不属现病史。B、C、D、E四项均围绕本次发病过程展开，属现病史"},{"q":"无尿是指24小时尿量","o":["0ml","＜50ml","＜100ml","＜150ml","＜400ml"],"a":2,"e":"正常成人24小时尿量为1000～2000ml；少于400ml或每小时少于17ml为少尿，少于100ml或12小时完全无尿为无尿，超过2500ml为多尿。0ml过于绝对，50ml、150ml均非界定值，400ml为少尿阈值，故无尿指24小时尿量少于100ml"},{"q":"下列能鉴别腹壁肿块的是","o":["患者仰卧抬头","侧卧抬头","站立抬头","平卧低头","侧卧低头"],"a":0,"e":"鉴别腹壁或腹腔内肿块，嘱患者仰卧位作屈颈抬肩即抬头动作使腹肌紧张：肿块更明显者位于腹壁，变不明显或消失者位于腹腔内、被收缩腹肌掩盖。侧卧、站立、平卧低头或侧卧低头均不能有效收缩腹肌，无法完成此项鉴别检查"},{"q":"下列出现腹腔积液的是","o":["卵巢囊肿","畸胎瘤","足月妊娠","人工气腹","结核性腹膜炎"],"a":4,"e":"结核性腹膜炎为腹膜慢性炎症，可产生大量渗出液形成腹腔积液，SAAG多小于11g/L。卵巢囊肿、畸胎瘤及足月妊娠为局限性包块或生理状态，人工气腹为人为注入气体，均非腹腔积液。腹腔积液常见病因尚有肝硬化、腹膜转移癌及肾病综合征"},{"q":"需保温保湿立即送检的临床标本是","o":["可疑细菌性痢疾患者的脓血便","可疑肺结核患者的痰","可疑肾盂肾炎患者的中段尿","可疑流行性脑脊髓膜炎患者的脑脊液","可疑败血症患者的血液"],"a":3,"e":"脑膜炎奈瑟菌对外界环境抵抗力弱，对寒冷、干燥敏感，离体后易自溶死亡，故疑似流行性脑脊髓膜炎的脑脊液须保温保湿并立即送检。痰、中段尿、脓血便及血液中的病原菌相对耐受，按常规条件送检即可，无此严格要求"},{"q":"肉眼血尿时，一般每升尿内含血量超过","o":["5ml","3ml","1ml","0.5ml","0.1ml"],"a":2,"e":"1000ml尿液含血量超过1ml即可呈淡红色洗肉水样，称为肉眼血尿。0.1ml、0.5ml含血量过少，肉眼不能辨认，仅镜检见红细胞，属镜下血尿；3ml、5ml虽可呈肉眼血尿，但非判定阈值，故超过1ml为标准"},{"q":"下列不是感染性发热的是","o":["肺炎发热","外伤发热","上感发热","无菌性坏死组织吸收热","疟疾发热"],"a":3,"e":"感染性发热由细菌、病毒、真菌、寄生虫等病原体及其产物引起，肺炎、上呼吸道感染、疟疾均属此类。无菌性坏死组织吸收热由组织坏死释放致热原所致，无病原体参与，属非感染性发热。外伤发热多与创面感染或血肿吸收有关，题干以无菌性坏死组织吸收热为非感染性代表"},{"q":"出血时间（Duke法）异常是","o":["＞3分","＞4分","＞5分","＞6分","＞7分"],"a":1,"e":"出血时间反映血小板数量、功能及血管壁脆性与通透性。Duke法正常为1～3分钟，超过4分钟即为异常，提示血小板减少、功能缺陷或血管壁异常。3分钟仍在正常范围，5、6、7分钟虽亦属延长，但判定阈值取4分钟。题干注明Duke法，不适用测定器法超过9分钟的标准"},{"q":"下列胸部听诊方法的描述错误的是","o":["被检者取坐位或卧位","听诊一般由肺尖开始自上而下检查","前后顺序为前胸部、侧胸部和背部","检查时要上下、左右对称部位进行对比","被检者闭口作均匀呼吸"],"a":4,"e":"胸部听诊时受检者取坐位或卧位，一般自肺尖开始自上而下，按前胸、侧胸、背部顺序，并在上下、左右对称部位对比。听诊应嘱受检者微张口作均匀呼吸，必要时深呼吸或咳嗽后听诊；闭口呼吸使气流受限、呼吸音减弱，故该描述错误"},{"q":"下列疾病中，经常见到心悸伴胸痛，但应除外","o":["心绞痛","肺梗死","心包炎","大叶性肺炎","心功能不全"],"a":4,"e":"心悸伴胸痛常见于心绞痛、肺梗死、心包炎及大叶性肺炎累及胸膜者，源于心肌缺血或胸膜、胸壁受累。心功能不全主要表现为心悸伴呼吸困难、端坐呼吸及水肿等淤血症状，胸痛并非其常见伴随表现，A、B、C、D四项均已给出明确胸痛关联"},{"q":"冲击触诊法，检查者以三四个并拢的手指放于腹壁上的相应部位，与腹壁的角度是","o":["30°～50°","50°～70°","70°～90°","90°～110°","110°～130°"],"a":2,"e":"冲击触诊法又称浮沉触诊法，检查者以并拢的示、中、环三指取70°～90°角置于腹壁，作急速有力的冲击，指端可感知腹腔脏器或包块浮沉感，多用于大量腹水时检查肝脾。30°～50°、50°～70°角度过平，110°以上过直，均不符合操作要求"},{"q":"下列各项均可引起肝浊音界扩大，但除外","o":["肝癌","肝炎后肝硬化","多囊肝","右心功能不全","酒精性肝硬化"],"a":1,"e":"肝浊音界扩大见于肝癌、肝脓肿、病毒性肝炎、肝淤血及多囊肝等肝体积增大情况，右心功能不全致肝淤血时亦可扩大。肝硬化尤其肝炎后肝硬化后期肝脏萎缩、体积缩小，肝浊音界缩小而非扩大，故为例外；酒精性肝硬化早期可因脂肪浸润致肝大"},{"q":"下列关于前列腺检查的内容，错误的是","o":["被检查者取肘膝卧位","检查者以示指进行肛诊，向背侧触诊","正常成人前列腺质韧，有弹性","前列腺分左、右两叶，之间可触及正中沟","前列腺肥大时正中沟消失"],"a":1,"e":"前列腺检查取肘膝卧位，检查者戴手套后以示指插入肛门，应向前即腹侧触诊方可触及前列腺，向背侧触诊方向错误。正常前列腺质韧有弹性，分左右两叶，其间可触及正中沟；前列腺肥大时正中沟变浅或消失，均属正确叙述"},{"q":"下列关于凝血因子描述正确的是","o":["正常人血浆中有14种凝血因子","依赖维生素K凝血因子包括Ⅱ、Ⅴ、Ⅸ、Ⅹ","PT延长代表凝血因子Ⅱ、Ⅴ、Ⅶ、Ⅹ的活性低于正常或抗凝物质的存在","内、外源性凝血系统形成凝血活酶时都需要因子Ⅷ的参与","因子Ⅶ和因子Ⅴ主要存在于正常人新鲜血清中"],"a":2,"e":"PT是外源性凝血系统筛选试验，延长见于因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏或低纤维蛋白原血症，也可见于抗凝物质存在，故该叙述正确。正常血浆凝血因子共12种而非14种；维生素K依赖因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ，不含Ⅴ；因子Ⅷ仅参与内源性凝血活酶形成；因子Ⅴ、Ⅶ主要存在于血浆而非新鲜血清"},{"q":"内生性致热原不包括","o":["炎性渗出物","IL-1","干扰素","IL-6","TNF"],"a":0,"e":"内生性致热原由单核-巨噬细胞等产生，包括白细胞介素-1、白细胞介素-6、肿瘤坏死因子及干扰素等。炎性渗出物与无菌坏死组织属外源性致热原，通过刺激机体产生内生性致热原而致热，本身并非内生性致热原，故为例外。B、C、D、E四项均为内生性致热原"},{"q":"在细胞质中出现粗大、圆而均匀，呈橘红色染色颗粒的白细胞为","o":["中性粒分叶核细胞","嗜酸性粒细胞","淋巴细胞","单核细胞","嗜碱性粒细胞"],"a":1,"e":"嗜酸性粒细胞胞质内充满粗大、整齐、均匀、紧密排列的橘红色即橘黄或橙红色嗜酸性颗粒，为其形态特征。中性粒细胞颗粒细小呈淡紫红；淋巴细胞胞质少、几无颗粒；单核细胞颗粒细小呈灰尘样；嗜碱性粒细胞含粗大紫黑颗粒，常覆盖核上"},{"q":"不属于血清学反应的试验是","o":["双向琼脂扩散","补体结合试验","病毒血凝抑制试验","病毒血凝试验","冷凝集试验"],"a":3,"e":"病毒血凝试验利用病毒表面血凝素直接凝集红细胞，无需抗体参与，属病毒鉴定方法而非抗原抗体血清学反应。双向琼脂扩散、补体结合试验、病毒血凝抑制试验及冷凝集试验均以抗原抗体特异性结合为基础，属血清学反应，故为例外"},{"q":"触诊肾脏，首选的方法是","o":["浅部触诊","冲击触诊","深插触诊","双手触诊","滑行触诊"],"a":3,"e":"肾脏位置较深，触诊首选双手触诊法：一手托起腰部，另一手置于腹壁，双手夹触并嘱患者深吸气使肾脏下移，更易触及。浅部触诊用于腹壁浅表病变；冲击触诊多用于大量腹水时的脏器触诊；深插触诊与滑行触诊均非肾脏检查的常规方法"},{"q":"在动脉血氧分压的叙述中，不正确的是","o":["健康成人随着年龄的增加而降低","正常值为95～100mmHg，但老年人需用预计公式计算正常值","可判断有无缺氧及缺氧的程度","可判断有无Ⅱ型呼吸衰竭","随海拔变化而变化"],"a":3,"e":"PaO2随年龄增长及海拔升高而变化，正常约95～100mmHg，老年人需按预计公式判断，可用于判定有无缺氧及其程度，呼吸衰竭的诊断亦以PaO2低于60mmHg为依据。但Ⅰ型与Ⅱ型呼吸衰竭的区分取决于PaCO2是否超过50mmHg，单凭PaO2不能判断类型，故该叙述不正确"},{"q":"哪种疾病患侧胸廓凹陷","o":["肺炎","肺气肿","胸腔积液","胸膜肥厚","皮下气肿"],"a":3,"e":"慢性胸膜肥厚与胸膜粘连牵拉胸壁，使患侧胸廓塌陷凹陷，常伴肋间隙变窄及气管移向患侧。肺气肿致胸廓膨隆呈桶状；胸腔积液或气胸使患侧胸廓饱满；肺炎多无胸廓形态改变；皮下气肿为胸壁积气，不引起患侧胸廓凹陷"},{"q":"下列有关心悸的叙述正确的是","o":["提示患有器质性心脏病","仅发生在心率增快时","仅发生在心率减弱时","提示存在心律或心率异常","一种自觉心脏跳动的不适感"],"a":4,"e":"心悸是患者自觉心脏跳动的不适感或心慌感，属主观症状而非客观体征。它可见于心律或心率异常，也可见于心脏搏动增强如发热、贫血、甲亢或神经敏感者，故不等于器质性心脏病，也不只发生在心率增快或减慢时。A项器质性心脏病、B、C项单凭心率快慢均不全面"},{"q":"以下不是心肌炎体征的是","o":["第一心音增强","心动过速","舒张期奔马律","下肢水肿","肺部湿啰音"],"a":0,"e":"心肌炎因心肌收缩力减弱，听诊第一心音减弱而非增强，故S1增强不是其体征。心动过速、舒张期奔马律为心肌受累常见表现；合并心力衰竭时可有下肢水肿及肺部湿啰音。第一心音强弱不等多见于心房颤动或完全性房室传导阻滞，均非本病体征"},{"q":"脊柱器质性侧凸的特点是","o":["半卧位时可以消失","改变体位不能使侧弯得到纠正","平卧时可消失","俯卧位时可消失","站位时可消失"],"a":1,"e":"器质性侧凸存在脊柱结构异常，特点是改变体位不能使侧凸纠正，常见于先天性脊柱发育不全、肌肉麻痹、慢性胸膜肥厚及胸廓畸形。姿势性侧凸无结构异常，早期弯曲不固定，平卧、半卧、俯卧或站位改变体位后侧凸可消失，故A、C、D、E均为姿势性侧凸特点"},{"q":"肺动脉瓣听诊区第二心音增强，最常见于","o":["高血压","冠心病","二尖瓣狭窄","肺动脉瓣狭窄","肺动脉瓣关闭不全"],"a":2,"e":"二尖瓣狭窄致左房压升高、肺静脉及肺毛细血管压力增高，继而肺动脉高压，使肺动脉瓣关闭有力、P2亢进，是肺动脉瓣区第二心音增强最常见原因。高血压主要致A2亢进；肺动脉瓣狭窄因通过瓣膜血流减少，P2反而减弱；冠心病与肺动脉瓣关闭不全亦非P2亢进的常见病因"},{"q":"有关于心脏杂音的正确叙述中，应除外","o":["收缩期杂音2/6级以下者，多属功能性","收缩期杂音3/6级以上者，肯定为器质性","心衰时，器质性杂音可减弱或消失","杂音是否为器质性主要根据杂音的性质及粗糙程度","舒张期杂音均有病理意义"],"a":1,"e":"收缩期杂音达3/6级以上多为病理性，但不能据此绝对判定为器质性，还须结合性质、传导及部位综合判断，故该说法错误。2/6级以下收缩期杂音多属功能性；舒张期与连续性杂音均为器质性；杂音是否器质性主要依据性质与粗糙程度；心衰时器质性杂音可减弱或消失"},{"q":"常见尿胆素原排泄减少的情况是","o":["肠梗阻","溶血","碱中毒","胆道梗阻","肝细胞性黄疸"],"a":3,"e":"胆道梗阻时胆汁排入肠道受阻，肠内胆红素减少，经细菌还原生成的尿胆原随之减少，完全梗阻时尿胆原可缺如，同时尿胆红素增加。溶血时胆红素生成增多使尿胆原增加；肝细胞性黄疸尿胆原可增多或正常；碱中毒与肠梗阻并非尿胆原减少的典型原因"},{"q":"下列说法错误的是","o":["胆囊炎多表现为持续性腹痛","幽门梗阻者一般呕吐后疼痛会缓解","钻顶样疼痛一般见于胆道蛔虫症","胃、十二指肠穿孔多为慢性胀痛","结肠病变，疼痛多在排便后减轻"],"a":3,"e":"胃、十二指肠穿孔为突发剧烈刀割样疼痛，迅速波及全腹并伴板样强直，并非慢性胀痛，故该说法错误。胆囊炎多表现为持续性腹痛；幽门梗阻呕吐后胃内压下降，疼痛缓解；胆道蛔虫症典型为钻顶样绞痛；结肠病变疼痛常于排便后减轻"},{"q":"慢性心功能不全产生水肿的最主要机制包括","o":["毛细血管内静水压减低","各种原因致水、钠潴留","肝脏合成白蛋白轻度减少","淋巴回流受阻","肾小球毛细血管滤过率增加"],"a":1,"e":"慢性心功能不全时心排血量下降，激活肾素-血管紧张素-醛固酮系统，引起水钠潴留、血容量增加，是水肿形成的最主要机制，同时静脉淤血使毛细血管内静水压升高。A项静水压应升高而非减低；C项白蛋白仅轻度减少，非主因；D项淋巴回流受阻不是心源性水肿主因；E项肾小球滤过率应下降"},{"q":"出血后促使血小板发生凝聚的重要物质是","o":["ATP","活化素","因子Ⅻ","PF3","ADP"],"a":4,"e":"出血时受损红细胞与血小板释放ADP，是诱导血小板聚集的重要物质，血小板聚集试验常以ADP为诱导剂。ATP为能量物质，无此作用；活化素不直接促聚集；因子Ⅻ参与内源性凝血启动；PF3为血小板膜磷脂，提供凝血催化表面，参与凝血而非直接促聚集"},{"q":"Kussmaul呼吸常见于","o":["肺炎","腹水","发热","尿毒症晚期","胸腔积液"],"a":3,"e":"Kussmaul呼吸为深长而规则的呼吸，是严重代谢性酸中毒的代偿表现，通过过度通气排出CO2以调节酸碱平衡，见于糖尿病酮症酸中毒及尿毒症酸中毒，故尿毒症晚期常见。肺炎、发热多表现为呼吸浅快；腹水、胸腔积液主要限制呼吸运动，无此深大呼吸特征"},{"q":"第一心音的特点包括","o":["音调较高（62Hz）","强度低，性质清脆","历时时间短（0.08s）","在心尖搏动之后出现","心尖部听诊最清楚"],"a":4,"e":"第一心音音调较低、时限较长约0.1秒，强度较响、性质较钝，与心尖搏动基本同步，在心尖部听诊最清楚，标志心室收缩开始。音调较高约62Hz、强度低而清脆、历时约0.08秒、心底部听诊清楚均为第二心音特点；S1在心尖搏动之后出现亦不准确"},{"q":"以下不是动眼神经麻痹的临床表现的是","o":["上睑下垂","瞳孔散大","眼球内收受限","眼球外展受限","眼球向下受限"],"a":3,"e":"动眼神经支配大部分眼外肌、提上睑肌及瞳孔括约肌，麻痹时表现为上睑下垂、瞳孔散大、眼球内收及向下活动受限。眼球外展受限由展神经受损所致；滑车神经损害表现为眼球向下及向外运动减弱，均不属动眼神经麻痹的临床表现"},{"q":"外源性凝血途径的筛查试验是","o":["APTT","SCT","RT","CT","PT"],"a":4,"e":"PT测定血浆凝固时间，是外源性凝血系统最灵敏、最常用的筛选试验，延长提示因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏或存在抗凝物质。APTT为内源性凝血途径的筛查试验；SCT、RT、CT主要反映内源性凝血或共同通路，均非外源性凝血的首选筛查指标"},{"q":"蛙腹见于","o":["腹膜有炎症或肿瘤浸润","腹腔大量积液","腹腔大量积气","腹腔巨大肿瘤","腹壁上的肿物"],"a":1,"e":"大量腹腔积液时腹压增高，仰卧位液体向两侧流聚，腹部两侧膨隆呈蛙腹状，常见于肝硬化门静脉高压。腹膜炎症或肿瘤浸润多表现为腹壁僵硬或压痛；腹腔大量积气呈气腹、腹部均匀膨隆；腹腔巨大肿瘤多为局限性隆起；腹壁肿物位置表浅，随体位改变不明显"},{"q":"外观清亮，比重为1.010，蛋白质浓度为1.5g/dl，单核细胞小于500×106/L的浆液提示","o":["感染性","渗出液","漏出液","无菌","结核"],"a":2,"e":"漏出液外观清亮透明，比重低于1.015，蛋白质浓度低、多低于25g/L，细胞数少且以单个核细胞为主，不易凝固，Rivalta试验阴性，符合所述特征。渗出液比重多超过1.018，蛋白质常高于30～40g/L，细胞数多且易凝固，见于感染、结核或肿瘤"},{"q":"如腹水量少于1000ml，最合适的检查体位是","o":["左侧卧位","肘膝位","坐位","俯卧位","右侧卧位"],"a":1,"e":"腹水少于1000ml时常规体位不易查出，取肘膝位使脐部处于最低点，自侧腹向脐部叩诊，鼓音转为浊音提示120ml以上积液，即水坑征。左侧卧、右侧卧及坐位用于检查中等量以上腹水，移动性浊音需1000ml以上；俯卧位不便叩诊，均非少量腹水的首选体位"},{"q":"Graham-Steell杂音最常见于","o":["三尖瓣关闭不全","主动脉瓣狭窄","肺动脉瓣狭窄","二尖瓣狭窄","主动脉瓣关闭不全"],"a":3,"e":"Graham Steell杂音为肺动脉扩张导致肺动脉瓣相对关闭不全所产生的舒张期递减型吹风样杂音，柔和局限、吸气末增强，常见于二尖瓣狭窄伴明显肺动脉高压。三尖瓣关闭不全为收缩期杂音；肺动脉瓣狭窄为收缩期喷射性杂音；主动脉瓣关闭不全产生Austin Flint心尖区舒张期杂音"},{"q":"正常人直立、骨盆固定的条件下，腰椎活动范围为","o":["后伸40°","前屈75°","右侧曲50°","左侧曲45°","旋转（一侧）35°"],"a":1,"e":"正常人直立、骨盆固定时腰椎活动范围为前屈75°～90°、后伸30°、左右侧弯20°～35°、旋转一侧30°，故前屈75°在正常范围内。后伸40°、左侧曲45°、右侧曲50°及旋转35°均超出正常参考值，不符合该体位下的腰椎活动度"},{"q":"慢性阻塞性肺气肿表现为","o":["FEV1及FVC下降","功能残气量及FVC下降","FEV1及RC/TLC（残气量/肺总量）下降","FEV1及FEV1/FVC下降","FEV1/FVC及FVC增加"],"a":3,"e":"阻塞性通气障碍时气道阻塞、呼气延长，FEV1及FEV1/FVC均降低，是慢性阻塞性肺气肿的典型肺功能改变。FVC下降并非本病主要特征，多正常或仅后期下降；残气量与肺总量之比在肺气肿应增高而非下降；FEV1/FVC及FVC增加与阻塞性改变方向相反"},{"q":"正常成年人能够听到支气管肺泡呼吸音的部位为","o":["胸骨两侧第2、3肋间隙","胸骨两侧第3、4肋间隙","肩胛间区第2、3胸椎水平","肩胛间区第3、4胸椎水平","肩胛下区"],"a":3,"e":"正常人可在胸骨两侧第1、2肋间隙、肩胛间区第3、4胸椎水平及肺尖前后部听到支气管肺泡呼吸音。胸骨两侧第2、3或3、4肋间隙并非典型听诊部位；肩胛间区第2、3胸椎水平偏高；肩胛下区正常为肺泡呼吸音，若闻及支气管肺泡呼吸音提示异常"},{"q":"血氨正常的疾病是","o":["肝性脑病","重症肝炎","尿毒症","休克","贫血"],"a":4,"e":"血氨升高主要见于严重肝脏疾病，如肝性脑病、重症肝炎，因肝脏尿素合成障碍致氨蓄积；尿毒症、休克等亦可伴血氨增高。单纯贫血不涉及肝脏尿素合成或氨代谢障碍，血氨正常。A、B两项为典型肝性脑病相关疾病，C、D项均伴明显代谢紊乱"},{"q":"关于弛张热的描述，下列不正确的是","o":["体温在39℃以上","体温波动大","每日温差达2℃以上","每日体温波动在1℃以内","常见于败血症、化脓性炎症等"],"a":3,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时内波动幅度大、温差超过2℃，但最低点仍高于正常，常见于败血症、化脓性炎症。每日体温波动在1℃以内是稽留热特点，体温持续于39～40℃高水平，故该项描述不正确。A、B、C、E均符合弛张热"},{"q":"下述各项均能判断黄疸，但除外","o":["巩膜黄染","口腔黏膜黄染","皮肤黄染","掌心黄染","血清总胆红素测定"],"a":3,"e":"黄疸表现为巩膜、口腔黏膜及皮肤黄染，其中巩膜黄染出现最早且连续，血清总胆红素测定可明确判断并分度。掌心黄染多由胡萝卜素血症等引起，不累及巩膜，血清胆红素正常，并非黄疸，故不能据此判断。A、B、C、E四项均为判断黄疸的可靠依据"},{"q":"肺泡呼吸音增强可见于下列情况，但需除外","o":["发热","甲亢","贫血","患侧全肺不张","酸中毒"],"a":3,"e":"肺泡呼吸音增强多因机体需氧量增加、呼吸深快，使进入肺泡的气流量增多，见于发热、甲亢、贫血及酸中毒等。患侧全肺不张时肺泡含气量显著减少，呼吸音减弱或消失，而非增强。压迫性肺不张因肺组织致密可听到较弱的支气管呼吸音，与全肺不张不同"},{"q":"心性混合性发绀常见于","o":["二尖瓣狭窄","缩窄性心包炎","法洛四联症","扩张型心肌病","高血压心脏病"],"a":2,"e":"心性混合性发绀因心脏异常通道使部分静脉血未经肺氧合直接进入体循环动脉，分流量超过心输出量三分之一即出现发绀，常见于法洛四联症、艾森门格综合征等发绀型先心病。二尖瓣狭窄、缩窄性心包炎、扩张型心肌病及高血压心脏病无异常分流，不属混合性发绀"},{"q":"一医生接诊一个患者后交代患者闭眼，往患者手里放置了一支钢笔，要求患者描述该物体的形状。这是检查","o":["触觉","实体觉","体表图形觉","皮肤定位觉","位置觉"],"a":1,"e":"实体觉检查嘱受检者闭目后用单手触摸熟悉物体如钢笔、钥匙、硬币，说出名称或描述形状，以了解其识别能力。触觉仅感受接触与否；体表图形觉为在皮肤上划图形后辨认；皮肤定位觉为指出被触点位置；位置觉为感知肢体所处位置，均非本题所述检查"},{"q":"下列各种药物或化学物质不会引起高铁血红蛋白血症的是","o":["亚硝酸盐","硝基胺","磺胺","氯化钾","伯氨喹"],"a":3,"e":"高铁血红蛋白血症由氧化剂使血红蛋白中二价铁氧化为三价铁、失去携氧能力所致，常见于亚硝酸盐、硝基胺类、磺胺类、伯氨喹及苯胺等中毒。氯化钾为电解质，无氧化作用，不引起高铁血红蛋白血症。A、B、C、E四项均为已知致病物质"},{"q":"代谢性碱中毒时","o":["血浆pH值增高，PaCO2代偿性增高，HCO3－下降","血浆pH值增高，PaCO2代偿性增高，HCO3－增高","血浆pH值增高，PaCO2下降，HCO3－下降","血浆pH值增高，PaCO2代偿性增高，HCO3－不变","血浆pH值下降，PaCO2代偿性增高，HCO3－下降"],"a":1,"e":"代谢性碱中毒原发改变为HCO3－增高，血浆pH升高；机体通过低通气使PaCO2代偿性增高，预计PaCO2=0.9×ΔHCO3－±5，极限约55mmHg。A、C、D项的HCO3－下降或不变与原发改变矛盾，E项pH下降与碱中毒相反，均不正确"},{"q":"一般与遗传无关的是","o":["慢性支气管炎","血友病","白化病","遗传性球形红细胞增多症","糖尿病"],"a":0,"e":"慢性支气管炎主要与吸烟、空气污染、感染及理化刺激等环境因素有关，一般与遗传无关。血友病、白化病、遗传性球形红细胞增多症均为明确遗传病；糖尿病尤其2型有家族聚集与遗传易感性，属遗传相关疾病，故为例外"},{"q":"肝病并发弥散性血管内凝血时下列哪一组试验最有诊断价值","o":["FⅧ：C降低，vWFAg/FⅧ：C比值增高","APTT、PT、TT均延长","AT、PC、PLG降低","b-TG、PF4和血清FDP均增高","3P试验阳性，FDP含量增高"],"a":0,"e":"肝病并发DIC时因子Ⅷ被大量消耗致FⅧ:C降低，血管内皮损伤释放vWF使vWF:Ag增高，故vWF:Ag/FⅧ:C比值明显增高，此组合对诊断最有价值。单纯肝病合成障碍虽可使APTT、PT、TT延长及抗凝血酶等降低，但FⅧ:C多不降低；3P试验与FDP异常亦非DIC所独有"},{"q":"肺气肿患者突然出现呼吸困难，对确定并发气胸有意义的检查是","o":["呼吸运动","触觉语颤","叩诊音","支气管语音","听觉语颤"],"a":2,"e":"肺气肿并发气胸时胸膜腔积气，患侧叩诊由过清音转为鼓音，是确定气胸最有意义的体征，结合呼吸运动减弱、语颤消失可进一步判断。呼吸运动、触觉语颤、支气管语音及听觉语颤改变均为非特异表现，肺气肿本身或胸腔积液亦可出现，不能单独确定气胸"},{"q":"外源性凝血从哪个因子开始激活","o":["Ⅲ","Ⅴ","Ⅻ","Ⅹ","Ⅱ"],"a":0,"e":"外源性凝血途径由组织损伤释放的组织因子即因子Ⅲ启动，因子Ⅲ与因子Ⅶ结合成复合物后激活因子Ⅹ，进入共同通路，其筛查试验为PT。因子Ⅻ为内源性凝血的启动因子；因子Ⅴ为共同通路辅因子；因子Ⅱ即凝血酶原属共同通路成分，均非外源性起始因子"},{"q":"下列均为消化性溃疡穿孔的体征，除外","o":["全腹压痛","肠鸣音减弱或消失","腹壁呈板样强直","肝浊音界缩小或消失","肠鸣音亢进"],"a":4,"e":"消化性溃疡穿孔后胃肠内容物进入腹腔引起弥漫性腹膜炎，表现为全腹压痛、腹壁板样强直、肠鸣音减弱或消失，肝浊音界缩小或消失提示气腹。肠鸣音亢进见于机械性肠梗阻，与穿孔后肠麻痹、腹膜炎时肠鸣音减弱相反，故为例外"},{"q":"无症状性血尿最常见于","o":["肾盂肾炎","薄基底膜肾病","神经源性膀胱","丝虫病","多囊肾"],"a":1,"e":"薄基底膜肾病以反复血尿为主要表现，常无症状、无高血压及肾功能损害，预后良好，是无症状性血尿的常见原因。肾盂肾炎多伴尿路刺激征与发热；神经源性膀胱以排尿障碍为主；丝虫病致乳糜尿；多囊肾常有家族史、血压升高及肾功能损害，均非无症状性血尿的常见病因"},{"q":"血清钾的生物学作用包括","o":["是维持细胞生理活动的主要阴离子","是保持机体的正常渗透压的主要离子","不参与糖及蛋白质代谢","保证神经肌肉的正常功能","大部分存在于细胞内液"],"a":3,"e":"钾是细胞内主要阳离子，参与维持细胞静息电位，保证神经肌肉的兴奋性与正常收缩功能，为其重要生物学作用。A项称钾为阴离子错误，钾为阳离子；B项维持血浆渗透压主要靠钠与白蛋白；C项钾参与糖与蛋白质代谢；E项大部分在细胞内属分布特点，非本题所问的功能概括"},{"q":"Grey Turner征见于","o":["Addison病","多发性神经纤维瘤","急性出血性胰腺炎","血色病","妊娠"],"a":2,"e":"Grey Turner征表现为腰部、季肋部及下腹部皮肤青紫瘀斑，因腹膜后出血经腹膜后间隙渗至侧腹壁皮下所致，见于重症急性出血性胰腺炎及肠绞窄。脐周皮肤发蓝为Cullen征，亦见于重症胰腺炎或异位妊娠破裂；Addison病为色素沉着，其余选项均无此征"},{"q":"下列各项均可出现肝浊音界扩大，但除外","o":["肝炎","肝癌","肝包虫","晚期肝炎后肝硬化","肝脓肿"],"a":3,"e":"肝炎、肝癌、肝脓肿及肝包虫均使肝脏体积增大，肝浊音界扩大。晚期肝炎后肝硬化肝脏萎缩、体积缩小，肝浊音界缩小，故为例外。肝硬化失代偿期还常伴腹水、脾大等门脉高压表现，但肝浊音界趋于缩小而非扩大"},{"q":"诊断甲状腺功能亢进的特征性改变是","o":["甲状腺弥漫、对称肿大","甲状腺质地较柔软","甲状腺出现结节改变","甲状腺可随吞咽动作上下移动","触诊有震颤或听诊能听到血管杂音"],"a":4,"e":"甲亢时甲状腺血流增多、增粗、流速加快，触诊可有震颤，听诊闻及低调连续性静脉嗡鸣音或收缩期动脉杂音，为特征性改变。弥漫对称肿大、质地柔软及随吞咽上下移动亦可见于单纯性甲状腺肿，并非甲亢特异；结节改变多提示结节性甲状腺肿"},{"q":"二尖瓣狭窄患者咳粉红色泡沫痰，两肺布满水泡音时，说明病情至少已处于","o":["肺动脉高压期","左心室衰竭期","左心房衰竭期","右心功能衰竭","疾病的终末阶段"],"a":2,"e":"二尖瓣狭窄使左房血液流出受阻，左房压升高导致肺静脉与肺毛细血管淤血，严重时发生肺水肿，出现咳粉红色泡沫痰、两肺布满湿啰音，属左心房衰竭期表现。左心衰竭多见于高血压、冠心病，二尖瓣狭窄时左室充盈反而减少；肺动脉高压期及右心衰竭期以呼吸困难、体循环淤血为主"},{"q":"下列哪种情况出现语音震颤增强","o":["肺泡内含气量过多","支气管阻塞","大量胸腔积液","肺泡内大面积炎症浸润","胸膜高度增厚"],"a":3,"e":"肺泡内大面积炎症浸润使肺组织实变、传导良好，语音震颤增强，见于大叶性肺炎实变期、大片肺梗死及空洞型肺结核。肺泡含气量过多如肺气肿、支气管阻塞如阻塞性肺不张、大量胸腔积液及胸膜高度增厚粘连均使语颤减弱或消失，故为例外"},{"q":"最可能导致室性心动过速和心室颤动的心电图表现是","o":["每分钟6个以上的室性期前收缩","多源性室性期前收缩","成对室性期前收缩","偶发室性期前收缩","R-on-T型室性期前收缩"],"a":4,"e":"R-on-T型室性期前收缩落在前一心搏的T波易损期，易诱发室性心动过速甚至心室颤动，危险性最高。每分钟6个以上、多源性及成对室性期前收缩虽属频发或复杂室早，风险较R-on-T为低；偶发室性期前收缩多无明显临床意义"},{"q":"尿频、尿急伴下肢感觉障碍，最常见的疾病是","o":["精神紧张","急性前列腺炎","神经源性膀胱","尿崩症","急性肾盂肾炎"],"a":2,"e":"尿频、尿急伴下肢感觉障碍提示中枢或周围神经病变累及排尿中枢及传导通路，最常见于神经源性膀胱，常伴排尿困难。精神紧张表现为神经性尿频但无感觉障碍；急性前列腺炎、急性肾盂肾炎伴发热及尿路刺激征；尿崩症以多尿、口渴为主"},{"q":"以下哪一项属于心电图的正常变异","o":["儿童右室占优势","V1～V3导联ST段弓背向上抬高","右束支传导阻滞","V1～V2导联呈QS型，V3呈QRS型","V1～V3导联R/S＞1，伴ST段压低"],"a":0,"e":"儿童心电图随发育由右心室占优势型逐渐转为左心室占优势型，儿童右室电位占优势属正常变异。V1～V3导联ST段弓背向上抬高提示急性前壁心肌梗死；V1～V2呈QS型、V3呈QRS型及V1～V3 R/S大于1伴ST压低均为异常；右束支传导阻滞属传导异常"},{"q":"ST段抬高不可见于下列哪种临床情况","o":["急性心肌梗死","应激性心肌病","心包炎","冠脉痉挛","主动脉瓣反流"],"a":4,"e":"急性心肌梗死、应激性心肌病、心包炎及冠脉痉挛均可出现ST段抬高，分别对应心肌缺血损伤、应激性心肌损伤、心包炎症及血管痉挛。主动脉瓣反流主要引起左室舒张期容量负荷增加与肥厚扩张，心电图多为左室高电压及继发性ST-T改变或ST段压低，不出现典型ST段抬高"},{"q":"慢性阻塞性肺疾病（COPD）的分级主要依赖","o":["FEV1及FVC","功能残气量及FVC","FEV1","FEV1及残气量/肺总量（RC/TLC）","FEV1/FVC及FVC"],"a":2,"e":"COPD严重程度分级主要依据吸入支气管扩张剂后FEV1占预计值的百分比：轻度不低于70%，中度60%～69%，中重度50%～59%，重度35%～49%，极重度低于35%。FEV1/FVC主要用于确定气流受限是否存在，FVC及残气量与肺总量之比用于评估限制或肺气肿程度，均非分级主要指标"},{"q":"关于A型血型，说法正确的是","o":["红细胞膜上有A抗原","红细胞膜上有B抗原","血清中有A抗原","血清中有抗A抗体","红细胞膜上有A抗体"],"a":0,"e":"ABO血型依红细胞表面抗原划分：A型红细胞膜上有A抗原，血清中含抗B抗体；B型有B抗原、含抗A抗体；AB型有两种抗原而无抗体；O型无抗原、含抗A及抗B抗体。抗体存在于血清而非红细胞膜上，血清中亦不含A抗原，故其余各项均错误"},{"q":"下列为胸部正常叩诊音的正确描述，但应除外","o":["正常胸部叩诊为清音","其音响的强弱及高低与肺的含气量多少有关","其音响的强弱及高低与胸壁的厚薄有关","其音响的强弱及高低与邻近器官的影响有关","前胸下部较上部叩诊音相对稍浊"],"a":4,"e":"正常胸部叩诊为清音，其音响强弱与肺含气量、胸壁厚薄及邻近器官影响有关。因肺上叶体积较小、含气量少且上胸部肌肉较厚，实际是前胸上部较下部叩诊音相对稍浊，所述下部较上部稍浊正好相反。背部因肌骨层次多较前胸稍浊，右侧腋下部受肝影响亦稍浊"},{"q":"出血时间正常的疾病是","o":["急性粒细胞性白血病","再生障碍性贫血","血小板减少性紫癜","血友病","放射线损伤"],"a":3,"e":"出血时间主要反映血小板数量、功能及血管壁状况。血友病为因子Ⅷ或Ⅸ缺乏，属二期止血障碍，血小板与血管壁均正常，故出血时间正常。急性粒细胞白血病、再生障碍性贫血、血小板减少性紫癜及放射线损伤均可致血小板减少或功能异常，使出血时间延长"},{"q":"退热期可导致","o":["Na＋潴留","Cl－潴留","水潴留","脱水","出汗减少"],"a":3,"e":"退热期体温骤降，皮肤血管扩张并大量出汗，水分随汗液丢失，可导致脱水，严重者出现循环衰竭。钠、氯潴留及水潴留多见于发热初期或心肾功能不全；出汗减少与退热期大量出汗的表现相反，A、B、C、E均不正确"},{"q":"消化性溃疡的主要症状是","o":["反酸","嗳气","恶心呕吐","上腹胀","节律性上腹痛"],"a":4,"e":"消化性溃疡以慢性、周期性、节律性上腹痛为主要症状，胃溃疡多在餐后痛，十二指肠溃疡多为空腹痛及夜间痛，进食或制酸可缓解。反酸、嗳气、恶心呕吐及上腹胀为伴随的消化不良症状，并非本病的主要或特征性表现"},{"q":"下述心包摩擦音的听诊特点均正确，但应除外","o":["性质粗糙，呈搔抓样","与心跳一致，声音呈三相","屏气时摩擦音消失","胸骨左缘第3、4肋间最响","坐位前倾位时更明显"],"a":2,"e":"心包摩擦音与心搏一致，性质粗糙呈搔抓样，胸骨左缘第3、4肋间最响，坐位前倾时更明显，屏气时仍存在，可据此与胸膜摩擦音鉴别。屏气时摩擦音消失是胸膜摩擦音的特点，因其随呼吸运动产生，故该叙述不属心包摩擦音特点。A、B、D、E均正确"},{"q":"人体内最不稳定的凝血因子，同时也是构成凝血和血栓形成共同环节的凝血因子是","o":["Ⅴ因子","Ⅷ因子","Ⅸ因子","Ⅹ因子","Ⅻ因子"],"a":0,"e":"因子Ⅴ是体内最不稳定的凝血因子，易降解失活；它作为辅因子参与凝血酶原酶复合物形成，是内、外源性凝血的共同环节。因子Ⅷ亦不稳定但仅参与内源性途径；因子Ⅸ、Ⅹ、Ⅻ稳定性相对较高，且因子Ⅻ属内源性接触激活因子，均非最不稳定且兼具共同环节者"},{"q":"面容惊愕、眼裂增宽、眼球突出、目光炯炯、兴奋不安、烦躁易怒的面容是","o":["急性病容","贫血面容","黏液性水肿面容","甲状腺功能亢进面容","伤寒面容"],"a":3,"e":"甲状腺功能亢进面容表现为面容惊愕、眼裂增宽、眼球突出、目光炯炯、兴奋不安、烦躁易怒，源于甲状腺激素过多致神经兴奋及眼征。急性病容面色潮红、表情痛苦；贫血面容面色苍白；黏液性水肿面容面色苍黄、脸厚面宽、目光呆滞；伤寒面容表情淡漠、反应迟钝"},{"q":"以下属于髓系细胞免疫标志是","o":["CD13","CD19","CD20","CD4","TdT"],"a":0,"e":"识别髓系细胞的抗体包括CD11b、CD11c、CD13、CD14、CD15、CD33、CD64、CD117等，故CD13属髓系免疫标志。CD19、CD20为B淋巴细胞标志；CD4为辅助性T细胞标志；TdT为淋巴母细胞即前体细胞标志，多见于急性淋巴细胞白血病，均非髓系"},{"q":"判定腹部膨隆时的体位是","o":["立位","左侧卧位","坐位","仰卧位","右侧卧位"],"a":3,"e":"腹部检查通常取仰卧位，双腿屈曲使腹壁松弛，便于观察腹部轮廓、膨隆或凹陷并进行触诊。立位多用于检查气腹、肠梗阻液平或脏器下垂；左侧卧、右侧卧主要用于移动性浊音等特定检查，均非常规判定腹部膨隆的体位"},{"q":"关于移动性浊音检查手法下列各项均正确，但除外","o":["患者仰卧位时，腹中部呈鼓音，两侧浊音","左侧卧位后，右侧腹叩呈鼓音，左侧浊音","右侧卧位后，右侧腹叩呈浊音，左侧鼓音","常常采用轻叩手法","常常采用多次变换体位反复叩诊"],"a":3,"e":"移动性浊音检查需患者仰卧、左侧卧、右侧卧多次变换体位反复叩诊：仰卧时腹中部鼓音、两侧浊音；左侧卧时右侧鼓音、左侧浊音；右侧卧时右侧浊音、左侧鼓音。该检查叩诊力度应适中偏重，轻叩法多用于心浊音界左界或脾浊音区，故该手法错误"},{"q":"急性无黄疸型病毒性肝炎的实验室表现是","o":["血清蛋白各项均有改变","血清蛋白电泳示异常蛋白带","ALT、AST升高","MAO增高","ALP明显增高"],"a":2,"e":"急性病毒性肝炎时肝细胞受损，ALT与AST显著升高，可达正常上限20～50倍甚至100倍，ALT升高更明显、DeRitis比值小于1，是诊断与随访的重要指标。血清蛋白各项改变多见于慢性肝病；异常蛋白带见于多发性骨髓瘤；MAO增高提示肝纤维化；ALP明显增高提示胆道梗阻或胆汁淤积"},{"q":"下列选项均为病理反射，除外","o":["Oppenheim征","Gordon征","Chaddock征","Romberg征","Hoffman征"],"a":3,"e":"病理反射为锥体束损害时释放的异常反射，包括Babinski征及其等位征Oppenheim征、Gordon征、Chaddock征，以及Hoffman征。Romberg征即闭目难立征，检查姿势平衡，阳性提示小脑或深感觉障碍，属共济运动检查，不属病理反射，故为例外"},{"q":"病情较轻患者的病程记录，记录的频率应该","o":["1日1次","1日数次","2～3日记录1次","5日记录1次","1周记录1次"],"a":2,"e":"日常病程记录频率依病情而定：病危者根据病情随时记录、每天至少一次；病重者至少2天一次；病情稳定或较轻者至少3天一次，故2～3日记录1次合适。1日1次或1日数次适用于病危、病重患者；5日、1周记录1次间隔过长，不符要求"},{"q":"在心浊音界各部的组成中心腰是指","o":["左心房与左心室交接处","升主动脉与上腔静脉交接处","主动脉与肺动脉段交接处","右心房与右心室交接处","主动脉与左心室交接处"],"a":4,"e":"心腰是心脏左界上肺动脉段与左心室之间的向内凹陷，相当于主动脉与左心室交接处，位于胸骨左缘第3、4肋间附近。左心房与左心室交接处实为左心耳构成左界第3肋间的部位，并非心腰。升主动脉与上腔静脉交接处属心底右侧结构，不参与左界形成。主动脉与肺动脉段交接处位置偏高，亦不构成心腰"},{"q":"深压触诊法可检查的体征是","o":["体表浅在病变，神经，阴囊精索","肠管，索条状包块，胃肠病变","肝、脾、肾和腹腔肿物的检查","腹腔压痛点，反跳痛","大量腹水时肝、脾检查"],"a":3,"e":"深压触诊法以并拢手指逐渐深压腹壁，用于探测腹腔深在病变、确定压痛点，并检查反跳痛，如阑尾、胆囊、输尿管压痛点。双手触诊法才是肝、脾、肾及腹腔肿物的检查方法。浅部触诊用于体表浅在病变、神经及阴囊精索。滑行触诊适用于肠管、索条状包块。大量腹水时肝脾检查用浮沉触诊法"},{"q":"代谢性碱中毒的代偿反应为","o":["HCO3－升高","PaO2升高","PaO2下降","PaCO2升高","PaCO2下降"],"a":4,"e":"官方答案为【PaCO2下降】，但依据教材，正确答案为【PaCO2升高】。代谢性碱中毒原发改变为HCO3－升高，机体通过低通气使CO2潴留，PaCO2继发性升高以维持碳酸氢盐与碳酸比值接近20比1。PaCO2下降是呼吸性碱中毒的原发改变，HCO3－升高是代谢性碱中毒的原发改变而非代偿反应；PaO2变化不是酸碱失衡的代偿指标"},{"q":"Courvoisier氏征常见于","o":["急性胆囊炎","胆石症","胰头癌","胆囊炎","肝癌"],"a":2,"e":"Courvoisier氏征指胆总管梗阻致黄疸进行性加深、胆囊显著肿大但无压痛，最常见于胰头癌压迫胆总管。胆总管结石所致梗阻常因胆囊壁慢性炎症纤维化皱缩、粘连而胆囊不肿大。急性胆囊炎的肿大胆囊有明显压痛，与无痛性肿大相反。肝癌不以胆总管梗阻和胆囊肿大为特征"},{"q":"以下不属于胃镜检查的并发症的是","o":["下颌关节脱位","食管或胃穿孔","腮腺肿大","心动过速","心搏骤停"],"a":3,"e":"胃镜检查的并发症包括咽部损伤、下颌关节脱位、食管或胃穿孔、腮腺肿大以及心搏骤停等严重心血管意外。心动过速属异位快速心律，多见于房性、交界性或室性心动过速，并非胃镜操作的特有并发症。下颌关节脱位因镜身通过咽部时张口过度所致，穿孔多发生于食管狭窄或操作粗暴时"},{"q":"下列各项为异常支气管肺泡呼吸音的特点，但应除外","o":["在正常肺泡呼吸音的区域内听到支气管肺泡呼吸音","产生机制为肺部实变区域较小且与正常肺组织混合存在","肺实变部位较深，并被正常肺组织所覆盖","常见于支气管肺炎及大叶肺炎初期","在胸腔积液的上方，肺膨胀不全区域很难听到"],"a":4,"e":"异常支气管肺泡呼吸音是在正常肺泡呼吸音区域听到支气管肺泡呼吸音，机制为小片实变与正常含气肺组织混合，或实变较深被正常肺组织覆盖。胸腔积液上方肺膨胀不全区域恰是其常见听诊部位，并非难以听到。支气管肺炎和大叶性肺炎初期因实变范围小、与正常组织混杂，故常可闻及"},{"q":"急性腹膜炎患者采取的体位正确的是","o":["被动体位","强迫仰卧位","强迫俯卧位","强迫侧卧位","强迫坐位"],"a":1,"e":"急性腹膜炎患者常取强迫仰卧位，仰卧并双腿蜷曲可减轻腹肌紧张与疼痛。强迫俯卧位见于脊柱疾病，可缓解脊背肌紧张。强迫侧卧位多为胸膜疾病患者采取患侧卧位，以限制患侧胸廓活动、减轻疼痛并利于健侧代偿呼吸。被动体位见于意识丧失或极度衰弱者，与腹膜炎的主动屈曲体位不同"},{"q":"二尖瓣狭窄时，舒张期隆隆样杂音的强度变化属下列哪种形式","o":["递增型","递减型","递增递减型","连续型","一贯型"],"a":0,"e":"递增型杂音由弱渐强，二尖瓣狭窄的舒张中晚期隆隆样杂音即属此型，因舒张晚期心房收缩使血流加速而杂音增强。递减型杂音由强渐弱，见于主动脉瓣关闭不全的舒张期叹气样杂音。连续型杂音贯穿收缩与舒张期，见于动脉导管未闭。一贯型杂音强度基本恒定，见于二尖瓣关闭不全的全收缩期杂音"},{"q":"腹部肥胖与腹腔内容物增多（积液、积气或巨大包块）进行鉴别时最简单的方法是","o":["腹部外形的变化","脐部凸出或凹陷","脐周腹围的大小程度","腹壁静脉有无曲张","腹式呼吸存在与否"],"a":1,"e":"脐部凸出或凹陷是鉴别腹壁肥胖与腹腔内容物增多的简便体征：肥胖者脐多深陷，腹腔积液、积气或巨大包块使腹内压升高时脐部凸出。腹壁静脉曲张提示门脉高压侧支循环建立，与腹壁脂肪无关。腹式呼吸存在与否反映膈肌及胸腹病变，脐周腹围大小受肥胖与腹水双重影响，均不能简单区分"},{"q":"本例心电图最可能的导联反接情况是（图12）","o":["V3和V4反接","V1和V2反接","V5和V6反接","V1和V6反接","V2和V3反接"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。胸导联V1置于胸骨右缘第4肋间，V2置于胸骨左缘第4肋间，V3为V2与V4连线中点，V4在左锁骨中线第5肋间，V5、V6依次位于腋前线、腋中线同一水平。V1与V2反接使右胸导联R/S移行规律颠倒，V5与V6反接仅累及侧壁导联，V3与V4反接则扰乱胸前导联正常的R波递增序列\n\n官方题库中缺失图片"},{"q":"肝素的抗凝作用尚需依赖下列哪一项","o":["抗凝血酶","肝素酶","蛋白C","α2巨球蛋白","血栓调节蛋白"],"a":0,"e":"肝素本身不直接灭活凝血因子，需与抗凝血酶结合，增强后者对凝血因子Ⅱa、Ⅹa等的灭活而发挥抗凝作用，故肝素治疗常见APTT延长。蛋白C和血栓调节蛋白属另一抗凝系统，主要灭活因子Ⅴa、Ⅷa。α2巨球蛋白虽可抑制多种蛋白酶，但与肝素抗凝无关。肝素酶为分解肝素的酶，并非其依赖因子"},{"q":"心尖部有收缩期吹风样杂音时，下列哪项最支持二尖瓣关闭不全的诊断","o":["杂音音调较低","杂音向左腋下传导","第一心音亢进","可闻及第三心音","杂音于吸气时增强"],"a":1,"e":"二尖瓣关闭不全的杂音为心尖区粗糙高调的全收缩期吹风样杂音，典型者向左腋下及左肩胛下区传导，这一传导方向是其区别于其他杂音的重要依据。杂音音调较低不符合其高调特点。第一心音亢进见于二尖瓣狭窄。第三心音可见于心衰等多种情况，吸气时增强的是右心来源杂音"},{"q":"局限性水肿不包括","o":["踝关节炎","蜂窝织炎","丝虫病","血栓性静脉炎","心源性水肿"],"a":4,"e":"心源性水肿主要由右心衰竭引起，为全身性水肿，从足部开始向上蔓延，性质坚实、移动性小，伴心脏增大、肝大、静脉压升高。踝关节炎、蜂窝织炎、丝虫病及血栓性静脉炎均因局部静脉或淋巴回流障碍产生局部性水肿，范围局限于病变肢体或区域，不波及全身"},{"q":"咳嗽伴有声音嘶哑，最可能发生病变的是","o":["喉下神经","三叉神经","喉返神经","舌咽神经","迷走神经"],"a":2,"e":"咳嗽声音嘶哑多因声带炎症或肿瘤压迫喉返神经，导致声带麻痹所致，喉返神经为迷走神经分支，支配除环甲肌外的喉肌。喉上神经支配环甲肌，损伤主要影响音调高低而非嘶哑。三叉神经主司面部感觉与咀嚼，舌咽神经司咽部感觉与吞咽，迷走神经干病变尚伴其他内脏症状，均非最直接病变部位"},{"q":"高钾血症初期，心电图主要表现为","o":["T波高尖","T波平坦","U波明显","ST段延长","ST段缩短"],"a":0,"e":"高钾血症早期血钾超过5.5mmol/L时，心电图主要表现为T波高尖、基底部变窄，并伴QT间期缩短，为复极加速所致。T波平坦或倒置多见于低钾血症、心肌缺血。U波明显是低钾血症的特征。高钾进一步加重至6.5mmol/L以上才出现QRS增宽、PR及QT延长，ST段并非早期主要改变"},{"q":"关于干啰音的特点阐述正确的是","o":["干啰音性质不易改变","部位不易变，较恒定","音调较低","是一种持续时间较长的带乐性的呼吸附加音","吸气及呼气均可闻及，但以吸气时为明显"],"a":3,"e":"干啰音是呼吸道狭窄或不完全阻塞时气流通过产生的持续时间较长的带乐性呼吸附加音，音调较高，频率300～500Hz，吸气呼气均可闻及但以呼气为著。其性质和部位易变，可于短期内消失或重现。音调较低、部位恒定是湿啰音特点。吸气明显亦不符合干啰音以呼气为主的时相特征"},{"q":"左室肥大，QRS波群电压增高，在各导联电压变化的标准是","o":["RaVL＜1.1mV","RaVR＞0.5mV","RⅠ＞1.0mV","RV5＋SV1＞4.0mV（男性）或＞3.5mV（女性）","RV1＋SV5＞1.2mV"],"a":3,"e":"左心室肥厚的心电图电压标准中，胸导联RV5＋SV1男性大于4.0mV、女性大于3.5mV为常用诊断标准。RV5或RV6单独大于2.5mV亦有价值。RV1＋SV5增大反映右心室肥厚，不是左室标准。肢体导联RⅠ需大于1.5mV方有意义，1.0mV偏低。aVL导联R波小于1.1mV更非左室肥大表现"},{"q":"潮气容积是指","o":["平静呼吸时，一次吸入的气量","平静呼吸时，一次呼出的气量","运动时，一次吸入的气量","运动时，一次呼出的气量","平静呼吸时，一次吸入和呼出的气量"],"a":4,"e":"潮气容积指平静呼吸时每次吸入或呼出的气量，正常成人约500ml，受吸气肌尤其膈肌功能影响，呼吸肌功能不全时降低。仅计吸入或仅计呼出虽数值相等，但未完整表述一次呼吸周期的通气量。运动时单次呼吸的气量属于深吸气量或运动中通气范畴，不是潮气容积的定义"},{"q":"引起心悸最常见的病因是","o":["心力衰竭","心律失常","冠心病","神经官能症","心肌病"],"a":1,"e":"心悸是自觉心跳不适，最常见病因为心律失常，尤以心动过速、心房颤动、期前收缩等使心室充盈减少、心肌与瓣膜张力骤变所致。心力衰竭和心肌病多通过心功能不全间接引起，并非最常见。冠心病以胸痛为主要表现。神经官能症属功能性原因，发生率低于心律失常"},{"q":"叩诊肺尖时，其正常宽度为","o":["1～2cm","3～4cm","4～6cm","7～8cm","叩不清"],"a":2,"e":"肺尖叩诊清音带即Kronig峡，正常宽度4～6cm，为肺尖在胸壁上的投影范围。右肺尖位置较低且右侧肩胛带肌肉较发达，故右侧较左侧稍窄。1～2cm或3～4cm明显低于正常，提示肺尖实变或胸膜增厚。肺气肿时肺过度充气可使Kronig峡增宽，并非叩不清"},{"q":"关于副神经检查，下列叙述哪项不正确","o":["观察胸锁乳突肌及斜方肌有无萎缩","有无斜颈及垂肩","嘱患者转颈测试胸锁乳突肌的肌力","嘱患者耸肩比较两侧肌力","观察双上肢肌肉有无萎缩"],"a":4,"e":"副神经为第Ⅺ对脑神经，支配胸锁乳突肌与斜方肌，检查时观察这两块肌有无萎缩、有无斜颈垂肩，并嘱转颈、耸肩比较双侧肌力。双上肢肌肉萎缩属上肢及臂丛或下运动神经元病变范畴，与副神经无关。观察胸锁乳突肌和斜方肌萎缩、转颈及耸肩测肌力均为副神经检查的正确内容"},{"q":"白细胞分类计数时，应在油镜下选择哪个部位有秩序地检查","o":["涂片头体部染色较好处","涂片体、尾交界处染色较好处","涂片体部染色较好处","涂片尾部染色较好处","涂片的两侧染色较好处"],"a":1,"e":"白细胞分类计数在油镜下进行，应选择染色良好、细胞分布均匀的涂片体尾交界处，按种类与发育阶段有序计数200～500个细胞。涂片头部细胞密集、尾部细胞易破碎变形，均不适合计数。仅选体部或两侧染色好处不能兼顾细胞分散与形态完整，体尾交界处最为适宜"},{"q":"关于血清学试验结果的分析错误的是","o":["试验阳性说明机体接触过病原体","单次试验阳性不能完全证明新近感染","试验阴性不能完全排除相应病原体感染的可能性","试验阳性即有诊断意义","试验有假阴性的可能"],"a":3,"e":"血清学试验阳性只说明机体可能接触过相应病原体，并不等于现症感染或具有确诊价值，需结合确诊试验、双份血清抗体效价4倍增高或临床表现判断。单次阳性不能证明新近感染，故试验阳性即有诊断意义的说法错误。阴性亦不能排除感染，因存在窗口期和假阴性可能"},{"q":"墨菲征阳性最常见于","o":["急性胰腺炎","急性胆囊炎","急性胃穿孔","胆石症","急性肝炎"],"a":1,"e":"墨菲征阳性提示胆囊触痛，最常见于急性胆囊炎，检查者按压右上腹胆囊区嘱深吸气，胆囊下移触及压痛而突然屏气即为阳性。胆石症常表现为胆绞痛，多无显著胆囊触痛。急性胰腺炎压痛位于上腹偏左并向背部放射。急性肝炎以肝大、肝区叩痛为主，胆囊肿大不明显"},{"q":"用于判断通气功能障碍性质的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":0,"e":"FEV1/FVC是判断通气功能障碍性质的核心指标，阻塞性通气障碍以流速降低为主，FEV1/FVC下降，限制性障碍则以肺容量减少为主，FEV1/FVC正常或升高。FEV1%pred和PEF主要反映气道阻塞程度及可逆性，FVC反映肺容量，MEF50为小气道流速指标，均不能单独区分阻塞与限制性质"},{"q":"既能听到心脏杂音又能触到震颤的疾病是","o":["风湿性心脏病二尖瓣狭窄","风湿性心脏病二尖瓣关闭不全","先天性心脏病房间隔缺损","高血压心脏病左心室大","甲状腺功能亢进"],"a":0,"e":"风湿性心脏病二尖瓣狭窄可在心尖区闻及舒张期隆隆样杂音，重度狭窄瓣口明显、血流湍流时可触及舒张期震颤，杂音与震颤并存。二尖瓣关闭不全多为收缩期吹风样杂音，通常无震颤。房间隔缺损杂音来自肺动脉瓣区相对狭窄。高血压心脏病左室大及甲亢多仅闻及杂音而无震颤"},{"q":"消化性溃疡的疼痛特点是","o":["上腹痛","剑突下痛","脐周痛","上腹部节律性，周期性痛","下腹痛"],"a":3,"e":"消化性溃疡疼痛典型表现为上腹部慢性反复发作、具有节律性和周期性的疼痛，胃溃疡多于餐后1小时内出现，经1～2小时缓解，十二指肠溃疡多为空腹痛，出血后疼痛减轻。单纯上腹痛过于笼统，剑突下痛与脐周痛定位不符，下腹痛更非溃疡疼痛部位，节律性与周期性最具特征"},{"q":"常见血清总胆固醇增高的疾病是","o":["贫血","急性重型肝炎","冠状动脉粥样硬化","甲状腺功能亢进症","肝硬化"],"a":2,"e":"血清总胆固醇增高是冠状动脉粥样硬化的重要危险因素，高胆固醇血症促进脂质在动脉壁沉积形成斑块。贫血和急性重型肝炎因肝脏合成功能受损或消耗，胆固醇多降低。甲状腺功能亢进时胆固醇合成与分解均加速，以分解为主而血胆固醇偏低。肝硬化肝细胞受损，胆固醇合成减少而降低"},{"q":"反映肝纤维化的血清学指标是","o":["胆固醇","乳酸脱氢酶（LDH）","γ-谷氨酰转肽酶（γ-GT，GGT）","透明质酸（HA）","胆汁酸"],"a":3,"e":"透明质酸是反映肝纤维化的常用血清学指标，肝纤维化时肝内胶原合成亢进、基质降解改变，血清透明质酸明显升高，其水平与纤维化程度相关。胆固醇和胆汁酸反映胆汁代谢与肝细胞功能。乳酸脱氢酶为细胞损伤的非特异酶。γ-谷氨酰转肽酶主要反映胆汁淤积和酒精性肝损伤，不特异提示纤维化"},{"q":"胸痛患者伴有心前区杂音及血压下降，其最可能的诊断是","o":["二尖瓣狭窄","心包炎","肺梗死","主动脉缩窄","自发性气胸"],"a":3,"e":"先天性主动脉缩窄可于胸骨左缘及心前区闻及收缩期杂音，并因上肢血压升高、下肢血压低于上肢而表现为血压异常，是本例最可能的诊断。二尖瓣狭窄杂音局限于心尖区且舒张期为主。心包炎以心包摩擦音为主。肺梗死多伴咯血与胸膜摩擦音。自发性气胸以呼吸音消失和鼓音为特征，均无此组合"},{"q":"书写病程记录的要求，以下各项错误的是","o":["首先要标明记录时间（采用12小时制或24小时制均可）","对病危患者应当根据病情变化随时记录书写，每天至少1次","对病重患者，至少2天记录1次病程记录","对病情稳定的患者，至少3天记录1次病程记录","常规会诊记录应该由会诊医师在会诊申请发出后48小时内完成"],"a":0,"e":"病程记录书写必须采用24小时制标注时间，采用12小时制或24小时制均可的说法与规范不符。病危患者应随病情变化随时记录、每天至少一次，病重者至少两天一次，病情稳定者至少三天一次。常规会诊记录应由会诊医师在会诊申请发出后48小时内完成，以上时间要求均正确"},{"q":"动态心电图的导联中显示P波清楚，最有助于分析心律失常的导联是","o":["CM5","CM1","MaVF","CM2","CM3和MaVF"],"a":1,"e":"CM1导联正极置于胸骨右缘第4肋间即V1位置，负极置于左锁骨下窝中三分之一处，能清楚显示P波，是动态心电图分析心律失常最常用的导联。CM5对缺血型ST段下移最敏感且QRS振幅高，用于心肌缺血检测。MaVF为下壁导联，CM2、CM3亦不如CM1突出P波"},{"q":"充盈膀胱与卵巢囊肿最有鉴别意义的体征是","o":["囊性感与实体感","有无移动性浊音","触诊形态","按之有无尿意","排尿或导尿后肿块体积变化"],"a":4,"e":"充盈膀胱与卵巢囊肿鉴别最有意义的是排尿或导尿后肿块体积变化：膀胱充盈排尿或导尿后浊音区转为鼓音、肿块缩小或消失，卵巢囊肿则大小不变。囊性感与实体感二者均可呈囊性。移动性浊音提示腹腔积液。触诊形态与按之有无尿意虽可参考，但不如排尿后体积改变确切"},{"q":"下列中最符合大红细胞直径的是","o":["12μm","11μm","10μm","＞10μm","≥10μm"],"a":3,"e":"正常红细胞直径6～9μm，平均7.5μm，大红细胞体积增大，直径超过10μm，常见于巨幼细胞贫血等。11μm、12μm虽也大于正常，但并非大红细胞的下限界定。10μm恰在正常上限，不足与大红细胞区分。直径等于或大于10μm的表述包含了10μm本身，未准确体现大于10μm的界限"},{"q":"怀疑原发性肝癌时，下列中首选的检查项目为","o":["ALP","AFP","γ-GT","AFU","ALT"],"a":1,"e":"甲胎蛋白是辅助诊断原发性肝癌最常用的肿瘤标志物，血清AFP持续显著升高并排除妊娠、活动性肝病及生殖腺胚胎肿瘤后即可高度怀疑肝癌，还可用于疗效监测与复发随访。ALP和γ-GT主要反映胆汁淤积。ALT反映肝细胞损伤。AFU虽可辅助，但敏感性与特异性均不及AFP"},{"q":"患者大量蛋白尿5年，诊断为肾病综合征，其蛋白尿的性质为","o":["肾小球性蛋白尿","肾小管性蛋白尿","溢出性蛋白尿","组织性蛋白尿","其他"],"a":0,"e":"肾病综合征的大量蛋白尿源于肾小球滤过屏障损伤，属肾小球性蛋白尿，以白蛋白等中大分子蛋白为主，伴低蛋白血症与水肿。肾小管性蛋白尿以α1、β2微球蛋白等小分子为主，见于肾盂肾炎、间质性肾炎。溢出性蛋白尿见于多发性骨髓瘤等，组织性蛋白尿为Tamm-Horsfall蛋白增多"},{"q":"下面是医生观察患者全身状况的视诊检查内容，但不包括","o":["年龄","发育","营养","体温","意识状态"],"a":3,"e":"全身状况视诊主要通过肉眼观察获得信息，包括年龄、发育、营养、意识状态、面容表情、体位步态等。体温须用体温计测量获得，属客观检查数据而非视诊所得，故不属于视诊内容。虽然一般检查包含体温，但其获取方式为测量，与年龄、发育、营养、意识状态的视诊性质不同"},{"q":"关于稽留热的描述，下列不正确的是","o":["体温维持在39～40℃以上","恒定维持高水平达数天或数周","体温波动范围不超过1℃","常见于大叶肺炎，斑疹伤寒及伤寒高热期","也见于疟疾、布鲁菌病"],"a":4,"e":"稽留热为体温恒定维持在39～40℃以上、数天或数周波动不超过1℃的热型，常见于大叶性肺炎、斑疹伤寒及伤寒高热期。疟疾表现为间歇热，体温骤升骤降、间歇期正常。布鲁菌病为波状热，体温渐升渐降反复起伏。二者均非稽留热，题干将其归为稽留热所见是错误的"},{"q":"空洞巨大、位置表浅且腔壁光滑的叩诊音应为","o":["过清音","浊鼓音","空瓮音","浊音","实音"],"a":2,"e":"空瓮音为鼓音的特殊类型，见于空洞巨大、位置表浅且腔壁光滑或张力性气胸，因叩诊时产生金属性回响而得名。过清音见于肺气肿等含气量增多、肺张力减弱。浊鼓音兼有浊音与鼓音特点，见于肺不张、肺炎充血期。单纯浊音或实音见于肺实变或胸腔积液，均无金属回响"},{"q":"再生障碍性贫血的血象不会表现为","o":["红细胞减少","白细胞减少","血小板减少","淋巴细胞比例下降","单核细胞减少"],"a":3,"e":"再生障碍性贫血因骨髓造血功能低下，全血细胞减少，表现为红细胞、白细胞、血小板均减少，但因中性粒细胞减少显著，淋巴细胞比例相对增高，绝对值并不增加，故不会出现淋巴细胞比例下降。单核细胞亦可减少。淋巴细胞比例下降多见于应用糖皮质激素、烷化剂或放射线损伤后"},{"q":"叩诊肝脏相对浊音界时，其叩诊音应是","o":["由清音转为实音","由浊音变为实音","由过清音转为实音","由清音转为鼓音","由清音转为浊音"],"a":4,"e":"叩诊肝上界时沿右锁骨中线由肺区向下叩，当清音转为浊音即为肝相对浊音界，此处为被肺遮盖的肝顶部。再向下叩1～2肋间浊音转为实音，为肝绝对浊音界，肝脏直接贴近胸壁。过清音转为实音不符合肝脏叩诊顺序，清音转鼓音见于含气空腔，均非相对浊音界的叩诊表现"},{"q":"关于过敏性紫癜关节痛，描述有误的是","o":["常伴双下肢皮肤紫癜","可伴消化道症状","可伴血尿、蛋白尿","血小板计数常减少","可由多种过敏原诱发"],"a":3,"e":"过敏性紫癜属血管壁通透性增高所致的血管性紫癜，表现为四肢对称性高出皮面的紫癜，可伴关节痛、腹痛及血尿蛋白尿，可由多种过敏原诱发，但血小板计数正常。血小板减少并非其特点。血小板计数常减少见于血小板减少性紫癜，两者止血检查不同，出血时间与血小板计数可资鉴别"},{"q":"关于肌张力下列哪项正确","o":["指肌肉运动时的最大收缩力","肌张力减弱时肢体强直","是指静息状态下的肌肉紧张度","肌张力增加时表现为关节过伸","肌张力增加主要由周围神经损害引起"],"a":2,"e":"肌张力指静息状态下的肌肉紧张度及被动运动时遇到的阻力，实质为牵张反射，检查时嘱肌肉放松，通过触摸肌肉硬度和伸屈肢体感知阻力判断。肌肉最大收缩力为肌力，非肌张力。肌张力减弱表现为肌肉松弛、关节过伸。肌张力增高属锥体束或锥体外系损害，多由中枢病变引起，而非周围神经损害"},{"q":"不会出现肝大的疾病是","o":["急性病毒性肝炎伴黄疸","肝硬化伴腹水","肝癌伴肝性脑病","肝脓肿伴右侧胸腔积液","右心衰竭伴下肢水肿"],"a":1,"e":"肝硬化伴腹水时肝脏多缩小或正常大小，表面凹凸不平、质硬，一般不出现肝大，故为本题答案。急性病毒性肝炎时肝脏轻度肿大、质稍韧有压痛。肝癌伴肝性脑病时肝脏多显著肿大、质硬有结节。肝脓肿伴胸腔积液时肝脏肿大伴压痛。右心衰竭致肝淤血时肝脏明显肿大、肝颈静脉回流征阳性"},{"q":"纤维支气管镜不容易发现下列哪部位的病灶","o":["肺尖","肺门","隆突","段支气管","声门"],"a":0,"e":"纤维支气管镜可观察声门、隆突、肺门及段支气管，对段及以上支气管腔内病灶发现率高。肺尖位于上叶尖段远端，镜身难以进入且角度受限，经支气管镜直视观察困难，故最不易发现。肺门和隆突为镜检必经部位。声门在插镜时首先经过，段支气管亦可直接观察，均较易发现"},{"q":"内源性凝血从哪个因子开始激活","o":["Ⅷ","Ⅸ","Ⅺ","Ⅻ","Ⅴ"],"a":3,"e":"内源性凝血途径由因子Ⅻ接触带负电荷的玻璃等表面被激活而启动，继而依次激活Ⅺ、Ⅸ、Ⅷ，最终形成凝血活酶。凝血时间测定即反映由因子Ⅻ激活到纤维蛋白形成的过程。因子Ⅷ、Ⅸ、Ⅺ属内源性途径后续因子。因子Ⅴ参与共同途径。外源性途径则由组织因子和因子Ⅶ启动，与Ⅻ无关"},{"q":"进行性排尿困难最常见的病因是","o":["尿道狭窄","膀胱癌","前列腺增生","膀胱颈部纤维性增生","膀胱结石"],"a":2,"e":"进行性排尿困难是老年男性前列腺增生的最典型表现，因增生的前列腺压迫尿道致尿线变细、排尿费力、尿流中断。尿道狭窄多有外伤或感染史，起病较急。膀胱癌以无痛性血尿为主。膀胱颈部纤维性增生少见。膀胱结石常致尿流突然中断伴排尿痛，均非进行性加重的常见原因"},{"q":"检测外源性凝血途径有无障碍的试验是","o":["凝血时间的测定","血浆复钙时间的测定","血浆凝血酶原时间的测定","血清凝血酶原时间的测定","简易凝血活酶生成试验"],"a":2,"e":"血浆凝血酶原时间测定是外源性凝血系统最灵敏、最常用的筛选试验，反映因子Ⅱ、Ⅴ、Ⅶ、Ⅹ及纤维蛋白原的功能，PT延长提示外源性途径障碍。凝血时间和复钙时间反映内源性凝血。血清凝血酶原时间测定并非常用外源性筛选。简易凝血活酶生成试验用于内源性凝血因子检测"},{"q":"下列关于艾滋病的叙述，除哪项外均正确","o":["其病原体为HIV","HIV为逆转录酶病毒","AIDS为严重的细胞免疫缺陷性疾患","AIDS为先天性免疫缺陷综合征","其血清学检查有间接荧光免疫法及病毒检查法"],"a":3,"e":"艾滋病即获得性免疫缺陷综合征，由HIV感染引起，属获得性而非先天性免疫缺陷，故该项错误。HIV为逆转录病毒，可结合CD4受体进入易感细胞造成细胞免疫严重缺陷。其血清学检查包括间接免疫荧光法及病毒核酸检测。其余各项表述均正确，病原体、病毒类别和检查方法均符合教材"},{"q":"造血物质缺乏所起的贫血包含","o":["尿毒症贫血","白血病贫血","巨幼细胞贫血","骨髓纤维化","地中海贫血"],"a":2,"e":"巨幼细胞贫血由叶酸或维生素B12等造血物质缺乏引起DNA合成障碍，红细胞发育障碍呈大细胞性，属造血物质缺乏性贫血。尿毒症贫血因促红素减少及毒素抑制。白血病贫血因骨髓被异常细胞浸润。骨髓纤维化为造血组织纤维化。地中海贫血属遗传性珠蛋白合成障碍，均非造血物质缺乏"},{"q":"为了确定肝外胆管阻塞的部位，需选择的检查是","o":["十二指肠引流","电子计算机体层扫描","经内镜逆行胰胆管造影","肝穿刺活检","B型超声检查"],"a":2,"e":"经内镜逆行胰胆管造影可经内镜直接观察壶腹区与乳头部病变，并注入造影剂分辨肝外或肝内胆管阻塞的具体部位，是判断肝外胆管阻塞部位的首选。十二指肠引流只能大致判断胆汁来源。B超可发现胆管扩张但定位欠精确。CT对软组织分辨率有限。肝穿刺活检用于肝实质病变，不用于胆管定位"},{"q":"普氏立克次体主要的传播途径是","o":["消化道","蚤叮咬后入血","螨叮咬后入血","虱叮咬后入血","鼠咬伤感染"],"a":3,"e":"普氏立克次体是流行性斑疹伤寒的病原体，主要通过人虱叮咬后经破损皮肤侵入血流而传播，虱吸血时排出含病原体的粪便，搔抓使其进入体内。蚤传播主要为鼠疫和地方性斑疹伤寒。螨传播见于恙虫病。消化道和鼠咬伤并非立克次体的主要传播方式，与普氏立克次体的传播循环不符"},{"q":"胸部语音震颤不减弱的疾病是","o":["肺组织炎性浸润","胸腔积液","肺气肿","胸膜肥厚","阻塞性肺不张"],"a":0,"e":"肺组织炎性浸润如大叶性肺炎实变期，因肺组织实变、含气量减少而传导良好，语音震颤增强而非减弱，故为本题答案。胸腔积液、胸膜肥厚使声波传导受阻，语颤减弱。肺气肿因肺泡含气过多、弹性减弱致语颤减弱。阻塞性肺不张时支气管阻塞、肺组织萎陷，语颤亦减弱"},{"q":"肾小球性蛋白尿见于以下疾病，但除外","o":["隐匿性肾小球肾炎","肾病综合征","急性肾小球肾炎","肾盂肾炎","慢性肾小球肾炎"],"a":3,"e":"肾盂肾炎主要累及肾小管和肾间质，属肾小管性蛋白尿，标志性蛋白为α1、β2微球蛋白等小分子蛋白，不是肾小球性蛋白尿。隐匿性肾小球肾炎、肾病综合征、急性及慢性肾小球肾炎均损伤肾小球滤过屏障，出现以白蛋白为主的肾小球性蛋白尿，故肾盂肾炎为例外"},{"q":"吸气时增强的杂音是","o":["三尖瓣关闭不全的杂音","二尖瓣关闭不全的杂音","二尖瓣狭窄的杂音","主动脉瓣狭窄的杂音","主动脉瓣关闭不全的杂音"],"a":0,"e":"三尖瓣关闭不全的杂音为右心来源，吸气时胸腔负压增大、回心血量增多，使右心搏出量增加，杂音随之增强，是其特征。二尖瓣关闭不全杂音向左腋下传导，吸气时多减弱。二尖瓣狭窄为舒张期隆隆样杂音，局限于心尖区。主动脉瓣狭窄和关闭不全均为左心来源，吸气时多减轻"},{"q":"以下哪个临床表现不是右侧三叉神经损伤表现","o":["右侧面部痛觉减退","右侧直接角膜反射消失","右侧咀嚼肌无力","下颌偏向右侧","右侧闭眼不紧"],"a":4,"e":"右侧闭眼不紧属面神经损伤表现，面神经支配眼轮匝肌，损伤后眼睑闭合不全，与三叉神经无关。三叉神经第3支支配咀嚼肌，损伤后右侧咀嚼肌无力、张口下颌偏向患侧。三叉神经眼支受损可使角膜反射传入中断，出现右侧直接角膜反射消失。面部痛觉减退亦为其感觉障碍表现"},{"q":"下列疾病不会引起中心型发绀的是","o":["慢性阻塞性肺疾病","感染性休克","急性左心衰竭","法洛四联症","Eisenmenger综合征"],"a":1,"e":"感染性休克时因微循环障碍、组织缺氧及外周血管收缩，属缺血性周围性发绀，不出现中心型发绀。慢性阻塞性肺疾病、法洛四联症和Eisenmenger综合征均因肺通气换气障碍或右向左分流使动脉血氧饱和度降低，引起中心性发绀。急性左心衰竭致肺淤血、肺水肿，氧合障碍亦为中心性"},{"q":"深反射检查时发现存在阵挛时，反射强度应该为","o":["0","1＋","2＋","3＋","4＋"],"a":4,"e":"反射强度分级中，阴性为反射消失，一个加号为减弱，两个加号为正常，三个加号为增强。四个加号表示反射亢进并伴有阵挛，属病理状况，故发现阵挛时应判为4＋。阵挛是锥体束以上病变致深反射高度亢进时，肌肉持续牵拉产生节律性收缩的表现，踝阵挛和髌阵挛最常见"},{"q":"下列哪项试验能较早的反映肾小球滤过功能的损害并估计其损害程度","o":["血尿素氮定量","血肌酐定量","内生肌酐清除率","自由水清除率","浓缩稀释试验"],"a":2,"e":"内生肌酐清除率在严格控制饮食和肌肉活动稳定时，血肌酐生成与尿排泄恒定，肌酐主要经肾小球滤过且不被重吸收，能较早、较准确反映肾小球滤过功能损害并估计程度。血尿素氮和血肌酐受饮食、肌肉量等影响，敏感性较低。自由水清除率和浓缩稀释试验主要反映肾小管浓缩稀释功能"},{"q":"患者疑似大叶性肺炎，下列哪项对诊断最有帮助","o":["呼吸困难","咳嗽","咳铁锈色痰","发热","发绀"],"a":2,"e":"咳铁锈色痰是肺炎链球菌所致大叶性肺炎的典型特征，对诊断最有帮助，源于肺泡内红细胞破坏后血红蛋白变性。呼吸困难、咳嗽、发热均为呼吸系统疾病常见非特异症状，缺乏定位价值。发绀仅提示缺氧程度，不能提示病因。铁锈色痰将该病与其他肺炎明确区分"},{"q":"间歇热最常见的疾病是","o":["渗出性胸膜炎","斑疹伤寒","疟疾","风湿热","败血症"],"a":2,"e":"间歇热表现为体温骤升至高峰后持续数小时又骤降至正常，无热期可持续一至数天并反复交替，最常见于疟疾，也见于急性肾盂肾炎。渗出性胸膜炎多表现为不规则热或低热。斑疹伤寒多为稽留热。风湿热热度不规则。败血症常呈弛张热，均非间歇热的典型疾病"},{"q":"有机磷中毒","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","眼睑下垂"],"a":1,"e":"有机磷杀虫剂中毒抑制胆碱酯酶，乙酰胆碱蓄积致毒蕈碱样作用，表现为双侧瞳孔缩小，伴腺体分泌增多、平滑肌痉挛等。瞳孔扩大见于颠茄类、酒精、氰化物中毒及阿托品作用。瞳孔大小不等等于颅内病变如脑疝。瞳孔缩小伴眼睑下垂为Horner综合征，均非单纯有机磷中毒表现"},{"q":"成年男性红细胞参考值为","o":["（3.5～5.5）×1012/L","（4.0～5.5）×1012/L","（4.0～6.0）×1012/L","（3.5～5.0）×1012/L","（3.0～5.0）×1012/L"],"a":1,"e":"成年男性红细胞计数参考值通常为每升4.0至5.5乘以10的12次方，本题据此作答。成年女性参考范围较低，约为每升3.5至5.0乘以10的12次方，相当于选项所列较低范围。新生儿红细胞明显增高，约为每升6.0至7.0乘以10的12次方。3.5至5.5的宽泛范围并非成年男性标准"},{"q":"有关捻发音错误的是","o":["是一种极细小而均匀一致的湿啰音","多在吸气末易听到","听诊时好像在耳旁用手指捻搓一束头发所产生的声音","高音调、高频率的细小破裂声","就是Velcro啰音"],"a":4,"e":"捻发音是极细小而均匀一致的湿啰音，多在吸气终末听及，声音类似在耳边用手指捻搓一束头发，属高音调、高频率的细小破裂声。Velcro啰音为弥漫性肺间质纤维化患者吸气后期出现的高调细湿啰音，类似撕开尼龙扣带的声音，二者听诊机制与临床意义不同，不能等同"},{"q":"腋测法体温的正常值是","o":["35～36℃","36.3～37.2℃","36.5～37.7℃","36～37℃","37.3～38℃"],"a":3,"e":"腋测法正常体温为36～37℃，简便安全且不易交叉感染，为最常用测定方法，测量时需擦干腋窝汗液。口测法正常值为36.5～37.7℃，较腋测法为高。肛测法一般较口测法高0.2～0.5℃，多用于婴幼儿及神志不清者。35～36℃偏低，37.3～38℃已属发热范围"},{"q":"最常见血清铁降低的疾病是","o":["急性重型肝炎","溶血性贫血","再生障碍性贫血","巨幼细胞贫血","消化道肿瘤"],"a":4,"e":"血清铁降低最常见于消化道肿瘤，因肿瘤慢性失血致缺铁，血清铁、铁蛋白下降，粪便隐血持续阳性可提示。溶血性贫血因红细胞破坏释放铁，血清铁多升高。再生障碍性贫血和巨幼细胞贫血铁利用减少，血清铁正常或升高。急性重型肝炎以肝细胞损伤为主，非血清铁降低的常见原因"},{"q":"长期反复咳大量脓臭痰伴咯血最可能为","o":["肺结核","急性肺炎","支气管扩张","慢性支气管炎","支气管哮喘"],"a":2,"e":"长期反复咳大量脓臭痰伴咯血最符合支气管扩张，因支气管壁破坏、管腔扩张扭曲，分泌物蓄积继发感染，痰量多且恶臭，常伴反复咯血。肺结核多有低热盗汗，痰中带血而非大量脓臭痰。慢性支气管炎痰量较少、多为白色黏痰。急性肺炎病程短。支气管哮喘以喘息为主，少有脓痰"},{"q":"关于皮肤划痕试验，正确的是","o":["用针加适度压力在皮肤上划压","几分钟后就会出现白色划痕","白色划痕持续时间较久，提示副交感神经兴奋性增高","红色划痕迅速出现且持续时间长，提示副交感神经兴奋性增高","不属于自主神经功能检查"],"a":3,"e":"皮肤划痕试验用钝头竹签适度加压划皮肤，红色划痕迅速出现、持续时间长、明显增宽隆起提示副交感神经兴奋性增高或交感神经麻痹。白色划痕持续超过5分钟提示交感神经兴奋性增高，而非副交感。白色划痕数秒出现属正常反应。该试验用于自主神经功能检查，针划过于锐利不符合操作规范"},{"q":"关于镜下血尿是指尿沉渣镜检红细胞","o":["0～3个/HPF","＞3个/HPF","＞5个/HPF","＞10个/HPF","＞20个/HPF"],"a":1,"e":"镜下血尿指离心尿液镜检红细胞超过3个每高倍视野，而外观无血色。玻片法红细胞0～2个每高倍视野属正常范围。超过5个或10个每高倍视野虽亦异常，但并非镜下血尿的界定标准。20个每高倍视野已属明显血尿，超出诊断阈值，均非准确定义"},{"q":"正常脑脊液中为主的细胞是","o":["单个核细胞","吞噬细胞","中性粒细胞","脉络丛细胞","室管膜细胞"],"a":0,"e":"正常脑脊液有核细胞分类以淋巴细胞和单核细胞等单个核细胞为主，二者比例约为7比3，可偶见内皮细胞。中性粒细胞增多提示化脓性脑膜炎等急性细菌感染。吞噬细胞、脉络丛细胞和室管膜细胞均非正常脑脊液的主要细胞成分，仅在特定病理或穿刺情况下出现"},{"q":"关于左房舒张晚期奔马律下述正确的是","o":["心室克服舒张末期压力增高方面加强收缩所致","病理性S4距S2较近，距S1较远","在心尖部稍内侧听诊最清晰","在吸气末加强","反映心室收缩期容量负荷过重"],"a":2,"e":"舒张晚期奔马律为病理性第四心音，音调较低、强度较弱，在S1前约0.1秒，于心尖部稍内侧听诊最清楚，呼气末更响。其产生源于心房收缩克服增高的舒张末期压力而加强收缩，并非心室收缩。它距S2较远而接近S1，反映心室舒张期压力负荷过重，而非收缩期容量负荷"},{"q":"不常见球蛋白升高的疾病是","o":["肝硬化","慢性炎症","急性肝炎","M蛋白血症","淋巴瘤"],"a":2,"e":"球蛋白升高常见于慢性炎症、肝硬化、M蛋白血症及淋巴瘤等，因免疫球蛋白合成活跃或单克隆增殖。急性肝炎以转氨酶升高为主，球蛋白多正常或仅轻度变化，不常见明显升高，故为例外。肝硬化时γ球蛋白增高显著。M蛋白血症出现单一克隆免疫球蛋白大量增多，淋巴瘤亦可伴球蛋白升高"},{"q":"对于一个已确诊患者的治疗措施不包括","o":["病因治疗","对症治疗","心理安慰","推拿、按摩","诊断性治疗"],"a":4,"e":"诊断性治疗是在诊断未明确时通过治疗反应验证假设的方法，患者已确诊后无需再行诊断性治疗，应按确诊结果处理。病因治疗针对根本病因，对症治疗缓解症状，心理安慰属支持性措施，推拿按摩可作为部分疾病的辅助康复手段，这些在确诊后均可根据病情合理采用"},{"q":"关于Kronig峡阐述不正确的是","o":["Kronig峡正常宽度为4～6cm","左侧较右侧宽","左侧较右侧窄","当肺炎浸润性结核时Kronig峡变窄","肺气肿时Kronig峡增宽"],"a":2,"e":"Kronig峡即肺尖叩诊清音带，正常宽4～6cm，因右肺尖位置较低且右侧肩胛带肌肉较发达，右侧较左侧稍窄，即左侧较右侧宽。故左侧较右侧窄的表述错误。肺炎浸润及肺结核致肺尖实变时Kronig峡变窄。肺气肿时肺过度充气使肺尖清音带增宽，均与病理生理相符"},{"q":"下列各项均为“急腹症”的病因，但除外","o":["肠梗阻","胃肠穿孔","卵巢扭转","宫外孕","肝淤血"],"a":4,"e":"急腹症以急性腹痛、腹膜刺激征为主要表现，肠梗阻、胃肠穿孔、卵巢扭转、宫外孕均可急性起病并需紧急处理，分别对应梗阻、穿孔、扭转缺血及异位妊娠破裂。肝淤血多由慢性右心衰竭引起，肝进行性肿大伴压痛及肝颈静脉回流征阳性，病程缓慢，不属急腹症病因"},{"q":"Austin-Flint杂音最常见于下列何种疾病","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，主动脉瓣关闭不全","风湿性心脏病，二尖瓣关闭不全","风湿性心脏病，主动脉瓣狭窄","风湿性心脏病，三尖瓣狭窄"],"a":1,"e":"Austin-Flint杂音见于中重度主动脉瓣关闭不全，因舒张期主动脉血液反流冲击二尖瓣，使二尖瓣处于半关闭状态形成相对狭窄，于心尖区产生舒张早期递减型柔和杂音，前倾坐位、深呼气后最清楚。器质性二尖瓣狭窄杂音为递增型隆隆样伴震颤。风湿性二尖瓣关闭不全为收缩期吹风样杂音，主动脉瓣狭窄为收缩期喷射性杂音"},{"q":"体温调节中枢的高级部分是","o":["视前区-前下丘脑","延髓","脑桥","中脑","脊髓"],"a":0,"e":"体温调节中枢的高级部分位于视前区-前下丘脑，此处存在体温调定点，整合产热与散热信息并通过神经体液途径维持体温恒定。延髓、脑桥、中脑参与基本生命活动中枢调节，但非体温调节的高级整合部位。脊髓仅完成低级反射，不能对体温进行高级调控"},{"q":"患者与人吵架后情绪激动，晕厥。情绪激动时可出现","o":["呼吸浅慢","Kussmaul呼吸","Biot呼吸","Cheyne-Stokes呼吸","呼吸深快"],"a":4,"e":"情绪激动或过度紧张时交感神经兴奋，出现呼吸深快并伴过度通气，使动脉血二氧化碳分压降低，引起呼吸性碱中毒，患者可感口周及肢端发麻，严重者手足搐搦。呼吸浅慢不符合激动时反应。Kussmaul呼吸为代谢性酸中毒的深大呼吸。Biot呼吸和Cheyne-Stokes呼吸均属呼吸中枢抑制性异常节律"},{"q":"关于肺部叩诊音，叙述不正确的是","o":["叩诊音类型与病变性质、范围及部位有关","当肺内含气量增多、肺张力减弱时，叩诊呈过清音","少量胸腔积液，叩诊不易发现","距胸部表面5cm以上、直径小于3cm的病灶，叩诊可以发现异常","肺内不含气的占位病变，叩诊呈浊音"],"a":3,"e":"肺部叩诊受病灶大小和深度限制，距胸部表面5cm以上的深部病灶、直径小于3cm的小病灶或少量胸腔积液常不能发现叩诊音改变，故该表述错误。叩诊音类型确实与病变性质、范围及部位有关。肺含气量增多、张力减弱时呈过清音。肺内不含气占位病变叩诊呈浊音"},{"q":"下列哪种情况胸骨左缘第2肋间可见异常搏动","o":["右心室肥大","肺动脉高压","升主动脉瘤","主动脉弓瘤","大动脉炎"],"a":1,"e":"胸骨左缘第2肋间为肺动脉瓣区，该处收缩期搏动多见于肺动脉扩张或肺动脉高压，也可见于瘦长青年体力活动或情绪激动时。右心室肥大搏动多在胸骨左下缘或剑突下。升主动脉瘤和主动脉弓瘤的搏动位于胸骨右缘第2肋间或胸骨上窝。大动脉炎以脉搏不对称、无脉为主要表现"},{"q":"心电图上的P波反应的是","o":["窦房结除极","窦房结复极","心房除极","心房复极","房室结除极"],"a":2,"e":"P波反映心房的除极过程，正常右心房先除极、左心房后除极，P波形态由两者综合形成。窦房结除极和复极产生的电位极小，体表心电图不能记录。心房复极波埋入QRS波群中不易辨认。房室结除极亦不形成可见的体表波，故P波并非上述任何一项"},{"q":"在下列病变时，叩诊心界可发生如下改变，但应除外","o":["左心室增大，叩诊心界向左、向下扩大","右心室明显肥大，叩诊心界同时向两侧扩大，以向左侧扩大为主","心包积液，立位和卧位时，叩诊心界不一样","肺气肿，叩诊心浊音界变小","缩窄性心包炎，叩诊心浊音界叩不出"],"a":4,"e":"缩窄性心包炎时心包增厚粘连限制心室充盈，心浊音界多正常或轻度增大，并可出现Kussmaul征，并非叩不出。左心室增大心界向左下扩大。右心室明显肥大心界向两侧扩大且以左侧为主。心包积液时心界向两侧扩大并随体位改变。肺气肿因肺过度充气使心浊音界变小甚至叩不出"},{"q":"正常情况下血液在血管内流动而不发生凝固主要取决于","o":["血液中凝血物质＞抗凝物质","血液中凝血物质＜抗凝物质","血液中凝血物质和抗凝物质呈动态平衡","血管壁维持正常功能","血小板的作用"],"a":2,"e":"正常血液在血管内流动而不凝固，主要依赖机体止凝血与抗凝血机制间的动态平衡，血管壁、血小板、凝血因子、抗凝因子及纤溶系统相互制约。若凝血物质大于抗凝物质则形成血栓，反之则出现出血倾向，均非正常状态。单纯血管壁完整或血小板作用只是平衡中的一个环节，不能单独维持流动状态"},{"q":"呕血最常见的原因为","o":["急性胃黏膜病变","食管静脉曲张破裂","消化性溃疡","食管贲门黏膜撕裂","胃癌"],"a":2,"e":"呕血原因以消化性溃疡最常见，其次为食管或胃底静脉曲张破裂，再次为急性糜烂出血性胃炎和胃癌。急性胃黏膜病变即急性糜烂出血性胃炎，发生率低于溃疡。食管贲门黏膜撕裂多有剧烈呕吐诱因。胃癌多为少量持续出血。故消化性溃疡居首位"},{"q":"在第一心音听诊的特点中，应除外下列哪项","o":["音调低（55～58Hz）","强度较第二心音响","性质较第二心音清脆","心尖部听诊最清晰","与心尖冲动同时出现"],"a":2,"e":"第一心音音调低、时限较长，在心尖区最响，与心尖冲动同时出现，强度较第二心音为响。第二心音音调较高、时限较短、性质较清脆，在心底部较响。故性质较第二心音清脆并非第一心音特点，而是第二心音的特征，本题应排除该项"},{"q":"机体黏膜抗感染的主要抗体是","o":["IgG","sIgA","IgM","IgE","IgD"],"a":1,"e":"分泌型IgA由呼吸道、消化道、泌尿生殖道淋巴样组织合成，经分泌上皮细胞排入唾液、泪液、乳汁及鼻腔、支气管、胃肠道分泌液，是黏膜局部抗感染的主要抗体。IgG为血清中主要抗体并可通过胎盘。IgM为初次免疫应答早期抗体。IgE参与过敏反应，IgD多为B细胞表面受体"},{"q":"主诉的概念是","o":["最主要的症状、体征及疾病演变过程","最主要的症状及伴随症状","最主要的症状及主要诱因","最主要症状起病情况","最主要症状、体征及持续时间"],"a":4,"e":"主诉是患者感受最主要的痛苦或最明显的症状和/或体征及其持续时间，也是本次就诊最主要的原因，一般不超过20字。仅列主要症状及伴随症状或诱因均未包含持续时间。疾病演变过程属现病史内容。缺少持续时间的主诉不符合书写规范，必须同时具备症状、体征与时间要素"},{"q":"血氯降低最常见于","o":["严重呕吐，腹泻","心力衰竭","尿道梗阻","呼吸性碱中毒","急性肾功能不全"],"a":0,"e":"严重呕吐、腹泻使含氯的胃液和肠液大量丢失，是血清氯降低最常见的原因，常伴低钾及代谢性碱中毒。心力衰竭多因淤血和水肿稀释致血氯正常或偏低，但非最常见。尿道梗阻和急性肾功能不全常因排氯障碍使血氯升高。呼吸性碱中毒时血氯可轻度升高以代偿，不导致显著降低"},{"q":"常见误诊的原因，不包括","o":["查体不详细、不确切","以一元论为指导","完全依赖辅助检查","多做检查","照搬指南"],"a":1,"e":"以一元论为指导主张用一种疾病解释患者全部表现，是临床诊断思维的重要原则，有助于避免割裂病情，不属误诊原因。查体不详细、不确切会遗漏关键体征。完全依赖辅助检查忽视临床综合分析易致误诊。照搬指南不顾个体差异以及盲目多做检查缺乏针对性，均可导致诊断失误"},{"q":"患者嗜好烟酒茶等习惯属于","o":["主诉","家族史","既往史","个人史","现病史"],"a":3,"e":"个人史记录出生地、长期居留地、生活习惯及烟酒药物等嗜好、职业与毒物接触、冶游史等，嗜好烟酒茶属个人史。主诉为就诊主要症状及持续时间。家族史关注亲属遗传或传染性疾病。既往史记录既往疾病与治疗。现病史为本次疾病发生演变及诊疗经过，均不包括个人嗜好"},{"q":"凝血过程中起加速（催化）作用的因子是","o":["Ca2＋","FⅤ","FⅩ","FⅫ","FⅡa"],"a":4,"e":"凝血酶即活化因子Ⅱ，属丝氨酸蛋白酶，可催化纤维蛋白原转变为纤维蛋白，并激活因子Ⅴ、Ⅷ、Ⅺ及血小板，在凝血过程中起核心加速催化作用。钙离子参与多步反应的桥接但非酶。因子Ⅴ为辅因子。因子Ⅹ为共同途径关键酶但其激活依赖上游。因子Ⅻ为接触激活因子，催化作用均不及凝血酶广泛"},{"q":"下列心律失常不会伴有心悸症状的是","o":["偶发室性期前收缩","阵发性室上性心动过速","心房颤动","右束支传导阻滞","二度房室传导阻滞"],"a":3,"e":"右束支传导阻滞仅使心室激动传导顺序改变，并不引起心率、节律或心搏强度的明显变化，患者多无症状，一般不伴心悸。偶发室性期前收缩可有心脏停搏感。阵发性室上性心动过速心率骤增。心房颤动心律绝对不齐。二度房室传导阻滞有心室漏搏，均可产生心悸"},{"q":"引起非淋菌性尿道炎最常见的病原体是","o":["解脲支原体","沙眼衣原体","性病淋巴肉芽肿衣原体","杜克雷嗜血杆菌","白假丝酵母菌"],"a":1,"e":"非淋菌性尿道炎主要由沙眼衣原体和解脲脲原体引起，其中沙眼衣原体是最常见的病原体，为专性细胞内寄生，采用细胞培养或核酸检测。性病淋巴肉芽肿衣原体引起性病淋巴肉芽肿。杜克雷嗜血杆菌引起软下疳。白假丝酵母菌引起念珠菌感染，均非非淋菌性尿道炎的主要病原"},{"q":"血浆缓冲系统中缓冲能力最强的是","o":["NaHCO3/H2CO3","KHb/Hb","血浆蛋白质-Na/血浆蛋白质","NaHPO4/NaH2PO4","KHCO3/H2CO3"],"a":0,"e":"血浆缓冲系统中碳酸氢钠与碳酸构成的缓冲对缓冲能力最强，含量高且可通过肺肾调节，是维持血浆pH稳定的主要缓冲体系。血红蛋白缓冲对主要存在于红细胞内。血浆蛋白缓冲对和磷酸盐缓冲对缓冲能力较弱。碳酸氢钾与碳酸主要存在于细胞内液，并非血浆主要缓冲对"},{"q":"正常情况下肠鸣音次数是","o":["1～2次/min","2～3次/min","3～4次/min","4～5次/min","5～10次/min"],"a":3,"e":"正常肠鸣音约每分钟4～5次，以脐旁为听诊点，其频率音响和音调变异较大，餐后频繁明显、休息时稀疏微弱。肠蠕动增强致每分钟10次以上称肠鸣音活跃。1～2次或2～3次每分钟偏少。5～10次每分钟已接近活跃上限，均非正常次数的准确表述"},{"q":"用轻叩诊法确定脾脏上界正常在","o":["腋中线第9肋间～11肋间","腋中线第10肋间～12肋间","腋前线第9肋间～11肋间","腋后线第10肋间～12肋间","腋后线第9肋间～11肋间"],"a":0,"e":"脾脏浊音区叩诊宜用轻叩法，在左腋中线上进行，正常于第9～11肋间叩及，长度约4～7cm，前方不超过腋前线。腋前线位置偏前或腋后线偏后均非标准叩诊线。第10～12肋间位置过低，超出正常脾浊音区范围，不符合正常脾上界的叩诊定位"},{"q":"左侧面神经损伤的临床表现不包括","o":["左侧闭眼不紧","左侧面部痛觉减退","左侧额纹浅","左侧鼻唇沟浅","左侧鼓腮漏气"],"a":1,"e":"面神经支配面部表情肌，左侧损伤表现为左侧额纹变浅、闭眼不紧、鼻唇沟变浅及鼓腮漏气等面部下部表情肌瘫痪。面部痛觉由三叉神经传导，左侧面部痛觉减退属三叉神经损伤表现，不出现于单纯面神经损伤。其余各项均为面神经麻痹的典型体征"},{"q":"有关问诊的方法，错误的是","o":["一般从礼节性的交谈开始","先自我介绍，讲明自己的职责","尽可能让患者充分的陈述他认为重要的情况","不可生硬的打断患者的叙述","收集病史，必须严格按时间顺序收集"],"a":4,"e":"采集病史时不必严格按症状出现的先后次序逐一询问，可根据具体情况灵活提问，但获得的资料应能按时间顺序整理书写主诉和现病史。要求必须严格按时间顺序收集的说法与规范不符。问诊一般从礼节性交谈开始，先自我介绍，让患者充分陈述，不生硬打断，均为正确方法"},{"q":"若颈部包块弹性大又无全身症状，应考虑","o":["囊肿","非特异性淋巴结炎","囊状瘤","淋巴结结核","血液系统疾病"],"a":0,"e":"颈部包块弹性大且无全身症状，提示囊肿可能，多为良性囊性肿物，触之有弹性感，与周围组织分界清楚。非特异性淋巴结炎常有红肿热痛等急性炎症表现。囊状瘤圆形光滑、有囊样感且压迫可缩小。淋巴结结核质地较硬、可粘连破溃。血液系统疾病多为全身性无痛性淋巴结肿大，伴全身症状"},{"q":"问诊现病史时应遵循的原则是","o":["先由开放性问题开始，再进行特殊提问","先搞清复杂问题","多进行特殊的诱导提问","多进行逼问，以免遗漏信息","尽量使用医学术语"],"a":0,"e":"问诊现病史应先采用开放性问题，让患者像讲故事一样叙述病情，获得大量资料后再着重追问重点细节，即先开放后特殊。先搞清复杂问题违背由浅入深原则。特殊诱导提问和逼问易致信息失真或遗漏。尽量使用医学术语会使患者理解困难，均不符合问诊原则"},{"q":"下列是免疫性血小板减少性紫癜骨髓象，但应除外","o":["增生活跃或明显活跃","粒红二系无明显异常","巨核细胞明显减少，增生减低","幼核型或颗粒型巨核明显增多","产板型巨核细胞减少"],"a":2,"e":"免疫性血小板减少性紫癜骨髓象增生活跃或明显活跃，巨核细胞数量增多或正常伴成熟障碍，产板型巨核细胞减少，粒红两系无明显异常。巨核细胞明显减少、增生减低实为再生障碍性贫血的骨髓特征，与巨核细胞增生旺盛相反。幼核型与颗粒型巨核细胞增多正反映成熟受阻"},{"q":"关于窦性心律的心电图诊断，错误的是","o":["Ⅰ导联P波直立","Ⅱ导联P波直立","aVR导联P波直立","V5导联P波直立","V6导联P波直立"],"a":2,"e":"窦性心律的P波在Ⅰ、Ⅱ、aVF、V4～V6导联直立，aVR导联倒置，这是激动起源于窦房结、除极综合向量指向左前下的结果。aVR导联P波直立实为房性心律或冠状窦心律的表现，与窦性相反。其余各导联P波直立均符合窦性心律特点"},{"q":"用于评价小气道功能障碍的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":4,"e":"MEF50即用力呼气50%肺容量时的最大呼气流量，与FEF50%等同，是反映小气道阻塞的敏感指标，结合FEF75%、FEF25%～75%诊断价值更高。FEV1/FVC项实为大气道阻塞的通气指标，FEV1%pred反映总体通气功能，PEF主要反映大气道通畅度，FVC为肺容量指标"},{"q":"下列关于间接叩诊法的叙述，正确的是","o":["为了更好地分辨叩诊音，在每个部位叩诊时，每次均可叩4～5次","确定心脏和肝脏的相对浊音界，宜采取轻叩诊法","确定心脏和肝脏的绝对浊音界，宜采取重叩诊法","病灶位置距体表深达7cm左右，需使用中度叩诊法","确定肝上界时，应采取重叩诊法"],"a":1,"e":"心、肝相对浊音界范围较小且位置较浅，宜用轻叩诊法；绝对浊音界范围大且位置深，需用中等力量叩诊。每次叩诊以2～3下为宜，每次4～5次实为过多。病灶距体表约7cm时需用重叩诊，肝上界叩诊同样用轻叩诊，重叩诊法项与此不符"},{"q":"关于肝界叩诊下列各项均正确，但除外","o":["右肩胛线上第10肋间","右锁骨中线上第5肋间","右锁骨中线上肝上、下界为9～11cm","叩诊肝下界比触诊的肝下缘高1～2cm","右腋中线上为第8肋间"],"a":4,"e":"肝上界在右锁骨中线第5肋间、右腋中线第7肋间、右肩胛线第10肋间，肝上下径约9～11cm。叩诊肝下界因含气肠管干扰常比触诊肝下缘高1～2cm。右腋中线第8肋间实为肺下界的位置，并非肝界，故为错误项"},{"q":"下列关于过氧化物酶（POX）染色，正确的是","o":["急性粒细胞白血病，白血病细胞呈强阳性反应","急性单核细胞白血病，白血病细胞呈强阳性反应","急性淋巴细胞白血病，白血病细胞呈强阳性反应","急性粒细胞白血病，白血病细胞呈阴性反应","嗜碱性粒细胞为阳性"],"a":0,"e":"POX染色中急性粒细胞白血病细胞多呈阳性至强阳性，反映粒系原始细胞富含过氧化物酶。急性单核细胞白血病呈弱阳性或阴性，急性淋巴细胞白血病呈阴性，嗜碱性粒细胞也为阴性。强阳性仅见于粒系，是急粒与急淋、急单鉴别的关键"},{"q":"关于肝大的下列描述均正确，但除外","o":["急性肝炎时，肝轻度肿大，光滑，缘钝，有压痛","肝淤血时，肝明显肿大，光滑，缘钝，有压痛","脂肪肝时，肝大，质硬，光滑，有压痛","肝硬化早期，肝大，质硬，不光滑，无压痛","肝癌时，肝大，质坚硬，不光滑，有压痛"],"a":2,"e":"脂肪肝所致肝大表面光滑、质软或稍韧，且无压痛，这是其特点。急性肝炎与肝淤血均质韧有压痛，肝硬化早期质硬、无压痛，肝癌则质坚硬如石、压痛明显。脂肪肝项言质硬、有压痛，与脂肪肝质地软、无压痛的实际表现相悖"},{"q":"支气管呼吸音易见于","o":["肺气肿","胸腔积液","气胸","压迫性肺不张","胸膜粘连"],"a":3,"e":"压迫性肺不张时肺组织致密，有利于支气管音传导，故于胸腔积液区上方可闻及强度较弱、位置遥远的支气管呼吸音。肺气肿与气胸时肺含气过多或气体阻隔，呼吸音减弱或消失，胸膜粘连并不产生支气管呼吸音"},{"q":"下列疾病均可引起腹部揉面感，但除外","o":["结核性腹膜炎","癌性腹膜炎","异位妊娠","急性胃肠穿孔","肝癌肝破裂"],"a":3,"e":"揉面感又称柔韧感，因慢性炎症致腹膜增厚、肠管粘连而形成，见于结核性腹膜炎与癌性腹膜炎。急性胃肠穿孔时腹膜受强烈刺激，腹肌强直硬如木板，为板状腹而非揉面感。异位妊娠与肝癌破裂同属急腹症，以肌紧张为主要表现"},{"q":"下列情况中凝血时间延长，但应除外","o":["严重肝损害","纤维蛋白原严重减少","甲、乙、丙型血友病","原发性血小板减少","应用肝素等抗凝药"],"a":3,"e":"凝血时间反映内源性凝血途径，严重肝损害致凝血因子合成减少、纤维蛋白原严重减少、血友病因子缺乏及肝素抗凝均使其延长。原发性血小板减少项实为出血时间延长的典型原因，血小板数量减少并不影响凝血时间，故为除外项"},{"q":"二尖瓣关闭不全时，可有下列哪种杂音","o":["心尖部全收缩期杂音，并在吸气时增强","心尖部全收缩期杂音，并在呼气时增强","心尖部舒张期杂音，并在呼气时增强","心尖部第一心音亢进","常伴有肺动脉瓣相对关闭不全"],"a":1,"e":"二尖瓣关闭不全时左室收缩期血液反流至左房，产生心尖区粗糙的吹风样全收缩期杂音，向左腋下传导。呼气时肺循环血量减少、左心充盈增加，左心杂音增强。吸气时增强项实为三尖瓣关闭不全等右心杂音的特点，呼气时增强才是左心瓣膜病变"},{"q":"关于大叶肺炎，哪项不正确","o":["稽留热","呼吸急促","铁锈色痰","多见于老年人","可出现胸痛"],"a":3,"e":"大叶性肺炎病原体多为肺炎链球菌，好发于青壮年，受凉、疲劳为诱因，典型表现为稽留热、胸痛、呼吸急促与铁锈色痰。多见于老年人项与青壮年好发的事实不符，稽留热、铁锈色痰、胸痛均为其典型表现"},{"q":"引起S2固定分裂的是","o":["右束支传导阻滞","右心衰竭","左束支传导阻滞","房间隔缺损","二尖瓣狭窄"],"a":3,"e":"房间隔缺损时左房血液分流至右房，使右心血量增加、排血时间延长，肺动脉瓣关闭明显延迟，S2分裂不受呼吸影响而固定。右束支传导阻滞或左束支传导阻滞影响心室内传导，右心衰竭与二尖瓣狭窄多表现为P2亢进或通常分裂，均非固定分裂"},{"q":"心电图示RV1＋SV5为1.5mV，额面电轴为110°，最可能的诊断是","o":["左房肥大","右房肥大","左室肥大","右室肥大","右束支传导阻滞"],"a":3,"e":"RV1+SV5大于1.05mV且额面电轴右偏达110度，符合右心室肥大的心电图标准，重症者电轴可更偏。左室肥大项实为RV5+SV1大于4.0mV或3.5mV伴电轴左偏，右房肥大表现为P波高尖，均与本例不符"},{"q":"流行性出血热的常见症状体征是","o":["发热伴寒战","发热伴口角疱疹","发热伴肝脾肿大","发热伴出血","发热伴昏迷"],"a":3,"e":"流行性出血热由汉坦病毒引起，发热同时伴皮肤黏膜出血、充血与渗血，是发热伴出血的代表性疾病。发热伴肝脾肿大项见于传染性单核细胞增多症、疟疾等，发热伴寒战多见于大叶性肺炎、败血症，发热伴昏迷提示中枢神经系统感染"},{"q":"正常P波形态特点是大部分导联上","o":["呈正负双向","与QRS波主波方向不一致","有切迹呈双峰样","一般是钝圆形，有时可能有轻度切迹","呈高尖形"],"a":3,"e":"正常P波代表心房肌除极，在大部分导联呈钝圆形，有时可见轻度切迹，时限不超过0.12秒。呈高尖形项实为右房肥大的肺型P波，有切迹呈双峰样项见于左房肥大的二尖瓣型P波，正负双向多为部分导联的正常表现"},{"q":"免疫性血小板减少性紫癜可出现","o":["BT及PT都正常","BT延长，PT减少","BT延长，PT增多","BT延长，PT正常","BT正常，PT减少"],"a":1,"e":"免疫性血小板减少性紫癜因免疫性破坏致外周血小板显著减少，出血时间随之延长，这是血小板数量减少的直接后果。出血时间正常而血小板正常项见于过敏性紫癜等血管性紫癜，出血时间延长而血小板增多项见于血小板增多症，出血时间延长而血小板正常项见于血小板无力症等"},{"q":"下列关于第四心音（S4）叙述正确的是","o":["青年患者的正常所见","在心底部听诊最清楚","在收缩早期时可听到","心房收缩引起的震动","在房颤的患者中可听到"],"a":3,"e":"第四心音产生于舒张晚期，由心房收缩使房室瓣及其相关结构突然紧张、振动所致，属病理性，在心尖部及其内侧最清楚。青年患者的正常所见实为第三心音，第四心音在房颤患者中不会出现，因为房颤时心房失去协调收缩"},{"q":"关于头颈部姿势的描述，下列哪项是错误的","o":["正常人颈部伸屈、转动自如","头不能抬起见于多发性肌炎","斜颈可见于颈肌外伤","颈部强直见于蛛网膜下腔出血","先天性斜颈者，健侧胸锁乳突肌粗短"],"a":4,"e":"先天性斜颈系病侧胸锁乳突肌挛缩、粗短，致头向病侧倾斜，复正头位时病侧胸锁乳突肌胸骨端隆起。健侧胸锁乳突肌粗短项将病侧误作健侧，与体征相反。颈部强直见于蛛网膜下腔出血，头不能抬起见于多发性肌炎"},{"q":"最不可能出现肢体导联低电压的是","o":["大量心包积液","心脏淀粉样变性","扩张型心肌病","肺栓塞","肥胖"],"a":3,"e":"肢体导联低电压指QRS振幅过低，见于大量心包积液、黏液性水肿、肥胖等因液体或脂肪阻隔，以及心脏淀粉样变性、扩张型心肌病等心肌病变。肺栓塞项实为肺血管阻塞，主要引起右心负荷增加与电轴右偏，一般不导致肢体导联低电压"},{"q":"肝大常见于下列疾病，但除外","o":["肝炎","肝淤血","脂肪肝","早期肝硬化","肺气肿"],"a":4,"e":"肝炎、肝淤血、脂肪肝与早期肝硬化均可致肝大，分别伴压痛、肝颈静脉回流征阳性、质地软或硬等特征。肺气肿项实为肺过度充气，表现为胸廓桶状、肝浊音界下移，并不引起肝脏本身肿大，故为除外项"},{"q":"肠鸣音亢进不会出现在","o":["腹泻","急性肠炎","胃肠道大出血","服用泻剂","麻痹性肠梗阻"],"a":4,"e":"肠鸣音亢进见于腹泻、急性肠炎、消化道出血及服泻剂后，因肠蠕动增强；机械性肠梗阻时肠腔扩大、积气增多，呈金属音调。麻痹性肠梗阻时肠壁肌肉麻痹、蠕动消失，肠鸣音减弱或消失，与亢进相反，故为正确除外项"},{"q":"心源性水肿发病机制说法正确的是","o":["毛细血管通透性增高","淋巴液回流受阻","毛细血管滤过压升高","血浆胶体渗透压降低","组织液蛋白含量高"],"a":2,"e":"心源性水肿的核心是有效循环血量减少致肾血流量下降、继发性醛固酮增多引起钠水潴留，同时静脉压升高使毛细血管滤过压增高，组织液生成大于回流。血浆胶体渗透压降低项实为肾病性或营养不良性水肿机制，毛细血管通透性增高项见于炎症性水肿"},{"q":"腰椎间盘突出症患者、坐骨神经痛患者检查结果均阳性的试验是","o":["摇摆试验","拾物试验","直腿抬高试验","屈颈试验","股神经牵拉试验"],"a":2,"e":"直腿抬高试验阳性指抬高不足70度即出现下肢后侧放射性疼痛，因神经根受牵拉所致，见于腰椎间盘突出症，也可见于单纯性坐骨神经痛。拾物试验用于儿童脊柱结核，股神经牵拉试验检查股神经，屈颈试验和摇摆试验针对腰椎病变但非两者共有"},{"q":"哪些常规导联出现特征性心电图改变提示可能有左室后壁心肌梗死","o":["V1～V3导联Q波","V3、V4（V5）导联或Q波","Ⅰ、aVL、V5、V6导联或Q波","V1、V2导联出现R波增高、S-T段压低及T波增高","Ⅱ、Ⅲ、aVF导联或Q波"],"a":3,"e":"正后壁心肌梗死时V7、V8、V9导联记录到异常Q波，其对应导联V1、V2出现R波增高、ST段压低及T波增高的对应性改变。V1～V3导联Q波项提示前间壁梗死，Ⅱ、Ⅲ、aVF导联Q波项为下壁梗死，Ⅰ、aVL、V5、V6导联Q波项为侧壁梗死"},{"q":"下列各项均为腹部触诊注意事项，但除外","o":["一般采取半卧位，两腿对称稍屈曲","患者保持镇静，避免紧张","患者做缓慢腹式呼吸运动","检查肾脏可采取坐位或立位","检查脾脏时可左侧卧位"],"a":0,"e":"腹部触诊时病人应排尿后取低枕仰卧位，两腿屈起并稍分开，使腹肌松弛，并作缓慢腹式呼吸。半卧位并两腿对称稍屈曲项与低枕仰卧位的要求不符，实为错误的体位描述。检查肾脏可取坐位或立位，检查脾脏可取左侧卧位"},{"q":"以下哪项心电图表现不会出现在急性广泛前壁ST段抬高型心肌梗死的患者","o":["V1～V5导联T波高尖","V1～V4导联ST段弓背抬高","Ⅰ、avL导联ST段弓背抬高","Ⅱ、Ⅲ、avF导联ST段弓背抬高","V7～V9导联ST段压低"],"a":3,"e":"急性广泛前壁心肌梗死病变在前壁，心电图表现为V1～V5导联T波高尖、ST段弓背向上抬高，可波及Ⅰ、aVL，对应导联V7～V9出现ST段压低。Ⅱ、Ⅲ、aVF导联抬高项实为急性下壁心肌梗死的表现，不属于广泛前壁梗死"},{"q":"下列疾病均可有明显腹壁肌紧张，除外","o":["急性胃肠穿孔","坏死性胰腺炎","急性胆囊炎","阑尾炎穿孔","慢性盆腔炎症"],"a":4,"e":"急性胃肠穿孔、坏死性胰腺炎、急性胆囊炎与阑尾炎穿孔均可刺激腹膜引起明显肌紧张，甚至板状腹。慢性盆腔炎症项因盆腔脏器炎症刺激缓和且腹壁肌受累不明显，一般不引起明显腹壁紧张，故为除外项"},{"q":"下述为检查腹部反跳痛的方法，但不包括","o":["以一两个手指逐渐深压腹部病变部位","在深压触诊的基础上迅速将手抬起","在深压触诊的基础上缓慢将手抬起","抬手同时询问患者是否感觉疼痛加重","抬手同时要观察患者的面部表情"],"a":2,"e":"检查反跳痛时以两三个手指逐渐深压腹部病变部位，使腹壁下陷，稍停片刻后迅速将手抬起，同时询问疼痛是否加重并观察面部表情。缓慢将手抬起项与迅速抬手的操作要求相反，无法引出反跳痛，故为不包括项"},{"q":"关于肥胖的测量，下列说法正确的是","o":["超过标准体重的10%为肥胖","BMI＝25是正常体重","BMI＝30是肥胖","BMI＝20是偏瘦","女性腰围≥90cm为肥胖"],"a":2,"e":"按世界卫生组织标准，体重指数达30为肥胖，我国标准则为28。超过标准体重10%项实为超重的旧标准，肥胖应为超过20%；体重指数25项属超重，体重指数20项在正常范围，女性腰围90cm项超出中心性肥胖的女性界值"},{"q":"维生素K缺乏导致皮肤黏膜出血的机制是","o":["毛细血管壁通透性增加","血小板聚集功能异常","血小板数量异常","肝脏产生的凝血酶原等减少","ATⅢ缺陷"],"a":3,"e":"维生素K是肝脏合成凝血因子Ⅱ即凝血酶原、Ⅶ、Ⅸ、Ⅹ所必需的辅因子，参与其羧化，缺乏时这些因子合成减少而致出血。毛细血管壁通透性增加项见于过敏性紫癜，血小板数量或聚集异常项与维生素K的作用无关"},{"q":"Ca2＋是凝血因子中的","o":["Ⅲ因子","Ⅳ因子","Ⅴ因子","Ⅷ因子","Ⅹ因子"],"a":1,"e":"凝血因子按罗马数字编号，Ⅳ因子即钙离子，参与凝血瀑布中多个步骤，是内源性与外源性凝血途径所必需。Ⅲ因子实为组织因子，Ⅴ因子为易变因子，Ⅷ因子为抗血友病因子，Ⅹ因子为Stuart因子，均非钙离子"},{"q":"在胸骨左缘第2肋间触到一连续性震颤，最常见于","o":["法洛四联症","动脉导管未闭","室间隔缺损","房间隔缺损","右位心"],"a":1,"e":"动脉导管未闭时主动脉与肺动脉之间存在持续性分流，在胸骨左缘第2肋间产生连续性机器样杂音并伴连续性震颤。室间隔缺损项实为胸骨左缘第3～4肋间收缩期震颤，房间隔缺损杂音多在胸骨左缘第2肋间收缩期，法洛四联症以发绀为主"},{"q":"脾大测量结果记录为-2cm，测量的线是在","o":["甲乙线","甲丙线","丁戊线","锁骨中线","腋中线"],"a":2,"e":"脾大测量中丁戊线指脾右缘至前正中线的最短距离，超过前正中线时以负值表示，记录负2cm即为此线。甲乙线测量左锁骨中线与肋缘交点至脾下缘，甲丙线测量至脾最远点，两者均用正值记录脾大程度"},{"q":"下列哪种情况肺泡呼吸音增强","o":["发绀","胸痛","重症肌无力","肺实变早期","胸腔积液"],"a":3,"e":"肺实变早期即大叶性肺炎充血期，肺组织充血，呼吸运动代偿性增强，可闻及肺泡呼吸音增强，随实变加重转为支气管呼吸音。胸痛与重症肌无力项因呼吸受限或呼吸肌无力使肺泡呼吸音减弱，胸腔积液项因液体阻隔致呼吸音减低或消失"},{"q":"右室心肌梗死ST段抬高出现在下列哪些导联","o":["V1，V2，V3导联","V3，V4，V5导联","V3R，V4R，V5R导联","V7，V8，V9导联","Ⅰ，aVL导联"],"a":2,"e":"诊断右心室心肌梗死需加作右胸导联V3R～V5R，急性下壁梗死时若这些导联ST段抬高即提示合并右室梗死。V1～V3项为前间壁导联，V7～V9项为后壁导联，Ⅰ、aVL项为高侧壁导联，均不能直接反映右室"},{"q":"FEV1 81%，FVC 75%，FEV1/FVC 90%，TLC 75%，DLCO 80%。肺功能诊断为","o":["阻塞性通气功能障碍","限制性通气功能障碍","混合性通气功能障碍","孤立性弥散功能减低","限制性通气功能障碍伴弥散功能减低"],"a":1,"e":"本例第一秒用力呼气容积与用力肺活量之比为90%且正常偏高，而用力肺活量与肺总量均降至75%，一氧化碳弥散量正常，符合限制性通气功能障碍以肺容量减少为主、流速比值正常或增高的特点。阻塞性项实为该比值显著降低，混合性项两者皆降，孤立性弥散减低项应有弥散量下降"},{"q":"关于心源性水肿机制，错误的是","o":["有效循环血量减少","肾血流量减少","低蛋白血症","继发性醛固酮增多","静脉压增高"],"a":2,"e":"心源性水肿源于有效循环血量减少、肾血流量下降、继发性醛固酮增多及静脉压升高，属钠水潴留与毛细血管压升高。低蛋白血症项实为营养不良性或肾病性水肿的主要机制，并非心源性水肿的原因，其余各项均为心源性水肿环节"},{"q":"湿啰音如发生在两肺底，多见于","o":["肺脓肿","支气管炎","肺结核","左心功能不全","大叶性肺炎"],"a":3,"e":"左心功能不全致肺淤血、肺水肿，液体渗入肺泡，两肺底出现湿啰音，常伴端坐呼吸与粉红色泡沫痰。肺脓肿项多为局限性湿啰音伴脓痰，大叶性肺炎项湿啰音局限于实变区，肺结核项多在上肺，均非两肺底弥漫性湿啰音"},{"q":"下列疾病中S1减弱的是","o":["二尖瓣狭窄","大面积心肌梗死","严重贫血","运动员运动后","甲状腺功能亢进"],"a":1,"e":"第一心音强度取决于心室收缩时室内压上升速率与瓣膜位置，大面积心肌梗死致心肌收缩力减弱，第一心音减弱。二尖瓣狭窄项因左室充盈减少、瓣膜位置低垂而第一心音亢进，严重贫血、甲亢及运动员运动后均因心肌收缩增强使第一心音增强"},{"q":"腹部听到连续性血管杂音，常见的病征是","o":["动脉瘤","动脉狭窄","腹壁静脉严重曲张","腹块压迫腹主动脉","肝癌压迫肝动脉"],"a":2,"e":"门静脉高压致腹壁静脉曲张时，脐周可闻及连续性静脉营营声，即Cruveilhier-Baumgarten综合征，属连续性杂音。动脉瘤项与动脉狭窄项均为收缩期杂音，肝癌压迫肝动脉项亦为收缩期杂音，均非连续性"},{"q":"下列各项均为腹部听诊内容，但除外","o":["肠鸣音","血管杂音","摩擦音","搔弹音","振水音"],"a":4,"e":"腹部听诊主要包括肠鸣音、血管杂音、摩擦音与搔弹音。振水音系胃内液体与气体撞击产生，多用冲击触诊法或空腹听诊判断幽门梗阻，通常归为叩诊或特殊检查，不列入常规腹部听诊内容，故为除外项"},{"q":"下列关于右心衰竭发生呼吸困难机制的叙述均正确，但除外","o":["右心房压升高，反射性兴奋呼吸中枢","上腔静脉压升高，反射兴奋呼吸中枢","肺循环压力升高，反射兴奋呼吸中枢","血氧含量减少，刺激呼吸中枢","淤血性肝大、胸腔积液等使呼吸受限"],"a":2,"e":"右心衰竭呼吸困难源于体循环淤血，表现为右房与上腔静脉压升高反射性兴奋呼吸中枢、血氧含量减少刺激呼吸中枢，以及淤血性肝大与胸腹水限制呼吸。肺循环压力升高项实为左心衰竭肺淤血的机制，与右心衰竭无关"},{"q":"红细胞大小不均在何种情况下最明显","o":["再生障碍性贫血","地中海贫血","溶血性贫血","失血性贫血","巨幼细胞贫血"],"a":4,"e":"红细胞大小不均指直径相差一倍以上，巨幼细胞贫血因DNA合成障碍致红细胞大小悬殊最为明显。再生障碍性贫血红细胞形态大致正常，地中海贫血以小细胞为主，溶血性贫血与失血性贫血可见一定程度大小不均，但均不及巨幼细胞贫血"},{"q":"下列哪项诊断门脉性肝硬化最可靠","o":["腹水","脾大","肝掌及蜘蛛痣","白蛋白/球蛋白倒置","肝穿刺活检有假小叶形成"],"a":4,"e":"假小叶形成是肝硬化的特征性病理改变，肝穿刺活检见假小叶可确诊门脉性肝硬化。腹水与脾大仅为门脉高压表现，肝掌、蜘蛛痣为肝功能减退体征，白蛋白与球蛋白比例倒置反映肝脏合成功能下降，均不能作为确诊依据"},{"q":"蜘蛛痣的发生与下列哪一因素有关","o":["雄激素增高","雄激素减少","甲状腺激素增高","雌激素减少","雌激素增高"],"a":4,"e":"蜘蛛痣的形成与肝脏对雌激素的灭活作用减弱有关，体内雌激素增高致小动脉末端扩张，常见于急慢性肝炎与肝硬化。雄激素增高项与蜘蛛痣无关，雌激素减少项方向相反，甲状腺激素增高项也不参与其形成"},{"q":"二尖瓣关闭不全时，最主要的体征是","o":["心尖冲动向左下移位","心尖冲动呈抬举性","肺动脉瓣区第二心音亢进分裂","心尖区收缩期吹风样杂音，粗糙，3/6级以上","心界向左下扩大"],"a":3,"e":"二尖瓣关闭不全最主要的体征是心尖区响亮粗糙、音调较高的三级以上全收缩期吹风样杂音，向左腋下与左肩胛下区传导。心尖冲动向左下移位与心界向左下扩大为左室增大表现，肺动脉瓣区第二心音亢进分裂提示肺动脉高压，均非最主要体征"},{"q":"下列是肺部叩诊呈浊音时正确的描述，但应除外","o":["与清音相反","叩诊音较长","高调而不响亮","叩诊时板指下的振动感较少","可见于肺部含气量减少"],"a":1,"e":"浊音的物理特点为音调较高、音响较弱、叩诊音较短，板指下振动感较少，见于肺部含气量减少如肺炎、肺不张。叩诊音较长实为清音的特点，与浊音相反，故为错误描述；高调不响亮与振动感少均符合浊音"},{"q":"梅尼埃病的临床特点不包括","o":["恶心、呕吐","眩晕","眼球震颤","听力减退","鼓膜穿孔"],"a":4,"e":"梅尼埃病因内耳膜迷路积水，以发作性眩晕、耳鸣、波动性听力减退为主，可伴恶心呕吐与眼球震颤。鼓膜穿孔项实为迷路炎或中耳炎的体征，梅尼埃病鼓膜完整，听力减退、眩晕、恶心呕吐、眼震均属其常见表现"},{"q":"最易引起S1增强的疾病是","o":["主动脉瓣关闭不全","二尖瓣关闭不全","二尖瓣狭窄","原发性高血压","主动脉瓣狭窄"],"a":2,"e":"二尖瓣狭窄时左室充盈减慢减少，收缩开始时二尖瓣位置低垂，室内压上升加速使瓣膜关闭振幅增大，第一心音亢进。主动脉瓣关闭不全项因左室容量负荷增加使二尖瓣位置较高而第一心音减弱，二尖瓣关闭不全项第一心音亦减弱，高血压项无特异增强"},{"q":"下列各项是心包积液的体征，但应除外","o":["心包叩击音","奇脉","颈静脉Kussmaul征","Ewart征","枪击音"],"a":4,"e":"大量心包积液可出现心包叩击音、奇脉、颈静脉怒张与Kussmaul征，左肺受压时产生Ewart征。枪击音项实为主动脉瓣关闭不全等周围血管征，于股动脉处闻及，与心包积液无关，故为除外项"},{"q":"小量咯血是指每日咯血量","o":["＜50ml","＜100ml","＜200ml","＜300ml","＜500ml"],"a":1,"e":"咯血量划分以每日100ml与500ml为界，每日100ml以内为小量咯血，100～500ml为中等量，500ml以上或一次100～500ml为大量。小量咯血常见于肺结核、支气管扩张等的早期或痰中带血"},{"q":"下列贫血属于小细胞低色素性贫血的是","o":["尿毒症所致贫血","恶性肿瘤所致贫血","缺铁性贫血","再生障碍性贫血","溶血性贫血"],"a":2,"e":"缺铁性贫血时血红蛋白合成不足，红细胞体积偏小、中央淡染区扩大，呈典型小细胞低色素性。再生障碍性贫血与尿毒症、恶性肿瘤所致贫血为正细胞正色素性，溶血性贫血多为正细胞性或大细胞性，均非小细胞低色素"},{"q":"上腹部听到振水音时可见于","o":["胃溃疡","胃扩张","急性胃炎","慢性胃炎","十二指肠球部溃疡"],"a":1,"e":"清晨空腹或餐后6～8小时以上仍闻及上腹振水音，提示胃内有液体与气体潴留，见于幽门梗阻或胃扩张。胃溃疡、急慢性胃炎与十二指肠球部溃疡一般不引起胃排空障碍与大量潴留，故不会出现持续性振水音"},{"q":"下列是支气管哮喘体征，哪项不正确","o":["胸廓呈吸气位","两肺叩诊过清音","两肺布满干鸣","呈混合性呼吸困难","呼吸动度变小"],"a":3,"e":"支气管哮喘因下呼吸道阻塞、呼气不畅，表现为呼气性呼吸困难，伴胸廓吸气位、两肺过清音与布满干鸣、呼吸动度变小。混合性呼吸困难吸气与呼气均费力，实为肺或胸膜病变使呼吸面积减少所致，如肺炎、胸腔积液，非哮喘特点"},{"q":"水肿伴体重减轻、消瘦者最可能是","o":["肝源性水肿","心源性水肿","营养不良性水肿","肾源性水肿","特发性水肿"],"a":2,"e":"营养不良性水肿因长期营养缺乏或慢性消耗致低蛋白血症，同时伴体重下降与消瘦。心源性水肿伴颈静脉怒张与呼吸困难，肾源性水肿伴蛋白尿，肝源性水肿伴腹水与肝掌，特发性水肿无消瘦，均不符合"},{"q":"引起吸收热的为","o":["急性溶血反应","结缔组织病","甲亢","心力衰竭","中暑"],"a":0,"e":"吸收热因无菌性坏死组织或红细胞破坏产物被吸收所致，急性溶血反应与输血反应、大面积烧伤、术后组织吸收均可引起。结缔组织病属免疫性发热，甲亢为产热增多，心衰为淤血性发热，中暑为体温调节障碍，均非吸收热"},{"q":"主动脉瓣关闭不全，出现周围血管征的原因是","o":["外周动脉硬化","回心血量增加","心输出量增大","收缩压增高、舒张压下降","中小动脉弹性增加"],"a":3,"e":"主动脉瓣关闭不全时舒张期血液反流，舒张压显著降低、脉压增大，形成水冲脉、枪击音、毛细血管搏动等周围血管征。外周动脉硬化项影响血管弹性，心输出量增大项与回心血量增加项不直接造成脉压显著增大，中小动脉弹性增加项与实际相反"},{"q":"肺动脉瓣第二心音（P2）减弱见于","o":["二尖瓣狭窄","肺动脉瓣狭窄","二尖瓣关闭不全","房间隔缺损","左心衰竭"],"a":1,"e":"肺动脉瓣狭窄时肺循环血流减少、半月瓣活动受限，肺动脉瓣第二心音减弱。二尖瓣狭窄、房间隔缺损与左心衰竭均致肺动脉高压或肺血增多，第二心音肺动脉瓣部分亢进；第二心音固定分裂见于房间隔缺损，这些病变都不会使其减弱"},{"q":"急性胰腺炎患者呕吐后腹痛常可","o":["减轻","缓解","加重","消失","无变化"],"a":4,"e":"急性胰腺炎因胰酶激活致胰腺自身炎症与腹膜刺激，腹痛持续而剧烈，呕吐后并不减轻，这是其与幽门梗阻等呕吐后腹痛缓解疾病的鉴别要点。减轻、缓解、消失项不符合胰腺炎腹痛持续的特征，腹痛无变化才是正确描述"},{"q":"玫瑰花结形成试验测值降低见于","o":["免疫缺陷性疾病","甲状腺功能亢进","甲状腺炎","重症肌无力","慢性活动性肝炎"],"a":0,"e":"红细胞玫瑰花结形成试验反映T细胞数量与功能，降低见于免疫缺陷性疾病、恶性肿瘤、某些病毒感染及大面积烧伤。甲状腺功能亢进、甲状腺炎、重症肌无力与慢性活动性肝炎项均为该试验升高所见，与降低方向相反"},{"q":"急性阑尾炎临床症状发生的顺序一般是","o":["先恶心后低热，再右下腹疼痛","先低热几小时后右下腹痛，呕吐","先呕吐，随即发热，腹痛","先上腹或脐周痛，继之恶心或呕吐，再右下腹痛","没有明确的顺序"],"a":3,"e":"急性阑尾炎腹痛始于中上腹或脐周，为内脏神经痛，数小时后炎症波及腹膜壁层，转为定位清楚的右下腹痛，即转移性右下腹痛，并伴恶心呕吐与轻度发热。先呕吐后发热腹痛项及先低热项均不符合这一典型顺序"},{"q":"下列疾病中通过骨髓检查可确诊的是","o":["缺铁性贫血","急性白血病","淋巴瘤","原发免疫性血小板减少症","溶血性贫血"],"a":1,"e":"急性白血病骨髓中原始与幼稚细胞大量增生，骨髓检查结合细胞化学染色可明确诊断与分型。缺铁性贫血靠铁代谢与血象，免疫性血小板减少症骨髓巨核细胞增多仅作排除，淋巴瘤需淋巴结活检，溶血性贫血依靠溶血实验室证据，均非骨髓确诊"},{"q":"成人清晨安静状态下的舌下温度正常范围是","o":["36～37℃","36.3～37.2℃","36.6～37.7℃","36.2～37.3℃","36.5～37.7℃"],"a":1,"e":"口测法即舌下测温正常值为36.3～37.2℃，测量准确但不适用于婴幼儿及神志不清者。36～37℃实为腋测法正常值，36.5～37.7℃为肛测法正常值，肛测法一般较口测法高0.2～0.5℃"},{"q":"在正常骨髓抽吸中发现的最大的细胞是","o":["成骨细胞","巨核细胞","成髓细胞","原红细胞","晚幼粒细胞"],"a":1,"e":"巨核细胞是正常骨髓中体积最大的细胞，直径可达数十微米，胞质丰富并裂解为血小板。成骨细胞、成髓细胞、原红细胞与晚幼粒细胞体积均远小于巨核细胞，巨核细胞裸核虽体积较大仍属巨核细胞系列"},{"q":"外周血中白细胞的组成主要的细胞是","o":["中性粒细胞","淋巴细胞","单核细胞","嗜酸性粒细胞","嗜碱性粒细胞"],"a":0,"e":"中性粒细胞占外周血白细胞总数的50%～70%，是数量最多的白细胞，也是急性炎症与细菌感染的主要反应细胞。淋巴细胞约占20%～40%，单核细胞、嗜酸性粒细胞与嗜碱性粒细胞所占比例均明显更低"},{"q":"临床诊断中，实践循证医学的基本步骤不包括下列哪一项","o":["临床问题的提出与构建","检索相关研究证据","进行诊断试验","诊断性试验证据的评价与应用","后效评价"],"a":2,"e":"实践循证医学的基本步骤包括提出并构建临床问题、检索相关研究证据、严格评价证据、应用证据及后效评价。进行诊断试验项实为临床诊疗中的具体检查行为，并非循证医学的方法学步骤，故为不包括项"},{"q":"在主动脉瓣及二尖瓣听诊区均听到舒张期杂音的患者，下列哪项检查结果可以明确该患者为单纯的主动脉瓣病变","o":["X线检查无左室增大","心电图检查示左室肥厚","主动脉影增宽","心脏彩超无左房扩大","第一心音不亢进"],"a":3,"e":"主动脉瓣关闭不全可在心尖区产生Austin Flint杂音，与二尖瓣狭窄的舒张期杂音相似，但前者无左房扩大，影像呈主动脉型、以左室增大为主。心脏彩超显示无左房扩大可明确排除二尖瓣狭窄，从而确定为单纯主动脉瓣病变"},{"q":"外致热原引起发热主要是","o":["激活局部的血管内皮细胞，释放致炎物质","刺激局部的神经末梢，释放神经介质","直接作用于下丘脑的体温调节中枢","激活产EP细胞导致内生致热原的产生和释放","加速分解代谢，产热增加"],"a":3,"e":"外源性致热原多为大分子物质，不能通过血脑屏障直接作用于体温调节中枢，而是激活中性粒细胞、单核巨噬细胞等产内生致热原细胞，使其产生并释放内源性致热原。直接作用于下丘脑项实为内源性致热原的作用方式，与外源性无关"},{"q":"听诊能发现的心律失常最常见于","o":["室上性心动过速","窦性心动过速","室性心动过速","心房颤动","一度房室传导阻滞"],"a":3,"e":"心房颤动听诊有三大特征：心音强弱不等、心律绝对不规则、脉搏短绌，据此即可临床诊断，是听诊可发现的最常见心律失常。室上性心动过速、室性心动过速多需心电图确认，一度房室传导阻滞无心脏听诊特异改变"},{"q":"正常成年人静息状态下呼吸频率为","o":["14～18次/min","12～20次/min","16～18次/min","16～20次/min","18～22次/min"],"a":1,"e":"正常成人静息状态下呼吸频率为12～20次/分，呼吸与脉搏之比约为1∶4，节律均匀。16～20次/分或14～18次/分等范围均非教材采用的标准区间，18～22次/分上限超过正常，故不正确"},{"q":"以下哪项属于T细胞膜分子","o":["CD20","CD40","CD8","CD80","CD22"],"a":2,"e":"CD8是细胞毒性T细胞的表面标志，与CD3、CD4同属T细胞分化抗原。CD20与CD22项是B细胞表面标志，CD40与CD80项主要表达于抗原提呈细胞及活化B细胞，均非T细胞特异分子"},{"q":"暂时性尿失禁常见于下列疾患，除了","o":["尿路感染","前列腺增生","急性精神错乱性疾病","药物反应","心理性忧郁症"],"a":1,"e":"暂时性尿失禁见于尿路感染、急性精神错乱性疾病、药物反应与心理性忧郁症，去除诱因后可恢复。前列腺增生项实为长期性尿失禁的原因，引起慢性尿潴留与充盈性尿失禁；脑卒中、痴呆所致者亦属长期性，均不属于暂时性"},{"q":"血清铁降低而总铁结合力增高，提示","o":["再生障碍性贫血","溶血性贫血","缺铁性贫血","铁粒幼细胞贫血","慢性感染性贫血"],"a":2,"e":"缺铁性贫血时体内铁缺乏，血清铁下降，肝脏代偿性合成转铁蛋白增加使总铁结合力升高，转铁蛋白饱和度降低。铁粒幼细胞贫血项血清铁增高，慢性感染性贫血项总铁结合力降低，溶血性贫血与再生障碍性贫血血清铁多正常或增高"},{"q":"叹气样呼吸见于","o":["喉炎","左心衰竭","右心衰竭","肺气肿","癔症"],"a":4,"e":"叹气样呼吸表现为间发性深大呼吸伴叹息声，多见于焦虑症、癔症等精神性呼吸困难，因过度通气可致呼吸性碱中毒。喉炎项表现为吸气性呼吸困难，左心衰竭项为心源性呼吸困难，肺气肿项为呼气性呼吸困难"},{"q":"血浆阴离子间隙（AG）指","o":["血浆阳离子减去阴离子","血浆阴离子减去阳离子","血浆阴离子总和","血浆[Cl－]与[HCO3－]之和减去[Na＋]","血浆[Na＋]减去[Cl－]与[HCO3－]之和"],"a":4,"e":"阴离子间隙指血浆中未测定阴离子与未测定阳离子的差值，计算公式为钠离子减去氯离子与碳酸氢根之和，正常8～16mmol/L，用于判断代谢性酸中毒类型。血浆阳离子减去阴离子项及阴离子总和项均未体现未测定离子的差值本质"},{"q":"以下哪项是B细胞的表面标志","o":["CD28","CD19","CD4","CD8","CD2"],"a":1,"e":"CD19是B细胞特异的表面分化抗原，与CD20、CD21、CD22同为B细胞检测标志。CD4与CD8项是T细胞亚群标志，CD2为T细胞标志，CD28为T细胞共刺激分子，均不属于B细胞"},{"q":"红细胞染色反应为低色素性，不见于","o":["缺铁性贫血","地中海贫血","铁粒幼细胞贫血","巨幼细胞贫血","某些血红蛋白病"],"a":3,"e":"低色素性指红细胞中央淡染区扩大、血红蛋白含量降低，见于缺铁性贫血、地中海贫血、铁粒幼细胞贫血及某些血红蛋白病。巨幼细胞贫血项实为大细胞高色素性，中央淡染区消失，故不属于低色素性贫血"},{"q":"肾在维持酸碱平衡中最主要的作用是","o":["直接排出酮体","排H＋保Na＋","重吸收HCO3－以恢复血中HCO3－浓度","对付气化酸","排出铵盐"],"a":2,"e":"肾通过排氢离子、重吸收碳酸氢根及排铵盐调节酸碱平衡，其中重吸收碳酸氢根以恢复并维持血中浓度是最主要的作用。直接排出酮体项与对付气化酸项并非肾脏主要机制，排氢保钠与排铵盐是排酸途径，服务于碳酸氢根的保存"},{"q":"不符合心肌缺血心电图改变的是","o":["ST段弓背向上抬高","T波高耸呈帐篷型改变","ST段水平型下移","ST段下垂型下移","T波倒置呈冠状T"],"a":1,"e":"心肌缺血的心电图改变包括T波低平、双向、倒置呈冠状T，以及ST段水平型或下垂型压低、损伤型ST段弓背向上抬高。T波高耸呈帐篷型项实为高钾血症的典型表现，不是心肌缺血改变，故为不符合项"},{"q":"大叶肺炎典型患者咳何种痰","o":["黄痰","白色泡沫痰","铁锈色痰","胶冻状痰","暗红色黏稠血痰"],"a":2,"e":"大叶性肺炎多由肺炎链球菌引起，实变期红细胞渗入肺泡并被巨噬细胞吞噬，形成含铁血黄素，咳出铁锈色痰，是其特征。黄痰提示化脓性感染，白色泡沫痰多见于慢性支气管炎，胶冻状痰见于克雷伯菌肺炎，暗红色黏稠血痰不见于大叶肺炎"},{"q":"呼吸性酸中毒时血浆PaCO2为","o":["40mmHg","45mmHg","35mmHg","20mmHg","＞80mmHg"],"a":1,"e":"动脉血二氧化碳分压正常为35～45mmHg，平均值40mmHg；超过45mmHg提示呼吸性酸中毒，低于35mmHg提示呼吸性碱中毒。本题以45mmHg为呼吸性酸中毒的判断界值，35mmHg项属呼碱方向，20mmHg项更低，均不符合"},{"q":"下列疾病均可出现肠鸣音亢进，但除外","o":["肠梗阻","低血钾","胃肠炎","消化道出血","服泻剂后"],"a":1,"e":"肠梗阻、胃肠炎、消化道出血及服泻剂后肠蠕动增强，均可出现肠鸣音亢进，机械性肠梗阻因肠腔扩大、积气增多而呈金属音调。低血钾项实为肠鸣音减弱的原因，因肠壁肌肉兴奋性下降、蠕动减弱，故为除外项"},{"q":"镜下血尿是指尿液离心沉淀后镜检结果显示红细胞","o":["＞3个/HPF","＞5个/HPF","＞2个/HPF","＞10个/HPF","＞8个/HPF"],"a":0,"e":"镜下血尿指尿色正常而离心沉淀后镜检每高倍视野红细胞超过3个，肉眼血尿则为尿呈洗肉水色或血色。玻片法红细胞0～2个每高倍视野、定量0～5个每微升为正常范围，其余5个、10个等界值均非镜下血尿的诊断标准"},{"q":"请问以下哪个凝血因子不存在于血浆中","o":["Ⅰ因子","Ⅱ因子","Ⅲ因子","Ⅳ因子","Ⅴ因子"],"a":2,"e":"Ⅲ因子即组织因子，存在于血管外组织细胞表面，与Ⅶ因子结合启动外源性凝血途径，正常血浆中并不存在。Ⅰ因子为纤维蛋白原、Ⅱ因子为凝血酶原、Ⅴ因子为易变因子，Ⅳ因子即钙离子，这四者均为血浆内的凝血因子，参与凝血瀑布反应"},{"q":"心脏听诊能确定诊断的心律失常是","o":["室性期前收缩","房性期前收缩","心房颤动","窦性心动过速","窦性心动过缓"],"a":2,"e":"心房颤动听诊表现为心音强弱绝对不等、心律绝对不规则、脉搏短绌，三者具备即可确定诊断。室性与房性期前收缩听诊可提示但确诊依赖心电图，窦性心动过速与窦性心动过缓仅为心率改变，听诊不能定性诊断"},{"q":"二度Ⅰ型房室传导阻滞，文氏现象的心电图特征是","o":["P-R间期进行性缩短","R-R间距进行性缩短","固定的房室3∶1传导","P-R间期进行性延长，伴QRS波脱漏","P-R间期进行性延长"],"a":3,"e":"二度Ⅰ型房室传导阻滞的文氏现象表现为P-R间期逐次延长，直至一个P波下传受阻、QRS波脱漏，漏搏后P-R间期又缩短，周而复始，同时R-R间距进行性缩短。固定3∶1传导项实为二度Ⅱ型的特点，P-R间期缩短项与文氏现象相反"},{"q":"分泌性腹泻可见于下列疾病，但除外","o":["慢性肠炎","霍乱","血管活性肽瘤","胃泌素瘤","小肠吸收不良综合征"],"a":4,"e":"分泌性腹泻由肠黏膜分泌过多液体所致，见于霍乱毒素、血管活性肽瘤与胃泌素瘤，慢性肠炎亦有分泌因素。小肠吸收不良综合征项实为渗透性或脂肪泻，因营养物质吸收障碍致肠腔渗透压升高，不属于分泌性腹泻"},{"q":"因为电延迟造成第一心音分裂的是","o":["右心衰竭","右束支传导阻滞","肺动脉高压","肺源性心脏病","Ebstein畸形"],"a":1,"e":"第一心音分裂因三尖瓣关闭明显迟于二尖瓣，电活动延迟见于完全性右束支传导阻滞，使右室激动与收缩延后。肺动脉高压、肺源性心脏病与Ebstein畸形项属机械活动延迟或瓣膜因素，右心衰竭不产生电延迟性第一心音分裂"},{"q":"正常脑脊液蛋白电泳含量最高的是","o":["α1球蛋白","α2球蛋白","β球蛋白","γ球蛋白","白蛋白"],"a":4,"e":"正常脑脊液蛋白电泳中白蛋白分子质量小、带负电荷多、泳动快，含量最高，约占一半以上。α1、α2、β与γ球蛋白含量均低于白蛋白，其中γ球蛋白泳动最慢；脑组织感染时先有白蛋白增高，随后球蛋白才增高，故γ球蛋白增高提示中枢免疫性或感染性病变"},{"q":"某患者复钙试验延长，吸附血浆能纠正，贮存血清不能纠正，最可能的诊断是","o":["因子Ⅵ缺乏","因子Ⅶ缺乏","因子Ⅷ缺乏","因子Ⅸ缺乏","因子Ⅹ缺乏"],"a":2,"e":"吸附血浆含因子Ⅷ、Ⅴ及纤维蛋白原，不含Ⅱ、Ⅶ、Ⅸ、Ⅹ；贮存血清含Ⅱ、Ⅶ、Ⅸ、Ⅹ而不含Ⅷ、Ⅴ。吸附血浆能纠正而贮存血清不能，说明缺乏的是因子Ⅷ。因子Ⅸ、Ⅹ、Ⅶ项存在于贮存血清中，应能被纠正，与此不符"},{"q":"对痛风性关节炎描述错误的是","o":["常因饮酒或高嘌呤饮食而诱发","关节痛剧烈，但间歇期常无症状","足跖趾关节常受累","常伴皮肤红肿热痛","多为对称性小关节肿痛"],"a":4,"e":"痛风性关节炎多为单关节发作，好发足第一跖趾关节，常因饮酒或高嘌呤饮食诱发，疼痛剧烈、间歇期无症状，伴局部红肿热痛。对称性小关节肿痛实为类风湿关节炎的特点，与痛风的单关节、非对称性分布不同"},{"q":"下列各项均为肠梗阻的临床共同表现，但除外","o":["腹痛","腹胀","休克","呕吐","便秘"],"a":2,"e":"肠梗阻的四大共同表现为腹痛、腹胀、呕吐与停止排便排气即便秘，机械性者肠鸣音亢进。休克项实为绞窄性肠梗阻或晚期并发症，因体液丢失、感染中毒所致，并非各类肠梗阻共有的早期表现，故为除外项"},{"q":"主要用于鉴别急性单核细胞白血病与急性粒细胞白血病的染色方法是","o":["糖原染色","非特异性酯酶染色","酸性磷酸酶染色","特异性酯酶染色","铁染色"],"a":1,"e":"非特异性酯酶染色主要存在于单核系细胞，急性单核细胞白血病呈阳性且能被氟化钠抑制，急性粒细胞白血病呈阴性或弱阳性、不被抑制，据此可鉴别两者。特异性酯酶染色项用于显示粒系，糖原染色项用于淋系鉴别，铁染色项用于贫血鉴别"},{"q":"触到右肾下极在正常人中不可见于","o":["身材瘦长者","肾下垂","游走肾","肾代偿性增大","肾肿瘤"],"a":4,"e":"正常人肾脏一般不易触及，但身材瘦长者、肾下垂、游走肾或肾代偿性增大时可触及右肾下极，均属正常或体位性情况。肾肿瘤项实为病理性肾脏肿大，质地坚硬、表面不平，不属正常人中可触及的情形"},{"q":"心电图检查V1导联位于胸骨右缘","o":["第一肋间","第二肋间","第三肋间","第四肋间","第五肋间"],"a":3,"e":"V1导联电极置于胸骨右缘第4肋间，V2置于胸骨左缘第4肋间，V3在V2与V4连线中点，V4在左锁骨中线与第5肋间交点，V5、V6依次向左腋前线与腋中线水平排列。第2肋间为胸骨右缘主动脉瓣区，非V1位置"},{"q":"白细胞计数正常值是","o":["（4.0～10）×109/L","（3.0～10）×109/L","（3.5～100）×109/L","（4.0～100）×109/L","（4.5～10）×109/L"],"a":0,"e":"成人白细胞计数正常参考范围为每升4～10乘以10的9次方，低于4为白细胞减少，高于10为增多。白细胞分类以中性粒细胞为主，其余选项的上限100明显过高，起点4.5偏高，均非标准正常值"},{"q":"某咯血患者面色晦暗、两颊暗红、口唇发绀，其病因应首先考虑","o":["肺结核","支气管扩张","二尖瓣狭窄","急性白血病","钩端螺旋体病"],"a":2,"e":"面色晦暗、双颊紫红、口唇发绀为二尖瓣面容，由风湿性心脏病二尖瓣狭窄致左房扩大、肺淤血与周围血管收缩所致，其咯血多为痰中带血或粉红色泡沫痰。肺结核与支气管扩张项无此面容，急性白血病项伴贫血出血倾向"},{"q":"关于病程记录的书写，下列哪项不正确","o":["症状及体征的变化","体检结果及分析","各级医师查房及会诊意见","每天均应记录1次","临床操作及治疗措施"],"a":3,"e":"日常病程记录的书写频次依病情而异：病危病人根据病情随时记录、每天至少一次，病重者至少2天一次，病情稳定者至少3天一次，并非每天均须记录。症状体征变化、体检结果分析、各级医师查房会诊意见与临床操作均属病程记录内容"},{"q":"72岁男性，胸痛来诊，下列哪个问题不合适","o":["您哪里不舒服","您胸痛时有没有心慌","胸痛时还有没有其他地方痛","胸痛的程度如何","胸痛怎样才能缓解"],"a":1,"e":"您胸痛时有没有心慌为封闭式诱导提问，易暗示病人作出肯定回答，不符合问诊应避免提示的原则。其余问句均为开放式提问，分别围绕部位、放射、程度与缓解方式展开，有利于病人自由描述胸痛特点"},{"q":"肝区叩击痛对下列诊断最有意义的是","o":["肝硬化","脂肪肝","肝内胆管结石","门静脉血栓","肝脓肿"],"a":4,"e":"肝区叩击痛在肝脓肿时因炎症累及肝包膜而明显，是定位肝内化脓性病变的重要体征，病毒性肝炎、肝癌亦可出现。肝内胆管结石项实为胆管梗阻与感染，以右上腹绞痛、黄疸为主；肝硬化项肝脏多缩小、质地变硬，叩击痛不显著"},{"q":"假性斑秃秃发区的特点不包括","o":["局部皮肤萎缩变薄","毛囊口消失","境界清楚","形状不规则","无明显炎症性改变"],"a":4,"e":"假性斑秃为瘢痕性脱发，秃发区皮肤萎缩变薄、毛囊口消失，境界清楚且形状不规则，早期可伴毛囊周围轻度炎症。无明显炎症性改变项实为斑秃的特征，后者皮肤光滑无萎缩、毛囊口存在、毛发可再生；境界清楚项虽两者共有，但假性斑秃同时有萎缩与毛囊口消失可资区别"},{"q":"抗ds-DNA抗体阳性最常见于","o":["系统性红斑狼疮","类风湿性关节炎","硬化病","皮肌炎","干燥综合征"],"a":0,"e":"抗双链DNA抗体针对DNA双螺旋结构，是系统性红斑狼疮的特异性自身抗体，滴度与疾病活动度尤其狼疮肾炎相关，活动期阳性率高。类风湿性关节炎项对应类风湿因子与抗角蛋白抗体；干燥综合征项实为抗SSA、抗SSB抗体相关；皮肌炎项以抗Jo-1等肌炎抗体为特征"},{"q":"问诊时，下列哪句话欠妥","o":["您腹痛的部位在何处","您的腹痛是锐痛？钝痛？饭前和饭后一样吗","您病后是否服过药","哪种情况下，腹痛会更严重一些","请谈谈你腹痛的情况吧"],"a":1,"e":"问诊应由一般提问逐步过渡到直接提问，避免把多个备选答案及进食关系一并抛出，带有暗示和诱导，易使患者顺从回答而失真。您病后是否服过药项虽为直接提问但内容中性，不属欠妥；哪种情况下腹痛更严重项实为开放式提问，有利于引出诱因；请谈谈腹痛情况项属一般提问，符合由一般到直接的原则"},{"q":"尿试带法临床应用对疾病的价值最小的是","o":["筛检","诊断","监测","预后","确诊"],"a":4,"e":"尿试带法操作简便、灵敏度高，适用于健康体检、疾病筛检与疗效监测，可提示蛋白、糖、潜血等异常，但不能单凭试带结果确定疾病性质。确诊项需依靠尿沉渣镜检、细菌培养或病理等金标准；诊断项实为结合临床的综合判断，试带仅提供线索；预后判断项还需尿蛋白定量与特定蛋白分析"},{"q":"患痔疮或肛裂，排出的粪便最可能的性状是","o":["脓血便","冻状便","鲜血便","干结便","黏液便"],"a":2,"e":"痔与肛裂均为肛门直肠末端病变，排便时粪便划破黏膜或擦过曲张静脉，血液鲜红、滴落或附着于粪便表面，不与粪便混合。脓血便项实为细菌性痢疾、溃疡性结肠炎等肠道炎症的表现；冻状便项描述的是过敏性肠炎、慢性菌痢；干结便项见于习惯性便秘，均无鲜血附着特征"},{"q":"诊断肥胖标准是","o":["超过标准体重15%以上","超过标准体重17%以上","超过标准体重20%以上","超过标准体重22%以上","超过标准体重25%以上"],"a":2,"e":"体内脂肪积聚过多致体重超过标准体重20%即为肥胖，计算时需排除肌肉发达与水分潴留因素，WHO并以BMI≥30、我国以BMI≥28作为判定标准。超过标准体重10%项实为超重，尚未达到肥胖；超过25%项虽属肥胖但非诊断界值；BMI判定项属于另一套标准，与体重百分比标准并列而非替代"},{"q":"凝血因子中纤维蛋白原是（ ）因子","o":["Ⅰ","Ⅱ","Ⅲ","Ⅶ","Ⅷ"],"a":0,"e":"纤维蛋白原即凝血因子Ⅰ，由肝脏合成，在凝血酶作用下转变为纤维蛋白，构成血栓网架，是凝血过程的共同终末底物。Ⅱ项实为凝血酶原；Ⅲ项为组织因子，由损伤组织释放启动外源性凝血；Ⅶ项为稳定因子，参与外源性途径；Ⅷ项为抗血友病因子，缺乏致血友病A"},{"q":"镜下脓尿是指尿沉渣镜检白细胞","o":["0～5个/HPF","＞5个/HPF","＞10个/HPF","＞15个/HPF","＞20个/HPF"],"a":1,"e":"尿沉渣镜检白细胞超过5个/HPF即为镜下脓尿，提示泌尿系统感染或炎症，玻片法女性正常可达0～5个/HPF，故以5为界。0～5个/HPF项属正常参考范围；超过10个/HPF项数值过高，会漏掉轻度脓尿；镜下血尿的判断项实为红细胞超过3个/HPF，与白细胞计数无关"},{"q":"多发性骨髓瘤是下列哪种细胞恶性增生性疾病","o":["网状细胞","浆细胞","内皮细胞","肥大细胞","脂肪细胞"],"a":1,"e":"多发性骨髓瘤是单克隆浆细胞恶性增殖性疾病，异常浆细胞在骨髓浸润并分泌单克隆免疫球蛋白，引起骨痛、贫血、肾损害与高钙血症。网状细胞项实为恶性组织细胞病相关；内皮细胞项对应血管肉瘤等血管源性肿瘤；肥大细胞项描述的是肥大细胞增多症；脂肪细胞项与骨髓脂肪浸润有关，均非骨髓瘤的本质"},{"q":"下列疾病都可引起S1增强，但除外","o":["二尖瓣狭窄","二尖瓣关闭不全","PR间期缩短","舒张期缩短","完全性房室传导阻滞"],"a":1,"e":"第一心音主要来自房室瓣关闭振动，二尖瓣狭窄时瓣叶弹性尚好、位置较低且左室充盈时间延长，关闭振动增强；PR间期缩短与舒张期缩短均使瓣膜位置更低、关闭更有力。二尖瓣关闭不全项实为S1减弱的原因；完全性房室传导阻滞项因房室分离可出现大炮音，并非持续S1增强的常规机制"},{"q":"先让患者仰卧，行腹部叩诊时，其中腹部呈鼓音，两侧呈浊音；转成左侧位时，左侧腹部浊音区增大，而右侧腹部转为鼓音，称为移动性浊音阳性，表示病征是","o":["幽门梗阻","急性胃扩张","巨大卵巢囊肿","腹腔内有游离腹水","尿潴留"],"a":3,"e":"腹腔内游离液体超过1000ml时，液体随体位流向低处，叩诊浊音区随之移动，出现移动性浊音，是腹腔积液的重要征象。巨大卵巢囊肿项实为腹中部浊音、两侧鼓音，浊音区不随体位移动；尿潴留项浊音限于耻骨上，排尿或导尿后转为鼓音；幽门梗阻与急性胃扩张项主要表现为胃泡鼓音区扩大或振水音"},{"q":"过氧化物酶染色呈阴性反应的疾病为","o":["急性淋巴细胞白血病","急性粒细胞白血病","急性早幼粒细胞白血病","急性粒-单核细胞白血病","急性单核细胞白血病"],"a":0,"e":"过氧化物酶染色定位于粒系细胞的嗜天青颗粒，急性淋巴细胞白血病为淋巴系起源，原始淋巴细胞不含该酶，故呈阴性，此染色是急淋与急粒鉴别的关键。急性粒细胞白血病项呈强阳性；急性早幼粒细胞白血病项阳性更强；急性单核细胞白血病项多为弱阳性或阴性，需结合特异性酯酶染色区分"},{"q":"GFR测定的参考方法是","o":["肌酐清除率","对氨基马尿酸清除率","尿素清除率","尿酸清除率","菊粉清除率"],"a":4,"e":"菊粉只经肾小球滤过，肾小管既不重吸收也不分泌，其清除率能准确反映肾小球滤过率，是GFR测定的参考方法。肌酐清除率项实为临床常用估算方法，因肾小管分泌肌酐而高估GFR；对氨基马尿酸清除率项测定的是肾血浆流量；尿素清除率项受肾小管重吸收影响；99mTc-DTPA法虽可媲美，仍以菊粉法为准"},{"q":"易致高血钾的是","o":["因长期不能进食而由静脉补充营养时","严重呕吐","静脉输入过多钾盐","糖和蛋白代谢旺盛","进食含钾较多食物"],"a":2,"e":"静脉输入过多钾盐直接使细胞外钾迅速升高，超过肾脏排钾能力即可引起高钾血症，严重时可致心室颤动与心脏停搏。长期不能进食静脉补营养项若不含钾，实为低钾原因；严重呕吐项因胃液丢失与代谢性碱中毒致低钾；糖和蛋白代谢旺盛项促使钾转入细胞内；进食含钾食物项在肾功能正常时可及时排出，不致蓄积"},{"q":"下列关于出血性疾病的皮肤黏膜出血情况，描述不正确的是","o":["可由血小板数量或功能异常引起","可由止血与凝血功能障碍引起","可引起全身性皮肤黏膜自发性出血","严重伤后出血不止","受轻伤后出血不止"],"a":3,"e":"皮肤黏膜出血以止血或凝血障碍为基础，特征为自发性出血或轻微损伤后出血不止，血小板异常与凝血因子缺乏均可致病。严重伤后出血不止项实为正常人也有的创伤反应，不属出血性疾病的特有表现；血小板数量或功能异常项、止血与凝血功能障碍项均为其机制；全身性自发性出血与轻伤后出血不止项是其典型特征"},{"q":"严重腹泻患者常引起","o":["血[Na＋HCO3－]上升","代谢性碱中毒","血中CO2结合力上升","低血钾","血液pH增加"],"a":3,"e":"严重腹泻时大量含钾肠液随粪便丢失，且进食减少、肾小管代偿性排钾，导致血钾降低，可出现乏力、心律失常与病理性u波。代谢性碱中毒项与腹泻丢失碱性肠液相反，实为代谢性酸中毒；血中CO2结合力上升项、血液pH增加项均不符合酸中毒改变；血Na＋HCO3－上升项同样与丢失HCO3－的病理生理相悖"},{"q":"下列哪项反映100ml动脉血中含氧总量","o":["P（A-a）O2","AG","BB","TCO2","SaO2"],"a":4,"e":"动脉血氧饱和度反映动脉血氧与血红蛋白结合的程度，以百分数表示，结合血红蛋白浓度即可判断血液携氧状况，是评价缺氧的重要指标。P（A-a）O2项实为肺泡与动脉氧分压差，反映肺换气功能；AG项为阴离子间隙，用于酸碱失衡分析；BB项为缓冲碱，TCO2项反映代谢性酸碱状态，均与动脉血含氧无关"},{"q":"正后壁心肌梗死的心电图改变不包括","o":["V7～V9导联出现异常Q波或QS波","V3R～V4R导联出现异常Q波或QS型","V1、V2导联R波增高","V7～V9导联ST段抬高0、1mV","V7～V9导联T波倒置"],"a":1,"e":"正后壁心肌梗死坏死型图形出现在V7～V9导联，表现为异常Q波或QS波、ST段抬高与T波倒置，对应性改变使V1、V2导联R波增高、ST段压低、T波高耸。V3R～V4R导联出现异常Q波或QS型项实为右心室梗死的定位表现；V1、V2导联R波增高项属正后壁梗死的对应性改变，并非错误表现"},{"q":"Beck三联征见于","o":["亚急性细菌性心内膜炎","渗出性心包炎","缩窄性心包炎","纤维蛋白性心包炎","心脏压塞"],"a":4,"e":"Beck三联征包括颈静脉怒张、动脉压下降和心音遥远，是急性心脏压塞的典型表现，因心包腔内压力急剧升高、心室充盈受限所致。渗出性心包炎项以心包积液与心包摩擦音为主，未必出现三联征；缩窄性心包炎项主要为慢性舒张受限与静脉淤血；纤维蛋白性心包炎项的标志是心包摩擦音，无液体填塞"},{"q":"下列哪种疾病引起的二尖瓣区收缩期吹风样杂音属功能性","o":["贫血性心脏病","甲状腺功能亢进","高血压心脏病","风湿性二尖瓣关闭不全","二尖瓣脱垂"],"a":1,"e":"甲状腺功能亢进时高动力循环使血流加速，瓣膜本身无器质性病变，产生二尖瓣区柔和的收缩期吹风样杂音，属功能性。风湿性二尖瓣关闭不全项与二尖瓣脱垂项均属器质性病变；高血压心脏病项与贫血性心脏病项实为心室或瓣环扩大导致的相对性关闭不全，瓣叶本身并无增厚挛缩"},{"q":"下列疾病BT不延长的是","o":["血小板减少性紫癜","血小板无力症","遗传性毛细血管扩张症","血友病A","血管性血友病"],"a":3,"e":"出血时间反映血管壁完整性与血小板数量、功能，血友病A缺乏凝血因子Ⅷ，属内源性凝血途径障碍，血小板与血管壁正常，故BT不延长而凝血时间延长。血小板减少性紫癜项与血小板无力症项分别因数量不足和功能缺陷致BT延长；遗传性毛细血管扩张症项属血管壁病变，可伴出血倾向；血管性血友病项因vWF缺陷影响血小板黏附而延长"},{"q":"正常人支气管呼吸音不易见于","o":["喉部","胸骨上窝","肩胛下区","背部第6、7颈椎附近","背部第1、2胸椎附近"],"a":2,"e":"支气管呼吸音是气流通过声门、气管与主支气管形成的湍流声音，正常仅在喉部、胸骨上窝及背部第6、7颈椎与第1、2胸椎附近闻及。肩胛下区项正常为肺泡呼吸音分布区，若此处闻及支气管呼吸音提示肺实变；喉部、胸骨上窝及胸椎附近三项均属正常可闻及部位，不构成异常"},{"q":"空腹痛常见于","o":["胃溃疡","十二指肠溃疡","胰腺炎","胆囊炎","胃炎"],"a":1,"e":"十二指肠溃疡的疼痛具有周期性与节律性，常在空腹或餐后3～4小时出现，进食后可缓解，与胃酸在排空后刺激溃疡面有关。胃溃疡项实为餐后痛，进食后胃窦扩张、胃酸分泌增加诱发；胰腺炎项为持续性上腹痛向背部放射；胆囊炎项以右上腹痛伴Murphy征阳性为特点；胃炎项疼痛多无明显节律"},{"q":"诊断学是用医学科学的方法对疾病的表现所作出的本质的判断，包括以下内容，除外","o":["对病人要进行问诊","对病人要进行体格检查","对病人要进行必要的实验室检查","对所得材料要进行综合归纳、分析、推理、判断，作出结论","要按上级医生的意见对病人作出临床诊断"],"a":4,"e":"诊断学通过问诊、体格检查和必要的实验室检查收集资料，再经综合归纳、分析、推理与判断形成结论，强调医师独立运用临床思维。按上级医生意见作出诊断项实为放弃独立判断，违背诊断学基本原则；问诊项、体格检查项与实验室检查项均为资料收集的基本手段；综合分析项则是从资料上升到诊断的必经环节"},{"q":"下列疾病肝浊音界均可扩大，但除外","o":["肝癌","急性重症肝衰竭","酒精性肝硬化","右心功能不全","多囊肝"],"a":1,"e":"肝浊音界扩大见于肝脏本身肿大或膈肌上移，肝癌、多囊肝为肝实质占位性肿大，右心功能不全致肝淤血肿大，酒精性肝硬化早期亦可有肝大。急性重症肝衰竭项实为肝细胞大片坏死导致肝脏体积缩小、浊音界缩小；肝癌项与多囊肝项属占位性肿大，右心功能不全项致肝淤血，均使肝浊音区扩大"},{"q":"患者入院心电图如图所示，下一步最关键的处理是","o":["给予心室起搏","给予心房起搏","静脉给予胺碘酮","静脉给予异丙肾上腺素","静脉补钾"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。若心电图表现为三度房室传导阻滞，P波与QRS波互不相关、心房率快于心室率，提示阻滞部位较低，因心室率过慢伴血流动力学障碍需植入心室起搏。心房起搏项不能纠正房室传导中断；胺碘酮项用于室性快速心律失常；异丙肾上腺素项仅可短期提高心率；静脉补钾项针对血钾异常，均非根本处理\n\n官方题库中缺失图片"},{"q":"疑为回归热的患者，血液涂片检查应做什么染色","o":["厚涂片吉姆萨染色","印度墨汁染色","革兰氏染色","瑞特染色","Fontana镀银染色"],"a":0,"e":"回归热螺旋体存在于发热期血液中，取外周血制备厚涂片后行吉姆萨染色，可在红细胞间找到细长螺旋体，是病原学诊断的直接方法。印度墨汁染色项实为隐球菌荚膜检查；革兰氏染色项用于细菌分类；Fontana镀银染色项虽可用于螺旋体，但多用于梅毒螺旋体等组织涂片；瑞特染色项常用于血细胞与疟原虫检查"},{"q":"心包叩击音主要见于","o":["心力衰竭","心房黏液瘤","缩窄性心包炎","急性心肌梗死","正常人"],"a":2,"e":"心包叩击音是缩窄性心包炎的特征性额外心音，出现在第二心音后0.09～0.12秒，因心室舒张突然受限、血流冲击僵硬心包产生，音调中频、短促而响亮。开瓣音项实为二尖瓣狭窄瓣叶弹性尚好的表现；肿瘤扑落音项描述的是心房黏液瘤；奔马律项提示心室舒张期负荷过重；正常人项不应闻及额外心音"},{"q":"胸膜摩擦音最常听到的部位是","o":["锁骨上窝","锁骨下窝","前下侧胸壁","肩胛间区","肩胛下区"],"a":2,"e":"胸膜摩擦音是脏、壁胸膜因炎症渗出变得粗糙，随呼吸相对滑动产生的摩擦声，前下侧胸壁呼吸动度最大，故最易闻及，屏气后消失可与心包摩擦音区别。锁骨上窝与锁骨下窝项肺尖呼吸动度小，很少闻及；肩胛间区与肩胛下区项虽可听诊，但动度不及前下侧胸壁，非最佳部位"},{"q":"Duroziez征是指","o":["明显颈动脉搏动","毛细血管搏动","枪击音","动脉双重杂音","点头运动"],"a":3,"e":"Duroziez征是以听诊器钟型体件稍加压于股动脉、开口偏向近心端时闻及的收缩期与舒张期双期吹风样杂音，属主动脉瓣重度关闭不全的周围血管征。毛细血管搏动项、点头运动项与明显颈动脉搏动项虽同属周围血管征，但分别为Quincke征、de Musset征等；枪击音项为股动脉收缩期短促射枪样音，均非双重杂音"},{"q":"重叠性奔马律见于","o":["心功能不全伴心动过速","心功能不全伴心动过缓","风湿性心脏病伴二度房室传导阻滞","冠状动脉粥样硬化性心脏病伴三度房室传导阻滞","肥厚型心肌病"],"a":0,"e":"重叠性奔马律发生于心率增快时，舒张早期与舒张晚期额外心音相互靠拢重叠，甚至与正常心音融合，常见于心功能不全伴心动过速，提示心室舒张期与收缩期负荷均加重。心功能不全伴心动过缓项心率慢，额外心音分离而不重叠；房室传导阻滞项因心房率与心室率关系异常，奔马律可不典型；肥厚型心肌病项多为房性奔马律"},{"q":"临床诊断思维的步骤和具体内容包括","o":["从解剖的观点，有何结构异常","考虑几个可能的致病因素","考虑病情的轻重，勿放过严重情况","寻找特殊的症状体征组合，进行鉴别诊断","以上都正确"],"a":4,"e":"临床诊断思维要求从解剖观点判断结构异常，从病因角度列举致病因素，评估病情轻重以免遗漏危重情况，并寻找特征性症状体征组合进行鉴别，四者均为具体内容。从解剖的观点项属病理解剖分析；考虑致病因素项属病因探查；考虑病情轻重项着眼危重识别；寻找症状体征组合项用于鉴别诊断，四项均在其列"},{"q":"下列哪种情况出现肝浊音界消失","o":["膈下脓肿","急性重型肝炎","急性胃肠穿孔","肝癌","肺气肿"],"a":2,"e":"急性胃肠穿孔后气体逸入腹腔并积聚于膈下，叩诊时肝浊音界消失而代之以鼓音，是急腹症的重要诊断征象。膈下脓肿项因肝下移、横膈升高使肝浊音区扩大；急性重型肝炎项肝细胞坏死致浊音界缩小而非消失；肝癌项肝脏肿大致浊音界扩大；肺气肿项肝浊音界下移缩小，均不出现浊音界消失"},{"q":"大量心包积液的脉搏是","o":["奇脉","迟脉","交替脉","水冲脉","重搏脉"],"a":0,"e":"大量心包积液导致心脏压塞时，吸气使右心回血受限、肺血管扩张致左心充盈减少，脉搏明显减弱或消失，形成奇脉，是心脏压塞的特征性脉搏。交替脉项实为左心衰竭的表现；水冲脉项见于主动脉瓣关闭不全、甲亢与严重贫血；迟脉项提示主动脉瓣狭窄；重搏脉项多见于伤寒等长期发热疾病"},{"q":"关于漏出液的特点，下列哪项是错误的","o":["漏出液多为非炎症所致","漏出液黏蛋白定性试验阳性","漏出液多为透明或微浊","漏出液比重多低于1.018","漏出液一般不自凝"],"a":1,"e":"漏出液多由非炎症因素引起，如静脉压升高或血浆胶体渗透压降低，液体静置后一般不自凝，外观透明或微浊，比重多低于1.018，蛋白含量低。黏蛋白定性试验阳性项实为渗出液特点，炎症刺激浆膜分泌大量黏蛋白，在稀乙酸中析出白色沉淀；漏出液黏蛋白很少，Rivalta试验应为阴性，此项描述与漏出液性质相悖"},{"q":"心电图检查的标准走纸速度是","o":["10mm/s","75mm/s","25mm/s","40mm/s","50mm/s"],"a":2,"e":"心电图标准走纸速度为25mm/s，此时横坐标每一小格1mm代表0.04秒，标准电压10mm/mV，是测量间期与波幅的统一基准。10mm/s项与50mm/s项均非常规标准，会改变波形时间宽度；75mm/s项与40mm/s项无标准依据；标准电压项与走纸速度分属定标与走纸两个参数，不能混为一谈"},{"q":"蛙状腹多见于","o":["巨大卵巢囊肿","肠梗阻","肠麻痹","气腹","腹腔积液"],"a":4,"e":"大量腹腔积液时液体因重力积于腹部两侧，仰卧位腹部扁平、两侧膨出，侧卧位时下侧腹部明显隆起，形似蛙腹，多见于肝硬化门静脉高压、心衰与肾病综合征。巨大卵巢囊肿项多呈圆形局限性包块，不随体位改变形状；肠梗阻与肠麻痹项为肠管积气扩张，叩诊鼓音；气腹项膈下积气，肝浊音界缩小或消失"},{"q":"诊断急性腹膜炎的最主要的体征是","o":["腹部压痛和反跳痛","腹式呼吸减弱或消失","腹胀的出现","肠鸣音的改变","移动性浊音"],"a":0,"e":"急性腹膜炎时壁层腹膜受炎性渗出物刺激，出现腹肌紧张、压痛与反跳痛，构成腹膜炎三联征，其中压痛与反跳痛是最具诊断价值的直接体征。腹式呼吸减弱或消失项、腹胀项、肠鸣音改变项与移动性浊音项均为腹膜炎的伴随表现，分别反映膈肌受限、肠麻痹与炎性渗出，但不能作为最主要诊断依据"},{"q":"胸腔积液的体征主要与哪种因素有关","o":["积液形成的缓急","积液的性质","原发病变","单侧或双侧","积液量"],"a":4,"e":"胸腔积液的体征主要取决于积液量，少量积液可无明显异常，中大量时出现叩诊浊音、语颤减弱、呼吸音减低及胸廓饱满，积液量越多体征越显著。积液形成的缓急项主要决定症状出现的急缓与程度；积液的性质项用于病因判断；原发病变项决定伴随表现；单侧或双侧项影响体征分布范围，均非决定体征的主要因素"},{"q":"第一心音的组成主要是","o":["半月瓣开放","心房收缩","房室瓣关闭的震动","乳头肌的收缩","血流冲击大血管的震动"],"a":2,"e":"第一心音主要由二尖瓣与三尖瓣关闭时瓣叶突然紧张、振动产生，标志心室收缩开始，其强度取决于心肌收缩力、心室充盈程度及瓣膜位置与结构。半月瓣开放项与血流冲击大血管项参与第二心音形成；心房收缩项产生第四心音；乳头肌收缩项参与第三心音的形成，均非第一心音的主要成分"},{"q":"下列哪种疾病是骨髓穿刺禁忌证","o":["粒细胞缺乏症","白血病","脾功亢进","血友病","再生障碍贫血"],"a":3,"e":"血友病为凝血因子Ⅷ或Ⅸ缺陷所致出血性疾病，骨髓穿刺易导致穿刺部位出血不止，属禁忌证，晚期妊娠亦应慎重。粒细胞缺乏症项、白血病项与再生障碍性贫血项本身即需骨髓象检查以明确诊断；脾功能亢进项也常需骨髓评估造血功能，均非骨穿禁忌"},{"q":"出院记录不包括","o":["入院诊断","出院医嘱","出院诊断","出院情况","门诊病历诊断"],"a":4,"e":"出院记录是患者本次住院的总结性文书，内容包括入院与出院日期、入院诊断、诊疗经过、出院诊断、出院时情况与出院医嘱等。门诊病历诊断项属门诊病历记录范畴，记录的是门急诊就诊时的初步判断，不纳入出院记录；入院诊断项、出院诊断项、出院情况项与出院医嘱项均为出院记录的必备组成部分"},{"q":"风湿性心瓣膜病，此诊断属于","o":["病因诊断","病理生理诊断","解剖诊断","功能诊断","临床诊断"],"a":0,"e":"病因诊断是明确疾病根本原因的诊断，风湿性心瓣膜病由风湿热引起，直接指出病因，对治疗与预防具有指导意义。病理解剖诊断项对应二尖瓣狭窄、肝硬化等具体形态改变；功能诊断项与病理生理诊断项对应心功能分级等；临床诊断项是各类诊断的综合表述，层次不同于病因诊断"},{"q":"进行腹部视诊时，不会见到胃肠型和蠕动波的是","o":["腹壁菲薄或松弛的老年人","幽门梗阻","小肠梗阻","结肠梗阻","大量腹水"],"a":4,"e":"胃肠型和蠕动波是胃肠道梗阻时梗阻近端胃或肠段充盈隆起、蠕动增强在腹壁的投影，正常人腹部一般不可见。腹壁菲薄或松弛的老年人项因腹壁薄可显露；幽门梗阻项可见胃型与胃蠕动波；小肠梗阻项与结肠梗阻项分别见肠型与蠕动波；大量腹水项仅表现为腹部膨隆、脐部凸出，不出现胃肠型及蠕动波"},{"q":"过氧化酶染色（POX）阴性的白血病是","o":["急性粒细胞白血病","急性淋巴细胞白血病","急性早幼粒细胞白血病","急性单核细胞白血病","急性粒-单核细胞白血病"],"a":1,"e":"过氧化物酶染色主要显示粒系细胞胞质内嗜天青颗粒中的酶活性，急性淋巴细胞白血病源于淋巴系，原始与幼稚淋巴细胞不含此酶，故呈阴性。急性粒细胞白血病项与急性早幼粒细胞白血病项均呈强阳性；急性单核细胞白血病项可呈弱阳性或阴性；急性粒-单核细胞白血病项部分细胞阳性，需结合酯酶染色鉴别"},{"q":"溶血法总补体检测以什么作为终点指标","o":["25%溶血","50%溶血","75%溶血","80%溶血","100%溶血"],"a":1,"e":"总补体溶血活性检测反映补体经典途径的综合水平，补体量在一定范围内与溶血程度呈正相关，以50%溶血作为终点最为敏感，因为该点附近曲线斜率最大。25%溶血项与75%溶血项处于曲线平坦段，补体量变化引起的溶血差异小、误差大；80%溶血项同理；100%溶血项已达最大溶血，无法区分补体水平的差异"},{"q":"对老年人问诊，下列哪项是错误的","o":["老年人问诊，应先简单清楚通俗易懂的问题","减慢问诊进度","问诊同时观察患者反应，判断有无思维障碍","老年人不易交流，可以直接问家属","仔细询问过去史及用药史"],"a":3,"e":"年龄本身不妨碍医患沟通，老年人问诊应先问简单清楚、通俗易懂的问题，放慢进度并观察其反应，同时详细询问既往史与用药史。老年人不易交流可以直接问家属项实为不恰当做法，应首先直接询问患者本人，家属仅作补充；认真倾听项、详细了解隐私项、关怀特殊患者项与沟通疾病知识项均符合问诊医德要求"},{"q":"检查心脏震颤常用","o":["手掌尺侧","全手掌","2～4指指腹","2、3指指尖","手掌桡侧"],"a":0,"e":"心脏震颤是触诊时手掌尺侧小鱼际或并拢指腹感受到的细小震动感，似猫喉部呼吸震颤，提示器质性心脏病，检查常用手掌尺侧。全手掌项仅用于初步确定心前区触诊部位与范围；2～4指指腹项虽可用于心尖搏动触诊，感知震颤仍以手掌尺侧更为敏感；手掌桡侧项非常规触诊部位"},{"q":"有关问诊的医德要求，医师不正确的做法是","o":["认真倾听患者的病情","对患者的隐私详细了解","对特殊患者，给予更多的关怀","对患者评价以前治疗方法是否得当","与患者及家属仔细沟通疾病相关知识"],"a":3,"e":"问诊中医德要求认真倾听患者陈述，详细了解与疾病相关的隐私并予以保密，对特殊患者给予更多关怀，与患者及家属充分沟通疾病知识。对患者评价以前治疗方法是否得当项实为不当做法，随意褒贬既往治疗既不属问诊内容，也易损害医患信任；其余四项均体现尊重、关怀与有效沟通的基本准则"},{"q":"钟摆律最常见于下列哪种疾病","o":["急性心肌梗死","二尖瓣狭窄","甲状腺功能亢进症","贫血","发热"],"a":0,"e":"钟摆律又称胎心律，因心肌严重受损、收缩期与舒张期时限几乎相等，听诊心音如钟摆摆动，最常见于急性心肌梗死，亦可见于重症心肌炎。甲状腺功能亢进项、贫血项与发热项仅使心率增快、心音增强，不出现时限等量改变；二尖瓣狭窄项以舒张期隆隆样杂音与S1亢进为主要表现，与钟摆律无关"},{"q":"心脏听诊时应注意下列各项，但除外","o":["诊察室环境安静","医生精神高度集中","患者必须采取仰卧位","医生站在病床的右侧","必要时需让患者改变体位"],"a":2,"e":"心脏听诊要求环境安静、医生精神高度集中，通常站在患者右侧按听诊区顺序进行，必要时让患者改变体位以利杂音显示。患者必须采取仰卧位项实为错误要求，听诊可据需要取坐位、左侧卧位或前倾坐位；诊察室环境安静项、医生精神集中项与站在右侧项均为常规要求；必要时改变体位项有助于鉴别杂音来源"},{"q":"下列哪组血浆离子浓度的变化能帮助诊断呼吸性酸中毒","o":["HCO3－升高，伴有K＋下降","HCO3－升高，伴有K＋升高","HCO3－升高，而K＋不变","HCO3－下降，伴有K＋下降","HCO3－下降，伴有K＋升高"],"a":1,"e":"呼吸性酸中毒原发为肺泡通气不足致PaCO2升高，肾脏代偿性保HCO3－使血浆HCO3－升高，同时酸中毒促使细胞内钾外移，出现血钾升高，两者并存支持诊断。HCO3－升高伴K＋下降项与酸中毒的电解质转移方向相反；HCO3－下降两项实为代谢性酸中毒的改变；HCO3－升高而K＋不变项忽略了酸中毒对血钾的影响"},{"q":"炎热环境中皮肤散热的主要形式是","o":["发汗","对流","血流","传导","辐射"],"a":0,"e":"当环境温度接近或高于皮肤温度时，辐射、传导与对流依赖温差散热的方式失效甚至反向吸热，蒸发成为唯一有效途径，故炎热环境中皮肤散热主要依靠发汗。辐射项在常温安静状态下是主要散热方式，高温时受限；传导项与对流项同样受环境温度制约；血流项实为调节皮肤温度的手段，本身不是散热形式"},{"q":"以下中性粒细胞减少见于","o":["放线菌病","流行性出血热","斑疹伤寒","梅毒","伤寒杆菌感染"],"a":4,"e":"伤寒杆菌为革兰阴性杆菌，其内毒素及免疫损伤可抑制骨髓造血并致外周血白细胞与中性粒细胞减少，是伤寒的特征性血象之一。流行性出血热项常见白细胞升高与异常淋巴细胞；斑疹伤寒项与梅毒项、放线菌病项并非以中性粒细胞减少为特征；伤寒杆菌感染项则明确引起白细胞与中性粒细胞减少"},{"q":"关于S3听诊特点，哪项是错误的","o":["出现在心室舒张早期","心尖部及其内上方听诊较清晰","坐位或立位时清晰","呼气末较清晰","成年人一般听不到"],"a":2,"e":"生理性第三心音出现在心室舒张早期快速充盈之末，于心尖部及其内上方听诊清晰，左侧卧位与呼气末更明显，成年人一般听不到。坐位或立位时清晰项实为错误描述，此时S3多减弱或消失；呼气末较清晰项反映S3在呼气时更易闻及；成年人一般听不到项用于区分生理性与病理性S3，儿童青少年可闻及"},{"q":"代表心脏实际大小的界限为","o":["心脏绝对浊音界","心脏相对浊音界","心左界","心右界","心底部界限"],"a":1,"e":"心脏相对浊音界是心脏未被肺组织遮盖部分在胸壁的投影，相当于心脏实际大小，叩诊时由清音变浊音处即为该界限。心脏绝对浊音界项仅代表心脏直接贴近胸壁的区域，小于实际心脏；心左界项与心右界项只是相对浊音界的一侧组成部分；心底部界限项范围局限，均不能代表心脏实际大小"},{"q":"室性奔马律提示","o":["左室充盈压下降","左房压下降","PCWP升高","心脏指数升高","左室射血分数升高"],"a":2,"e":"室性奔马律即舒张早期奔马律，源于心室舒张期负荷过重、充盈压升高，血液冲击室壁引起振动，见于左心衰竭，提示肺毛细血管楔压升高。左室充盈压下降项与左房压下降项同心衰病理生理相反；心脏指数升高项与左室射血分数升高项代表心功能改善，均不会出现室性奔马律"},{"q":"为了解近端肾小管的功能损害程度，应选择的试验是","o":["尿β2微球蛋白定量","血尿素氮定量","血肌酐定量","尿比重测定","尿渗透压测定"],"a":0,"e":"尿β2微球蛋白分子量小，可自由滤过肾小球，正常时几乎全部被近端肾小管重吸收，尿中含量极低；近端小管受损时重吸收减少、尿β2微球蛋白升高，是评价近端肾小管功能的敏感指标。血尿素氮项与血肌酐项反映肾小球滤过功能；尿比重项与尿渗透压项主要反映远端肾小管的浓缩稀释功能"},{"q":"风湿性心脏病严重主动脉瓣关闭不全时，脉搏触诊时可有","o":["平脉","重搏脉","交替脉","水冲脉","奇脉"],"a":3,"e":"主动脉瓣重度关闭不全时舒张期血液反流致脉压增大，脉搏骤起骤落如潮水涨落，形成水冲脉，常伴毛细血管搏动与枪击音等周围血管征。奇脉项见于心脏压塞与缩窄性心包炎；交替脉项提示左心衰竭；重搏脉项多见于伤寒等；平脉项为正常脉搏，均非主动脉瓣关闭不全的体征"},{"q":"以下不符合渗出液特点的是","o":["穿刺液自凝","呈现不同颜色或混浊","比重大于1.018","李凡他试验阴性","细胞数大于500×106/L"],"a":3,"e":"渗出液多由炎症、肿瘤等引起，因含大量黏蛋白与细胞成分，常呈不同颜色或混浊、比重大于1.018、易自凝、细胞数超过500×10^6/L，李凡他试验阳性。李凡他试验阴性项实为漏出液特点，漏出液黏蛋白极少，在稀乙酸中不出现白色沉淀；比重大于1.018项、穿刺液自凝项与细胞数增多项均符合渗出液特征"},{"q":"患者肢体能抬离床面，能对抗重力，但不能完全对抗阻力，其肌力为","o":["1级","2级","3级","4级","5级"],"a":3,"e":"肌力4级指肢体能抬离床面并对抗重力，尚能作抗阻力动作但力量不完全，该患者表现与此相符。3级项仅能抬离床面而完全不能抗阻力；2级项只能在床面水平移动、不能抵抗重力；1级项仅有肌肉收缩而无肢体动作；5级项为正常肌力、可完全对抗阻力，均与题目描述不符"},{"q":"因长期大量使用抗生素引起的腹泻或鹅口疮多属于","o":["内源性感染","医源性感染","交叉感染","外源性感染","隐性感染"],"a":0,"e":"长期大量使用抗生素抑制肠道或口腔正常菌群，使原本存在于体内的机会致病菌异常增殖，引起抗生素相关性腹泻或鹅口疮，病原体来自自身菌群，属内源性感染。外源性感染项病原体来自宿主体外；医源性感染项强调感染与医疗操作相关；交叉感染项指患者之间或医患之间的传播；隐性感染项指无症状的感染状态"},{"q":"诊断二尖瓣狭窄最有意义的体征是","o":["心尖部第一心音亢进","肺动脉瓣区第二心音亢进","二尖瓣区收缩期杂音","肺动脉瓣区收缩期杂音","心尖部舒张期隆隆样杂音"],"a":4,"e":"心尖部舒张期隆隆样杂音是二尖瓣狭窄的特征性体征，由舒张期血流通过狭窄瓣口产生涡流所致，呈递增型，左侧卧位更清晰，具定性诊断价值。心尖部第一心音亢进项与肺动脉瓣区第二心音亢进项为辅助体征，特异性较低；二尖瓣区收缩期杂音项提示关闭不全；肺动脉瓣区收缩期杂音项多属相对性肺动脉瓣狭窄"},{"q":"以下不是胃镜检查适应证的是","o":["原因不明的上消化道出血","胃内异物","食管静脉曲张破裂出血","急性腹痛伴肝浊音界消失","胃癌术后随访"],"a":3,"e":"急性腹痛伴肝浊音界消失提示急性胃肠穿孔，穿孔后行胃镜注气会加重腹腔污染与腹膜炎，属禁忌。原因不明的上消化道出血项与食管静脉曲张破裂出血项均为胃镜诊断与止血的适应证；胃内异物项可用胃镜取出；胃癌术后随访项属胃镜常规复查范畴，均可行镜检查"},{"q":"脑膜刺激征不会见于","o":["脑膜炎","蛛网膜下腔出血","颅压增高状态","脑膜脑炎","脑梗死"],"a":4,"e":"脑膜刺激征是脑膜受激惹的表现，包括颈强直、Kernig征与Brudzinski征，见于脑膜炎、脑膜脑炎、蛛网膜下腔出血及颅内压增高。脑梗死项为脑组织缺血性病变，未直接累及脑膜，一般无脑膜刺激征；脑膜炎项与脑膜脑炎项直接侵犯脑膜；蛛网膜下腔出血项因血液刺激脑膜；颅压增高状态项可致颈强直"},{"q":"下列不会引起周围性发绀的疾病是","o":["肺炎","右心衰竭","缩窄性心包炎","严重休克","上腔静脉阻塞综合征"],"a":0,"e":"周围性发绀源于周围循环血流障碍，多见于肢体末端与下垂部位，按摩或加温后减轻。右心衰竭项、缩窄性心包炎项与上腔静脉阻塞项属淤血性周围性发绀；严重休克项属缺血性周围性发绀；肺炎项影响肺泡通气与换气，使血氧饱和度下降，实为中心性发绀，不属周围性发绀病因"},{"q":"下列影响心音强弱改变因素的叙述是正确的，但除外","o":["心室收缩力和收缩速度","血压高低及心率快慢","瓣膜完整性与活动性","心室充盈情况与瓣膜位置","大量心包积液"],"a":1,"e":"影响心音强度的主要因素是心肌收缩力与心室充盈程度、瓣膜位置和结构活动性，心包积液使心音传导受阻而减弱，肺含气量、胸壁病变等心外因素亦有影响。血压高低及心率快慢项主要影响心排血量与心肌耗氧，并非心音强弱的直接决定因素；心室收缩力和收缩速度项、瓣膜完整性与活动性项、心室充盈与瓣膜位置项、大量心包积液项均是明确的影响因素"},{"q":"下列疾病可见中性粒细胞减少，但应除外","o":["病毒感染","骨髓转移癌","脾功能亢进","慢性粒细胞白血病","系统性红斑狼疮"],"a":3,"e":"慢性粒细胞白血病以骨髓粒细胞系过度增生为特征，外周血白细胞显著升高、中性粒细胞增多，故不出现粒细胞减少。病毒感染项可抑制骨髓或使粒细胞分布异常；脾功能亢进项因粒细胞破坏增多；系统性红斑狼疮项由免疫性破坏所致；骨髓转移癌项因骨髓造血受抑，四者均可致中性粒细胞减少"},{"q":"从临床思维的角度看，常见造成误诊漏诊的原因不包括下列哪一项","o":["基本素材不齐","观察不细致或检验结果误差","医学知识不足，缺乏临床经验","早期罕见疑难病例","医患关系不佳"],"a":4,"e":"从临床思维角度，误诊漏诊常源于基本素材不齐、观察不细致或检验误差、医学知识与经验不足，以及疾病早期表现不典型或属罕见疑难病例。医患关系不佳项虽影响沟通与配合，但不属于临床思维层面的误诊原因；其余四项分别对应资料收集、观察判断、知识储备与疾病本身特点四个环节，均为常见原因"},{"q":"常见惊厥伴高血压、脑膜刺激征阳性的疾病是","o":["蛛网膜下腔出血","高血压脑病","肺性脑病","癔症","丘脑出血"],"a":0,"e":"蛛网膜下腔出血时血液进入蛛网膜下腔刺激脑膜，出现剧烈头痛与脑膜刺激征，颅内压骤升及血管痉挛可诱发惊厥，并常伴血压升高。高血压脑病项虽有高血压与惊厥，但无脑膜刺激征；癔症项为功能性障碍，无器质性体征；肺性脑病项有慢性肺病基础与二氧化碳潴留；丘脑出血项以意识障碍与偏瘫为主"},{"q":"二尖瓣狭窄的杂音性质是","o":["吹风样","隆隆样","叹气样","机器样","乐音样"],"a":1,"e":"二尖瓣狭窄时舒张期血流经狭窄瓣口形成涡流，产生心尖区舒张中晚期隆隆样杂音，呈递增型，局限于心尖区，左侧卧位明显。吹风样项实为二尖瓣或三尖瓣关闭不全的杂音；叹气样项描述主动脉瓣关闭不全的舒张期杂音；机器样项见于动脉导管未闭；乐音样项多提示感染性心内膜炎赘生物或瓣膜穿孔"},{"q":"血小板在凝血过程中的主要作用是","o":["作为因子Ⅲ参与凝血过程","激活因子Ⅻ","释放ADP","提高PF3（磷脂）活性","稳定纤维蛋白"],"a":3,"e":"血小板膜表面的磷脂酰丝氨酸即血小板第3因子，为凝血因子Ⅹa、Ⅴa与钙离子结合形成凝血酶原酶提供催化表面，从而加速凝血酶生成，是血小板促凝作用的核心。因子Ⅲ项实为组织因子，由损伤组织释放；激活因子Ⅻ项由胶原等启动；释放ADP项主要参与血小板聚集；稳定纤维蛋白项是因子ⅩⅢ的功能"},{"q":"右心室肥大心尖冲动的位置为","o":["向左下移位","向右移位","向右上移位","向左上移位","向左移位"],"a":4,"e":"右心室增大时心尖搏动向左移位但不向下，因右室构成心前壁主体、扩大后推挤心尖向左，同时胸骨左下缘或剑突下可出现抬举样搏动。向左下移位项实为左心室增大的表现；向左上移位项不符合心室扩大的方向；向右移位项见于右位心或纵隔移位；向右上移位项非心室肥大的典型体征"},{"q":"收缩期杂音伴收缩中晚期喀喇音，最常见于下列何种疾病","o":["二尖瓣脱垂","二尖瓣狭窄","二尖瓣上赘生物形成","肺动脉瓣狭窄","主动脉瓣狭窄"],"a":0,"e":"收缩中晚期喀喇音由二尖瓣瓣叶在收缩期脱入左房、瓣叶或腱索突然紧张产生，合并收缩晚期杂音即为二尖瓣脱垂综合征，是该病的特征性听诊表现。二尖瓣狭窄项为舒张期隆隆样杂音；肺动脉瓣狭窄项与主动脉瓣狭窄项为收缩期喷射性杂音伴收缩早期喷射音；赘生物形成项多产生乐音样杂音，均非中晚期喀喇音"},{"q":"粒细胞减少症主要是指外周血中性粒细胞计数持续低于","o":["5.0×109/L","1.5×109/L","4.0×109/L","2.0×109/L","3.0×109/L"],"a":1,"e":"中性粒细胞绝对值持续低于1.5×10^9/L即为粒细胞减少症，是白细胞减少中更具临床意义的部分，易继发感染。低于0.5×10^9/L项实为粒细胞缺乏症，病情更危重；白细胞总数低于参考区间下限项称白细胞减少，与粒细胞减少概念不同；4.0×10^9/L与5.0×10^9/L处于白细胞总数正常范围，不构成粒细胞减少"},{"q":"判断肺实变最敏感的指标是","o":["病理性支气管呼吸音","胸语音","耳语音","叩诊浊音","语音震颤增强"],"a":2,"e":"耳语音检查时患者以耳语声调发音，正常胸壁仅闻及极微弱音响，肺实变时因组织传导增强可清楚听到音调较高的耳语音，是发现肺实变最敏感的听诊体征。病理性支气管呼吸音项、胸语音项与语音震颤增强项虽也是实变体征，但出现相对较晚；叩诊浊音项需实变范围较大才明显，敏感性不及耳语音"},{"q":"正常情况下，哪个腔室产生最大的电活动","o":["左心房","左心室","右心房","右心室","心房"],"a":1,"e":"正常心室除极综合向量以左心室占优势，因左室壁厚、心肌质量远大于右室，产生的电动力最大，这也是胸导联R波自V1至V5逐渐增高的原因。左心房项与右心房项除极形成P波，电压较低；右心室项壁薄、电动力小，仅在右室肥厚时优势改变；心房项笼统，不能与心室相比"},{"q":"IgA IgD和IgE型的免疫球蛋白不能与C1q结合，是由于","o":["分子结构容易","Fc段无补体结合位点","Fab段无补体结合位点","VH无补体结合位点","VL无补体结合位点"],"a":1,"e":"补体经典途径的启动依赖C1q与免疫球蛋白Fc段的结合位点，该位点位于IgG的CH2区或IgM的CH3区；IgA、IgD与IgE的Fc段缺乏此结构，故不能结合C1q、不能激活经典途径。Fab段项实为抗原结合部位；VH项与VL项即可变区，决定抗原特异性，均不参与补体结合"},{"q":"下列情况可见血块退缩不良，不会见于下列哪一种情况","o":["血小板减少性紫癜","血小板功能异常","凝血因子异常","纤维蛋白原显著降低","过敏性紫癜"],"a":4,"e":"血块退缩依赖血小板数量与功能及纤维蛋白原、凝血因子正常，血小板减少性紫癜、血小板功能异常、凝血因子异常与纤维蛋白原显著降低时均可出现退缩不良。过敏性紫癜项实为血管壁通透性与脆性增加所致血管性紫癜，血小板计数与凝血功能均正常，血块退缩不受影响，故不会见于该病"},{"q":"下列是吸气性呼吸困难的特点，但应除外","o":["吸气显著困难","重者出现“三凹征”","常伴有干咳及高调吸气性喉鸣","常伴有手足搐搦","常见于喉部及气管疾病（如喉水肿、气管异物）"],"a":3,"e":"吸气性呼吸困难因喉部、气管等上呼吸道狭窄阻塞所致，表现为吸气显著困难、重者出现三凹征，常伴干咳及高调吸气性喉鸣。常伴有手足搐搦项实为精神性呼吸困难的特点，由过度通气导致呼吸性碱中毒；吸气显著困难项、三凹征项、喉鸣项与喉部及气管疾病病因项均符合吸气性呼吸困难的典型表现"},{"q":"下列因素均是功能性便秘的原因，但除外","o":["进食量少","甲状腺功能亢进症","肠易激综合征","应用抗胆碱能药","腹肌及盆肌张力不足"],"a":1,"e":"功能性便秘多因进食量少、膳食纤维不足、肠易激综合征、抗胆碱能药物抑制肠蠕动或腹肌盆肌张力不足导致排便动力缺乏。甲状腺功能亢进症项实为腹泻原因，因代谢亢进、肠蠕动加快；其余四项分别通过减少肠内容物、改变肠动力、药物抑制与排便肌力不足促成便秘，均属功能性病因"},{"q":"焦虑症的核心症状是","o":["紧张不安","过度担心","胸闷气短","睡眠困难","警觉性增高"],"a":1,"e":"焦虑症的精神病理核心是过度担心，即对尚未发生或难以预料的危险与不幸事件产生与现实不相称的担忧，属预期性焦虑，并常伴自主神经症状与运动性不安。紧张不安项与警觉性增高项为焦虑的常见伴随表现；胸闷气短项属自主神经反应；睡眠困难项为继发症状，均非核心特征"},{"q":"在各种免疫球蛋白中，初次免疫应答有关的是","o":["IgG","IgA","IgM","IgE","IgD"],"a":2,"e":"IgM是初次免疫应答中最早出现的抗体，无论在个体发育还是抗原刺激后均先于其他免疫球蛋白产生，提示原发性感染，如脐血IgM升高提示宫内感染。IgG项实为再次免疫应答的主要抗体、血清含量最高；IgA项主要参与黏膜局部免疫；IgE项与Ⅰ型超敏反应及寄生虫感染相关；IgD项多为B细胞表面受体"},{"q":"下列为舒张期额外心音，但应除外哪项","o":["奔马律","喀喇音","开瓣音","心包叩击音","肿瘤扑落音"],"a":1,"e":"舒张期额外心音包括舒张早期奔马律、舒张晚期奔马律、开瓣音、心包叩击音与肿瘤扑落音，分别提示心室负荷过重、二尖瓣狭窄、缩窄性心包炎与心房黏液瘤。喀喇音项实为收缩期额外心音，出现于第一心音后0.08秒以上，由二尖瓣脱入左房、腱索突然拉紧产生，不属于舒张期额外心音"},{"q":"胸骨左缘第2肋间的收缩期震颤，最常见于","o":["主动脉瓣狭窄","肺动脉瓣狭窄","主动脉瓣关闭不全","肺动脉瓣关闭不全","动脉导管未闭"],"a":1,"e":"胸骨左缘第2肋间为肺动脉瓣区，该处收缩期震颤最常见于肺动脉瓣狭窄，因血流通过狭窄瓣口产生湍流，常伴粗糙的收缩期喷射性杂音与P2减弱。胸骨右缘第2肋间收缩期震颤项实为主动脉瓣狭窄；同一部位连续性震颤项提示动脉导管未闭；胸骨左缘第3～4肋间收缩期震颤项对应室间隔缺损；心尖区舒张期震颤项见于二尖瓣狭窄"},{"q":"肝细胞中与胆红素结合的主要物质是","o":["乙酰基","硫酸根","甲基","葡萄糖醛酸","甘氨酸"],"a":3,"e":"肝细胞摄取非结合胆红素后，在滑面内质网经葡萄糖醛酸转移酶催化，与葡萄糖醛酸结合生成单或双葡萄糖醛酸胆红素，即结合胆红素，水溶性增加后可随胆汁排入肠道。乙酰基项、硫酸根项、甲基项与甘氨酸项均非肝细胞内胆红素结合的主要物质；胆红素在肠道还原为尿胆原，与肝细胞结合过程无关"},{"q":"关于主诉的描述，以下正确的是","o":["主诉不能出现疾病名称","主诉是患者的主要症状，不能包括客观体征","主诉多于一个症状时，一般按照症状的重要程度排序","主诉一般不能超过20个字","主诉应包括患者的所有症状"],"a":3,"e":"主诉是患者最主要的症状或体征及其持续时间，要求简明精练，一般一至两句、20字左右，故以20字为限的描述正确。主诉不能出现疾病名称项过于绝对；不能包括客观体征项与事实不符，体征亦可作主诉；按重要程度排序项实为按发生先后；包括所有症状项违背简明原则，均非正确描述"},{"q":"正常成人肺下界的移动范围是","o":["4～6cm","6～8cm","5～7cm","7～9cm","3～5cm"],"a":1,"e":"正常成人肺下界移动范围为6～8cm，由深吸气与深呼气时肺下界最高、最低两点间距离测得，移动度与肋膈窦大小有关，腋中线及腋后线处最大。4～6cm项与5～7cm项低于正常下限；7～9cm项偏高；3～5cm项明显减小，均不符合正常参考范围"},{"q":"下述问诊方法，正确的是","o":["问诊中可以经常做些疾病相关情况的引导提示","可以对病人重复提问","避免使用有特定意义的医学术语","不要在问诊中核实病人陈述过去的不确切病史","问诊时医生语音要严肃、锐利"],"a":2,"e":"问诊必须使用患者易懂的词语，避免带有特定含义的医学术语，以免患者误解或顺从回答，影响病史真实性。问诊中经常做引导提示项实为暗示性提问，应予避免；对病人重复提问项会降低患者信心；不核实不确切病史项易致资料失真；语音严肃锐利项不利于建立信任，均非正确方法"},{"q":"门诊接诊一名发热的患者，首先应主要收集哪方面病史","o":["发热的伴随症状","发热的治疗过程","患者做过哪些检查","患者发热的时间、规律及热型","患者有无特殊人群接触史"],"a":3,"e":"门诊接诊发热患者，首先应问清发热的时间、规律及热型，如稽留热、弛张热、间歇热等，因不同病因热型各异，对病因判断和鉴别诊断最有价值。发热的伴随症状项、治疗过程项与检查项属进一步补充内容；特殊人群接触史项用于流行病学判断，均应在掌握热型基础上再采集"},{"q":"二尖瓣相对性关闭不全的杂音可见于下列疾病，但应除外","o":["扩张型心脏病","贫血性心脏病","高血压心脏病","乳头肌功能失调","风湿性心脏病主动脉瓣狭窄"],"a":3,"e":"二尖瓣相对性关闭不全指瓣叶本身无病变，因左心室或瓣环扩大致对合不良，扩张型心肌病、贫血性心脏病与高血压心脏病均可通过左室扩大引起。乳头肌功能失调项实为器质性二尖瓣关闭不全的原因，因瓣下结构受损致瓣叶对合障碍；其余三项均以心腔或瓣环扩大为基础，属相对性关闭不全范畴"},{"q":"主动脉瓣狭窄重要的体征是","o":["主动脉瓣区可闻及收缩期喷射性杂音","主动脉瓣区第二心音减弱","脉压小","杂音向颈部传导","脉细弱，呈迟脉"],"a":0,"e":"主动脉瓣狭窄最重要、最典型的体征是主动脉瓣区粗糙响亮的收缩期喷射性杂音，呈递增递减型，向颈部传导，常伴震颤，反映瓣口狭窄与血流加速。主动脉瓣区第二心音减弱项、脉压小项与脉细弱呈迟脉项均为伴随的周围血管表现；杂音向颈部传导项是杂音的特性而非独立体征，重要性不及杂音本身"},{"q":"作Valsalva动作时，可使下列疾病的杂音增强的是","o":["特发性肥厚性主动脉瓣下狭窄","主动脉瓣狭窄","肺动脉瓣狭窄","扩张型心肌病","法洛四联症"],"a":0,"e":"Valsalva动作使胸腔内压升高、回心血量减少，经瓣膜产生的杂音一般减轻，而特发性肥厚性主动脉瓣下狭窄因左室容量减小、流出道梗阻加重，杂音反而增强。主动脉瓣狭窄项、肺动脉瓣狭窄项与法洛四联症项的杂音随回心血量减少而减弱；扩张型心肌病项多因心腔扩大致相对性关闭不全，杂音亦不增强"},{"q":"胸壁有静脉曲张，血流方向自下而上，见于","o":["上腔静脉梗阻","下腔静脉梗阻","哺乳期妇女","胸腔淋巴管阻塞","门静脉高压"],"a":1,"e":"下腔静脉梗阻时，下半身血液经腹壁浅静脉向上回流，故胸腹壁曲张静脉血流方向自下而上，是判断梗阻部位的重要依据。上腔静脉梗阻项血流方向自上而下；门静脉高压项表现为脐周静脉放射状曲张，脐以上向上、脐以下向下，呈水母头；哺乳期妇女项仅为静脉显露，无方向异常；胸腔淋巴管阻塞项不引起静脉曲张"},{"q":"第二心音通常分裂中，由肺动脉瓣关闭明显迟于主动脉瓣关闭时间所致的病变中，最常见的是","o":["完全右束支传导阻滞","二尖瓣关闭不全","室间隔缺损","完全左束支传导阻滞","主动脉瓣狭窄"],"a":0,"e":"第二心音通常分裂指肺动脉瓣关闭明显迟于主动脉瓣，最常见于完全性右束支传导阻滞，因右室激动与收缩延迟使P2后移，吸气时更明显。完全左束支传导阻滞项致主动脉瓣关闭延迟，出现逆分裂；二尖瓣关闭不全项与室间隔缺损项主要产生收缩期杂音；主动脉瓣狭窄项可致S2反常分裂，均非通常分裂的常见原因"},{"q":"关于Damoiseau曲线的描述，下列正确的是","o":["患者取坐位时，积液的上界呈一弓形曲线","曲线的最低点位于同侧脊柱旁","曲线的最高点在腋中线上","曲线由内上方向外下方下降","曲线形成是因为胸腔内侧承受液体的阻力最大"],"a":0,"e":"Damoiseau曲线是中等量胸腔积液患者取坐位时叩诊所得的弓形上界，最低点位于对侧脊柱旁，最高点在腋后线，由最高点向内下方下降。曲线最低点位于同侧脊柱旁项与最高点在腋中线项均与描述不符；由内上方向外下方下降项方向相反；胸腔内侧承受液体阻力最大项不是形成机制，实为肺组织弹性回缩与胸腔负压差异所致"},{"q":"下列均为腹部触诊的内容，但除外","o":["腹壁紧张度","压痛","腹部肿块","振水音","移动性浊音"],"a":4,"e":"腹部触诊内容包括腹壁紧张度、压痛与反跳痛、腹部肿块以及振水音等，通过手的感觉判断腹内脏器与腹膜情况。移动性浊音项实为腹部叩诊内容，需借助体位改变叩击浊音区判断有无腹腔积液，不属触诊范畴；腹壁紧张度项、压痛项与腹部肿块项分别判断腹膜刺激与包块性质，振水音项借冲击触诊听取胃内液体振荡声"},{"q":"仅与体液免疫有关的细胞是","o":["Th2细胞","TDTH细胞","Th0","Th1细胞","CTL细胞"],"a":0,"e":"Th2细胞通过分泌IL-4、IL-5、IL-6等细胞因子辅助B细胞活化、增殖并分化为浆细胞产生抗体，仅参与体液免疫。Th1细胞项与TDTH细胞项均参与细胞免疫及迟发型超敏反应；CTL细胞项即细胞毒性T细胞，直接杀伤靶细胞；Th0项为尚未分化的初始T细胞，可向Th1或Th2分化，不专属体液免疫"},{"q":"由凝血障碍引起皮肤黏膜出血的疾病是","o":["原发免疫性血小板减少症","严重肝脏疾病","再生障碍性贫血","巨幼细胞贫血","过敏性紫癜"],"a":1,"e":"严重肝脏疾病时肝细胞受损，纤维蛋白原、凝血酶原及其他凝血因子合成减少，导致凝血功能障碍，出现皮肤黏膜出血倾向。原发免疫性血小板减少症项、再生障碍性贫血项与巨幼细胞贫血项均因血小板减少或生成异常所致；过敏性紫癜项属血管壁通透性增加的血管性出血，均非凝血因子缺乏"},{"q":"网织红细胞成人参考值（百分数）为","o":["0.1%～1.1%","0.2%～1.2%","0.3%～1.3%","0.4%～1.4%","0.5%～1.5%"],"a":4,"e":"网织红细胞为晚幼红细胞脱核后的未成熟红细胞，成人百分数参考区间0.5%～1.5%，计数反映骨髓红系造血：溶血、急性失血及贫血治疗有效时增高，再生障碍性贫血时减少。A项0.1%～1.1%、B项0.2%～1.2%起点过低，C项0.3%～1.3%与D项0.4%～1.4%整体下移，均非成人参考区间"},{"q":"有关PEF的描述正确的是","o":["反映日变异率","是用力肺活量测定过程中，呼气流速最快的瞬间流速","日常变异率≥15%对支气管哮喘诊断有意义","日常变异率正常值＜15%","主要反映小气道有无阻塞"],"a":1,"e":"最大呼气流量(PEF)指用力肺活量测定过程中呼气流速最快时的瞬间流速，主要反映呼吸肌力量及气道有无阻塞。C项日常变异率≥20%才对哮喘诊断有意义，15%数值偏小；D项正常变异率应＜20%而非＜15%；A项反映日变异率的是PEF日间变异率这一衍生指标，并非PEF本身；E项小气道阻塞需靠小气道功能检查，PEF主要反映大气道"},{"q":"波状热最常见的疾病是","o":["霍奇金病","重症肺结核","疟疾","伤寒","布氏杆菌病"],"a":4,"e":"波状热体温渐升至39℃以上，数天后渐降至正常，反复多次，最常见于布鲁氏菌病，与布鲁氏菌感染后反复菌血症有关。C项疟疾表现为间歇热，寒战高热与无热期规律交替；D项伤寒为稽留热；A项霍奇金病可见回归热；B项重症肺结核多为弛张热或不规则热，均非波状热"},{"q":"下面关于第二心音的叙述中，不正确的是","o":["标志着心室舒张的开始","半月瓣突然关闭引起的瓣膜振动所产生的","房室瓣的关闭也参与第二心音的形成","在心尖搏动之后出现","心底部听诊最清楚"],"a":2,"e":"第二心音在心室舒张开始时出现，主要由主动脉瓣与肺动脉瓣突然关闭、血流减速引起瓣膜振动产生，音调高而脆，心底部听诊最清楚。C项称房室瓣关闭参与S2形成不成立，参与S2的是房室瓣的开放及半月瓣关闭；A、B、D、E四项分别对应S2的时相、机制、与心尖搏动不同步及听诊部位，均正确"},{"q":"下列关于心脏视诊要点的叙述都正确，但除外","o":["应在温暖环境自然光线下进行","患者采取仰卧位，检查者站在患者右侧","观察心前区异常隆起和搏动时，两眼应与胸廓同高","视诊心尖冲动时，双眼应与心尖区呈垂直位置","检查者站在患者右侧，双眼视线与心尖呈切线位"],"a":3,"e":"视诊心尖冲动时双眼应与心尖区呈切线位，视线与胸壁相切才能看清搏动的幅度与范围；若呈垂直位置俯视，搏动会被胸壁遮挡。D项所述垂直位置错误，E项切线位才是正确方法。C项观察心前区隆起时两眼与胸廓同高、B项仰卧位检查者站右侧、A项温暖自然光线下进行，均为视诊基本要求"},{"q":"如图，心电图诊断正确的是","o":["三度房室传导阻滞","窦性心动过缓","窦性停搏","二度房室传导阻滞","心房扑动"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。三度房室传导阻滞的心电图为P波与QRS波各自独立、互不相关，心房率快于心室率，可伴交界性或室性逸搏心律。窦性心动过缓每个P波后均有QRS波群；窦性停搏表现为长间歇内无P波；二度房室传导阻滞存在部分下传的QRS；心房扑动见锯齿状F波\n\n官方题库中缺失图片"},{"q":"脑脊液白细胞数1000×106/L以上，以多核细胞为主，蛋白质增高，糖和氯化物降低，首先考虑哪种诊断的可能","o":["细菌性脑膜炎","病毒性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":0,"e":"脑脊液白细胞显著增多并以多核细胞为主，蛋白增高、糖和氯化物降低，是细菌性脑膜炎的典型改变，因中性粒细胞浸润和细菌消耗糖所致。B项病毒性脑膜炎糖与氯化物正常、以淋巴细胞为主；C项结核性脑膜炎和D项隐球菌性脑膜炎均起病较缓，以淋巴细胞为主，糖降低但白细胞多为数百；E项流行性乙型脑炎属病毒性"},{"q":"55岁男性，胸痛1小时入院，现病史还需要问","o":["胸痛发生的急缓","有无冠心病","胸痛的性质和程度","胸痛的部位及有无放射","胸痛的诱因"],"a":1,"e":"55岁急性胸痛患者，现病史采集除疼痛特点外还须追问既往有无冠心病及类似发作史，以判断本次发作的基础病因与危险分层，这是本题的关键补充。A项急缓、C项性质程度、D项部位及放射、E项诱因均属胸痛本身特征的常规描述，为基础问诊内容；既往冠心病史则直接决定病因判断与处理方向"},{"q":"左心功能减退时，出现第二心音逆分裂，是因为","o":["吸气时，右室射血期延长","吸气时，左室射血期延长","呼气时，左室射血期延长","呼气时，右室射血期延长","呼气时，左室射血期缩短"],"a":2,"e":"第二心音逆分裂指主动脉瓣关闭明显晚于肺动脉瓣，呼气相分裂反而明显，见于左室射血时间延长的疾病。左心功能减退、主动脉瓣狭窄时左室射血延长，呼气时更显著，故选呼气时左室射血期延长。A、D项涉及右室射血延长，见于二尖瓣狭窄伴肺动脉高压等，表现为通常分裂且吸气明显；B项吸气时左室射血延长不符合生理"},{"q":"下列可以传导头痛感觉的脊神经是","o":["第1/2/3颈神经","第4/5/6颈神经","第7颈神经","第1/2胸神经","第3/4/5胸神经"],"a":0,"e":"头痛的牵涉与传导可经上三对颈神经(C1～C3)实现，枕大神经、枕小神经等来自高位颈神经，故传导头痛感觉的脊神经为第1/2/3颈神经。B项第4/5/6颈神经主要支配颈肩部感觉与运动，其病变多表现为颈肩痛；C项第7颈神经支配上肢；D、E项胸神经支配躯干与腹壁，均不传导头部感觉"},{"q":"关于再生障碍性贫血的骨髓象和血象，错误的是","o":["呈全血细胞减少，少数病例早期可仅1系或2系细胞减少","网织红细胞减低","骨髓小粒镜检空虚","非造血细胞减少","骨髓造血功能低下"],"a":3,"e":"再生障碍性贫血为骨髓造血功能衰竭，血象呈全血细胞减少、网织红细胞减低，骨髓造血功能低下、骨髓小粒镜检空虚，非造血细胞(淋巴细胞、浆细胞、组织细胞等)比例反而增高。D项称非造血细胞减少与再障骨髓象相反，故错误。A、B、C、E四项分别符合再障的全血细胞减少、网织红细胞低、小粒空虚与造血低下"},{"q":"引起中枢性呕吐的病因包括下列疾病，但除外","o":["脑膜炎","迷路炎","颅内血肿","脑出血","抗癌药物"],"a":1,"e":"迷路炎为化脓性中耳炎并发的前庭周围性病变，眩晕伴呕吐属周围性前庭性呕吐，不属中枢性呕吐，故选迷路炎。A项脑膜炎、C项颅内血肿、D项脑出血均因颅内压增高或刺激呕吐中枢引起中枢性呕吐；E项抗癌药物通过刺激催吐化学感受区导致中枢性呕吐"},{"q":"不出现枪击音的病理情况是","o":["主动脉瓣关闭不全","甲状腺功能亢进症","严重贫血","心力衰竭","动脉导管未闭"],"a":3,"e":"枪击音属周围血管征，因脉压增大、血流冲击动脉壁所致，见于主动脉瓣关闭不全、甲状腺功能亢进、严重贫血及动脉导管未闭等高动力状态。心力衰竭时心肌收缩力下降、脉压减小，不出现枪击音。A、B、C、E四项均可致脉压增大而出现枪击音，D项心力衰竭脉压小，故为例外"},{"q":"当体重增加超过标准体重多少时称为肥胖","o":["超过10%","超过18、5%","超过20%","超过28%","超过30%"],"a":2,"e":"体重超过标准体重10%为超重，超过20%为肥胖，须排除肌肉发达或水分潴留因素，故选超过20%。A项10%为超重界限而非肥胖；B项18.5%为体重指数正常下限的混淆数值；D项28%为我国BMI肥胖界值、E项30%为WHO的BMI肥胖界值，二者均以BMI而非标准体重百分比计，故不合题意"},{"q":"第三心音（S3）符合下述哪项描述","o":["一种音调高的声音","老年患者的正常发现","呼气末听诊较清楚","坐位或立位时增强","胸骨左缘Ⅳ肋间听诊最清楚"],"a":2,"e":"第三心音出现在心室舒张早期快速充盈期末，因血流冲击室壁使心室壁、腱索、乳头肌振动产生，音调轻而低，局限于心尖区或其内上方，仰卧位、呼气时较清楚，故呼气末听诊较清楚正确。A项音调高是对S2的描述，S3音调低；B项S3在健康儿童青少年可闻及，老年患者出现多为病理性；D项立坐位时S3减弱；E项胸骨左缘Ⅳ肋间非其最佳听诊区"},{"q":"下列关于正常体温的描述哪项是正确的","o":["腋窝体温一般为36.5～37℃","正常体温每日波动范围不超过0.5℃","一般下午体温较早晨稍低","一般肛门内体温比腋窝体温略低","剧烈运动或进餐后体温可略升高"],"a":4,"e":"正常体温受内外因素影响略有波动，剧烈运动、劳动或进餐后产热增加，体温可略升高，故选E。A项腋窝体温正常为36～37℃；B项24小时波动范围一般不超过1℃而非0.5℃；C项下午体温较早晨稍高而非稍低；D项肛门内体温比腋窝高约0.5℃，是三者中最高的，不是略低"},{"q":"下述是深部滑行触诊的方法，哪项是不正确的","o":["检查时嘱病人张口平静呼吸","检查时嘱病人深呼气后屏气","可以与病人谈话以转移其注意力","医生同时并拢二、三、四指末端逐渐触向腹腔的脏器或包块","触诊时在触及物上做上、下、左、右滑动触摸"],"a":1,"e":"深部滑行触诊法检查时嘱病人张口平静呼吸，或与病人谈话转移注意力，使腹肌松弛，医生以并拢的二、三、四指末端逐渐触向腹腔脏器或包块，并在其上下左右滑动触摸。B项嘱病人深呼气后屏气属于肝脏触诊或穿刺等配合方法，不是深部滑行触诊的要求。A、C、D、E四项均符合该手法操作要点"},{"q":"下列哪项不是导致假性血尿的原因","o":["服用利福平","食用甜菜","卟啉代谢障碍或损伤引起的肌红蛋白尿","痔疮出血","精囊腺炎"],"a":4,"e":"假性血尿指尿色发红但镜检无红细胞，见于利福平、甜菜等色素摄入，血红蛋白尿、肌红蛋白尿及卟啉代谢障碍，或痔疮出血、月经血污染。精囊腺炎表现为血精及精液性状改变，并不导致尿色发红，故为除外项。A、B项为食物药物色素，C项为血红蛋白/肌红蛋白尿，D项为邻近部位出血污染"},{"q":"血友病A B分别缺乏以下哪种凝血因子","o":["FⅣ、FⅧ","FⅢ、FⅤ","FⅧ、FⅪ","FⅧ、FⅨ","FⅪ、FⅨ"],"a":3,"e":"血友病A为凝血因子Ⅷ缺乏，血友病B为因子Ⅸ缺乏，二者均为X连锁隐性遗传的内源性凝血途径障碍，APTT延长，故选FⅧ、FⅨ。A项FⅣ不是血友病缺乏因子；C项FⅪ缺乏为因子Ⅺ缺乏症；B、E项中FⅢ、FⅤ、FⅪ组合均不符合血友病A、B的因子定义"},{"q":"RBC结构异常见于下列情况，但应除外","o":["嗜碱性点彩","染色质小体","Cabot环","有核RBC","镰形细胞"],"a":4,"e":"红细胞结构异常指Wright-Giemsa染色后红细胞内出现特殊有形成分，包括嗜碱性点彩、染色质小体、Cabot环及有核红细胞等。镰形细胞属于红细胞形态(形状)异常，由HbS聚合所致，不属结构异常，故为除外项。A、B、C、D四项均为红细胞内异常结构的经典内容"},{"q":"门诊病历的书写，下列哪项不正确","o":["症状及体征","检查结果及分析","急症患者在24h内完成即可","现病史","治疗措施"],"a":2,"e":"门(急)诊病历应及时书写，抢救记录于抢救结束后6小时内完成，入院记录才是在病人入院后24小时内完成。C项把24小时用于急症门诊病历，属于时限混淆，故不正确。A项症状及体征、B项检查结果及分析、D项现病史、E项治疗措施，均属门诊病历应包含的基本内容"},{"q":"适用于体表浅在病变检查和评估的是","o":["冲击触诊法","双手触诊法","深压触诊法","滑动触诊法","浅部触诊法"],"a":4,"e":"浅部触诊法用掌指关节和腕关节协同动作以旋转或滑动方式轻压触摸，可触及深度约1cm，适用于体表浅在病变如关节、软组织、浅部动静脉、神经、阴囊和精索的检查和评估。A项冲击触诊法用于大量腹腔积液；B项双手触诊法用于肝脾肾等；C项深压触诊法用于压痛点及反跳痛；D项滑动触诊法多用于腹腔脏器，均非体表浅在病变首选"},{"q":"发作性呼吸困难伴哮鸣音，最常见于","o":["大叶性肺炎","渗出性胸膜炎","气胸","喉癌","支气管哮喘"],"a":4,"e":"发作性呼吸困难伴哮鸣音以支气管哮喘最常见，为气道高反应性导致广泛气道痉挛，呼气性呼吸困难伴弥漫性哮鸣音。A项大叶性肺炎以发热、铁锈色痰为主；B项渗出性胸膜炎以胸痛、呼吸受限为主；C项气胸突发呼吸困难但多无哮鸣音；D项喉癌表现为吸气性呼吸困难与局限性喘鸣"},{"q":"E试验与纸片琼脂扩散法的不同之处是","o":["接种菌准备","平板接种","测出药物的MIC","孵育时间","孵育温度"],"a":2,"e":"E试验采用含浓度梯度的塑料条，孵育后可直接读取抑菌圈与条交界处刻度，测出药物的最小抑菌浓度(MIC)，这是与K-B纸片琼脂扩散法最本质的区别。A项接种菌准备、B项平板接种、D项孵育时间、E项孵育温度两法基本相同，均按标准化操作，故不能作为鉴别点"},{"q":"下列均为临床诊断思维方法，但除外","o":["实事求是的对待客观临床资料","首先考虑功能性疾病，然后再考虑器质性疾病","尽量用一种疾病解释多种临床表现","几种诊断同时存在，首先选择多发病的诊断","简化思维程序的原则"],"a":1,"e":"临床诊断思维要求实事求是对待客观资料，尽量用一种疾病解释多种表现，多种诊断并存时首选多发病，并遵循简化思维程序原则。在器质性与功能性疾病鉴别困难时应首先考虑器质性疾病，以免延误治疗；B项主张先考虑功能性疾病，与该原则相反，故为除外项。A、C、D、E四项均为正确的诊断思维方法"},{"q":"治疗史隶属于","o":["既往史","系统回顾","现病史","婚姻史","个人史"],"a":2,"e":"现病史记录本次疾病的发生、演变及诊疗经过，患者针对本次疾病接受的治疗及其反应属于现病史中的诊疗情况。治疗史不应归入A项既往史，既往史记录既往疾病史；也不属B项系统回顾、D项婚姻史或E项个人史，后三者分别记录各系统症状、婚育情况及生活经历"},{"q":"以下哪项是输血同意书不需包括的内容","o":["患者年龄","科别","输血指征","血型","医师签名"],"a":3,"e":"输血治疗同意书是履行告知与签字的文书，需载明患者姓名、年龄、科别等身份信息、诊断与输血指征、输血风险及医师签名，作为同意与免责依据。D项血型属于实验室血型鉴定与交叉配血记录内容，载于病历检验部分，并非同意书必备项目。A、B、C、E四项分别属于身份信息、指征告知与生效签名要件"},{"q":"下列疾病均出现肝大，但除外","o":["脂肪肝","早期肝硬化","Budd-Chiari综合征","肝炎","亚急性重型肝炎"],"a":4,"e":"急性与亚急性重型肝炎因肝细胞广泛坏死肝脏缩小，故不出现肝大，为除外项。A项脂肪肝、D项肝炎均可致肝大且质地稍韧；C项Budd-Chiari综合征因肝静脉回流受阻而肝大；B项早期肝硬化肝脏可增大，晚期才缩小"},{"q":"下述情况可出现异常支气管呼吸音，但除外","o":["大叶肺炎实变期","肺脓肿","空洞型肺结核","气胸","胸腔积液"],"a":3,"e":"异常支气管呼吸音需肺组织致密、传导增强才产生，见于大叶肺炎实变期、肺脓肿、空洞型肺结核及胸腔积液上方的压迫性肺不张。D项气胸时胸膜腔积气，肺被压缩、含气量减少且呼吸音减弱或消失，不利于支气管音传导，故不出现异常支气管呼吸音。A、B、C、E四项均可形成有利于传导的实变或压迫性不张"},{"q":"本例患者行本次心电图检查时，心室率大约是","o":["65次/min","55次/min","40次/min","35次/min","80次/min"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心室率需依据心电图RR间期计算，40次/min属显著心动过缓，多见于三度房室传导阻滞或交界性、室性逸搏心律。65次/min与80次/min在正常或轻度增快范围；55次/min为轻度窦性心动过缓；35次/min更慢，常见于室性逸搏或严重传导阻滞，均需结合图或病例判断\n\n官方题库中缺失图片"},{"q":"以下各诊断属于病因诊断的是","o":["肝硬化","风湿性心脏病","尿毒症","肾小球肾炎","心功能不全"],"a":1,"e":"病因诊断是能指出疾病根本病因的诊断，风湿性心脏病由风湿热所致，明确了病因，故属病因诊断。A项肝硬化、C项尿毒症、E项心功能不全多反映病理形态或功能状态，属病理生理或功能诊断；D项肾小球肾炎以病变性质命名，归为病理诊断而非病因诊断"},{"q":"肺泡呼吸音减弱不易见于","o":["肺气肿","胸腔积液","气胸","尿毒症性酸中毒","肺不张"],"a":3,"e":"尿毒症性酸中毒时血中酸性代谢产物增多，刺激呼吸中枢出现深长快速的Kussmaul呼吸，肺泡呼吸音增强而非减弱，故选尿毒症性酸中毒。A项肺气肿肺泡含气过多、B项胸腔积液与C项气胸使肺受压或含气减少、E项肺不张通气受限，均导致肺泡呼吸音减弱"},{"q":"呕吐过程中包括下列动作，但除外","o":["胃引力减弱","膈肌上升","腹肌收缩","胃窦部收缩","贲门开放"],"a":1,"e":"呕吐是复杂反射动作，表现为胃张力减低(胃引力减弱)、贲门开放、胃窦收缩，同时膈肌下降并腹肌收缩以升高腹压，将胃内容物排出。B项膈肌上升与呕吐时膈肌下降、参与增加腹压的机制相反，故为除外项。A、C、D、E四项分别为胃张力改变、腹肌与胃窦收缩及贲门开放，均属呕吐动作"},{"q":"慢性上腹痛最常见的病因是","o":["消化性溃疡","慢性胰腺炎","胃癌","肠寄生虫病","慢性胆囊炎"],"a":0,"e":"慢性反复发作、具周期性与节律性的上腹痛是消化性溃疡的典型表现，故消化性溃疡为慢性上腹痛最常见病因。B项慢性胰腺炎多为持续性上腹痛伴脂肪泻；C项胃癌多见于中老年，疼痛无规律并伴消瘦贫血；D项肠寄生虫病以脐周痛为主；E项慢性胆囊炎疼痛位于右上腹并向右肩放射"},{"q":"梗阻性黄疸的原因最常见的是","o":["肝细胞内胆红素蓄积过多","大量红细胞破坏","肝细胞膜通透性增大","肝内胆管胆汁淤积","肝细胞内胆红素结合过多"],"a":3,"e":"梗阻性(胆汁淤积性)黄疸由胆道梗阻或胆汁分泌障碍致结合胆红素反流入血，肝内胆管胆汁淤积是其常见原因，故选D。A项肝细胞内胆红素蓄积过多与C项肝细胞膜通透性增大属肝细胞性黄疸机制；B项大量红细胞破坏致非结合胆红素增多，属溶血性黄疸；E项胆红素结合障碍亦非梗阻机制"},{"q":"血浆内常被测定的主要阴离子是","o":["Cl－与HCO3－","Cl－与SO42－","HCO3－与SO42－","HCO3－与HPO42－","Cl－与HPO42－"],"a":0,"e":"血浆中主要阳离子为Na+，主要阴离子为Cl－和HCO3－，二者是血浆渗透压与酸碱平衡的主要成分，也是阴离子间隙计算的组成项。B、C项中的SO42－与D、E项中的HPO42－在血浆中浓度较低，属未测定阴离子，不是常测定的主要阴离子"},{"q":"下列关于测量血压的描述哪项是正确的","o":["正常人从左右两臂测出的数值相差大约20mmHg","当Korotkoff音消失时为收缩压","听诊器胸件塞在袖带下","测下肢血压应选较窄的袖带","测量前，病人应在安静环境下休息5～10min"],"a":4,"e":"测量血压前病人应在安静环境休息5～10分钟，半小时禁烟禁咖啡、排空膀胱，故选E。A项正常人双上肢血压相差约5～10mmHg而非20mmHg；B项Korotkoff音消失为舒张压，出现时为收缩压；C项听诊器胸件应置于袖带下缘之外，不能塞入袖带下；D项测下肢血压应选较宽袖带而非较窄"},{"q":"以手按压胸部皮下气肿的部位，可出现","o":["水泡音","捻发音","握雪感","压痛","揉面感"],"a":2,"e":"胸部皮下气肿时气体积存于皮下组织，用手按压可使气体在组织间隙移动，产生握雪感(捻发感)，故选握雪感。B项捻发音为听诊时类似捻动头发的声音或湿啰音，不是按压手感；A项水泡音属湿啰音；D项压痛为炎症或损伤表现；E项揉面感见于结核性腹膜炎的腹壁触诊"},{"q":"下列为自主神经功能检查项目，但不包括","o":["眼心反射","卧立试验","竖毛反射","角膜反射","皮肤划纹征"],"a":3,"e":"自主神经功能检查包括眼心反射、卧立试验、竖毛反射、皮肤划纹征等，用以评估交感与副交感神经功能。D项角膜反射由三叉神经传入、面神经传出，属脑神经反射，用于检查脑神经与意识状态，不属自主神经功能检查项目。A、B、C、E四项均为自主神经检查的常规方法"},{"q":"在心电图上最早出现的幅度较小的P波，反映的是","o":["心房的复极过程","心房的除极过程","心室的复极过程","心室的除极过程","心房到心室激动的一个完整过程"],"a":1,"e":"P波是心电图上最早出现的幅度较小的波，反映心房的除极过程，故选心房的除极过程。A项心房复极过程主要由PR段反映；C项心室复极过程对应T波；D项心室除极过程对应QRS波群；E项心房到心室激动的完整过程涵盖PR间期，均非P波本身含义"},{"q":"入院记录应该在患者入院后（ ）内完成","o":["6h","8h","12h","24h","上级医生查完前"],"a":3,"e":"入院记录应于病人入院后24小时内完成，由住院医师书写，内容与要求同住院病历但更简明扼要。A项6小时是抢救记录完成时限；B、C项8小时与12小时无对应病历时限规定；E项以上级医生查房为准不符合病历书写规范，故均不正确"},{"q":"下列病变的查体所见错误的是","o":["胸腔积液时患侧呼吸音减弱","支气管肺炎时可闻及湿啰音","肺栓塞时可闻及胸膜摩擦音","阻塞性肺不张时呼吸音增强","肺结核时可闻及湿啰音"],"a":3,"e":"阻塞性肺不张因支气管阻塞，肺泡含气量减少、通气受限，呼吸音减弱或消失，故'呼吸音增强'错误。A项胸腔积液患侧呼吸音减弱正确；B项支气管肺炎可闻及湿啰音；C项肺栓塞累及胸膜时可闻及胸膜摩擦音；E项肺结核可闻及湿啰音，均正确"},{"q":"下列关于便潜血试验的描述，哪项错误","o":["该试验对少量消化道出血有诊断价值","消化性溃疡活动期呈间断阳性","消化道肿瘤时呈持续阳性","服用铋剂药物，便为黑便，便潜血试验为阳性","便潜血试验前应素食3天"],"a":3,"e":"服用铋剂后大便变黑，但黑便由药物本身染色所致，粪便隐血试验并不阳性，故该项描述错误。A项隐血试验对少量消化道出血有诊断价值；B项消化性溃疡活动期出血呈间断阳性；C项消化道肿瘤持续出血呈持续阳性；E项检查前素食3天可避免食物色素干扰，均正确"},{"q":"心前区隆起主要见于","o":["肺源性心脏病","先天性心脏病","大量心包积液","肥厚性心肌病","高血压心脏病"],"a":1,"e":"心前区隆起主要见于儿童期即已发生的心脏病，如先天性心脏病或风湿性心脏病，因胸骨尚软、心脏扩大长期压迫胸壁所致，故先天性心脏病为主要原因。A项肺源性心脏病、E项高血压心脏病多见于成人，胸廓已定型；C项大量心包积液主要致心界扩大；D项肥厚性心肌病少有明显心前区隆起"},{"q":"患者胸痛、咳嗽、呼吸困难，下列哪项有助于鉴别气胸和胸腔积液","o":["呼吸运动","叩诊音","气管位置","呼吸音","摩擦音"],"a":1,"e":"气胸叩诊呈鼓音，胸腔积液叩诊呈浊音或实音，二者叩诊音截然不同，故叩诊音最有鉴别价值。A项呼吸运动与D项呼吸音在两者均减弱，难以区分；C项气管位置在大量气胸与大量积液时均移向健侧；E项摩擦音为胸膜炎体征，非二者鉴别要点"},{"q":"触诊心尖冲动常用","o":["右手全手掌","右手掌尺侧","右手掌桡侧","右手示指、中指指腹","右手第2～4指指腹"],"a":3,"e":"触诊心尖冲动常用右手示指、中指指腹并拢，置于心尖区感受搏动的位置、范围与强度，故选右手示指、中指指腹。A项右手全手掌用于触诊开始时初步确定心前区搏动部位和范围；B项掌尺侧(小鱼际)多用于感受震颤；C项掌桡侧非标准用法；E项第2～4指范围偏大，非最常用"},{"q":"下列体征，提示心源性水肿特异性最高的是","o":["肝颈静脉反流征阳性","腹腔积液","肝脾肿大","胸腔积液","双下肢水肿"],"a":0,"e":"肝颈静脉反流征阳性是右心衰竭的特征性体征，压迫淤血肝脏使回心血量增加，右心房不能接受而使颈静脉压上升，对心源性水肿特异性最高。B项腹腔积液、C项肝脾肿大、D项胸腔积液亦可发生于肝病或肾病；E项双下肢水肿更常见于心衰以外的静脉功能不全或肾病"},{"q":"患者，男，66岁。发现高血压3年，未治疗。查体：BP 150/85mmHg。该患者的血压属于","o":["正常高值","单纯收缩期高血压","理想血压","正常血压","2级高血压"],"a":1,"e":"收缩压150mmHg处于1级高血压范围，舒张压85mmHg未达90mmHg，符合收缩压≥140mmHg且舒张压＜90mmHg的单纯收缩期高血压定义。A项正常高值为120～139/80～89mmHg；C项理想血压＜120/80mmHg；D项正常血压＜120/80mmHg；E项2级高血压需收缩压≥160或舒张压≥100mmHg"},{"q":"尿失禁的病因不包括","o":["尿道、膀胱先天性疾患","尿道、膀胱创伤","累及尿道、膀胱的手术","神经源性膀胱","前尿道疾患"],"a":4,"e":"尿失禁病因包括先天性疾病(如尿道上裂)、创伤(分娩、骨盆骨折)、手术(前列腺手术等)及神经源性膀胱等。E项前尿道疾患主要引起排尿困难、尿流变细或尿潴留，而非尿失禁，故为不包括项。A、B、C、D四项分别对应先天、创伤、手术与神经源性病因"},{"q":"关于临床诊断思维，以下说法不正确的是","o":["模式识别的诊断活动多数是在潜意识中进行，不是正确的临床思维","临床思维的基石是正确收集临床资料","诊断应优先考虑常见病和多发病","当诊断不清时，如患者存在可治性疾病的可能，可给予诊断性治疗的手段尽可能减轻患者痛苦","临床思维应考虑患者整体，而不是只考虑患者的诊断"],"a":0,"e":"模式识别是凭经验对疾病特征性表现整体识别的诊断方法，虽多在潜意识中进行，却是有经验医师常用的正确临床思维，结合其他方法可提高诊断效率，故'不是正确的临床思维'说法错误。B项临床思维的基石是正确收集资料、C项优先考虑常见病多发病、D项必要时诊断性治疗、E项考虑患者整体，均为正确原则"},{"q":"下列是再生障碍性贫血外周血象，但应除外","o":["血红蛋白显著减少","红细胞显著减少","网织红细胞增多","白细胞显著减少","血小板显著减少"],"a":2,"e":"再生障碍性贫血因骨髓造血功能低下，外周血全血细胞减少，血红蛋白、红细胞、白细胞、血小板均显著减少，网织红细胞亦减少。C项网织红细胞增多提示骨髓红系增生旺盛，见于溶血性贫血、急性失血或缺铁性贫血治疗有效时，与再障不符，故为除外项。A、B、D、E四项均符合再障血象"},{"q":"区别心肌梗死和变异型心绞痛，最有诊断意义的心电图改变是","o":["频发室性期前收缩","ST段抬高","T波异常高耸","病理性Q波","QRS波群低"],"a":3,"e":"病理性Q波是心肌坏死的表现，心肌梗死因心肌坏死出现时限≥0.03秒、振幅≥1/4R的异常Q波，而变异型心绞痛为一过性冠脉痉挛，仅表现为暂时性ST段抬高，无坏死故无病理性Q波，最具鉴别意义。B项ST段抬高两者均可出现；A项室性期前收缩非特异性；C项T波高耸可见于超急性期；E项QRS低电压无关"},{"q":"下图所示心电图的正确诊断是","o":["窦性心律，心电图正常","窦性心律，左房增大","窦性心律，预激综合征","窦性心律，左室肥厚","窦性心律，右室肥厚"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。预激综合征的心电图特征为PR间期缩短＜0.12秒、QRS波群增宽并可见delta波、继发性ST-T改变，系房室旁路前传所致。左房增大表现为II导联P波增宽呈双峰；左室肥厚表现为左室面高电压伴ST-T改变；右室肥厚表现为右室面高电压及电轴右偏；正常心电图无上述改变\n\n官方题库中缺失图片"},{"q":"多发性骨髓瘤时引起的红细胞形态异常可见于下列哪种情况","o":["靶形RBC","镰形RBC","RBC缗钱状改变","球形RBC","嗜碱点彩RBC"],"a":2,"e":"多发性骨髓瘤时大量单克隆免疫球蛋白使红细胞表面负电荷降低，红细胞相互黏连呈串条状，形成缗钱状排列，故选RBC缗钱状改变。A项靶形红细胞见于珠蛋白生成障碍性贫血；B项镰形红细胞见于HbS病；D项球形红细胞见于遗传性球形红细胞增多症；E项嗜碱点彩见于铅中毒等"},{"q":"心肌梗死时心电图通常不会有","o":["ST段弓背向下抬高","镜像导联ST段压低","可见Q波","ST段抬高伴T波倒置","PR段无明显压低或者抬高"],"a":0,"e":"心肌梗死时ST段呈弓背向上型抬高，可与高耸T波相连，并出现镜像导联ST段压低、病理性Q波及ST抬高伴T波倒置等演变。A项弓背向下(凹面向上)抬高见于急性心包炎或早期复极，而非心肌梗死，故选A。B、C、D、E四项均可出现在心肌梗死的心电图演变中"},{"q":"不符合原发免疫性血小板减少症实验室检查结果的是","o":["血小板相关抗体增多","血小板计数减少","凝血酶原时间延长","网织血小板百分率增高","巨核细胞正常或增加"],"a":2,"e":"原发免疫性血小板减少症是自身抗体介导的血小板破坏增多，表现为血小板计数减少、血小板相关抗体增多、网织血小板增高及骨髓巨核细胞正常或增加。C项凝血酶原时间反映外源性凝血因子功能，ITP凝血因子正常故PT不延长，故选C。A、B、D、E四项均符合ITP实验室检查"},{"q":"间歇热与回归热的区别是","o":["热度高低不一","发热期与无热期交替存在","体温上升急缓","体温下降急缓","发热期与无热期持续时间的长短"],"a":4,"e":"间歇热与回归热均有发热期与无热期交替，区别在于两者持续时间长短：间歇热高热仅持续数小时，无热期1天至数天；回归热高热期与无热期各持续若干天后规律性交替。A项热度高低、B项是否交替、C项体温上升急缓、D项下降急缓均非二者主要区别"},{"q":"关于疾病的诊断，下列哪种说法错误","o":["病因诊断首先考虑常见病、多发病","疾病诊断首先考虑器质性疾病","疾病诊断首先考虑可治性疾病的诊断","尽可能以多种疾病去解释多种临床表现","诊断应尽可能考虑当地流行和发生的传染病和地方病"],"a":3,"e":"临床诊断应尽可能以一种疾病去解释多种临床表现，优先选择单一诊断，避免用多个诊断分别解释各个症状，故选D。A项病因诊断首先考虑常见病多发病、B项首先考虑器质性疾病、C项首先考虑可治性疾病、E项考虑当地传染病与地方病，均为正确的诊断思维原则"},{"q":"下列哪一项为外源性凝血系统活性的综合性检查","o":["活化部分凝血活酶时间","简易凝血活酶生成试验","血清凝血酶原时间","血浆凝血酶原时间","血浆复钙时间"],"a":3,"e":"血浆凝血酶原时间(PT)是外源性凝血系统较为灵敏和最常用的筛选试验，反映因子Ⅱ、Ⅴ、Ⅶ、Ⅹ及纤维蛋白原的功能，故选PT。A项活化部分凝血活酶时间(APTT)反映内源性凝血系统；B项简易凝血活酶生成试验、E项血浆复钙时间也主要反映内源性途径；C项血清凝血酶原时间非外源性综合检查"},{"q":"下列疾病引起腹部膨隆均考虑出现腹腔积液，但除外","o":["肝硬化门静脉高压","腹膜癌转移","缩窄性心包炎","结核性腹膜炎","卵巢囊肿"],"a":4,"e":"卵巢囊肿所致腹部膨隆叩诊浊音不呈移动性，尺压试验可见腹主动脉搏动传导，并非腹腔积液，故选卵巢囊肿。A项肝硬化门静脉高压、B项腹膜癌转移、C项缩窄性心包炎、D项结核性腹膜炎均可产生腹腔积液而致腹部膨隆"},{"q":"下列体征对于诊断胸腔积液，正确的是","o":["气管移向健侧，有支气管呼吸音，病侧叩诊浊音","气管移向健侧，病侧叩诊浊音，听到胸膜摩擦音","气管移向健侧，病侧叩诊鼓音，支气管语音弱","气管移向病侧，病侧叩诊浊音，支气管语音弱","气管居中，病侧叩诊浊音，听到胸膜摩擦音"],"a":0,"e":"中至大量胸腔积液时病侧胸廓饱满、呼吸动度减弱，气管移向健侧，积液区叩诊浊音或实音，积液区上方因压迫性肺不张可闻及支气管呼吸音，故选A。B、E项胸膜摩擦音见于纤维素性胸膜炎；C项叩诊鼓音见于气胸；D项气管移向病侧见于肺不张，均不符合胸腔积液"},{"q":"用力解便后出现发绀，血压升高，心率增高，继而出现胸闷、呼吸困难、端坐位，两肺满布哮鸣音，可能诊断为","o":["支气管哮喘","喘息性支气管炎","心源性哮喘","心绞痛发作","肺炎"],"a":2,"e":"用力排便使腹压升高、回心血量增加，心脏负荷骤增，诱发急性左心衰竭，出现发绀、血压升高、端坐呼吸及两肺满布哮鸣音，为心源性哮喘。A项支气管哮喘多无高血压与心脏负荷诱因；B项喘息性支气管炎以慢性咳喘为主；D项心绞痛以胸痛为主；E项肺炎以发热咳痰为主"},{"q":"呼吸系统系统回顾应包括下述项目，应除外","o":["咳嗽的性质和程度","咳痰的颜色、黏稠度","呼吸困难的性质、程度和出现时间","胸痛的部位、性质","发热的时间、程度"],"a":4,"e":"呼吸系统系统回顾围绕咳嗽、咳痰、咯血、呼吸困难、胸痛等症状展开，包括咳嗽性质程度、痰的色质、呼吸困难性质程度与时间、胸痛部位性质等。E项发热的时间与程度属全身症状，归入现病史或全身情况问诊，不属呼吸系统回顾项目"},{"q":"患者明确诊断为大叶性肺炎，下列说法错误的是","o":["常呈稽留热","多见于有基础疾病的人","主要病原体为病毒","可表现为头痛、咳嗽、咳铁锈色痰","病情易转为慢性，迁延不愈"],"a":2,"e":"大叶性肺炎主要病原体为肺炎链球菌等细菌，典型表现为稽留热、头痛、咳嗽与铁锈色痰，故'主要病原体为病毒'错误。A项稽留热、D项铁锈色痰均符合本病；B项多见于有基础疾病者更符合支气管肺炎；E项迁延不愈并非本病特点，本病多急性起病、及时治疗可痊愈"},{"q":"下列为正常人出现支气管肺泡呼吸音的常见部位，但应除外","o":["胸骨左侧第1、2肋间隙","胸骨右侧第1、2肋间隙","背部第6、7颈椎水平","肩胛间区第3、4胸椎水平","两肺尖的前后部位"],"a":2,"e":"支气管肺泡呼吸音正常分布于胸骨两侧第1、2肋间隙、肩胛间区第3、4胸椎水平及肺尖前后部。背部第6、7颈椎及第1、2胸椎附近是支气管呼吸音的正常听诊区，而非支气管肺泡呼吸音，故选C。A、B、D、E四项均为支气管肺泡呼吸音的正常分布部位"},{"q":"下列有关脉压减小的叙述正确的是","o":["系指脉压30mmHg","为上下肢血压差异常所致","常伴有交替脉","主要见于主动脉瓣狭窄","也可见于动静脉瘘"],"a":3,"e":"脉压减小指脉压＜30mmHg，主要见于主动脉瓣狭窄、心包积液及严重心力衰竭等，故选主要见于主动脉瓣狭窄。A项30mmHg为临界表述而非减小定义；B项上下肢血压差异常与此无关；C项交替脉是左心衰的脉搏特征；E项动静脉瘘因舒张压下降致脉压增大，而非减小"},{"q":"正常QTc应","o":["≤320ms","≤360ms","≤400ms","≤440ms","≤480ms"],"a":3,"e":"QT间期受心率影响大，需用Bazett公式校正为QTc=QT/√RR，传统QTc正常上限为0.44秒(440ms)，超过即认为QT延长，故选≤440ms。A项320ms、B项360ms数值过低；C项400ms低于常用上限；E项480ms已明显延长，属异常范围"},{"q":"正常输卵管的长度是","o":["7～14cm","8～14cm","6～14cm","9～15cm","10～15cm"],"a":1,"e":"正常输卵管长约8～14cm，表面光滑、质韧无压痛，肿胀增粗或粘连固定伴压痛多见于急慢性炎症或结核，故选8～14cm。A项7～14cm、C项6～14cm下限偏小；D项9～15cm、E项10～15cm上下限均偏移，均非教材给出的长度区间"},{"q":"患十二指肠球部溃疡的患者，当发生幽门梗阻时可发现的体征是","o":["肠型","移动性浊音阳性","液波震颤","振水音","高亢肠鸣音"],"a":3,"e":"幽门梗阻时胃内容物排空受阻，空腹或餐后6～8小时以上上腹部仍可闻及气液撞击的振水音，是其特征性体征，故选振水音。A项肠型与E项高亢肠鸣音见于肠梗阻；B项移动性浊音阳性、C项液波震颤均为腹腔积液表现"},{"q":"站立位胸膜腔最低位置是","o":["左脏胸膜下界","肋膈窦","心脏切迹","斜裂","右肺前界"],"a":1,"e":"站立位时胸膜腔最低部位是肋膈窦，为肋胸膜与膈胸膜在肺下界以下的转折处，约2～3个肋间高度，胸腔积液最先积聚于此。A项左脏胸膜下界、C项心脏切迹、D项斜裂、E项右肺前界均非胸膜腔最低位"},{"q":"关于心脏视诊的叙述，下列哪项是正确的","o":["左心室肥大时，胸骨左缘第3肋间可见异常搏动","剑突下搏动亦可见于腹动脉瘤","右心室肥大心尖冲动向右移位","胸腔积液心尖冲动向患侧移位","小儿心脏扩大都有心前区隆起"],"a":1,"e":"剑突下搏动可由右心室收缩期搏动或腹主动脉搏动产生，瘦长体型者亦可见腹主动脉瘤所致搏动，故选剑突下搏动亦可见于腹动脉瘤。A项胸骨左缘第3～4肋间搏动为右室肥大征象；C项右室肥大心尖冲动向左移位而非右移；D项胸腔积液心尖冲动移向健侧；E项小儿心脏扩大并非都伴心前区隆起"},{"q":"体格检查时，对淋巴结的检查，正确的是","o":["先全身各部分查体，再系统地检查全身浅表淋巴结","查体一般只能检查身体各部浅表淋巴结","检查淋巴结应该双手同时触诊","肿大淋巴结的个数对判断良恶性疾病最重要","肿大淋巴结的大小对判断良恶性疾病最重要"],"a":1,"e":"淋巴结分布于全身，但一般体格检查仅能检查身体各部表浅的淋巴结，深部淋巴结需影像等检查，故选B。A项淋巴结检查应在相应身体部位检查过程中同步进行，而非全身查完后再系统检查；C项并非强求双手同时触诊；D、E项判断良恶性应综合硬度、活动度、粘连、压痛等，不能仅凭个数或大小"},{"q":"关于病理反射，正确的是","o":["指锥体束病损时，大脑失去了对脑干和脊髓的抑制作用而出现的异常反射","1岁半以内的婴儿由于神经系统发育不完善，不能出现病理反射","成人在正常时亦可出现病理反射","跟腱反射和膝反射属于病理反射","肱二头肌反射是病理反射"],"a":0,"e":"病理反射指锥体束病损时大脑失去对脑干和脊髓抑制作用而出现的异常反射，如Babinski征，故选A。B项1岁半以内婴幼儿因神经系统发育未完善可出现此类反射，不属病理性；C项成人正常时不出现病理反射；D项跟腱反射、膝反射与E项肱二头肌反射均属深反射，不是病理反射"},{"q":"符合上消化道出血粪便隐血试验阳性，最少出血量为","o":["2ml","5ml","10ml","15ml","20ml"],"a":1,"e":"消化道每日出血量在5～10ml以内时粪便外观无改变、镜检无红细胞，需隐血试验才能检出，称为隐血便，故最少出血量为5ml。A项2ml低于可检出阈；C项10ml、D项15ml、E项20ml均非最小检出量，量更大时可出现黑便或肉眼血便"},{"q":"肺在维持酸碱平衡中的作用","o":["排出CO2是肺的唯一的功能","对固定酸没有作用","通过调节CO2排出，肺可恢复HCO3－浓度","可直接呼出酮体","对气化酸和固定酸都起作用"],"a":2,"e":"肺通过改变通气量调节CO2排出，从而调整血浆H2CO3浓度，使[HCO3-]/[H2CO3]比值维持在20/1左右，参与酸碱平衡代偿，故选通过调节CO2排出恢复平衡。A项排出CO2并非肺的唯一功能；D项酮体不能经肺呼出；E项肺主要调节挥发酸(碳酸)，固定酸主要由肾脏排出"},{"q":"主动脉瓣关闭不全时Austin-Flint杂音的产生机制正确的是","o":["经主动脉瓣逆流的血液将二尖瓣后叶推起","经主动脉瓣逆流的血液将二尖瓣前叶推起","肺动脉扩张血液反流所致","左心房舒张期负荷增加所致","左心室扩张使二尖瓣相对关闭不全所致"],"a":1,"e":"主动脉瓣关闭不全时，舒张期反流血液冲击并推起二尖瓣前叶，使其处于半关闭状态、限制瓣口开放，形成相对性二尖瓣狭窄，在心尖区产生柔和递减型舒张中晚期隆隆样杂音，即Austin-Flint杂音，故选经主动脉瓣逆流的血液将二尖瓣前叶推起。A项后叶说法错误；C项肺动脉扩张、D项左房负荷增加均非其机制；E项二尖瓣相对关闭不全不符合相对狭窄的实质"},{"q":"关于医嘱单，描述正确的是","o":["医师不得下达口头医嘱","取消医嘱需用红笔标注并签字","每项医嘱可包括多个内容","护士给药完毕后书写医嘱停止时间","抢救时，护士可直接执行口头医嘱，无需复述"],"a":1,"e":"医嘱内容需要取消时，应使用红色墨水标注'取消'字样并签名，故取消医嘱需用红笔标注并签字正确。A项医师在抢救等情况下可下达口头医嘱；C项每项医嘱只包含一个内容；D项医嘱的停止时间应由医师书写，而非护士给药后书写；E项抢救时护士执行口头医嘱须复述确认"},{"q":"关于肾脏功能检测，下列哪项不正确","o":["菊粉清除率可准确代表肾小球滤过率","β2-MG测定是诊断肾脏近曲小管受损的敏感指标","尿内出现大量蛋白尿并不能说明肾功能损伤严重","酚红排泌试验可反映肾小管的重吸收功能","血尿素和肌酐主要反映肾小球滤过功能"],"a":3,"e":"酚红排泌试验主要反映肾小管的排泌功能，而非重吸收功能，故选D。A项菊粉清除率可准确代表肾小球滤过率；B项β2-微球蛋白测定是诊断近曲小管受损的敏感指标；C项大量蛋白尿主要反映肾小球滤过膜屏障受损，与肾功能损害程度不平行；E项血尿素和肌酐主要反映肾小球滤过功能"},{"q":"全身神经系统检查不包括","o":["脑神经检查","运动神经检查","感觉神经检查","大脑精神状态的检查","自主神经的检查"],"a":3,"e":"全身神经系统检查主要包括脑神经、运动神经、感觉神经、反射及自主神经等检查，故选大脑精神状态的检查为不包括项。A项脑神经检查、B项运动神经检查、C项感觉神经检查、E项自主神经检查均属神经系统检查范畴；精神状态属一般状况与意识检查内容，不列为神经系统常规检查项目"},{"q":"慢性睾丸肿痛多见于","o":["流行性腮腺炎后","隐睾症","白血病睾丸浸润","精索静脉曲张","睾丸结核"],"a":4,"e":"睾丸慢性肿痛多由结核引起，故选睾丸结核。A项流行性腮腺炎并发的是急性睾丸炎，表现为急性肿痛；B项隐睾症为睾丸下降异常；C项白血病睾丸浸润多表现为一侧睾丸无痛性肿大质硬；D项精索静脉曲张表现为精索蚯蚓团样感，可致睾丸萎缩而非慢性肿痛"},{"q":"纸片扩散法药敏试验中，MH平板的厚度应为","o":["1mm","2mm","3mm","4mm","5mm"],"a":3,"e":"纸片扩散法药敏试验中，M-H琼脂平板厚度应为4mm，过薄会使抑菌圈偏大、过厚则偏小，从而影响结果判读，故选4mm。A项1mm、B项2mm、C项3mm均偏薄，D项4mm为标准厚度；E项5mm偏厚。其余接种菌浓度、平板接种与孵育温度时间均按统一标准操作"},{"q":"心前区触及心包摩擦感提示","o":["右侧胸膜炎","主动脉瓣狭窄","二尖瓣狭窄","心包炎","二尖瓣反流"],"a":3,"e":"心包摩擦感是急性心包炎时心包膜纤维素渗出致表面粗糙，心脏收缩时脏、壁两层心包摩擦产生的振动传至胸壁所致，故选心包炎。A项右侧胸膜炎产生胸膜摩擦感，屏气时消失；B项主动脉瓣狭窄、C项二尖瓣狭窄与E项二尖瓣反流各产生相应杂音，均无心包摩擦感"},{"q":"正常尿比重范围，应是","o":["1.010±0.003","1.003～1.040","1.010～1.030","1.015～1.025","1.025以上"],"a":3,"e":"正常人尿比重一般为1.015～1.025，晨尿较高，可反映肾小管浓缩稀释功能，故选1.015～1.025。B项1.003～1.040为尿比重可能出现的极端范围；C项1.010～1.030接近随机尿范围；A项1.010±0.003为等渗尿附近；E项1.025以上见于脱水或心衰等浓缩状态"},{"q":"反映胆汁淤滞的酶包括","o":["ALT、AST","MAO、PH","LDH、PK","ALP、ALT","ALP、GGT"],"a":4,"e":"反映胆汁淤滞的酶主要为ALP和GGT，二者在胆道梗阻或胆汁淤积时平行升高，故选ALP、GGT。A项ALT、AST主要反映肝细胞损伤；B项MAO、PH与肝纤维化相关；C项LDH、PK为组织细胞内酶，特异性低；D项ALT属肝细胞损伤酶，不能与ALP并列作为胆汁淤滞指标"},{"q":"高血压时心电图最不可能出现下列哪种改变","o":["左室面高电压","电轴左偏","复极异常","QRS波轻度增宽","胸前导联T波高尖"],"a":4,"e":"高血压长期压力负荷致左室肥厚，心电图表现为左室面高电压、电轴左偏、复极异常(ST-T改变)及QRS波轻度增宽。E项胸前导联T波高尖是高血钾或心肌梗死超急性期的表现，不是高血压的典型改变，故选胸前导联T波高尖。A、B、C、D四项均可见于高血压心脏损害"},{"q":"局部视诊包括下列各项，但应除外","o":["胸廓","腹形","包块硬度","关节外形","骨骼"],"a":2,"e":"局部视诊是用肉眼观察胸廓、腹形、关节外形、骨骼等体表可见的轮廓与形态改变。C项包块硬度需通过触诊按压感知，属触诊内容而非视诊，故为除外项。A项胸廓、B项腹形、D项关节外形、E项骨骼均可由视诊直接观察"},{"q":"发热时体温上升期的表现不包括","o":["疲乏无力","肌肉酸痛","皮肤苍白","出汗多，皮肤潮湿","畏寒或寒战"],"a":3,"e":"体温上升期因产热大于散热，表现为疲乏无力、肌肉酸痛、皮肤苍白、畏寒或寒战。D项出汗多、皮肤潮湿是体温下降期散热增加的表现，不属于体温上升期，故选D。A、B、C、E四项均为体温上升期的典型表现"},{"q":"肺动脉瓣听诊区第二心音减弱，最常见于","o":["肺动脉瓣狭窄","二尖瓣狭窄","二尖瓣关闭不全","房间隔缺损","室间隔缺损"],"a":0,"e":"第二心音的肺动脉瓣成分(P2)减弱见于肺循环阻力降低、血流减少或肺动脉瓣狭窄，故肺动脉瓣狭窄最常见。B项二尖瓣狭窄与D项房间隔缺损、E项室间隔缺损均可致肺动脉高压或肺血增多，使P2亢进；C项二尖瓣关闭不全主要影响心尖区收缩期杂音"},{"q":"心电图Ⅱ、Ⅲ、aVF导联ST段弓背向上抬高提示哪个部位的心肌梗死","o":["高侧壁","后侧壁","下壁","前壁","后壁"],"a":2,"e":"Ⅱ、Ⅲ、aVF导联面向心脏下壁，这些导联ST段弓背向上抬高提示下壁心肌梗死，多由右冠状动脉或左回旋支闭塞所致。A项高侧壁对应Ⅰ、aVL；B项后侧壁与E项后壁对应V7～V9；D项前壁对应V3～V5，均非Ⅱ、Ⅲ、aVF导联"},{"q":"正常成年人体内HbA占","o":["98%","60%","50%","3%","＜1%"],"a":0,"e":"正常成人血红蛋白以HbA为主，约占98%，由两条α链和两条β链组成。D项3%约为HbA2所占比例；E项＜1%为HbF，胎儿期HbF可高达6%～93%；B项60%、C项50%均远低于实际比例"},{"q":"红细胞内游离原卟啉增多最常见于","o":["巨幼细胞贫血","溶血性贫血","再生障碍性贫血","恶性贫血","铁粒幼细胞贫血"],"a":4,"e":"铁粒幼细胞贫血时亚铁血红素合成障碍、铁利用不良，铁不能与原卟啉结合，导致红细胞内游离原卟啉增多，并可见环形铁粒幼红细胞，故选铁粒幼细胞贫血。A项巨幼细胞贫血为DNA合成障碍；B项溶血性贫血、C项再生障碍性贫血与D项恶性贫血均非铁利用障碍性疾病的典型表现"},{"q":"标准V7导联位置正确的是","o":["左侧腋前线V4导联同一水平","左侧腋中线V4和V5同一水平","左侧肩胛线V4～V6同一水平","左侧脊柱旁线V4～V6同一水平","左侧腋后线V4～V6同一水平"],"a":4,"e":"标准V7导联位于左侧腋后线与V4同一水平处，用于诊断后壁心肌梗死，故选左侧腋后线V4～V6同一水平。A项左侧腋前线V4水平无对应标准导联；B项左侧腋中线V4同一水平为V6位置；C项左侧肩胛线V4水平为V8；D项左侧脊柱旁线V4水平为V9"},{"q":"正常人潮气容积为500ml，其中无效腔气有","o":["150ml","200ml","100ml","250ml","50ml"],"a":0,"e":"正常成人潮气容积约500ml，其中约150ml为无效腔气，不参与气体交换，仅在呼吸细支气管以上气道起传导作用，亦称解剖无效腔，故选150ml。B项200ml、C项100ml、D项250ml、E项50ml均偏离解剖无效腔的正常值"},{"q":"心脏杂音的强度与哪项因素无关","o":["狭窄程度","血流速度","压力阶差","血液黏度","心肌收缩力"],"a":3,"e":"心脏杂音强度主要取决于狭窄程度、血流速度、压力阶差及心肌收缩力等因素，与血液黏度无关，故选血液黏度。A项狭窄越重杂音越响；B项血流速度越快杂音越强；C项压力阶差越大杂音越响；E项心肌收缩力影响流速与杂音强度"},{"q":"典型的再生障碍性贫血（急性型）的骨髓增生程度是","o":["增生极度活跃","增生明显活跃","增生活跃","增生减低","增生极度减低"],"a":4,"e":"急性型再生障碍性贫血病情重、进展快，骨髓增生极度减低，有核细胞显著减少，成熟红细胞与有核细胞比例约200∶1，高倍镜下有核细胞数＜5个，故选增生极度减低。A项增生极度活跃、B项增生明显活跃多见于白血病；C项增生活跃为正常骨髓象；D项增生减低可见于慢性再障"},{"q":"下列各项均为正常腹部可触到的包块，但除外","o":["腹直肌腱划","触及胆囊","右肾下极","乙状结肠索","骶骨岬"],"a":1,"e":"正常胆囊隐存于肝脏之后，不能触及，胆囊肿大时方可在右肋缘下腹直肌外缘触到，故'触及胆囊'不是正常腹部可触到的结构。A项腹直肌腱划、C项右肾下极(消瘦者)、D项乙状结肠索、E项骶骨岬均属正常腹部可触及的结构"},{"q":"下列各项均为消化性溃疡的并发症，但除外","o":["出血","幽门梗阻","恶性贫血","恶变","穿孔"],"a":2,"e":"消化性溃疡的并发症包括出血、穿孔、幽门梗阻和恶变，恶性贫血是自身免疫性胃炎致内因子缺乏、维生素B12吸收障碍所致，与溃疡无关，故选恶性贫血。A、B、D、E四项均为消化性溃疡的四大并发症"},{"q":"关于未结合胆红素的叙述，错误的是","o":["在溶血性黄疸时显著增高","在血浆中与白蛋白的结合是可逆的","在血浆中与白蛋白结合后毒性变小","在梗阻性黄疸时显著增高","肝细胞损伤也会升高"],"a":3,"e":"梗阻性黄疸时胆道阻塞，结合胆红素反流入血，以结合胆红素显著增高为主，未结合胆红素不高，故'在梗阻性黄疸时显著增高'错误。A项溶血性黄疸以非结合(未结合)胆红素增高为主；B项未结合胆红素与白蛋白结合可逆且结合后毒性减小；C项同上；E项肝细胞损伤时两者均升高"},{"q":"下列情况是中性粒细胞病理增多的原因，但应除外","o":["急性感染","急性溶血","急性失血","恶性肿瘤","再生障碍性贫血"],"a":4,"e":"再生障碍性贫血因骨髓造血功能低下，外周血中性粒细胞减少而非增多，故选再生障碍性贫血。A项急性感染、B项急性溶血、C项急性失血、D项恶性肿瘤均可引起中性粒细胞病理增多，其中急性感染最常见"},{"q":"下列哪种试验准确地反映肾小球滤过率","o":["内生肌酐清除率","菊粉清除率","尿素清除率","血尿素酸","β2-微球蛋白"],"a":1,"e":"菊粉清除率可准确反映肾小球滤过率，因菊粉可自由滤过且不被肾小管重吸收或排泌，是测定GFR的金标准，故选菊粉清除率。A项内生肌酐清除率是临床常用近似指标，准确度略逊；C项尿素清除率受肾小管重吸收及尿量影响；D项血尿素受饮食与分解代谢干扰；E项β2-微球蛋白主要反映肾小管功能"},{"q":"关于血培养的运送和处理，下列错误的是","o":["血培养抽取后，立即送到微生物实验室","如不能立即送往实验室，置4℃冰箱冷藏","如不能立即送往实验室，置35～37℃孵箱中","如暂不能立即送往实验室，可放室温保存","实验室接受到培养瓶，应立即置35～37℃孵箱或血培养仪中"],"a":1,"e":"血培养标本采集后应立即送检，不能即刻送检时应置室温或35～37℃孵箱保存，切勿冷藏，低温会抑制或杀灭脑膜炎奈瑟菌、淋病奈瑟菌等怕冷病原菌。置4℃冷藏的做法错误，是本题所选。立即送实验室、置孵箱及实验室接收后立即孵育均为正确处理；血常规等标本可短期冷藏，与血培养要求不同"},{"q":"两侧肺底出现湿啰音最常见于哪种疾病","o":["肺气肿","心力衰竭","肺结核","支气管哮喘","支气管扩张"],"a":1,"e":"两侧肺底湿啰音多见于心力衰竭所致肺淤血和支气管肺炎，因重力作用液体和分泌物易积聚于肺底。局限性湿啰音仅提示局部病变，如肺炎、肺结核或支气管扩张，不同于双侧对称性分布；两肺野满布湿啰音则见于急性肺水肿和严重支气管肺炎，范围更广。肺气肿、支气管哮喘以干啰音或呼吸音减弱为主"},{"q":"左心衰竭咯血的痰液特点为","o":["浆液性粉红色泡沫样痰","黏稠暗红色血痰","砖红色胶冻样痰","铁锈色样痰","鲜红色样痰"],"a":0,"e":"左心衰竭致急性肺水肿时，肺毛细血管压力急剧升高，血浆和红细胞渗入肺泡，形成浆液性粉红色泡沫样痰，为其典型表现。砖红色胶冻样痰见于肺炎克雷伯菌肺炎；黏稠暗红色血痰多见于肺栓塞；铁锈色痰为肺炎链球菌肺炎特征；二尖瓣狭窄咯血多为暗红色，均非左心衰竭所见"},{"q":"动脉导管未闭的脉搏是","o":["奇脉","迟脉","交替脉","水冲脉","重搏脉"],"a":3,"e":"动脉导管未闭时舒张期主动脉血液经未闭导管分流至肺动脉，舒张压降低、脉压增大，出现骤起骤落的水冲脉，抬高前臂更明显。迟脉见于主动脉瓣狭窄，脉搏上升缓慢；交替脉为节律规则而强弱交替，见于心衰；奇脉吸气时明显减弱，见于心包积液；重搏脉见于主动脉硬化等，均非本病脉搏"},{"q":"下列哪项为左心室肥大的心电图表现","o":["RV1＋SV5＞1.2mV","RV1＞1.0mV","RaVL＜1.1mV","RV5＋SV1＞4.5mV","RaVR＞0.5mV"],"a":3,"e":"左心室肥厚时胸导联QRS电压增高，RV5或RV6＞2.5mV、RV5+SV1＞4.0mV（男）或＞3.5mV（女），本题RV5+SV1＞4.5mV符合左室高电压标准。RV1+SV5＞1.05mV及RaVR＞0.5mV为右心室肥厚表现；RaVL＜1.1mV数值偏低无诊断意义；RV1＞1.0mV亦非左室肥厚指标"},{"q":"成年男性与女性颈部外形较明显的区别是","o":["男性静坐时颈部血管可显露","男性颈部较细长","男性甲状软骨较突出","男性转头时可见胸锁乳突肌突出","男性颈部直立，两侧对称"],"a":2,"e":"正常人颈部直立、两侧对称，男性甲状软骨较突出，女性则平坦不显著，这是成年男女颈部外形最明显的区别。颈部粗细长短受体型和营养影响，男女均可有；胸锁乳突肌突起在转头时男女皆可见；静坐时颈部血管显露与体位、消瘦有关，均非性别固有差异"},{"q":"隐性黄疸时，血清总胆红素含量为","o":["1.71～3.42μmol/L","5.13～6.84μmol/L","8.55～15.4μmol/L","17.1～34.2μmol/L","73.4μmol/L"],"a":3,"e":"正常血清总胆红素为3.4～17.1μmol/L，当胆红素升至17.1～34.2μmol/L时临床不易察觉，称隐性黄疸或亚临床黄疸。超过34.2μmol/L才出现可见黄疸；8.55～15.4μmol/L仍属正常范围；73.4μmol/L已属轻度黄疸，均不符合隐性黄疸的界定"},{"q":"关于内源性致热原的描述，错误的是","o":["又称白细胞致热源","可通过副交感神经使机体散热减少","包括白介素-1、肿瘤坏死因子","通过垂体内分泌因素使机体产热增多","可通过血脑脊液屏障"],"a":1,"e":"内源性致热原又称白细胞致热原，包括白介素-1、肿瘤坏死因子、干扰素等，可透过血-脑脊液屏障作用于体温调定点，并经垂体内分泌因素使产热增多。其使散热减少是通过交感神经使皮肤血管及竖毛肌收缩、停止排汗实现，而非副交感神经，故该项描述错误"},{"q":"关于体温的论述，下列正确的是","o":["体温低于36.5℃称体温过低","甲状腺功能亢进患者常有体温过低","体温升高超出正常范围称为发热","无菌性炎症一般无发热","慢性消耗性疾病患者常有体温升高"],"a":2,"e":"发热是指机体在致热原作用或体温调节中枢功能障碍时，体温升高超出正常范围，此论述正确。体温过低指低于正常而非低于36.5℃这一固定值；甲亢因代谢亢进常有体温偏高而非过低；无菌性炎症如组织坏死吸收亦可发热；慢性消耗性疾病多见体温偏低"},{"q":"以下为血红蛋白测定值，其中符合中度贫血的是","o":["＜60g/L","90～60g/L","90～70g/L","80～60g/L","＜70g/L"],"a":1,"e":"贫血按血红蛋白浓度分度：轻度＞90g/L但低于参考下限，中度60～90g/L，体力劳动时心慌气短。＜60g/L为重度，30～59g/L休息时即心慌气短；＜30g/L为极重度。90～70g/L、80～60g/L并非标准分度区间，故中度贫血为90～60g/L"},{"q":"患者，女，25岁，腹痛来诊。下述哪个问题不合适","o":["请告诉我你哪里不舒服","请告诉我你痛的情况","疼痛像什么样","疼痛是刺痛吗","痛的部位有变动吗"],"a":3,"e":"腹痛问诊应遵循从一般提问到直接提问的原则，先让病人开放描述，“疼痛是刺痛吗”属诱导性直接提问，易限制病人表述，不合适。“哪里不舒服”“痛的情况”“疼痛像什么样”“部位有变动吗”均为开放式提问，有利于获取真实信息，符合问诊要求"},{"q":"关于阵发性室上性心动过速的心电图特点，下列哪项不正确","o":["突发突止","频率在160～250次/min","节律快而规律，RR间期绝对匀齐","QRS波一般不正常","可见逆传p波"],"a":4,"e":"官方答案为【可见逆传p波】，但依据教材，正确答案为【QRS波一般不正常】。阵发性室上速发作突发突止、频率160～250次/分、RR绝对匀齐，QRS波群形态一般正常，仅在伴室内差异性传导、束支阻滞或经旁路前传时才呈宽QRS。逆行P′波虽常不易辨别，但并非不可见，故“可见逆传p波”作为不正确项不成立"},{"q":"固定型上气道阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":2,"e":"固定型上气道阻塞（如气管狭窄、肿瘤）使气道管径在吸气和呼气时均固定受限，故流量-容积曲线吸气相与呼气相均出现平台。可变型胸外阻塞（如喉软化）仅吸气相受限呈吸气相平台；可变型胸内阻塞仅呼气相受限呈呼气相平台，均与固定型的双相平台不同"},{"q":"冠心病患者出现哪项体征，提示早期左心功能不全","o":["颈静脉怒张","左心室扩大","心尖部舒张期奔马律","肺部啰音","肝大，下肢水肿"],"a":2,"e":"心尖部舒张期奔马律为病理性S3，是左心室舒张期负荷过重、心肌张力减低与顺应性减退的表现，提示严重器质性心脏病，为早期左心功能不全的敏感体征。颈静脉怒张、肝大及下肢水肿为右心衰或体循环淤血表现；左心室扩大属结构改变，肺部啰音多在肺淤血明显时出现"},{"q":"下列均为正确触诊脾脏的方法，但除外","o":["患者仰卧位两腿稍屈曲","医生右手掌平放于上腹部与肋大致成垂直方向","医生左手掌置于患者左腰部第4～6肋处","随患者深呼吸运动进行触脾","右侧卧位触脾时，右下肢伸直，左下肢屈曲"],"a":2,"e":"脾脏双手触诊时病人仰卧、两腿稍屈曲，医生左手应绕过腹前方置于左胸下部第9～11肋处，将脾脏向前托起，右手掌平放脐部与左肋弓垂直，配合深呼吸迎触脾尖。置于左腰部第4～6肋处位置过高且非托脾标准手法，故该项不属于正确触脾方法"},{"q":"现病史的内容不包括","o":["发病情况","主要症状特点及其发展变化情况","手术外伤史","发表以来诊治经过及结果","伴随症状"],"a":2,"e":"现病史反映本次疾病发生、发展、演变和诊治经过，包括起病情况、主要症状特点及发展变化、诊治经过与结果、伴随症状等。手术外伤史属既往史内容，记录病人过去的健康和疾病情况，不纳入现病史，故不属于现病史的组成部分"},{"q":"迟脉最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","伤寒","心包积液","原发性高血压"],"a":1,"e":"迟脉指脉搏上升缓慢、波峰平钝，因左心室射血受阻、动脉压上升缓慢所致，最常见于主动脉瓣狭窄。主动脉瓣关闭不全因脉压增大呈水冲脉；伤寒常表现为相对缓脉，脉率与体温不相称；心包积液多见奇脉，均非迟脉的典型病因"},{"q":"肌肉松弛，伸屈阻力低，关节活动范围扩大。这不见于以下哪种病变","o":["周围神经病变","脊髓前角病变","肌源性病变","长时间上单位神经元损伤病变","小脑病变"],"a":3,"e":"肌张力降低表现为肌肉松软、伸屈阻力低、关节活动范围扩大，见于下运动神经元病变如周围神经病变、脊髓前角病变，以及肌源性病变和小脑病变。长时间上运动神经元损伤则致肌张力增高、痉挛性瘫痪，故不属于肌张力降低的病变"},{"q":"奇脉的产生与下列因素有关","o":["周围血管弹性差","呼气时胸腔压力改变","心肌收缩力差","左室心搏出量低","周围血管扩张"],"a":3,"e":"奇脉指吸气时脉搏明显减弱或消失，见于心包积液、缩窄性心包炎，机制为吸气时右心回流增加而左室心搏出量降低，致收缩压下降。呼气时胸腔压力改变并非常规机制；周围血管弹性差、血管扩张影响脉压但不产生奇脉；心肌收缩力差亦非主要因素"},{"q":"蛋白尿是指尿蛋白定量试验","o":["＞50mg/24h","＞80mg/24h","＞100mg/24h","＞150mg/24h","＞200mg/24h"],"a":3,"e":"蛋白尿指尿蛋白定量超过150mg/24h（或超过100mg/L），尿蛋白定性呈阳性。正常人24小时尿蛋白＜150mg；50～100mg/24h仍在正常范围；200mg/24h虽属蛋白尿但非界定阈值，故蛋白尿的诊断界值为＞150mg/24h"},{"q":"上消化道出血部位一般是指","o":["食道","贲门","幽门","十二指肠球部","屈氏韧带以上的消化器官"],"a":4,"e":"上消化道以屈氏韧带（十二指肠悬韧带）为界，其上方的消化道包括食管、胃、十二指肠及肝胆胰等器官出血统称上消化道出血。食管、贲门、幽门、十二指肠球部均只是其中一段，不能概括全部，故以屈氏韧带以上消化器官为准确定义"},{"q":"关于心脏触诊，正确的是","o":["心底部异位搏动提示肺动脉高压","二尖瓣狭窄可触及心尖区舒张期震颤","大面积心肌梗死可触及心尖抬举样搏动","大量心包积液可触及心包摩擦感","主动脉狭窄可触及胸骨右缘第2肋间舒张期震颤"],"a":1,"e":"二尖瓣狭窄时左房血液流入受阻，舒张期可于心尖区触及舒张期震颤，左侧卧位更明显，为本病特征性触诊体征。主动脉瓣狭窄应在胸骨右缘第2肋间触及收缩期震颤而非舒张期；大量心包积液时心包摩擦感反而消失；心底部异位搏动并非肺动脉高压特异体征"},{"q":"急性肝损伤时，改变最早的血清蛋白成分是","o":["白蛋白","α球蛋白","前白蛋白","β球蛋白","γ球蛋白"],"a":2,"e":"前白蛋白由肝细胞合成，半衰期约2天，明显短于白蛋白，故比白蛋白更能早期反映肝细胞损害，急性肝损伤时其血清浓度下降最早。白蛋白半衰期长，变化滞后；α、β、γ球蛋白半衰期长且受其他因素影响，均不作为早期肝损伤的敏感指标"},{"q":"下列情况均可引起P2增强，但除外","o":["房间隔缺损","二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣狭窄","动脉导管未闭"],"a":3,"e":"P2增强见于肺血增多或肺动脉高压，房间隔缺损、动脉导管未闭因左向右分流致肺血增多，二尖瓣狭窄致肺动脉高压，均可使P2亢进。肺动脉瓣狭窄时瓣口狭窄致通过血流减少、P2减弱而非增强，故为例外"},{"q":"稽留热常见于","o":["风湿热","疟疾","伤寒","布鲁菌病","渗出性胸膜炎"],"a":2,"e":"稽留热表现为体温恒定维持在39～40℃以上数天至数周，24小时波动不超过1℃，常见于伤寒高热期、大叶性肺炎。弛张热24小时波动超过2℃且均在正常以上，见于败血症、风湿热；间歇热高热与无热交替，见于疟疾；渗出性胸膜炎多为不规则热"},{"q":"下述查体所见均可在胸腔积液与气胸时出现，但应除外","o":["患侧饱满","气管向健侧移位","呼吸音减弱或消失","患侧呼吸动度减弱","叩诊呈浊音"],"a":4,"e":"胸腔积液与气胸均可表现为患侧饱满、呼吸动度减弱、呼吸音减弱或消失，并因胸腔内压力增高使气管向健侧移位。叩诊音二者不同：胸腔积液为浊音，气胸为鼓音，故叩诊呈浊音不会在气胸出现，为例外项"},{"q":"采集病史时，不恰当的提问是","o":["发病后用过哪些药物","您的尿液是红色的吗","什么情况下疼痛加重","多在什么情况下发病","您哪儿不舒服"],"a":1,"e":"采集病史应先开放式提问再逐步深入，“您的尿液是红色的吗”属诱导性直接提问，易使病人顺从回答而遗漏真实情况，不恰当。“您哪儿不舒服”为一般提问，“发病后用过哪些药物”“什么情况下加重”“多在什么情况下发病”均为围绕病情的具体询问，符合由一般到直接的问诊原则"},{"q":"单纯性收缩期高血压的诊断标准是","o":["收缩压≥140mmHg","收缩压≥160mmHg或舒张压≤90mmHg","收缩压≥140mmHg和舒张压＜90mmHg","收缩压≥140～160mmHg","收缩压≥160mmHg"],"a":2,"e":"单纯收缩期高血压指在未用降压药情况下，收缩压≥140mmHg而舒张压＜90mmHg，多见于老年人动脉顺应性下降。收缩压≥160mmHg或仅舒张压异常均不符合；单纯收缩压≥140mmHg未限定舒张压亦不准确，须同时满足舒张压＜90mmHg"},{"q":"该心电图的诊断考虑","o":["完全性右束支传导阻滞","窦性心律，完全性左束支传导阻滞","窦性心律，左前分支传导阻滞","窦性心律，左后分支传导阻滞","窦性心律，完全性右束支传导阻滞"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。完全性右束支传导阻滞心电图表现为V1、V2导联呈rsR′或M型，V5、V6导联S波宽钝，QRS时限≥0.12秒，心电轴多正常。完全性左束支阻滞则V1、V2呈QS或rS、V5、V6 R波宽钝伴切迹；左前、左后分支阻滞分别表现为电轴左偏和右偏，均需依赖图形判定\n\n官方题库中缺失图片"},{"q":"听到开瓣音常提示","o":["二尖瓣狭窄伴二尖瓣关闭不全","二尖瓣严重狭窄，瓣膜钙化","二尖瓣狭窄分离术的禁忌证","二尖瓣狭窄伴左心衰竭","二尖瓣轻、中度狭窄，瓣膜弹性和活动性较好"],"a":4,"e":"开瓣音为二尖瓣狭窄时瓣膜开放突然受阻产生的拍击样音，提示瓣膜弹性和活动度尚好，多见于轻、中度狭窄，是二尖瓣分离术适应证的重要参考。瓣膜严重钙化僵硬时开瓣音消失；开瓣音距S2越近提示左房压越高、狭窄越重，而非瓣膜条件好"},{"q":"下述哪种物质可刺激T淋巴细胞发生细胞分化","o":["抗体","补体","植物血凝素","绵羊RBC","小鼠RBC"],"a":2,"e":"植物血凝素（PHA）为非特异性有丝分裂原，可刺激T淋巴细胞转化为母细胞、核酸与蛋白质合成增加，用于T细胞转化试验评估细胞免疫功能。绵羊红细胞用于E花环试验检测T细胞数量，并不刺激其分化；抗体、补体参与体液免疫和调理，无促T细胞转化作用"},{"q":"周围血管征不见于","o":["伤寒","动静脉瘘","主动脉瓣关闭不全","甲亢","严重贫血"],"a":0,"e":"周围血管征包括水冲脉、枪击音、毛细血管搏动等，源于脉压增大，见于主动脉瓣关闭不全、动静脉瘘、甲亢、严重贫血。伤寒表现为相对缓脉，脉率与体温不相称，无脉压增大，故不出现周围血管征"},{"q":"下列是关于舒张晚期奔马律的正确描述，但应除外","o":["也称收缩前期奔马律","也称第四心音奔马律","也称房性奔马律","也称室性奔马律","实际上是由病理性第四心音与第一、第二心音构成"],"a":3,"e":"舒张晚期奔马律又称收缩前期奔马律、第四心音奔马律、房性奔马律，由病理性S4与第一、第二心音构成，源于心房收缩克服心室充盈阻力。室性奔马律是舒张早期奔马律（第三心音奔马律）的别称，不属于舒张晚期奔马律，故为例外"},{"q":"发热时糖代谢变化为","o":["糖原分解增多，糖异生增强，血糖升高，乳酸增多","糖原分解增多，糖异生减少，血糖升高，乳酸减少","糖原分解减少，糖异生减少，血糖降低，乳酸增多","糖原分解减少，糖异生增加，血糖降低，乳酸减少","糖原分解增多，糖异生不变，血糖波动，乳酸减少"],"a":0,"e":"发热时交感神经兴奋，肾上腺素、糖皮质激素分泌增多，促进肝糖原分解和糖异生增强，血糖升高；同时组织相对缺氧使无氧酵解加强，乳酸增多。糖原分解减少、糖异生减少或血糖降低均与发热时的代谢应激状态相反"},{"q":"不常见杵状指（趾）表现的疾病是","o":["支气管肺癌","先天性心脏病，法洛四联症","肢端肥大症","肺性肥大性骨关节病","支气管扩张症"],"a":2,"e":"杵状指（趾）见于支气管肺癌、法洛四联症等发绀型先心病、肺性肥大性骨关节病和支气管扩张症，与慢性缺氧、中毒性损害致指端软组织增生有关。肢端肥大症因生长激素过多表现为头颅增大、下颌突出、唇舌肥厚等特殊面容，不以杵状指为特征"},{"q":"体温上升期的热代谢特点是","o":["产热和散热平衡","散热大于产热","产热大于散热","产热障碍","散热障碍"],"a":2,"e":"体温上升期因致热原使体温调定点上移，机体通过交感神经使皮肤血管收缩、排汗停止，同时骨骼肌阵缩产热增加，产热大于散热，体温因而上升。产热散热平衡见于高热持续期；散热大于产热见于退热期；单纯产热或散热障碍不能概括该期特点"},{"q":"下列为测量体温时，可能出现的误差，但不包括","o":["测量体温前未把体温计汞柱甩到36℃以下","测量体温时未将体温计夹紧","体温计附近有影响局部体温的冰袋或热水袋","测体温常在早晨低、下午高，日温总在1℃内波动","测体温前用热水漱口、热毛巾擦腋下"],"a":3,"e":"测量体温前未甩汞柱、未夹紧体温计、附近有冰袋或热水袋、测量前用热水漱口或热毛巾擦腋下，均可造成读数偏差，属测量误差。而早晨低、下午高、24小时波动不超过1℃是体温的正常生理变异，并非测量误差"},{"q":"细胞免疫的主要效应细胞CTL由下列哪种细胞辅助产生","o":["Th1细胞","TDTH细胞","Th2细胞","B细胞","NK细胞"],"a":0,"e":"细胞免疫的主要效应细胞CTL（细胞毒性T细胞）在Th1细胞辅助下增殖分化，Th1分泌IL-2、IFN-γ等细胞因子促进其活化。Th2主要辅助B细胞介导体液免疫；TDTH为迟发型超敏反应效应细胞；NK细胞属固有免疫，无需抗原致敏，均非辅助CTL产生的主要细胞"},{"q":"建立慢性阻塞性肺疾病的诊断需要以下哪项","o":["FEV1降低","FVC降低","FEV1/FVC降低","咳嗽、咳痰","RV降低"],"a":2,"e":"慢性阻塞性肺疾病以持续气流受限为特征，肺功能检查示阻塞性通气障碍，FEV1/FVC降低是建立诊断的必备条件。单纯FEV1降低也可见于限制性通气功能障碍；FVC降低多见于限制性病变；RV降低不符合COPD气体陷闭特点；咳嗽咳痰仅为症状"},{"q":"下列哪种情况在常规导联心电图上不出现典型心肌梗死图形","o":["前间壁心肌梗死","前壁心肌梗死","下壁心肌梗死","后壁心肌梗死","前侧壁心肌梗死"],"a":3,"e":"后壁心肌梗死在常规12导联上无典型异常Q波，需加作V7～V9导联才能记录到异常Q波或QS波，常规导联仅见V1、V2对应性改变如R波增高、ST段压低、T波高耸。前间壁、前壁、下壁及前侧壁梗死均可在常规导联相应部位出现典型梗死图形"},{"q":"下列哪项心电图表现提示室内传导阻滞","o":["心电图上QRS波群的时限超过0.10s","QRS波群的形态与典型的LBBB和RBBB均不相似","整个希氏-浦肯野系统的冲动传导弥漫性减慢的结果，导致心室心肌的激动全面性一致延迟","肢体导联上呈现RBBB，而心前区导联上呈现LBBB表现，或反之","肢体导联呈左前分支阻滞，胸导联呈左后分支阻滞，或反之"],"a":0,"e":"室内传导阻滞时激动在室内传导延迟，心电图主要表现为QRS波群时限延长超过0.10秒。其余选项分别描述激动全面一致延迟、QRS形态与典型束支阻滞均不相似、不同导联呈现相反束支阻滞图形等，属于束支或分支阻滞的具体类型，不能概括室内传导阻滞的基本特征"},{"q":"尿失禁的概念是指","o":["尿液从不正常的径路流出","由于严重的膀胱炎有尿液不断从尿道流出","由于膀胱肌损伤，尿液不自主流出","输尿管口异位，尿液从尿道口旁或尿道排出","由于膀胱挛缩，尿液不断从尿道流出"],"a":2,"e":"尿失禁指膀胱括约肌损伤或神经功能障碍致排尿自控能力下降或丧失，尿液不自主流出，本题所述膀胱肌损伤致尿液不自主流出符合其概念。尿液从异常径路流出属尿瘘；严重膀胱炎致尿液不断流出为急迫性尿失禁的表现之一，但非其定义"},{"q":"关于急性阑尾炎，哪项正确","o":["右下腹无压痛，可排除阑尾炎","凡是上腹痛或下腹痛都要考虑阑尾炎可能","急性阑尾炎穿孔时，X线检查见膈下有游离气体","保守治疗时，腹痛突然减轻肯定炎症消退","急性阑尾炎都有恶心、呕吐、腹泻等消化道症状"],"a":1,"e":"急性阑尾炎早期可为中上腹或脐周弥散内脏痛，数小时后转移并固定于右下腹，故上腹痛或下腹痛均需考虑阑尾炎可能。发病早期右下腹可无压痛，不能据此排除；穿孔X线膈下游离气体亦见其他空腔脏器穿孔；恶心呕吐等消化道症状并非每例都有"},{"q":"最容易发生心房颤动的疾病是","o":["贫血","心肌炎","二尖瓣狭窄","高热","预激综合征"],"a":2,"e":"二尖瓣狭窄时左心房扩大、心房肌纤维化，易发生心房颤动，是其最常见的心律失常之一。贫血、心肌炎、高热、预激综合征虽可诱发心律失常，但并发房颤的概率远低于二尖瓣狭窄，故二尖瓣狭窄最易发生心房颤动"},{"q":"尿中胆红素阳性，主要是由于血中增加的是","o":["未结合胆红素","结合胆红素","胆绿素","血红素","与清蛋白结合的胆红素"],"a":1,"e":"结合胆红素为水溶性，血中浓度超过肾阈约34μmol/L时可经肾小球滤过出现在尿中，使尿胆红素阳性。未结合胆红素与清蛋白结合，分子大不能滤过；胆绿素、血红素并非尿胆红素的主要来源，故尿胆红素阳性反映血中结合胆红素增高"},{"q":"以下是医生运用血压计正确的测血压方法，但哪项是错误的","o":["患者采取坐位，安静休息10min以后","肘部应与心脏同一水平，上臂伸直并稍外展","袖带气囊部分对准肱动脉，紧贴皮肤缚于上臂","袖带下缘应距肘弯横纹上2cm处","再将听诊器胸件放于袖带下肱动脉上"],"a":4,"e":"测血压时听诊器胸件应置于肘窝肱动脉搏动处，不能塞入袖带下方，否则袖带充气会压迫胸件产生杂音并影响读数，故该项错误。取坐位安静休息、肘部与心脏同水平、袖带气囊对准肱动脉并紧贴皮肤、下缘距肘横纹约2cm均为正确操作"},{"q":"骨髓细胞学检查对下列哪种疾病具有明确诊断作用","o":["失血性贫血","溶血性贫血","再生障碍性贫血","粒细胞缺乏症","类白血病反应"],"a":2,"e":"再生障碍性贫血因骨髓造血功能衰竭，骨髓涂片及活检示增生低下、巨核细胞明显减少、造血细胞减少而脂肪组织增多，骨髓细胞学检查对其有明确诊断价值。失血性、溶血性贫血及粒细胞缺乏症骨髓多增生活跃；类白血病反应为外周血象改变，均非骨髓确诊指征"},{"q":"慢性充血性心力衰竭的患者胸腔积液中蛋白质与血清中蛋白质的比值常小于","o":["0.1","0.2","0.3","0.5","0.6"],"a":3,"e":"慢性充血性心力衰竭所致胸腔积液为漏出液，因静水压升高、蛋白漏出少，积液蛋白/血清蛋白比值常＜0.5，且积液蛋白浓度多较低。渗出液该比值＞0.5，多见于炎症、肿瘤；0.1、0.2、0.3数值过低，不符合漏出液常规界限"},{"q":"下列情况下常发生“火车头”奔马律的是","o":["舒张早期奔马律与舒张晚期奔马律的互相重叠","舒张早期奔马律与舒张晚期奔马律的同时存在","收缩晚期喀喇音与舒张早期奔马律的同时存在","收缩早期喀喇音与舒张晚期奔马律的同时存在","收缩中期喀喇音与舒张晚期奔马律的同时存在"],"a":1,"e":"火车头奔马律由舒张早期奔马律与舒张晚期奔马律同时存在、在快速心率下重叠形成，三个额外心音类似火车行驶声。单纯舒张早期或晚期奔马律单独存在不呈火车头样；收缩期喀喇音与奔马律组合并非其构成，多见于二尖瓣脱垂等"},{"q":"凝血时间延长，出血时间正常的疾病是","o":["特发性或继发性血小板减少性紫癜","过敏性紫癜","血友病","血管性假血友病","再生障碍性贫血"],"a":2,"e":"血友病因凝血因子Ⅷ或Ⅸ缺乏，内源性凝血途径障碍，故凝血时间延长；而血管壁和血小板功能正常，出血时间正常。特发性血小板减少性紫癜、血管性假血友病因血小板或vWF异常致出血时间延长；再生障碍性贫血兼具血小板减少，出血时间亦延长"},{"q":"S2反常分裂可见于","o":["正常儿童和青年","完全性右束支传导阻滞","完全性左束支传导阻滞","房间隔缺损","二尖瓣关闭不全"],"a":2,"e":"S2反常分裂又称逆分裂，指主动脉瓣关闭迟于肺动脉瓣，吸气时分裂变窄、呼气时变宽，见于完全性左束支传导阻滞。完全性右束支阻滞使右室排血延迟，表现为通常分裂；房间隔缺损为固定分裂；二尖瓣关闭不全致左室射血缩短，亦可呈通常分裂"},{"q":"关于病程记录说法不正确的是","o":["由经治医师书写，不能由实习医师或试用期医务人员书写","内容要真实，记录及时","要有分析判断和预见","病危患者每天至少记录1次","病重患者至少2天记录1次"],"a":0,"e":"日常病程记录可由住院医师书写，也可由实习医务人员或试用期医务人员书写，但须有上级医师审阅、修改并签名，故“不能由实习医师书写”的说法不正确。内容真实及时、有分析判断和预见、病危每天至少记录1次、病重至少2天记录1次均为正确要求"},{"q":"急性弥漫性腹膜炎患者为减轻腹痛，常采取何种体位","o":["侧卧位","仰卧位、双下肢屈曲","仰卧位、两下肢伸直","俯卧位","半卧位"],"a":1,"e":"急性弥漫性腹膜炎病人为减轻腹痛、降低腹肌紧张，常被迫采取仰卧位并双下肢屈曲，此即强迫仰卧位。侧卧位多用于胸膜疾病以减轻患侧胸廓活动；半卧位有利于脓液流向盆腔局限，是后期或术后体位，而非急性期缓解腹痛的主要体位"},{"q":"下列是二尖瓣狭窄时经常出现的症状，但应除外","o":["声音嘶哑","吞咽困难","劳力性呼吸困难","咯血","心绞痛"],"a":4,"e":"心绞痛是主动脉瓣狭窄的典型三联征之一，由左室肥厚致氧耗增加及冠状动脉供血不足引起，并非二尖瓣狭窄的常见症状。二尖瓣狭窄因左房扩大可压迫左喉返神经致声音嘶哑、压迫食管致吞咽困难，并有劳力性呼吸困难、咯血等表现"},{"q":"关于肝脏触诊下列各项均正确，但除外","o":["正常成人的肝肋缘下触不到","深吸气，肋弓下触及肝下缘1cm内，不属于肝大","剑下触及肝下缘3cm内，不属于肝大","如肋下触及肝大3cm，质软、光滑，无压痛，可判定为肝大","肝脏质地分三级，正常肝无压痛"],"a":3,"e":"正常成人肝多在肋缘下触不到，瘦长体型者深吸气时肋下可及1cm以内、剑突下3cm以内，均非肝大。肋下触及3cm虽超出常规，但质软、光滑、无压痛者可见于脂肪肝或体型因素，不能仅凭此一律判定为肝大，须综合质地、压痛及影像判断，故该项表述不当"},{"q":"关于细湿啰音的描述，正确的是","o":["又称捻发音","发生于细支气管","多在呼气末出现","常见于肺淤血","咳嗽后不能消失"],"a":3,"e":"细湿啰音又称小水泡音，发生于小支气管，多在吸气后期出现，常见于细支气管炎、支气管肺炎、肺淤血和肺梗死。捻发音是高音调细小爆裂音，与细湿啰音不同；中湿啰音发生于中等支气管、多在吸气中期；肺底捻发音咳嗽后可消失，细湿啰音一般持续存在"},{"q":"下列对确诊支气管哮喘最有意义是","o":["支气管激发实验阳性","静脉输注氨茶碱有效","血中嗜酸性粒细胞增多","反复发作的喘息、呼吸困难","发作时双肺弥漫性哮鸣音"],"a":0,"e":"支气管激发试验通过刺激使支气管平滑肌收缩，测定气道反应性，阳性对无症状或缓解期、肺功能正常的可疑哮喘及咳嗽变异性哮喘有确诊价值。氨茶碱有效、嗜酸性粒细胞增多、反复喘息及双肺哮鸣音均为辅助或临床表现，缺乏特异性，不能作为确诊依据"},{"q":"患者腹胀半年余，粪便中见到较多的淀粉颗粒，常见于","o":["慢性胰腺炎","慢性肝炎","乙状结肠癌","溃病性结肠炎","直肠癌"],"a":0,"e":"粪便中出现较多淀粉颗粒提示淀粉消化不全，常见于慢性胰腺炎等胰腺外分泌功能不全，因胰淀粉酶分泌减少所致。慢性肝炎、乙状结肠癌、溃疡性结肠炎、直肠癌主要影响消化吸收或肠道黏膜，不以淀粉颗粒增多为特征，多见黏液脓血便或排便习惯改变"},{"q":"巨幼细胞贫血易引起以下哪种改变","o":["空泡变性","棒状小体","核右移","核左移","Dohle体"],"a":2,"e":"巨幼细胞贫血因DNA合成障碍致中性粒细胞分叶过多，出现5叶以上超过3%，称核右移，也见于造血功能衰退或抗代谢药物。核左移见于感染等致杆状核增多；棒状小体（Auer小体）见急性白血病；Dohle体为中性粒细胞毒性改变，见于严重感染"},{"q":"心源性哮喘可见于以下疾病，但哪一项除外","o":["急性左心衰竭","高血压心脏病","扩张性心脏病","肺源性心脏病","液体负荷过重"],"a":3,"e":"心源性哮喘是急性左心衰竭致肺淤血、肺水肿引起的呼吸困难，见于高血压心脏病、扩张型心肌病、液体负荷过重等左心疾病。肺源性心脏病由慢性肺部疾病致右心负荷增加，其呼吸困难为肺源性，不属于心源性哮喘范畴"},{"q":"急性心包炎早期具有诊断价值的症状或体征是","o":["奇脉","血压下降，脉压减少","心包摩擦音","Kussmaul征（＋）","Ewart征（＋）"],"a":2,"e":"急性心包炎早期心包脏层与壁层因纤维蛋白沉积而粗糙，心脏搏动时产生摩擦，听诊心包摩擦音，与心搏一致且屏气时仍存在，是早期具诊断价值的体征。积液增多后摩擦音消失；奇脉、血压下降、Kussmaul征、Ewart征是大量积液或心脏压塞时的表现"},{"q":"S2通常分裂见于下列疾病，但除外","o":["完全右束支阻滞","肺动脉瓣狭窄","二尖瓣狭窄","肺动脉高压","主动脉瓣狭窄"],"a":4,"e":"S2通常分裂是临床上最常见类型，由右室排血时间延长（肺动脉瓣狭窄、二尖瓣狭窄伴肺动脉高压）或左室射血缩短（二尖瓣关闭不全）所致。主动脉瓣狭窄使左心排血受阻、主动脉瓣关闭延迟，导致S2反常分裂而非通常分裂，故为例外"},{"q":"肺泡呼吸音减弱或消失的原因不包括","o":["胸廓活动受限","呼吸肌疾病","支气管阻塞","压迫性肺膨胀不全","机体需氧量增加"],"a":4,"e":"肺泡呼吸音减弱或消失见于胸廓活动受限、呼吸肌疾病、支气管阻塞及压迫性肺膨胀不全等使进入肺泡气流量减少的情况。机体需氧量增加时呼吸深快、通气增强，反而使肺泡呼吸音增强，如运动、发热、代谢亢进，故不属于减弱原因"},{"q":"脑积水时的头颅改变是","o":["方颅","小颅","尖颅","巨颅","长颅"],"a":3,"e":"脑积水因颅内压增高致额、顶、颞、枕部膨大呈圆形，颜面相对很小，并出现落日现象，称巨颅。方颅见于小儿佝偻病或先天性梅毒；小颅见于小头畸形；尖颅见于颅缝早闭；长颅见于马方综合征，均与脑积水的头颅改变不同"},{"q":"能确定有心肌缺血的心电图改变是","o":["电轴显著左偏","左心室面电压增高","V5导联ST段近似水平下移＜0.1mV","P波电压＞0、3mV","V4、V5、V6的ST段水平下移＞0.2mV伴T波倒置"],"a":4,"e":"心肌缺血的心电图表现为相应导联ST段水平型或下斜型压低伴T波倒置，V4、V5、V6导联ST段水平下移＞0.2mV伴T波倒置是明确缺血改变。电轴左偏、左室电压增高为心室肥厚或传导异常表现；V5导联ST段下移＜0.1mV程度轻、特异性不足"},{"q":"心包积液叩诊时","o":["心浊音界向左下增大","心浊音界向右增大","梨形心","心界向两侧增大，同时心浊音界可随体位而改变","靴型心"],"a":3,"e":"心包积液时心浊音界向两侧扩大，相对与绝对浊音界几乎相同，并随体位改变，坐位呈三角形烧瓶样、卧位心底部增宽。向左下增大呈靴形心见于主动脉瓣关闭不全；梨形心见于二尖瓣狭窄，两者均为心腔增大所致，不随体位改变"},{"q":"临床出血患者，APTT延长而PT正常，最可能缺陷的是","o":["FⅩ","FⅡ","FⅤ","FⅧ","FⅫ"],"a":3,"e":"APTT是内源性凝血系统的筛选试验，PT正常而APTT延长提示内源性途径因子缺陷，以因子Ⅷ缺乏（血友病A）最常见。FⅦ缺乏致PT延长而APTT正常；FⅩ、FⅤ、FⅡ属共同途径，其缺乏常致PT和APTT同时延长，不符合本题表现"},{"q":"急性病毒性肝炎时，反映肝损伤的最敏感指标是","o":["ALT","AST","ALP","AFP","MAO"],"a":0,"e":"ALT主要存在于肝细胞胞质，半衰期约47小时，较AST（17小时）长，急性病毒性肝炎时ALT升高更明显，是反映肝细胞损伤最敏感的指标。AST亦升高但特异性略低；ALP、γ-GT反映胆汁淤积；MAO反映肝纤维化；AFP为肝癌标志物"},{"q":"正常心尖冲动直径的范围为","o":["0.5～1.0cm","1.0～1.5cm","1.5～2.0cm","2.0～2.5cm","2.5～3.0cm"],"a":3,"e":"正常成人心尖搏动位于第5肋间左锁骨中线内侧0.5～1.0cm处，搏动范围直径2.0～2.5cm。0.5～1.0cm是搏动位置距锁骨中线的距离，并非直径；其余数值均偏离正常心尖冲动范围"},{"q":"一中年职业女性患者，择期行子宫肌瘤切除术，手术同意书不能由谁签字","o":["患者丈夫","患者本人","患者父母","患者子女","患者朋友"],"a":4,"e":"手术同意书应由病人本人签署，病人不具备完全民事行为能力时由其法定代理人签字，配偶、父母、子女属法定代理人范围。患者朋友不属于法定代理人，无权代为签字，故不能由朋友签署"},{"q":"凝血功能障碍所致出血的实验室筛选试验，其主要表现是","o":["出血时间延长，束臂试验阳性","血小板减少，凝血时间延长","血小板减少，出血时间延长","血块回缩不佳，血小板聚集率下降","血浆凝血酶原时间延长，部分凝血活酶时间延长"],"a":4,"e":"凝血功能障碍源于凝血因子缺乏，筛选试验以PT（外源性凝血系统）和APTT（内源性凝血系统）延长为主要表现。出血时间、束臂试验、血小板计数及血块回缩主要反映血管壁和血小板功能异常，属初期止血筛查，不直接反映凝血因子缺陷"},{"q":"急性发热或体温上升期","o":["交感神经兴奋，心率加快，外周血管收缩，血压上升","交感神经兴奋，心率加快，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管收缩，血压上升","交感神经兴奋，心率减慢，外周血管舒张，血压上升"],"a":0,"e":"急性发热或体温上升期，交感神经兴奋、儿茶酚胺分泌增多，致心率加快、外周血管收缩、血压上升，同时皮肤血管收缩使散热减少、产热增加。迷走神经兴奋致心率减慢，外周血管舒张致血压下降，均与发热时的交感兴奋状态相反"},{"q":"面容潮红、兴奋不安、鼻翼翕动、口唇疱疹、表情痛苦的面容是","o":["肾病面容","贫血面容","慢性病容","急性病容","黏液水肿面容"],"a":3,"e":"急性病容表现为面色潮红、兴奋不安、鼻翼扇动、口唇疱疹、表情痛苦，多见于肺炎球菌肺炎、疟疾等急性感染性疾病。慢性病容憔悴晦暗、表情忧虑；肾病面容苍白浮肿；黏液水肿面容苍白虚肿、表情淡漠，均与题干描述不符"},{"q":"患者对青霉素、磺胺等药物过敏应记录于","o":["现病史","既往史","家族史","个人史","婚育史"],"a":1,"e":"既往史记录病人过去的健康状况和疾病情况，包括传染病史、外伤手术史、预防接种史及食物或药物过敏史，故青霉素、磺胺过敏应记入既往史。现病史仅反映本次疾病的发生发展过程；家族史记亲属疾病；个人史记生活习惯等"},{"q":"临床表现为咯血伴脓痰常见于下列疾病，但需除外","o":["干性支气管扩张","湿性支气管扩张","肺脓肿","化脓性肺炎","空洞型肺结核并发感染"],"a":0,"e":"咯血伴脓痰见于支气管扩张、肺脓肿、肺囊肿合并感染、支气管胸膜瘘等，湿性支气管扩张、肺脓肿、化脓性肺炎及空洞型肺结核并发感染均可出现。干性支气管扩张以反复咯血为主要表现，咳嗽轻、少痰或无脓痰，故为例外"},{"q":"舒张早期奔马律由下列哪项构成","o":["S1分裂及S2","S1及主动脉瓣S2分裂","S1S2及病理性S4","S1及肺动脉瓣S2分裂","S1S2及病理性S3"],"a":4,"e":"舒张早期奔马律是病理性第三心音，由S1、S2及病理性S3构成，伴心率增快时S2与S3间距和S1与S2相仿，听诊如奔马。舒张晚期奔马律由S1、S2及病理性S4构成；S1或S2分裂形成的是心音分裂，均非舒张早期奔马律的组成"},{"q":"与血小板黏附功能无关的是","o":["血管内皮损伤","需有vWF","需有GPⅠb","需有Fg","需有GPV"],"a":3,"e":"血小板黏附依赖血小板膜糖蛋白GPⅠb/Ⅴ/Ⅸ通过vWF与内皮下胶原结合，需血管内皮损伤暴露胶原、vWF及GPⅠb参与。纤维蛋白原（Fg）主要与GPⅡb/Ⅲa结合介导血小板聚集，而非黏附；GPⅤ属黏附受体复合物成分，与黏附相关"},{"q":"下列关于肋骨和肋间隙的描述，错误的是","o":["肋骨在背部与相应的胸椎相连","第11、12肋骨不与胸骨相连","肋间隙为两个肋骨之间的空隙","第1肋骨和第2肋骨之间的间隙为第2肋间隙","大多数肋骨可在胸壁上触及"],"a":3,"e":"肋间隙为两肋骨之间的空隙，第1肋骨下面的间隙为第1肋间隙，第2肋骨下面的间隙为第2肋间隙，依次类推，故第1与第2肋骨之间为第1肋间隙而非第2。胸骨角平第2肋软骨是计数标志；第11、12肋为浮肋不与胸骨相连"},{"q":"下列主诉，哪一项最为确切","o":["咽痛、高热、寒战、气短","右胸痛、咳嗽","胃溃疡3年，呕血1h","活动后心悸气短2年，下肢水肿2周","2天来无诱因发热"],"a":3,"e":"主诉应为病人最主要的症状或体征及其持续时间，一两句话概括。“活动后心悸气短2年，下肢水肿2周”含主要症状和时间，最确切。“咽痛、高热、寒战、气短”及“右胸痛、咳嗽”缺时间；“胃溃疡3年，呕血1h”含诊断名称；“2天来无诱因发热”过于笼统"},{"q":"风湿性心脏病，主动脉瓣狭窄最主要的体征是","o":["心脏向左下扩大明显","胸骨左缘第3、4肋间有舒张期杂音","周围血管征（＋）","抬举样心尖冲动","主动脉瓣区收缩期喷射性杂音伴第二心音减弱"],"a":4,"e":"风湿性心脏病主动脉瓣狭窄最主要体征是主动脉瓣区（胸骨右缘第2肋间）闻及粗糙的收缩期喷射性杂音，向颈部传导伴震颤，且第二心音主动脉瓣成分减弱。周围血管征见于主动脉瓣关闭不全；抬举样心尖冲动为左室肥厚表现，均非本病最主要体征"},{"q":"安静状态下，出现ST段抬高，持续数分钟后回落，且不形成Q波，诊断上首先应该考虑","o":["劳力性心绞痛","急性心肌炎","急性肺栓塞","变异性心绞痛","主动脉夹层"],"a":3,"e":"安静状态下出现ST段抬高、持续数分钟后回落且不形成Q波，是变异性心绞痛的典型表现，由冠状动脉痉挛致一过性严重心肌缺血引起。急性心肌梗死ST段持续抬高并形成病理性Q波；急性心包炎ST抬高广泛且无对应导联压低；劳力性心绞痛多表现为ST压低"},{"q":"左侧大量胸腔积液时心浊音界出现的改变为","o":["心浊音界变小，甚至叩不出","使心脏呈横位，心界向两侧扩大","心界在患侧叩不出，在健侧向外移位","心底部浊音区增宽","心界向患侧移位"],"a":2,"e":"左侧大量胸腔积液时患侧胸膜腔被液体占据，心界在患侧叩不出，纵隔及心脏被推向健侧，致心界向健侧外移。心包积液时心界向两侧扩大且随体位改变；大量腹腔积液抬高横膈使心脏呈横位，均与单侧胸腔积液的推挤效应不同"},{"q":"中枢性发热见于","o":["肺炎","脑膜炎","脑出血","风湿热","肿瘤"],"a":2,"e":"中枢性发热是体温调节中枢本身受损所致，脑出血、脑震荡、脑挫伤等颅内疾病直接损害体温调节中枢，引起中枢性发热。肺炎、风湿热、肿瘤多通过致热原或免疫机制发热；脑膜炎为颅内感染性发热，均非单纯中枢调节障碍"},{"q":"下列哪种疾病不会引起消瘦","o":["糖尿病","甲状腺功能低下","慢性胆囊炎","胃溃疡","先天性乳糖酶缺乏"],"a":1,"e":"甲状腺功能低下因甲状腺激素不足、基础代谢率降低及黏液水肿，患者常体重增加、畏寒，不会引起消瘦。糖尿病因糖利用障碍致脂肪分解增加；慢性胆囊炎、胃溃疡因消化吸收受影响；先天性乳糖酶缺乏因腹泻和吸收不良，四者均可导致体重下降与消瘦"},{"q":"下列为严重肺气肿的体征，但不符合的是","o":["视诊胸廓呈漏斗状","触诊语颤减弱","叩诊肺肝界下移","叩诊双肺呈过清音","听诊双侧呼吸音减弱"],"a":0,"e":"严重肺气肿因肺泡过度充气，胸廓呈桶状、肋间隙增宽，而非漏斗状；漏斗胸是胸骨剑突处先天内陷畸形。语颤减弱、双肺过清音、肺肝界下移及呼吸音减弱均为肺气肿典型体征，其中过清音最具特征"},{"q":"心包叩击音最常见于","o":["大量心包积液","二尖瓣狭窄","缩窄性心包炎","主动脉瓣关闭不全","右束支传导阻滞"],"a":2,"e":"心包叩击音是缩窄性心包炎的特征性额外心音，在S2后约0.09～0.12秒出现，中频、较响而短促，因心室舒张突然受限、室壁振动所致。开瓣音见于二尖瓣狭窄（S2后0.05～0.06秒，拍击样）；大量心包积液表现为心音遥远，均非心包叩击音"},{"q":"呕血时，出血量超过（ ）可致循环障碍（失血性休克）","o":["400ml","800ml","1000ml","1500ml","2000ml"],"a":2,"e":"呕血量超过1000ml或超过循环血量的20%时，可致失血性休克，出现周围循环衰竭表现，属急症需紧急处理。少量出血（＜5ml）仅隐血试验阳性；50～100ml可出现黑便；400ml左右可有头晕心悸等，但一般不致休克"},{"q":"以下均为急性腹膜炎感染中毒后期的表现，除外","o":["精神抑郁，面色灰白","皮肤及舌面干燥，眼球及两颊内陷","脉搏频数而无力","血压下降","呼吸频速表浅"],"a":4,"e":"急性腹膜炎感染中毒后期因高热、不能进食、呕吐、失水及酸中毒，出现精神萎靡、面色灰白、皮肤舌面干燥、眼球两颊内陷、脉搏频数无力、血压下降等休克与中毒表现。呼吸浅速是早期因腹痛、腹肌紧张所致的体征，不属于感染中毒后期表现"},{"q":"反映肝脏纤维化的酶是","o":["γ-GT","ALP","MAO","ALT","AST"],"a":2,"e":"单胺氧化酶（MAO）可加速胶原纤维交联，其血清活性与体内结缔组织增生呈正相关，是反映肝脏纤维化的酶，重症肝硬化及伴肝硬化的肝癌常增高。ALT、AST反映肝细胞损伤；ALP、γ-GT反映胆汁淤积和胆道病变，均非纤维化指标"},{"q":"下列各项为产生局部水肿的原因，但应除外","o":["淋巴回流受阻","局部蜂窝织炎","低蛋白血症","局部静脉受压","毛细血管通透性增加"],"a":2,"e":"低蛋白血症使血浆胶体渗透压降低，液体进入组织间隙，引起全身性水肿，如营养不良性水肿、肾病性水肿，不属于局部水肿原因。淋巴回流受阻、局部蜂窝织炎、局部静脉受压及毛细血管通透性增加均局限于某部位，导致局部水肿"},{"q":"病史中最重要的是","o":["个人史","婚姻史","家族史","既往史","现病史"],"a":4,"e":"现病史是病史中的主体和最重要部分，反映病人患病后的全过程，包括起病情况、症状演变及诊治经过，对诊断和鉴别诊断价值最大。个人史、婚姻史、家族史和既往史提供背景信息，重要性均不及现病史"},{"q":"自律性最低的组织是","o":["窦房结","心房传导阻滞","房室交界组织","房室束","浦肯野纤维"],"a":4,"e":"心脏特殊传导系统各部位自律性不同：窦房结最高（60～100次/分）为正常起搏点，房室交界次之，房室束更低，浦肯野纤维最低（约20～40次/分），故自律性最低的是浦肯野纤维。窦房结自律性最高而非最低，房室交界处于中间水平"},{"q":"关于心源性水肿的特点，正确的是","o":["从眼睑面部开始延及全身","从足部开始向上延及全身","水肿时最先出现腹水","上肢、颈部水肿","单侧下肢凹陷性水肿"],"a":1,"e":"心源性水肿主要由右心衰竭致体循环静脉淤血，水肿从足部开始，逐渐向上延及全身，发展较慢，性质较坚实、移动性小，伴心脏增大、肝大、静脉压升高。从眼睑颜面开始是肾源性水肿特点；以腹水为主见于肝源性水肿；单侧下肢水肿多为局部静脉或淋巴问题"},{"q":"对退行性骨关节炎描述错误的是","o":["多见于中老年人","晨僵时间小于30min","关节肿痛对称分布","爬楼、久站后疼痛加剧","休息能缓解疼痛"],"a":2,"e":"退行性骨关节炎多见于中老年人，因关节软骨退变和骨质增生所致，晨僵时间短于30分钟，活动或爬楼、久站后疼痛加剧，休息可缓解，常累及负重关节且不对称。关节肿痛对称分布是类风湿关节炎的特点，不属于退行性骨关节炎"},{"q":"临床上，一旦心房颤动患者的心室律变得规则，出现下列哪种情况的可能性最小","o":["恢复窦性心律","房扑及固定的房室传导比例","房性心动过速","如心室律变慢而规则，提示完全房室传导阻滞","出现二度Ⅰ型房室传导阻滞"],"a":4,"e":"心房颤动心室律绝对不齐，若变得规则，可能为恢复窦性心律、转为房扑伴固定房室传导比例、房性心动过速，或出现完全房室传导阻滞致心室律慢而规则。二度Ⅰ型房室传导阻滞因PR间期逐渐延长至QRS脱漏，心室律反而不规则，可能性最小"},{"q":"下列关于心音分裂的说法正确的是","o":["S2分裂一般不因呼吸而变异","生理情况下心尖区最容易听到S2分裂","S2分裂都是病理性的","生理情况下吸气时S2分裂更加明显","反常分裂是指S2的主动脉瓣成分早于肺动脉瓣成分"],"a":3,"e":"生理情况下深吸气时胸腔负压增加，右心回心血量增多、右室排血时间延长，肺动脉瓣关闭迟于主动脉瓣，使S2分裂在吸气时更明显，以肺动脉瓣区最清楚。固定分裂不受呼吸影响，见于房间隔缺损；反常分裂主动脉瓣成分迟于肺动脉瓣，吸气时分裂变窄"},{"q":"下列各项均为肝脏触诊检查方法，但除外","o":["单手触诊法","双手触诊法","钩指触诊法","浮沉触诊法","滑行触诊法"],"a":4,"e":"肝脏触诊常用单手触诊法、双手触诊法、钩指触诊法，腹腔积液时可用浮沉触诊法。滑行触诊法主要用于胆囊、膀胱及腹部包块的触诊，或鉴别横结肠等易误为肝下缘的结构，不属于肝脏触诊的基本方法"},{"q":"肛门指诊的正确方法是","o":["探查示指与肛门口垂直","探查示指先在肛门轻轻按摩","探查示指通过肛门后快速插入直肠","探查示指戴手套后即进行指诊","探查示指不需等待肛门括约肌放松后才进行指诊"],"a":1,"e":"肛门指诊时医生右手示指戴手套或指套并涂润滑剂，先置于肛门外口轻轻按摩，待肛门括约肌适应放松后再徐徐插入直肠，以免引起疼痛和括约肌痉挛。示指需涂润滑剂并与肛管方向一致，通过肛门后应缓慢插入，戴手套后不能直接指诊"},{"q":"水冲脉的发生机制为","o":["脉压缩小","脉压增大","脉压正常","收缩压降低","舒张压升高"],"a":1,"e":"水冲脉表现为脉搏骤起骤落，其机制是脉压增大，即收缩压升高而舒张压降低，见于主动脉瓣关闭不全、甲亢、动静脉瘘、严重贫血等。脉压缩小或收缩压降低、舒张压升高会使脉搏减弱，不产生水冲脉"},{"q":"下列说法正确的是","o":["心悸即心跳加快","心脏神经官能症时出现心悸，但不伴有心前区疼痛","心悸可见于窦性心动过缓","心悸与心律失常发生的严重程度成正比","心悸代表患有心脏疾病"],"a":2,"e":"心悸是病人自觉心跳或心慌的不适感，心动过速、过缓或心律不齐均可出现，窦性心动过缓（心率＜60次/分）亦然，故该说法正确。心悸不等同于心跳加快，也不与心律失常严重程度成正比；心脏神经官能症可有心悸并伴心前区疼痛，心悸亦可见于无心脏病人群"},{"q":"腹痛伴里急后重可见于","o":["肠结核","急性细菌性痢疾","伤寒","副伤寒","结肠癌"],"a":1,"e":"里急后重提示病变以直肠、乙状结肠为主，表现为便意频繁、肛门坠胀而排便不畅，急性细菌性痢疾病变主要位于结肠直肠段，故腹痛伴里急后重最常见于此。肠结核与伤寒、副伤寒病变主要在回肠等小肠，多表现为腹痛、腹泻或便秘，无此直肠刺激征。结肠癌虽可发生于直肠，但以慢性腹泻、便血、消瘦为主，里急后重并非其典型表现"},{"q":"对化脓性关节炎的特点描述不正确的是","o":["细菌直接侵入关节","多累及双下肢","伴有高热、寒战","开放性外伤是重要感染途径","常有多关节同时受累"],"a":4,"e":"化脓性关节炎多由细菌经血行或开放性外伤直接侵入关节引起，起病急骤，伴高热寒战、局部红肿灼热，以髋膝等下肢负重关节多见，常为单关节发病，故多关节同时受累并非其特点。多关节受累实为类风湿关节炎、系统性红斑狼疮等关节病变的表现。细菌直接侵入关节与开放性外伤为重要感染途径、伴高热寒战、好发下肢负重关节均符合本病特点"}];
